// ===================== 💾 STORAGE (IndexedDB + cache đồng bộ, tự migrate từ localStorage) =====================
// Lý do: localStorage chỉ ~5MB → ảnh base64 (roster/VFX) dễ tràn. IndexedDB chứa vài trăm MB.
// _store = cache RAM để mọi code load/save cũ vẫn đọc/ghi ĐỒNG BỘ như trước; ghi xuống IndexedDB nền.
const _STORE_KEYS = ['cbs_fan_avatars','cbs_scene','cbs_roster','cbs_vfx_library','cbs_debuff_vfx','cbs_rt_season','cbs_rt_blocked','cbs_vfx_seed_done','cbs_char_stats','cbs_update_notes','cbs_tierlist'];
let _store = {};   // cache RAM
let _idb = null;   // kết nối IndexedDB (null nếu trình duyệt chặn → fallback localStorage)
function _idbOpen(){
  return new Promise((res,rej)=>{
    let r; try{ r=indexedDB.open('cbs_db',1); }catch(e){ return rej(e); }
    r.onupgradeneeded=()=>{ try{ r.result.createObjectStore('kv'); }catch(e){} };
    r.onsuccess=()=>res(r.result);
    r.onerror=()=>rej(r.error);
  });
}
function _idbSet(k,v){ if(!_idb) return; try{ _idb.transaction('kv','readwrite').objectStore('kv').put(v,k); }catch(e){} }
function _idbDel(k){ if(!_idb) return; try{ _idb.transaction('kv','readwrite').objectStore('kv').delete(k); }catch(e){} }
async function initStore(){
  try{ _idb = await _idbOpen(); }catch(e){ _idb=null; }
  if(_idb){
    await new Promise((res)=>{
      let store; try{ store=_idb.transaction('kv','readonly').objectStore('kv'); }catch(e){ return res(); }
      let pending=_STORE_KEYS.length;
      _STORE_KEYS.forEach(k=>{
        let g; try{ g=store.get(k); }catch(e){ if(--pending===0) res(); return; }
        g.onsuccess=()=>{ if(g.result!=null) _store[k]=g.result; if(--pending===0) res(); };
        g.onerror=()=>{ if(--pending===0) res(); };
      });
    });
  }
  // MIGRATE: key nào IDB chưa có mà localStorage đang có → copy sang IDB (giữ nguyên localStorage làm backup)
  _STORE_KEYS.forEach(k=>{
    if(_store[k]==null){
      let ls=null; try{ ls=localStorage.getItem(k); }catch(e){}
      if(ls!=null){ _store[k]=ls; _idbSet(k,ls); }
    }
  });
  await _loadDefaultSave();
}
// 🌐 BẢN ONLINE (Netlify): trình duyệt người xem chưa có roster/avatar/VFX → tự nạp file default_save.json đặt cạnh game
//    (chính là file Export Save của chủ game). Mỗi lần deploy save mới (_ver khác) thì nạp đè bản mới.
//    Mở bằng file:// ở máy (chạy local) thì bỏ qua hoàn toàn — dữ liệu local giữ nguyên như cũ.
async function _loadDefaultSave(){
  if(!/^https?:$/.test(location.protocol)) return;
  try{
    const r=await fetch('default_save.json',{cache:'no-cache'}); if(!r.ok) return;
    const bundle=await r.json(); const ver=String(bundle._ver||'');
    let cur=null; try{ cur=localStorage.getItem('cbs_default_ver'); }catch(e){}
    if(ver && cur===ver && storeGet('cbs_roster')!=null) return;   // đã nạp đúng bản này rồi
    // save to quá 100MB/file của GitHub → mỗi mục cắt thành nhiều mảnh text (bundle.parts = {key:[đường dẫn mảnh...]}), tải song song rồi ghép lại
    if(bundle.parts){ for(const [k,files] of Object.entries(bundle.parts)){
      const txt=await Promise.all(files.map(f=>fetch(f,{cache:'no-cache'}).then(x=>{ if(!x.ok) throw new Error(f); return x.text(); })));
      bundle[k]=txt.join(''); } }
    const KEEP=['cbs_char_stats','cbs_rt_season','cbs_rt_blocked','cbs_tierlist'];   // tiến độ RIÊNG của người chơi (thống kê, mùa giải) — chỉ nạp lần đầu, cập nhật sau KHÔNG đè
    for(const k of _STORE_KEYS){ if(bundle[k]==null) continue; if(KEEP.includes(k) && storeGet(k)!=null) continue; _store[k]=bundle[k]; if(_idb) await _idbPutAwait(k,bundle[k]); else { try{ localStorage.setItem(k,bundle[k]); }catch(e){} } }
    try{ localStorage.setItem('cbs_default_ver',ver); }catch(e){}
  }catch(e){}
}
function storeGet(k){ return (_store[k]!=null)?_store[k]:null; }
function storeSet(k,v){ _store[k]=v; if(_idb) _idbSet(k,v); else { try{ localStorage.setItem(k,v); }catch(e){} } }
function storeDel(k){ delete _store[k]; if(_idb) _idbDel(k); else { try{ localStorage.removeItem(k); }catch(e){} } }

// ===== EXPORT/IMPORT: chuyển dữ liệu (roster + ảnh avatar, VFX library, leaderboard, update note...) giữa các nơi lưu trữ khác nhau (VD: Simple Browser trong VS Code <-> mở file trực tiếp bằng Chrome, 2 origin khác nhau nên KHÔNG tự dùng chung storage được) =====
// Luôn hiện kèm modal có ô text để copy/paste tay — vì tải file bằng <a download> hay bị chặn trong webview hạn chế (Simple Browser), không thể tin tưởng 100%.
function exportSaveData(){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi
  const bundle = {};
  _STORE_KEYS.forEach(k=>{ const v=storeGet(k); if(v!=null) bundle[k]=v; });
  const json = JSON.stringify(bundle);
  try{
    const blob = new Blob([json], {type:'application/json'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const stamp = new Date().toISOString().slice(0,10);
    a.href = url; a.download = `chaos-battle-save-${stamp}.json`;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  }catch(e){ /* webview có thể chặn tải file — vẫn còn ô copy bên dưới làm dự phòng */ }
  document.getElementById('dataTransferTitle').textContent = '📤 Export Save';
  document.getElementById('dataTransferExportView').style.display = '';
  document.getElementById('dataTransferImportView').style.display = 'none';
  document.getElementById('dataTransferText').value = json;
  document.getElementById('dataTransferOverlay').classList.add('open');
}
function _copyDataTransferText(btn){
  const ta = document.getElementById('dataTransferText');
  ta.focus(); ta.select();
  const feedback = (ok) => {
    if(!btn) return;
    const orig = btn.textContent;
    btn.textContent = ok ? '✅ Đã copy!' : '⚠️ Lỗi, tự bấm Cmd+C';
    setTimeout(()=>{ btn.textContent = orig; }, 1800);
  };
  const legacyFallback = () => {
    let ok=false;
    try{ ok = document.execCommand('copy'); }catch(e){}
    feedback(ok);
  };
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(ta.value).then(()=>feedback(true)).catch(legacyFallback);
  } else {
    legacyFallback();
  }
}
function importSaveData(){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi
  document.getElementById('dataTransferTitle').textContent = '📥 Import Save';
  document.getElementById('dataTransferExportView').style.display = 'none';
  document.getElementById('dataTransferImportView').style.display = '';
  document.getElementById('dataTransferFileInput').value = '';
  document.getElementById('dataTransferPasteBox').value = '';
  document.getElementById('dataTransferOverlay').classList.add('open');
}
function closeDataTransfer(){
  document.getElementById('dataTransferOverlay').classList.remove('open');
}
function _dtLog(msg){
  const el = document.getElementById('dataTransferDebug');
  if(el) el.textContent += msg + '\n';
}
function _idbPutAwait(k,v){
  return new Promise((resolve)=>{
    if(!_idb){ resolve({ok:false, reason:'không có kết nối IndexedDB (đang fallback localStorage)'}); return; }
    try{
      const req = _idb.transaction('kv','readwrite').objectStore('kv').put(v,k);
      req.onsuccess = () => resolve({ok:true});
      req.onerror = () => resolve({ok:false, reason: (req.error&&req.error.name)+': '+(req.error&&req.error.message)});
    }catch(e){ resolve({ok:false, reason:'throw: '+e.message}); }
  });
}
async function _applyImportedBundle(json){
  _dtLog(`[parse] độ dài chuỗi nhận được: ${json.length} ký tự`);
  let bundle;
  try{ bundle = JSON.parse(json); }
  catch(e){ _dtLog('[parse] LỖI: '+e.message); alert('Nội dung không hợp lệ: '+e.message); return; }
  _dtLog('[parse] OK, các mục tìm thấy trong file: '+Object.keys(bundle).join(', '));
  let count = 0, failCount = 0, presentCount = 0;
  for(const k of _STORE_KEYS){
    if(bundle[k]==null){ _dtLog(`[${k}] không có trong file, bỏ qua`); continue; }
    presentCount++;
    const v = bundle[k];
    _store[k] = v; // cập nhật cache RAM ngay, dùng được luôn trong phiên hiện tại dù ghi đĩa có lỗi hay không
    const sizeKB = (v.length/1024).toFixed(1);
    let r;
    if(_idb){ r = await _idbPutAwait(k, v); }
    else { try{ localStorage.setItem(k,v); r={ok:true}; }catch(e){ r={ok:false, reason:e.message}; } }
    _dtLog(`[${k}] ${sizeKB}KB -> ${r.ok ? '✅ đã ghi đĩa' : '❌ LỖI: '+r.reason}`);
    if(r.ok) count++; else failCount++;
  }
  if(!count){ _dtLog('KHÔNG có mục nào ghi thành công.'); alert('Không ghi được dữ liệu — xem log debug trong khung Import để biết lỗi cụ thể.'); return; }
  if(failCount>0){
    _dtLog(`Hoàn tất: ${count}/${presentCount} mục ghi thành công, ${failCount} mục LỖI (xem chi tiết ở trên).`);
    alert(`Chỉ ghi được ${count}/${presentCount} mục, còn ${failCount} mục bị lỗi khi ghi đĩa — xem log debug trong khung Import để biết cụ thể mục nào. KHÔNG tải lại trang để m còn đọc log.`);
    return;
  }
  _dtLog(`Hoàn tất: ${count}/${presentCount} mục đã ghi đĩa thành công.`);
  alert(`Đã nhập ${count} mục dữ liệu (roster, ảnh, VFX, leaderboard...). Đang tải lại trang...`);
  location.reload();
}
function _runImportSaveData(){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi
  document.getElementById('dataTransferDebug').textContent = '';
  const pasted = document.getElementById('dataTransferPasteBox').value.trim();
  if(pasted){ _dtLog('[nguồn] dán tay, độ dài: '+pasted.length+' ký tự'); _applyImportedBundle(pasted); return; }
  const file = document.getElementById('dataTransferFileInput').files[0];
  if(!file){ alert('Chọn 1 file .json hoặc dán nội dung vào ô bên dưới.'); return; }
  _dtLog(`[file] ${file.name}, ${(file.size/1024/1024).toFixed(2)}MB`);
  const reader = new FileReader();
  reader.onerror = () => _dtLog('[đọc file] LỖI: '+reader.error);
  reader.onload = () => { _dtLog('[đọc file] xong, '+reader.result.length+' ký tự'); _applyImportedBundle(reader.result); };
  reader.readAsText(file);
}

