const MC_BASE_MOUNT = {1:{x:0.4978,y:0.0095}, 2:{x:0.4981,y:0.0099}, 3:{x:0.7207,y:0.0103}, 4:{x:0.4985,y:0.0129}, 5:{x:0.8494,y:0.009}};
const MC_TOP_MOUNT  = {1:{x:0.7851,y:0.9771}, 2:{x:0.6752,y:0.9712}, 3:{x:0.7087,y:0.9639}, 4:{x:0.6972,y:0.979},  5:{x:0.8542,y:0.9638}};
const MC_BASE_H = 46*1.2; // +20% theo yêu cầu
const MC_TOP_H = 30*1.1*0.9; // +10% rồi -10% theo yêu cầu lần lượt
// 📡 bán kính vùng "rada" quanh hòm — ĐỊCH (hoặc vật triệu hồi của địch) đi vào đúng vùng vẽ này là hòm tự lắp súng ngay,
// KHÔNG còn cần Mechanic Cat tự thân đi tới hòm nữa. Vùng hiển thị (vẽ) và vùng kích hoạt (check va chạm) LUÔN dùng
// chung đúng 1 con số này để không bao giờ lệch nhau giữa cái mắt thấy và cái thực sự kích hoạt.
const MC_RADAR_R = 38*1.2*1.9*1.1;
// khẩu 4: ảnh base vốn RỘNG BẢN hơn hẳn 3 khẩu kia (tỉ lệ ~2.2:1 so với ~1.1-1.3:1), nòng ngắn tương ứng nên hay bị thân súng "nuốt" mất,
// nhìn như lắp ngược/thiếu nòng — phóng to riêng phần Top (nòng) của khẩu 4 để luôn thò rõ ra khỏi thân, cân đối lại với 3 khẩu còn lại
const MC_TOP_H_MUL = {4:1.4};
// 🎯 Vector THẬT từ khớp xoay (MC_TOP_MOUNT) tới đúng đầu nòng, đo trực tiếp bằng pixel-scan (tìm cột trong suốt=0 đầu tiên từ trái).
// Trước đây tính sai: coi đầu nòng nằm NGANG HÀNG với khớp xoay (chỉ trừ khoảng cách theo trục X), nhưng ảnh gốc vẽ nòng CHÉO hẳn lên trên
// (đo được lệch tới ~60-70% chiều cao ảnh) → đạn/hiệu ứng chớp nòng bắn ra bị lệch hẳn lên trên/xuống dưới so với đầu nòng vẽ trên màn hình.
const MC_MUZZLE_OFFSET = {1:{dx:-0.7812,dy:-0.5992}, 3:{dx:-0.7010,dy:-0.5723}, 4:{dx:-0.6922,dy:-0.6923}, 5:{dx:-0.8476,dy:-0.6776}};
// tính đúng toạ độ đầu nòng THẬT ngoài màn hình: lấy vector cục bộ (trong hệ toạ độ ảnh gốc chưa xoay) rồi xoay đúng bằng góc đã xoay lúc vẽ (_drawAng+PI)
function _mcMuzzlePoint(turretType, mt, drawAng, topW, topH, mirrored){
  const off = MC_MUZZLE_OFFSET[turretType] || {dx:-0.75, dy:-0.6};
  // góc dưới-trái (mirrored): ảnh nòng vẽ lật NỘI DUNG quanh khớp xoay + xoay góc "_drawAng" (không +180°, xem draw()) —
  // vector cục bộ tới đầu nòng cũng phải đảo dấu trục X (đối xứng qua khớp xoay) để khớp đúng nội dung đã lật
  const localDx = (mirrored?-off.dx:off.dx)*topW, localDy = off.dy*topH;
  const th = mirrored ? drawAng : drawAng+Math.PI; // đúng góc xoay thật sự dùng lúc vẽ Top (xem ctx.rotate(...) trong draw())
  const c=Math.cos(th), s=Math.sin(th);
  return { x: mt.x + localDx*c - localDy*s, y: mt.y + localDx*s + localDy*c };
}
// 📡 hiệu ứng rada quanh hòm ĐANG CHỜ kích hoạt — vòng tròn viền + sóng lan toả + cánh quét xoay liên tục.
// Bán kính LUÔN truyền đúng bằng MC_RADAR_R (hằng số dùng CHUNG với chỗ check va chạm thật) — vùng hiển thị và vùng
// kích hoạt thật vì vậy không bao giờ lệch nhau, người xem thấy vòng tròn tới đâu là biết chính xác vùng kích hoạt tới đó.
function _mcDrawRadarSweep(cx, cy, r){
  const t=Date.now();
  ctx.save();
  ctx.translate(cx,cy);
  ctx.strokeStyle='rgba(0,229,255,0.4)'; ctx.lineWidth=1.2;
  ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
  for(let i=0;i<2;i++){
    const p=((t/1400 + i*0.5) % 1);
    ctx.beginPath(); ctx.arc(0,0,r*p,0,Math.PI*2);
    ctx.strokeStyle=`rgba(0,229,255,${0.45*(1-p)})`; ctx.lineWidth=1.5;
    ctx.stroke();
  }
  const ang=(t/850)%(Math.PI*2);
  let sweep=null;
  try{ sweep=ctx.createConicGradient(ang,0,0); }catch(e){}
  if(sweep){
    sweep.addColorStop(0,'rgba(120,245,255,0.4)');
    sweep.addColorStop(0.17,'rgba(0,229,255,0)');
    sweep.addColorStop(1,'rgba(0,229,255,0)');
    ctx.fillStyle=sweep;
    ctx.beginPath(); ctx.moveTo(0,0); ctx.arc(0,0,r,0,Math.PI*2); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}
// 📦 hòm chế tạo ụ súng vẽ VECTOR (thay cho ảnh PNG cũ trông xấu) — khối lập phương giả 3D (3 mặt: trên/trái/phải),
// viền kim loại góc, đinh tán, biểu tượng 🔧 phát sáng ở giữa để rõ ràng "đây là hòm ĐỂ CHẾ TẠO ra ụ súng"
function _mcDrawCrate(cx, cy, sz, glowAmt){
  const half=sz/2, topH=sz*0.34;
  ctx.save();
  ctx.translate(cx,cy);
  if(glowAmt>0){ ctx.shadowColor='#90caf9'; ctx.shadowBlur=10*glowAmt; }
  ctx.lineJoin='round'; ctx.strokeStyle='#3e2723'; ctx.lineWidth=Math.max(1,sz*0.045);
  // mặt trên (sáng nhất) — hình thoi
  ctx.fillStyle='#a1887f';
  ctx.beginPath(); ctx.moveTo(0,-half); ctx.lineTo(half,-half+topH*0.55); ctx.lineTo(0,-half+topH); ctx.lineTo(-half,-half+topH*0.55); ctx.closePath();
  ctx.fill(); ctx.stroke();
  // mặt trái (tối vừa)
  ctx.fillStyle='#795548';
  ctx.beginPath(); ctx.moveTo(-half,-half+topH*0.55); ctx.lineTo(0,-half+topH); ctx.lineTo(0,half); ctx.lineTo(-half,half-topH*0.55); ctx.closePath();
  ctx.fill(); ctx.stroke();
  // vệt gỗ chéo trang trí trên mặt trái
  ctx.strokeStyle='rgba(62,39,35,0.4)'; ctx.lineWidth=Math.max(1,sz*0.025);
  ctx.beginPath(); ctx.moveTo(-half*0.75,-half*0.15); ctx.lineTo(-half*0.2,half*0.55); ctx.stroke();
  // mặt phải (tối nhất)
  ctx.strokeStyle='#3e2723'; ctx.lineWidth=Math.max(1,sz*0.045);
  ctx.fillStyle='#5d4037';
  ctx.beginPath(); ctx.moveTo(half,-half+topH*0.55); ctx.lineTo(0,-half+topH); ctx.lineTo(0,half); ctx.lineTo(half,half-topH*0.55); ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.strokeStyle='rgba(0,0,0,0.35)'; ctx.lineWidth=Math.max(1,sz*0.025);
  ctx.beginPath(); ctx.moveTo(half*0.2,-half*0.1); ctx.lineTo(half*0.7,half*0.5); ctx.stroke();
  // 4 đinh tán kim loại ở góc mặt trên
  ctx.fillStyle='#cfd8dc';
  [[0,-half+2],[half*0.62,-half+topH*0.55],[0,-half+topH-2],[-half*0.62,-half+topH*0.55]].forEach(([px,py])=>{
    ctx.beginPath(); ctx.arc(px,py,Math.max(0.8,sz*0.035),0,Math.PI*2); ctx.fill();
  });
  // biểu tượng cờ lê 🔧 phát sáng giữa hòm — dấu hiệu "hòm chế tạo ụ súng"
  ctx.save();
  ctx.shadowColor='#fff59d'; ctx.shadowBlur=6+4*Math.max(0,glowAmt);
  ctx.font=`${Math.round(sz*0.42)}px serif`;
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('🔧',0,half*0.08);
  ctx.restore();
  ctx.restore();
}
const MC_BASE_IMGS = {1:MECH_T1_BASE_IMG,2:MECH_T2_BASE_IMG,3:MECH_T3_BASE_IMG,4:MECH_T4_BASE_IMG,5:MECH_T5_BASE_IMG};
const MC_TOP_IMGS  = {1:MECH_T1_TOP_IMG, 2:MECH_T2_TOP_IMG, 3:MECH_T3_TOP_IMG, 4:MECH_T4_TOP_IMG, 5:MECH_T5_TOP_IMG};
function _mcMount(turretType, crateX, crateY, baseImg, atTop){
  const m = MC_BASE_MOUNT[turretType]||{x:0.5,y:0.02};
  const bw = (baseImg && baseImg.naturalWidth) ? MC_BASE_H*(baseImg.naturalWidth/baseImg.naturalHeight) : MC_BASE_H;
  const baseTop = crateY - MC_BASE_H*0.72;
  let my = baseTop+m.y*MC_BASE_H;
  // gắn ở 2 góc TRÊN arena: thân bị lật dọc để nép sát cạnh trên (xem chỗ vẽ Base), khớp xoay của nòng súng cũng phải lật theo đúng vị trí mới, không thì nòng gắn sai chỗ trên thân
  if(atTop) my = 2*crateY - my;
  return {x: crateX-bw/2+m.x*bw, y: my, baseW: bw};
}
// 🎨 "nâng đồ hoạ đỡ 2D": tô sẵn 1 lớp gradient sáng-trên/tối-dưới lên sprite súng (source-atop trên canvas riêng, không lem ra ngoài) để trông có khối hơn — cache theo type+kích thước, chỉ dựng 1 lần
const _mcShadeCache={};
function _mcShaded(img, w, h, cacheKey){
  if(!img || !img.complete || !img.naturalWidth) return img;
  const _cw=Math.max(1,Math.round(w)), _ch=Math.max(1,Math.round(h));
  const _key=cacheKey+'_'+_cw+'x'+_ch;
  const _cached=_mcShadeCache[_key];
  if(_cached) return _cached;
  const _oc=document.createElement('canvas');
  _oc.width=_cw; _oc.height=_ch;
  const _octx=_oc.getContext('2d');
  _octx.drawImage(img,0,0,_cw,_ch);
  _octx.globalCompositeOperation='source-atop';
  const _g=_octx.createLinearGradient(0,0,0,_ch);
  _g.addColorStop(0,'rgba(255,255,255,0.24)');
  _g.addColorStop(0.45,'rgba(255,255,255,0.02)');
  _g.addColorStop(1,'rgba(0,0,0,0.3)');
  _octx.fillStyle=_g;
  _octx.fillRect(0,0,_cw,_ch);
  _mcShadeCache[_key]=_oc;
  return _oc;
}
