// 🪓 RÌU LEVIATHAN: ném bám theo địch → GĂM vào người → 1s sau tự bay ngược về tay (như búa Thor) → ném tiếp.
//    Trúng lần lẻ: 100 + chậm 2s · lần chẵn: 150 + ĐÓNG BĂNG 1s (dùng khối băng của Mlem Cat). Đếm lại mỗi lần roll ra rìu.
const LV_CATCH_CD=60;   // rìu về tay → nghỉ 1s rồi mới ném tiếp
const LV_SLOW_DMG=100, LV_FREEZE_DMG=150, LV_SLOW_T=120, LV_FREEZE_T=60, LV_STUCK_T=60, LV_SPEED=10;
function _lvThrow(f,e){
  const hx=f.x+(e.x>=f.x?1:-1)*f.size*0.8, hy=f.y-f.size*0.2;
  f._lvAxe={st:'fly', x:hx, y:hy, tgt:e, a:Math.atan2(e.y-hy,e.x-hx), spin:0, t:0, trail:[], c:0};
  playSample('wg_axe_whoosh',0.7);
}
function _lvTick(f){
  const A=f._lvAxe; if(!A) return;
  if(f.dead){ f._lvAxe=null; return; }
  A.t++; A.c++; A.trail.push([A.x,A.y,A.spin]); if(A.trail.length>6) A.trail.shift();
  if(A.st==='fly'){
    const e=A.tgt;
    if(!e || e.dead || !(e.hp>0) || A.t>90){ A.st='ret'; A.t=0; return; }
    const dx=e.x-A.x, dy=e.y-A.y, d=Math.hypot(dx,dy)||1;
    A.a=Math.atan2(dy,dx); A.x+=dx/d*LV_SPEED; A.y+=dy/d*LV_SPEED; A.spin+=0.55;
    if(d < (e.size||20)*0.85){
      f._lvHitN=(f._lvHitN||0)+1; const frz=f._lvHitN%2===0;
      e.takeDamage(frz?LV_FREEZE_DMG:LV_SLOW_DMG, f);
      if(frz){ e.stun=Math.max(e.stun||0,LV_FREEZE_T); e._mlemFreezeT=LV_FREEZE_T; e._iceSeed=Math.random()*99; playSample('mlem_freeze',1.0); addShake(7,10);
        spawnParticles(e.x,e.y,'#e1f5fe',18,false,true); spawnParticles(e.x,e.y,'#4fc3f7',12,false,true); }
      else { e._maxwellSlowTimer=Math.max(e._maxwellSlowTimer||0,LV_SLOW_T); addShake(5,8); spawnParticles(e.x,e.y,'#b3e5fc',10,false,true); }
      playSample('wg_blade_impact',0.8);
      A.st='stuck'; A.t=0; A.ox=-Math.cos(A.a)*(e.size||20)*0.45; A.oy=-Math.sin(A.a)*(e.size||20)*0.45; A.frz=frz;
    }
  } else if(A.st==='stuck'){
    const e=A.tgt;
    if(e && !e.dead){ A.x=e.x+A.ox; A.y=e.y+A.oy; }
    if(A.t>=LV_STUCK_T || !e || e.dead){ A.st='ret'; A.t=0; playSample('wg_axe_whoosh',0.7); if(e&&!e.dead) spawnParticles(A.x,A.y,'#b3e5fc',6,false,true); }
  } else {   // 'ret' — bay ngược về tay, càng lúc càng nhanh
    const hx=f.x, hy=f.y-f.size*0.2, dx=hx-A.x, dy=hy-A.y, d=Math.hypot(dx,dy)||1, sp=Math.min(18,8+A.t*0.6);
    A.a=Math.atan2(dy,dx); A.x+=dx/d*sp; A.y+=dy/d*sp; A.spin-=0.6;
    if(d<f.size*0.9 || A.t>120){ f._mwAtkCD=LV_CATCH_CD;   // ⏱️ về tới tay phải chờ 1s mới ném tiếp (đỡ spam)
      f._lvAxe=null; addShake(3,5); playSample('bk_clang',0.6); spawnParticles(hx,hy,'#e1f5fe',8,false,true); }
  }
}
function _lvDraw(f){
  const A=f._lvAxe, im=MAXWELL_LEVIATHAN_IMG; if(!A || !im.naturalWidth) return;
  const h=f.size*1.7, w=h*im.naturalWidth/im.naturalHeight;
  const one=(x,y,rot,al)=>{ ctx.save(); ctx.globalAlpha=al; ctx.translate(x,y); ctx.rotate(rot); ctx.drawImage(im,-w*0.55,-h*0.3,w,h); ctx.restore(); };
  if(A.st!=='stuck'){
    ctx.save(); ctx.globalCompositeOperation='lighter';   // ❄️ vệt băng sau rìu
    A.trail.forEach((q,k)=>{ const g=ctx.createRadialGradient(q[0],q[1],0,q[0],q[1],h*0.5); g.addColorStop(0,`rgba(140,210,255,${0.06*(k+1)})`); g.addColorStop(1,'rgba(100,180,255,0)'); ctx.fillStyle=g; ctx.beginPath(); ctx.arc(q[0],q[1],h*0.5,0,Math.PI*2); ctx.fill(); });
    ctx.restore();
    A.trail.forEach((q,k)=>{ if(k<A.trail.length-1) one(q[0],q[1],q[2],0.08*(k+1)); });
    one(A.x,A.y,A.spin,1);
  } else {   // găm vào người: lưỡi chém vào phía trước, cán chĩa ra sau, rung nhẹ lúc mới găm
    const wob=A.t<10?Math.sin(A.t*1.6)*0.25*(1-A.t/10):0;
    ctx.save(); ctx.translate(A.x,A.y); ctx.rotate(A.a+wob); if(Math.cos(A.a)<0) ctx.scale(1,-1);   // mép lưỡi (bên phải ảnh) bổ vào người, cán thõng xuống
    if(A.frz){ ctx.globalCompositeOperation='lighter'; const g=ctx.createRadialGradient(0,0,0,0,0,h*0.6); g.addColorStop(0,'rgba(180,230,255,0.5)'); g.addColorStop(1,'rgba(120,200,255,0)'); ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,h*0.6,0,Math.PI*2); ctx.fill(); ctx.globalCompositeOperation='source-over'; }
    ctx.drawImage(im,-w*0.8,-h*0.13,w,h); ctx.restore();   // đặt mép lưỡi (≈95% bề ngang, 13% chiều cao ảnh) lún vào thân
  }
}
const MAXWELL_DEATHNOTE_IMG = new Image(); MAXWELL_DEATHNOTE_IMG.src = 'assets/img/maxwell/MAXWELL_DEATHNOTE_IMG.webp';   // 📓 sổ Death Note (bìa đen chữ gothic)
try{ const _dnFont=new FontFace('DNScript','url(assets/fonts/PinyonScript.ttf)'); _dnFont.load().then(ff=>document.fonts.add(ff)).catch(()=>{}); }catch(e){}   // ✒️ chữ viết tay uốn lượn (Pinyon Script, OFL)
// 📓 DEATH NOTE: mở sổ → tên meme địch được VIẾT dần trên đầu nó trong 2s (chữ uốn lượn phát sáng đỏ, ngòi bút + tia lửa
//    chạy theo nét) → viết xong: cười ác + chớp đỏ → địch bị ghi tên VĨNH VIỄN: mất 25 máu mỗi giây tới hết trận,
//    trên đầu lơ lửng cuốn sổ đen toả quầng đỏ. Mỗi địch chỉ bị ghi 1 lần (ghi hết rồi thì không roll ra sổ nữa).
const DN_WRITE_T=120, DN_DMG=25;
function _dnTargets(f){ return fighters.filter(u=>u.team!==f.team && !u.dead && !u._dnMark); }
function _dnName(u){ return _nameParts(u.name||'').main || (u.name||'???'); }
function _dnStart(f){
  const pool=_dnTargets(f); if(!pool.length) return false;
  const e=f.enemy, tg=(e && pool.includes(e)) ? e : pool.sort((a,b)=>Math.hypot(a.x-f.x,a.y-f.y)-Math.hypot(b.x-f.x,b.y-f.y))[0];
  f._dnW={tgt:tg, t:0, sp:[]};
  _dnSfxStop(f); const a=AUDIO_SAMPLES['dn_theme']; if(a){ try{ const c=a.cloneNode(); c.volume=1; _mixRoute(c); c.play().catch(()=>{}); f._dnSfx=c; }catch(e){} }   // 🎵 rút được sổ → nhạc Death Note
  return true; }
function _dnSfxStop(f){ if(f && f._dnSfx){ _stopLoopAudio(f._dnSfx); f._dnSfx=null; } }
function _dnEnd(f){ _dnSfxStop(f); f._dnW=null; f._mwItem=null; f._mwPhase='postuse_wait'; f._mwPostUseTimer=30; }
function _dnTick(f){
  const W2=f._dnW; if(!W2) return;
  const tg=W2.tgt; if(!tg || tg.dead){ _dnEnd(f); return; }
  W2.t++;
  if(W2.t>=DN_WRITE_T){   // ✒️ viết xong → ghi tên vĩnh viễn
    tg._dnMark={src:f, t0:performance.now(), name:_dnName(tg)}; tg._dnT=0;
    addShake(6,12); spawnParticles(tg.x,tg.y,'#b71c1c',16,false,true);
    floatTexts.push({x:tg.x,y:tg.y-tg.size-30,text:'📓 NAME WRITTEN',color:'#ff1744',life:60,big:true});
    _dnEnd(f); }
}
// toạ độ dòng chữ trên đầu địch
function _dnTextPos(u){ return [u.x, u.y-u.size*1.1-58]; }
function _dnDrawText(txt,x,y,px,k,al,flash){
  ctx.save(); ctx.font=`${px}px DNScript, "Apple Chancery", cursive`; ctx.textAlign='left'; ctx.textBaseline='middle';
  const w=ctx.measureText(txt).width, x0=x-w/2;
  ctx.translate(x,y); ctx.rotate(-0.06); ctx.translate(-x,-y);
  ctx.beginPath(); ctx.rect(x0-px, y-px*1.6, (w+px*1.2)*k+px*0.4, px*3.2); ctx.clip();   // lộ dần từ trái sang phải = đang viết
  ctx.globalAlpha=al;
  ctx.shadowColor=flash?'#ffffff':'#ff1744'; ctx.shadowBlur=px*(flash?0.9:0.5);
  ctx.lineJoin='round'; ctx.lineWidth=Math.max(2,px*0.13); ctx.strokeStyle='#1a0000'; ctx.strokeText(txt,x0,y);
  const g=ctx.createLinearGradient(0,y-px*0.6,0,y+px*0.6); g.addColorStop(0,flash?'#ffffff':'#ff8a80'); g.addColorStop(0.5,'#ff1744'); g.addColorStop(1,'#7f0000');
  ctx.fillStyle=g; ctx.fillText(txt,x0,y);
  // nét gạch dưới uốn lượn (swash) chạy theo chữ
  ctx.shadowBlur=px*0.35; ctx.strokeStyle='rgba(255,40,60,0.85)'; ctx.lineWidth=Math.max(1.2,px*0.06); ctx.beginPath();
  for(let i=0;i<=30;i++){ const u=i/30, xx=x0-px*0.3+(w+px*0.6)*u, yy=y+px*0.62+Math.sin(u*Math.PI*3)*px*0.12-Math.sin(u*Math.PI)*px*0.1; i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy); }
  ctx.stroke(); ctx.restore();
  return [x0+w*k, y]; }
// ✒️ đang viết (trên đầu Maxwell): chữ hiện dần + ngòi bút lông vũ ở đầu nét + tia lửa đỏ
function _dnDrawWriting(f){
  const W2=f._dnW, tg=W2&&W2.tgt; if(!tg || tg.dead) return;
  const k=Math.min(1,W2.t/(DN_WRITE_T*0.92)), [x,y]=_dnTextPos(f), name=_dnName(tg), px=Math.max(22,Math.min(40,f.size*0.85));   // ✒️ chữ hiện trên đầu MAXWELL (người đang viết)
  // vòng phù chú mờ xoay sau chữ
  ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.translate(x,y); ctx.rotate(performance.now()/900); ctx.strokeStyle=`rgba(255,30,60,${0.18+0.1*Math.sin(W2.t*0.2)})`; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.arc(0,0,px*1.7,0,Math.PI*2); ctx.stroke(); ctx.beginPath(); ctx.arc(0,0,px*1.45,0,Math.PI*2); ctx.stroke();
  for(let i=0;i<12;i++){ const a=i/12*Math.PI*2; ctx.beginPath(); ctx.moveTo(Math.cos(a)*px*1.45,Math.sin(a)*px*1.45); ctx.lineTo(Math.cos(a+0.2)*px*1.7,Math.sin(a+0.2)*px*1.7); ctx.stroke(); }
  ctx.restore();
  const [tx,ty]=_dnDrawText(name,x,y,px,k,1,false);
  if(k<1){
    const bob=Math.sin(W2.t*0.9)*px*0.18;
    if(Math.random()<0.6) particles.push({x:tx,y:ty+bob,vx:(Math.random()-0.5)*1.2,vy:-(0.3+Math.random()*1),color:Math.random()<0.5?'#ff1744':'#ffcdd2',gravity:0.02,life:18,maxLife:18,size:1.2+Math.random()*1.5});
    ctx.save(); ctx.translate(tx,ty+bob); ctx.rotate(-0.7);   // 🪶 bút lông vũ
    ctx.fillStyle='#f5f5f5'; ctx.strokeStyle='#212121'; ctx.lineWidth=1.2;
    ctx.beginPath(); ctx.moveTo(0,0); ctx.quadraticCurveTo(px*0.25,-px*0.6,px*0.12,-px*1.5); ctx.quadraticCurveTo(-px*0.3,-px*0.7,0,0); ctx.fill(); ctx.stroke();
    ctx.strokeStyle='#9e9e9e'; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(px*0.1,-px*1.4); ctx.stroke();
    ctx.fillStyle='#ff1744'; ctx.beginPath(); ctx.arc(0,0,2.2,0,Math.PI*2); ctx.fill();
    ctx.restore(); }
}
// 📓 dấu bị ghi tên: lúc vừa viết xong tên loé trắng rồi bay lên tan · sau đó cuốn sổ đen nhỏ lơ lửng toả quầng đỏ trên đầu
function _dnDrawMark(u){
  const M=u._dnMark, age=performance.now()-M.t0, [x,y]=_dnTextPos(u), px=Math.max(22,Math.min(40,u.size*0.85));
  if(age<700 && M.src && !M.src.dead){ const q=age/700, [sx,sy]=_dnTextPos(M.src), spx=Math.max(22,Math.min(40,M.src.size*0.85)); _dnDrawText(M.name,sx,sy-q*spx*0.8,spx*(1+0.15*Math.sin(q*Math.PI)),1,1-q,q<0.35); }   // viết xong: tên trên đầu Maxwell loé trắng rồi tan
  const im=MAXWELL_DEATHNOTE_IMG; if(!im.naturalWidth) return;
  const a=Math.min(1,age/400), bh=Math.max(16,u.size*0.5), bw=bh*im.naturalWidth/im.naturalHeight, by=y+px*0.15+Math.sin(performance.now()/350)*3;
  ctx.save(); ctx.globalAlpha=a;
  ctx.globalCompositeOperation='lighter'; const g=ctx.createRadialGradient(x,by,0,x,by,bh*1.1); g.addColorStop(0,`rgba(255,20,40,${0.45+0.2*Math.sin(performance.now()/200)})`); g.addColorStop(1,'rgba(255,0,0,0)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,by,bh*1.1,0,Math.PI*2); ctx.fill(); ctx.globalCompositeOperation='source-over';
  ctx.translate(x,by); ctx.rotate(Math.sin(performance.now()/500)*0.12); ctx.drawImage(im,-bw/2,-bh/2,bw,bh);
  ctx.restore();
  if(Math.random()<0.04) particles.push({x:x+(Math.random()-0.5)*bw*0.6,y:by+bh*0.5,vx:0,vy:0.6,color:'#b71c1c',gravity:0.05,life:26,maxLife:26,size:1.6});   // giọt mực đỏ nhỏ xuống
}
// 🔫 tiếng minigun Maxwell: file mc_sfx_machinegun vốn đã là 1 TRÀNG liên thanh 1.5s — phát chồng 1 bản mỗi viên (0.15s/viên)
//    làm ~10 bản đè nhau, to gấp mấy lần tiếng thường. Giờ chỉ giữ ĐÚNG 1 bản lặp suốt lúc đang bắn, ngừng bắn 0.25s là tắt.
function _mgSfxKeep(f){ f._mgLast=performance.now(); f._mgLastTick=tick;
  if(!f._mgSfx){ const a=AUDIO_SAMPLES['mc_sfx_machinegun']; if(a){ try{ const c=a.cloneNode(); c.loop=true; c.volume=0.6; _mixRoute(c); c.play().catch(()=>{}); f._mgSfx=c; }catch(e){} } } }
// ngừng bắn >16 nhịp game (hoặc trận đứng yên >0.7s) → tắt
function _mgSfxCheck(f){ if(f._mgSfx && (f.dead || tick-(f._mgLastTick||0)>16 || performance.now()-(f._mgLast||0)>700)){ _stopLoopAudio(f._mgSfx); f._mgSfx=null; } }
