function _rmWhite(img,thr){
  const oc=document.createElement('canvas');
  oc.width=img.naturalWidth;oc.height=img.naturalHeight;
  const ox=oc.getContext('2d');ox.drawImage(img,0,0);
  const id=ox.getImageData(0,0,oc.width,oc.height),d=id.data;
  for(let i=0;i<d.length;i+=4){if(d[i]>thr&&d[i+1]>thr&&d[i+2]>thr)d[i+3]=0;}
  ox.putImageData(id,0,0);img._proc=oc;
}
