SUS_IMP_MELEE_IMG.addEventListener('load',()=>_rmWhite(SUS_IMP_MELEE_IMG,245));const IDLE_ANIMS = [
  { key:'none',    label:'None',    fn:(t,s)=>({ox:0,oy:0,sx:1,sy:1,r:0}) },
  { key:'bounce',  label:'Bounce',  fn:(t,s)=>({ox:0,oy:Math.sin(t/18)*6,sx:1,sy:1,r:0}) },
  { key:'float',   label:'Float',   fn:(t,s)=>({ox:0,oy:Math.sin(t/28)*4,sx:1,sy:1,r:0}) },
  { key:'pulse',   label:'Pulse',   fn:(t,s)=>{ const p=1+Math.sin(t/20)*0.08; return {ox:0,oy:0,sx:p,sy:p,r:0}; }},
  { key:'breathe', label:'Breathe', fn:(t,s)=>{ const p=1+Math.sin(t/40)*0.06; return {ox:0,oy:0,sx:p,sy:1/p,r:0}; }},
  { key:'sway',    label:'Sway',    fn:(t,s)=>({ox:0,oy:0,sx:1,sy:1,r:Math.sin(t/25)*0.12}) },
  { key:'wobble',  label:'Wobble',  fn:(t,s)=>({ox:Math.sin(t/12)*3,oy:0,sx:1,sy:1,r:Math.sin(t/12)*0.06}) },
  { key:'spin',    label:'Spin',    fn:(t,s)=>({ox:0,oy:0,sx:1,sy:1,r:t*0.04}) },
  { key:'jelly',   label:'Jelly',   fn:(t,s)=>{ const p=1+Math.sin(t/14)*0.12; return {ox:0,oy:0,sx:p,sy:2-p,r:0}; }},
  { key:'vibrate', label:'Vibrate', fn:(t,s)=>({ox:(Math.random()-0.5)*4,oy:(Math.random()-0.5)*4,sx:1,sy:1,r:0}) },
  { key:'lean',    label:'Lean',    fn:(t,s)=>({ox:0,oy:0,sx:1,sy:1,r:Math.sin(t/35)*0.18}) },
  { key:'dizzy',   label:'Dizzy',   fn:(t,s)=>({ox:Math.cos(t/15)*5,oy:Math.sin(t/15)*3,sx:1,sy:1,r:Math.sin(t/20)*0.15}) },
];

let selectedAnimKey = 'bounce';
let selectedFacing = 'right'; // default: image faces right

function setFacing(dir){
  selectedFacing = dir;
  document.getElementById('facingLeftBtn').style.cssText='flex:1;padding:6px;border-radius:6px;cursor:pointer;font-size:0.65rem;'+(dir==='left'?'border:2px solid #f0c040;background:#1a1500;color:#f0c040;':'border:2px solid #2a2a40;background:#0a0a18;color:#888;');
  document.getElementById('facingRightBtn').style.cssText='flex:1;padding:6px;border-radius:6px;cursor:pointer;font-size:0.65rem;'+(dir==='right'?'border:2px solid #f0c040;background:#1a1500;color:#f0c040;':'border:2px solid #2a2a40;background:#0a0a18;color:#888;');
  document.getElementById('facingLeftBtn').textContent='← Nhìn Trái'+(dir==='left'?' ✓':'');
  document.getElementById('facingRightBtn').textContent='→ Nhìn Phải'+(dir==='right'?' ✓':'');
}
let animPreviewFrames = {};

function buildAnimPicker(){
  const grid = document.getElementById('animGrid');
  if(!grid) return;
  grid.innerHTML='';
  IDLE_ANIMS.forEach(anim=>{
    const tile = document.createElement('div');
    tile.className='anim-tile'+(selectedAnimKey===anim.key?' selected':'');
    tile.dataset.key=anim.key;

    // mini canvas preview
    const cv=document.createElement('canvas');
    cv.width=48; cv.height=48;
    tile.appendChild(cv);

    const lbl=document.createElement('span');
    lbl.textContent=anim.label;
    tile.appendChild(lbl);

    tile.onclick=()=>{
      selectedAnimKey=anim.key;
      document.querySelectorAll('.anim-tile').forEach(t=>t.classList.remove('selected'));
      tile.classList.add('selected');
    };
    grid.appendChild(tile);

    // animate preview
    let tf=0;
    function previewLoop(){
      if(!document.body.contains(cv) || cv.offsetParent===null) return; // gỡ khỏi DOM hoặc modal ẨN → dừng hẳn (mở lại buildAnimPicker dựng mới)
      tf++;
      const c=cv.getContext('2d');
      c.clearRect(0,0,48,48);
      const {ox,oy,sx,sy,r}=anim.fn(tf,20);
      c.save();
      c.translate(24+ox,24+oy); c.rotate(r); c.scale(sx,sy);
      c.font='28px serif'; c.textAlign='center'; c.textBaseline='middle';
      c.fillText('😊',0,0);
      c.restore();
      requestAnimationFrame(previewLoop);
    }
    previewLoop();
  });
}


let GAME_SPEED = 1.2/1.1; // tổng GAME_SPEED×TIME_SCALE = +20% tốc độ toàn game (giảm từ +32%) — đỡ tốn CPU vì bớt số tick logic chạy mỗi frame
