// ===================== DEBUFF VFX (dùng chung toàn bộ char) =====================
const DEBUFF_TYPES = [
  { key:'poison', label:'Độc',        emoji:'☠️', color:'#76ff03' },
  { key:'stun',   label:'Choáng/Stun',emoji:'💫', color:'#f59e0b' },
  { key:'freeze', label:'Đóng băng',  emoji:'❄️', color:'#40c4ff' },
  { key:'slow',   label:'Làm chậm',   emoji:'🐌', color:'#ffcc80' },
  { key:'bleed',  label:'Chảy máu',   emoji:'🩸', color:'#e53935' },
  { key:'burn',   label:'Cháy',       emoji:'🔥', color:'#ff7043' },
];
let debuffVfx = {};        // key -> dataURL
const debuffVfxImgs = {};  // key -> Image (đã nhận diện lưới)
function loadDebuffVfx(){
  try{ const raw=storeGet('cbs_debuff_vfx'); if(raw) debuffVfx=JSON.parse(raw)||{}; }catch(e){ debuffVfx={}; }
  for(const t of DEBUFF_TYPES){
    const url=debuffVfx[t.key];
    if(url){
      const img=new Image();
      img.onload=()=>{ const det=_detectVfxGrid(img); if(det){img._cols=det.cols;img._rows=det.rows;img._frames=det.frames;} else {img._cols=Math.max(1,Math.round(img.naturalWidth/(img.naturalHeight||1)));img._rows=1;img._frames=img._cols;} img._additive=_isVfxDarkBg(img); debuffVfxImgs[t.key]=img; };
      img.src=url;
    } else { debuffVfxImgs[t.key]=null; }
  }
}
// vẽ 1 sprite-sheet lặp theo thời gian (đồng bộ) tại (x,y)
// ❄️ VFX SLOW (vẽ tay, thay hẳn VFX cũ): NHIỀU bông tuyết li ti bám quanh người con bị làm chậm — hình bông tuyết
// 6 cánh có nhánh (theo mẫu VFX cũ). Bông tuyết bake sẵn 1 ảnh (có quầng sáng xanh), mỗi con dính slow chỉ vẽ lại
// ảnh đó ~16 lần ở các điểm cố định quanh mép thân (theo seed riêng nên nhìn như tuyết BÁM, không chạy lung tung),
// mỗi bông tự xoay chậm + lấp lánh + trôi nhẹ.
let _snowSpriteCv=null;
function _snowSprite(){
  if(_snowSpriteCv) return _snowSpriteCv;
  const S=64, c=document.createElement('canvas'); c.width=c.height=S;
  const g=c.getContext('2d'); g.translate(S/2,S/2);
  g.lineCap='round'; g.shadowColor='#7fd8ff'; g.shadowBlur=6;
  for(const [col,lw] of [['rgba(150,220,255,0.9)',4.2],['#ffffff',2.2]]){
    g.strokeStyle=col; g.lineWidth=lw;
    for(let i=0;i<6;i++){
      g.save(); g.rotate(i*Math.PI/3);
      g.beginPath(); g.moveTo(0,0); g.lineTo(0,-24); g.stroke();                              // cánh chính
      for(const [y,l] of [[-9,6],[-16,5]]){                                                   // 2 cặp nhánh chữ V
        g.beginPath(); g.moveTo(0,y); g.lineTo(-l,y-l); g.moveTo(0,y); g.lineTo(l,y-l); g.stroke();
      }
      g.restore();
    }
  }
  g.shadowBlur=0; g.fillStyle='#ffffff'; g.beginPath(); g.arc(0,0,3,0,Math.PI*2); g.fill();  // tâm
  _snowSpriteCv=c; return c;
}
// ai đang dính BẤT KỲ kiểu làm chậm nào (dùng chung cho bông tuyết + lớp xanh lam nhẹ trên người)
function _isSlowedU(u){ return (u._iceSlowTimer||0)>0 || (u._slowTimer||0)>0 || (u._maxwellSlowTimer||0)>0 || (u._droolSlowTimer||0)>0 || (u._cvSlowTimer||0)>0 || (u._pakistanSlowTimer||0)>0 || (u._sgSlowTimer||0)>0 || (u._mlemStacks||0)>0; }
// 🧊 bản tô xanh lam của avatar (cache 1 lần/ảnh) — phủ RẤT NHẸ lên người lúc bị làm chậm
function _slowTint(img){
  if(img._slowTint) return img._slowTint;
  const src=_stickerMask(img);
  const c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const g=c.getContext('2d'); g.drawImage(src,0,0);
  g.globalCompositeOperation='source-atop'; g.fillStyle='#6fb8ff'; g.fillRect(0,0,c.width,c.height);
  img._slowTint=c; return c;
}
// ❄️ bông tuyết BÁM trên người: mỗi bông nằm yên 1 chỗ ngẫu nhiên trên/quanh thân (không xoay, không trôi),
// tự hiện lên – lấp lánh ngẫu nhiên – tắt đi, rồi mọc lại ở chỗ ngẫu nhiên khác. Toạ độ tính theo người nên bám theo khi di chuyển.
// ❄️ chùm bông tuyết bung ra 1 lần (vd trúng bóng tuyết) — bông tuyết cùng hình với VFX slow
let snowBursts=[];
function _snowBurst(x,y,size){
  for(let i=0;i<9;i++){ const a=Math.random()*Math.PI*2, sp=0.8+Math.random()*1.8;
    snowBursts.push({x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,d:size*(0.12+Math.random()*0.14),t:0,life:22+Math.random()*14,rot:Math.random()*6.28,vr:(Math.random()-0.5)*0.2}); }
}
function _drawSnowBursts(){
  if(!snowBursts.length) return;
  const sp=_snowSprite(); ctx.save();
  for(let i=snowBursts.length-1;i>=0;i--){
    const q=snowBursts[i]; q.t++; if(q.t>=q.life){ snowBursts.splice(i,1); continue; }
    q.x+=q.vx; q.y+=q.vy; q.vx*=0.9; q.vy*=0.9; q.rot+=q.vr;
    ctx.globalAlpha=1-q.t/q.life;
    ctx.save(); ctx.translate(q.x,q.y); ctx.rotate(q.rot); ctx.drawImage(sp,-q.d/2,-q.d/2,q.d,q.d); ctx.restore();
  }
  ctx.restore();
}
// 🌧️ TRẦM CẢM: mây mưa riêng trên đầu — ai nhìn cũng hiểu "đang buồn". Càng nhiều stack mây càng đen, mưa càng
// nặng hạt; từ stack 3 thỉnh thoảng loé sét trong mây. Toàn hình khối + nét vẽ, không gradient → rẻ.
function _drawDepressCloud(u,aO,stO){
  const s=u.size, st=Math.min(4,stO!=null?stO:(u._emotionalStacks||0)), tm=Date.now()/1000;
  const a=aO!=null?aO:Math.min(1,(u._depressDebuffTimer||0)/20);                       // hiện lên / tan đi nhẹ nhàng
  const cx=u.x+Math.sin(tm*1.3)*s*0.05, cy=u.y-s*1.62+Math.sin(tm*2)*s*0.03, w=s*0.95;
  const shade=[118,100,84,70,58][st];                                     // mây đen dần theo stack
  ctx.save();
  // 💧 mưa: vệt mảnh rơi từ đáy mây xuống tới đỉnh đầu
  const nDrop=8+st*4, top=cy+w*0.28, bot=u.y-s*0.55;
  ctx.strokeStyle=`rgba(120,170,230,${0.75*a})`; ctx.lineWidth=Math.max(1,s*0.028); ctx.lineCap='round';
  ctx.beginPath();
  for(let i=0;i<nDrop;i++){
    const fx=cx+((i+0.5)/nDrop-0.5)*w*1.5, sp=0.9+((i*37)%10)/10;
    const k=((tm*1.6*sp)+(i*0.37))%1, y=top+(bot-top)*k, len=s*0.14;
    ctx.moveTo(fx-len*0.12,y); ctx.lineTo(fx,y+len);
  }
  ctx.globalAlpha=1; ctx.stroke();
  // ☁️ thân mây: 5 khối tròn chồng lên nhau + lớp bóng dưới đáy
  ctx.globalAlpha=0.94*a;
  const puff=(x,y,r,c)=>{ ctx.fillStyle=c; ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill(); };
  const c1=`rgb(${shade},${shade+8},${shade+20})`, c2=`rgb(${shade-18},${shade-12},${shade})`;
  puff(cx-w*0.42,cy+w*0.08,w*0.3,c2); puff(cx+w*0.44,cy+w*0.09,w*0.28,c2);
  puff(cx-w*0.18,cy-w*0.1,w*0.38,c1); puff(cx+w*0.2,cy-w*0.06,w*0.34,c1); puff(cx,cy+w*0.1,w*0.36,c1);
  ctx.fillStyle=c2; ctx.fillRect(cx-w*0.62,cy+w*0.08,w*1.24,w*0.26);   // đáy mây phẳng
  // ⚡ sét loé trong mây (từ stack 3)
  if(st>=3 && Math.sin(tm*7.3)>0.93){
    ctx.strokeStyle='rgba(255,245,170,0.95)'; ctx.lineWidth=Math.max(1.2,s*0.04);
    ctx.beginPath(); ctx.moveTo(cx+w*0.05,cy+w*0.1); ctx.lineTo(cx-w*0.08,cy+w*0.3); ctx.lineTo(cx+w*0.06,cy+w*0.3); ctx.lineTo(cx-w*0.1,cy+w*0.55); ctx.stroke();
  }
  ctx.restore();
}
// 🔋 thanh stack trầm cảm: CỤC PIN "năng lượng sống" 5 vạch dưới chân — mỗi stack tụt 1 vạch. Pin đổi màu theo
// mức còn lại (xanh → vàng → cam → đỏ); còn đúng 1 vạch (sắp nổ EMOTIONAL DAMAGE) thì vạch đỏ nhấp nháy + pin run.
function _drawTearMeter(u,stO){
  const st=Math.min(5,stO!=null?stO:(u._emotionalStacks||0)), left=5-st, s=u.size, tm=Date.now()/1000;
  const bw=s*1.0, bh=s*0.36, x0=u.x-bw/2, y0=u.y+s+s*0.18, warn=left<=1;
  const jx=warn?Math.sin(tm*40)*s*0.015:0, jy=warn?Math.cos(tm*37)*s*0.012:0;
  const col = left>=4 ? '#4caf50' : left===3 ? '#fdd835' : left===2 ? '#ff9800' : '#f44336';
  ctx.save(); ctx.translate(jx,jy);
  const r=bh*0.22, lw=Math.max(1.5,s*0.04);
  // vỏ pin
  ctx.fillStyle='rgba(15,18,24,0.72)';
  ctx.beginPath(); ctx.roundRect ? ctx.roundRect(x0,y0,bw,bh,r) : ctx.rect(x0,y0,bw,bh); ctx.fill();
  ctx.lineWidth=lw; ctx.strokeStyle='rgba(235,240,245,0.95)'; ctx.stroke();
  ctx.fillStyle='rgba(235,240,245,0.95)'; ctx.fillRect(x0+bw, y0+bh*0.3, bw*0.07, bh*0.4);   // núm pin
  // 5 vạch: còn lại bao nhiêu thì tô bấy nhiêu (từ trái sang)
  const pad=bw*0.06, gap=bw*0.03, cw=(bw-pad*2-gap*4)/5, ch=bh-pad*1.6;
  for(let i=0;i<5;i++){
    const on=i<left;
    if(on && warn && Math.sin(tm*12)<0) continue;                      // vạch cuối nhấp nháy
    ctx.fillStyle= on ? col : 'rgba(255,255,255,0.08)';
    ctx.fillRect(x0+pad+i*(cw+gap), y0+pad*0.8, cw, ch);
  }
  ctx.restore();
}
// 🌫️ người đang trầm cảm: ám một lớp xám xanh u ám nhẹ (cache 1 lần/ảnh)
// 👻 bị Giám Ngục hút hồn: bản TÁI NHỢT (mất 60% màu + sáng lên chút) dựng sẵn 1 lần — phủ lên sprite thay cho ctx.filter (nặng)
function _soulPale(img){
  if(img._soulPale) return img._soulPale;
  const src=_stickerMask(img);
  const c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const g=c.getContext('2d'); g.drawImage(src,0,0);
  g.globalCompositeOperation='saturation'; g.fillStyle='rgba(128,128,128,0.6)'; g.fillRect(0,0,c.width,c.height);
  g.globalCompositeOperation='screen'; g.fillStyle='rgb(22,22,22)'; g.fillRect(0,0,c.width,c.height);
  g.globalCompositeOperation='destination-in'; g.drawImage(src,0,0);
  img._soulPale=c; return c;
}
function _gloomTint(img){
  if(img._gloomTint) return img._gloomTint;
  const src=_stickerMask(img);
  const c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const g=c.getContext('2d'); g.drawImage(src,0,0);
  g.globalCompositeOperation='source-atop'; g.fillStyle='#3d4a5c'; g.fillRect(0,0,c.width,c.height);
  img._gloomTint=c; return c;
}
function _drawSlowFrost(u){
  const sp=_snowSprite(), s=u.size;
  if(!u._snowF) u._snowF=[];
  const F=u._snowF;
  const spawn=q=>{ const a=Math.random()*Math.PI*2, r=Math.sqrt(Math.random())*s*1.05;
    q.dx=Math.cos(a)*r; q.dy=Math.sin(a)*r*1.05; q.d=s*(0.11+Math.random()*0.14);
    q.t=0; q.life=45+Math.random()*70; q.tw=0.08+Math.random()*0.14; q.ph=Math.random()*6.28; q.rot=Math.random()*Math.PI; return q; };
  while(F.length<16){ const q=spawn({}); q.t=Math.random()*q.life; F.push(q); }   // lần đầu: rải đều tuổi cho khỏi hiện cùng lúc
  ctx.save();
  for(const q of F){
    q.t++; if(q.t>=q.life) spawn(q);
    const k=q.t/q.life, fade=Math.min(1,k*6)*Math.min(1,(1-k)*6);              // hiện lên / tắt đi nhanh
    const tw=0.45+0.55*Math.max(0,Math.sin(q.t*q.tw+q.ph));                     // lấp lánh ngẫu nhiên từng bông
    ctx.globalAlpha=fade*tw;
    ctx.save(); ctx.translate(u.x+q.dx, u.y+q.dy); ctx.rotate(q.rot);
    ctx.drawImage(sp,-q.d/2,-q.d/2,q.d,q.d);
    ctx.restore();
  }
  ctx.restore();
}
function _drawDebuffFX(img, x, y, sizePx){
  if(!img||!img.complete||!img.naturalWidth) return;
  const cols=img._cols||1, rows=img._rows||1, frames=img._frames||(cols*rows);
  const fw=img.naturalWidth/cols, fh=img.naturalHeight/rows;
  const fr=Math.floor(Date.now()/55) % frames; // ~18fps loop
  const sx=(fr%cols)*fw, sy=Math.floor(fr/cols)*fh;
  const sc=sizePx/fw, dW=fw*sc, dH=fh*sc;
  ctx.save(); ctx.translate(x,y);
  if(img._additive) ctx.globalCompositeOperation='lighter';
  ctx.drawImage(img, sx,sy, fw,fh, -dW/2,-dH/2, dW,dH);
  ctx.restore();
}
// loadDebuffVfx() — dời vào _boot()

// ===================== 🎬 VFX LIBRARY (thư viện hiệu ứng, preview chạy thật) =====================
let vfxLibrary = [];        // [{id, name, url, grid:'', additive:null|true|false}]
const vfxLibImgs = {};      // id -> Image (đã gắn _cols/_rows/_frames/_additive)
const _vfxLibState = {};    // id -> {frame, ft, t} trạng thái animation preview
let _vfxLibRAF = null;
function saveVfxLib(){ _vfxNameCacheClear(); try{ storeSet('cbs_vfx_library', JSON.stringify(vfxLibrary)); }catch(e){} }
function _buildVfxLibImg(e){
  const img = new Image();
  img.onload = ()=>{
    let cols, rows, frames;
    const g = (e.grid||'').trim().toLowerCase().replace('×','x');
    const m = g.match(/^(\d+)(?:x(\d+))?$/);
    if(m){ cols=+m[1]; rows=m[2]?+m[2]:1; frames=cols*rows; }
    else {
      const det=_detectVfxGrid(img);
      if(det){ cols=det.cols; rows=det.rows; frames=det.frames; }
      else { cols=Math.max(1,Math.round(img.naturalWidth/(img.naturalHeight||1))); rows=1; frames=cols; }
    }
    img._cols=cols; img._rows=rows; img._frames=frames;
    img._additiveAuto=_isVfxDarkBg(img);
    img._additive=(e.additive==null)?img._additiveAuto:!!e.additive;
    img._flip=(e.flip==null)?true:!!e.flip; // hướng sprite khi bay theo vận tốc: true=lật 180° (mặc định, khớp VFX cũ), false=giữ nguyên hướng gốc
    _vfxLibState[e.id]={frame:0,ft:0,t:0};
    const meta=document.getElementById('vfxmeta_'+e.id);
    if(meta) meta.textContent=cols+'×'+rows+' · '+frames+'f · '+(img._additive?'✨ glow':'normal');
    // 🩹 VFX nền đen kiểu glow nhưng KHÔNG có alpha trong suốt thật (ảnh đục hoàn toàn) → tự vá: alpha = độ sáng
    // (đây là nguyên nhân gây "viền vuông đen" khi vẽ VFX loại này lên nền sáng — vá 1 lần, tự áp dụng lại mỗi lần mở game)
    if(img._additiveAuto && _isVfxFullyOpaque(img)){
      _fixOpaqueVfxAlpha(img, (fixed)=>{
        fixed._cols=cols; fixed._rows=rows; fixed._frames=frames;
        fixed._additiveAuto=true; fixed._additive=(e.additive==null)?true:!!e.additive;
        fixed._flip=img._flip;
        vfxLibImgs[e.id]=fixed; // thay ảnh đang dùng bằng bản đã vá alpha
        _vfxLibState[e.id]={frame:0,ft:0,t:0};
      });
    }
  };
  img.src=e.url;
  vfxLibImgs[e.id]=img;
}
// dò xem ảnh có ĐỤC HOÀN TOÀN không (alpha~255 khắp nơi) — dấu hiệu ảnh "nền đen" không có transparency thật,
// chỉ trông giống trong suốt vì màu quá tối, sẽ lộ viền vuông khi vẽ additive/normal lên nền sáng
function _isVfxFullyOpaque(img){
  try{
    const w=img.naturalWidth, h=img.naturalHeight;
    const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
    const c=cv.getContext('2d'); c.drawImage(img,0,0);
    const d=c.getImageData(0,0,w,h).data;
    const stepX=Math.max(1,Math.floor(w/60)), stepY=Math.max(1,Math.floor(h/60));
    let checked=0, opaque=0;
    for(let y=0;y<h;y+=stepY){ for(let x=0;x<w;x+=stepX){ checked++; if(d[(y*w+x)*4+3]>=250) opaque++; } }
    return checked>0 && (opaque/checked)>0.97;
  }catch(e){ return false; }
}
// vá: chuyển ảnh "nền đen đục" thành có alpha thật = độ sáng (RGB giữ nguyên) — kỹ thuật chuẩn cho VFX glow
function _fixOpaqueVfxAlpha(img, cb){
  try{
    const w=img.naturalWidth, h=img.naturalHeight;
    const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
    const c=cv.getContext('2d'); c.drawImage(img,0,0);
    const imgData=c.getImageData(0,0,w,h);
    const d=imgData.data;
    for(let i=0;i<d.length;i+=4){ d[i+3]=Math.max(d[i],d[i+1],d[i+2]); }
    c.putImageData(imgData,0,0);
    const fixed=new Image();
    fixed.onload=()=>cb(fixed);
    fixed.src=cv.toDataURL('image/png');
  }catch(e){ /* lỗi (VD ảnh dính CORS) → bỏ qua, giữ nguyên ảnh gốc */ }
}
