let _vfxLibReturnScreen='selectScreen';
function openVfxLib(returnScreen){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi
  _vfxLibReturnScreen = returnScreen || 'selectScreen';
  document.getElementById(_vfxLibReturnScreen).classList.remove('active');
  document.getElementById('vfxLibScreen').classList.add('active');
  renderVfxLib();
  if(!_vfxLibRAF) _vfxLibRAF=requestAnimationFrame(_vfxLibTick);
}
function closeVfxLib(){
  if(_vfxLibRAF){ cancelAnimationFrame(_vfxLibRAF); _vfxLibRAF=null; }
  document.getElementById('vfxLibScreen').classList.remove('active');
  document.getElementById(_vfxLibReturnScreen).classList.add('active');
}


// 🎞️ GIF → spritesheet: tự đọc thẳng nhị phân file GIF (GIF87a/89a) + tự giải nén LZW để lấy
// ĐÚNG từng khung gốc — không phụ thuộc trình duyệt có chịu chạy animation cho ảnh ẩn hay không
// (cách cũ dựa vào browser tự phát rồi "chụp" lại canvas, không ổn định nên đổi qua parse tay).
function _lzwDecodeGif(bytes, minCodeSize, pixelCount){
  const clearCode = 1<<minCodeSize, eoiCode = clearCode+1;
  let codeSize, dict, nextCode;
  function resetDict(){
    dict=[]; for(let i=0;i<clearCode;i++) dict[i]=[i];
    nextCode=clearCode+2; codeSize=minCodeSize+1;
  }
  resetDict();
  const out=[];
  let bitBuf=0, bitCnt=0, bp=0, prev=null;
  function readCode(){
    while(bitCnt<codeSize){
      if(bp>=bytes.length) return eoiCode;
      bitBuf|=bytes[bp++]<<bitCnt; bitCnt+=8;
    }
    const c=bitBuf&((1<<codeSize)-1); bitBuf>>=codeSize; bitCnt-=codeSize; return c;
  }
  while(out.length<pixelCount){
    const code=readCode();
    if(code===clearCode){ resetDict(); prev=null; continue; }
    if(code===eoiCode) break;
    let entry;
    if(dict[code]) entry=dict[code];
    else if(code===nextCode && prev) entry=prev.concat([prev[0]]);
    else break; // code hỏng/không hợp lệ → dừng an toàn
    for(let k=0;k<entry.length;k++) out.push(entry[k]);
    if(prev){
      dict[nextCode]=prev.concat([entry[0]]); nextCode++;
      if(nextCode===(1<<codeSize) && codeSize<12) codeSize++;
    }
    prev=entry;
  }
  return out;
}
function _deinterlaceGif(indices, width, height){
  const out=new Array(width*height);
  const passes=[[0,8],[4,8],[2,4],[1,2]];
  let srcRow=0;
  for(const [start,step] of passes){
    for(let row=start; row<height; row+=step){
      const so=srcRow*width, doo=row*width;
      for(let x=0;x<width;x++) out[doo+x]=indices[so+x];
      srcRow++;
    }
  }
  return out;
}
function _parseGifBuffer(buffer){
  const data=new Uint8Array(buffer);
  let p=0;
  const sig=String.fromCharCode(data[0],data[1],data[2],data[3],data[4],data[5]);
  if(sig!=='GIF87a' && sig!=='GIF89a') throw new Error('không phải file GIF hợp lệ');
  p=6;
  const width=data[p]|(data[p+1]<<8); p+=2;
  const height=data[p]|(data[p+1]<<8); p+=2;
  const packed=data[p++];
  const gctFlag=(packed&0x80)!==0, gctSize=2<<(packed&0x07);
  p++; // background color index (không dùng)
  p++; // pixel aspect ratio (không dùng)
  let gct=null;
  if(gctFlag){ gct=[]; for(let i=0;i<gctSize;i++){ gct.push([data[p],data[p+1],data[p+2]]); p+=3; } }
  const frames=[];
  let transIdx=-1, disposal=0, delay=10;
  while(p<data.length){
    const blockType=data[p++];
    if(blockType===0x21){ // extension
      const label=data[p++];
      if(label===0xF9){
        p++; // block size = 4
        const pk=data[p++];
        disposal=(pk>>2)&0x07;
        const transFlag=(pk&0x01)!==0;
        delay=(data[p]|(data[p+1]<<8))*10; p+=2;
        const ti=data[p++]; transIdx=transFlag?ti:-1;
        p++; // block terminator
      } else {
        let size; while((size=data[p++])!==0){ p+=size; }
      }
    } else if(blockType===0x2C){ // image descriptor
      const left=data[p]|(data[p+1]<<8); p+=2;
      const top=data[p]|(data[p+1]<<8); p+=2;
      const w=data[p]|(data[p+1]<<8); p+=2;
      const h=data[p]|(data[p+1]<<8); p+=2;
      const pk=data[p++];
      const lctFlag=(pk&0x80)!==0, interlace=(pk&0x40)!==0, lctSize=2<<(pk&0x07);
      let lct=null;
      if(lctFlag){ lct=[]; for(let i=0;i<lctSize;i++){ lct.push([data[p],data[p+1],data[p+2]]); p+=3; } }
      const minCodeSize=data[p++];
      const lzwBytes=[];
      let size;
      while((size=data[p++])!==0){ for(let i=0;i<size;i++) lzwBytes.push(data[p+i]); p+=size; }
      let indices=_lzwDecodeGif(lzwBytes, minCodeSize, w*h);
      if(interlace) indices=_deinterlaceGif(indices, w, h);
      frames.push({left,top,width:w,height:h,colorTable:lct||gct,transparentIndex:transIdx,disposal,delay,indices});
      transIdx=-1; disposal=0; delay=10;
    } else if(blockType===0x3B || blockType===undefined){ break; } // trailer / hết file
    else { break; } // block lạ → dừng an toàn thay vì loop vô hạn
  }
  if(!frames.length) throw new Error('GIF không có khung hình nào');
  return {width,height,frames};
}
function _renderGifFrames(gif){
  const {width,height,frames}=gif;
  const acc=document.createElement('canvas'); acc.width=width; acc.height=height;
  const actx=acc.getContext('2d');
  const out=[];
  let prevDisposal=0, prevRect=null, prevSnapshot=null;
  for(const f of frames){
    if(prevRect){
      if(prevDisposal===2) actx.clearRect(prevRect.left,prevRect.top,prevRect.width,prevRect.height);
      else if(prevDisposal===3 && prevSnapshot) actx.putImageData(prevSnapshot,prevRect.left,prevRect.top);
    }
    const needSnap=f.disposal===3;
    const beforeSnap=needSnap?actx.getImageData(f.left,f.top,f.width,f.height):null;
    const colorTable=f.colorTable||[[0,0,0]];
    const frameImgData=actx.createImageData(f.width,f.height);
    for(let i=0;i<f.indices.length;i++){
      const ci=f.indices[i];
      if(ci===f.transparentIndex) continue; // để trong suốt (giữ nguyên pixel nền cũ)
      const col=colorTable[ci]||[0,0,0];
      frameImgData.data[i*4]=col[0]; frameImgData.data[i*4+1]=col[1]; frameImgData.data[i*4+2]=col[2]; frameImgData.data[i*4+3]=255;
    }
    // putImageData ghi đè cả pixel alpha=0 → phải vẽ qua 1 canvas tạm rồi drawImage để tôn trọng trong suốt
    const frameCanvas=document.createElement('canvas'); frameCanvas.width=f.width; frameCanvas.height=f.height;
    frameCanvas.getContext('2d').putImageData(frameImgData,0,0);
    actx.drawImage(frameCanvas,f.left,f.top);
    const snapCanvas=document.createElement('canvas'); snapCanvas.width=width; snapCanvas.height=height;
    snapCanvas.getContext('2d').drawImage(acc,0,0);
    out.push({canvas:snapCanvas});
    prevDisposal=f.disposal; prevRect={left:f.left,top:f.top,width:f.width,height:f.height}; prevSnapshot=beforeSnap;
  }
  return out;
}
function _gifFileToSpriteSheet(file, onDone, onError){
  const reader=new FileReader();
  reader.onload=(e)=>{
    try{
      const gif=_parseGifBuffer(e.target.result);
      const rendered=_renderGifFrames(gif);
      const n=Math.max(1,rendered.length);
      const fw=gif.width, fh=gif.height;
      const cols=Math.ceil(Math.sqrt(n)), rows=Math.ceil(n/cols);
      const sheet=document.createElement('canvas'); sheet.width=cols*fw; sheet.height=rows*fh;
      const sctx=sheet.getContext('2d');
      rendered.forEach((fr,i)=>{ sctx.drawImage(fr.canvas,(i%cols)*fw,Math.floor(i/cols)*fh); });
      onDone(sheet.toDataURL('image/png'), cols, rows, n);
    }catch(err){ onError&&onError(err.message||String(err)); }
  };
  reader.onerror=()=>{ onError&&onError('Không đọc được file GIF'); };
  reader.readAsArrayBuffer(file);
}
function onVfxLibFiles(ev){
  const files=[...(ev.target.files||[])];
  const _cntEl=document.getElementById('vfxLibCount');
  files.forEach(f=>{
    const isGif = f.type==='image/gif' || /\.gif$/i.test(f.name);
    const _nm=f.name.replace(/\.[^.]+$/,'').slice(0,24)||'VFX';
    if(isGif){
      if(_cntEl) _cntEl.textContent='⏳ Đang xử lý GIF "'+_nm+'"... (đợi gif chạy hết 1 vòng)';
      _gifFileToSpriteSheet(f, (dataUrl,cols,rows,n)=>{
        const entry={ id:'vfx_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),
          name:_nm, url:dataUrl, grid:cols+'x'+rows, additive:null };
        vfxLibrary.push(entry); _buildVfxLibImg(entry); saveVfxLib(); renderVfxLib();
      }, (err)=>{ alert('Không xử lý được GIF "'+_nm+'": '+err); renderVfxLib(); });
    } else {
      const r=new FileReader();
      r.onload=(e)=>{
        const entry={ id:'vfx_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),
          name:_nm, url:e.target.result, grid:'', additive:null };
        vfxLibrary.push(entry); _buildVfxLibImg(entry); saveVfxLib(); renderVfxLib();
      };
      r.readAsDataURL(f);
    }
  });
  ev.target.value='';
}
function deleteVfx(id){
  const e=vfxLibrary.find(x=>x.id===id);
  if(!confirm('Xoá VFX "'+(e?e.name:'')+'" khỏi thư viện?')) return;
  vfxLibrary=vfxLibrary.filter(x=>x.id!==id);
  delete vfxLibImgs[id]; delete _vfxLibState[id];
  saveVfxLib(); renderVfxLib();
}
function renameVfx(id,val){ const e=vfxLibrary.find(x=>x.id===id); if(e){ e.name=val.slice(0,24); saveVfxLib(); } }
function setVfxGrid(id,val){ const e=vfxLibrary.find(x=>x.id===id); if(e){ e.grid=val.trim(); _buildVfxLibImg(e); saveVfxLib(); } }
function cycleVfxAdditive(id){
  const e=vfxLibrary.find(x=>x.id===id); if(!e) return;
  // bỏ Auto: chỉ 2 trạng thái — glow(true) / normal(false)
  e.additive = (e.additive===false) ? true : false;
  _buildVfxLibImg(e); saveVfxLib(); renderVfxLib();
}
function cycleVfxFlip(id){
  const e=vfxLibrary.find(x=>x.id===id); if(!e) return;
  // hướng sprite khi đạn bay theo vận tốc — bật (mặc định) = lật 180°, tắt = giữ nguyên hướng gốc của ảnh
  e.flip = (e.flip===false) ? true : false;
  _buildVfxLibImg(e); saveVfxLib(); renderVfxLib();
}

// ===================== 🔧 XỬ LÝ SPRITE SHEET LƯỚI KHÔNG ĐỀU (an toàn: cần người nhập số frame/hàng, không tự đoán mù) =====================
// dò các HÀNG có nội dung (alpha>10) trong toàn ảnh
function _vfxDetectRowRanges(d,w,h){
  const rowHas=new Array(h).fill(false);
  for(let y=0;y<h;y++){ for(let x=0;x<w;x++){ if(d[(y*w+x)*4+3]>10){ rowHas[y]=true; break; } } }
  const ranges=[]; let start=-1;
  for(let y=0;y<h;y++){ if(rowHas[y]&&start===-1) start=y; if(!rowHas[y]&&start!==-1){ ranges.push([start,y-1]); start=-1; } }
  if(start!==-1) ranges.push([start,h-1]);
  return ranges;
}
// dò các CỘT có nội dung trong khoảng [y0,y1] của 1 hàng
function _vfxDetectColRanges(d,w,y0,y1){
  const colHas=new Array(w).fill(false);
  for(let y=y0;y<=y1;y++){ for(let x=0;x<w;x++){ if(d[(y*w+x)*4+3]>10) colHas[x]=true; } }
  const ranges=[]; let start=-1;
  for(let x=0;x<w;x++){ if(colHas[x]&&start===-1) start=x; if(!colHas[x]&&start!==-1){ ranges.push([start,x-1]); start=-1; } }
  if(start!==-1) ranges.push([start,w-1]);
  return ranges;
}
// gộp các range cách nhau <= tol (khe hở nhỏ do viền mờ/anti-alias, không phải khoảng trống thật giữa 2 frame)
function _vfxMergeClose(ranges,tol){
  const merged=[];
  for(const r of ranges){
    if(merged.length && r[0]-merged[merged.length-1][1]<=tol) merged[merged.length-1][1]=r[1];
    else merged.push([r[0],r[1]]);
  }
  return merged;
}
// chỉnh số range về ĐÚNG targetCount: thiếu thì tách range rộng nhất làm đôi, dư thì gộp range hẹp nhất vào hàng xóm gần nhất
function _vfxSplitToCount(ranges,targetCount){
  ranges=ranges.map(r=>[r[0],r[1]]);
  while(ranges.length<targetCount){
    let bi=0,bw=-1;
    ranges.forEach((r,i)=>{ const w=r[1]-r[0]; if(w>bw){bw=w;bi=i;} });
    const [a,b]=ranges[bi], mid=Math.floor((a+b)/2);
    ranges.splice(bi,1,[a,mid],[mid+1,b]);
  }
  while(ranges.length>targetCount){
    let si=0,sw=Infinity;
    ranges.forEach((r,i)=>{ const w=r[1]-r[0]; if(w<sw){sw=w;si=i;} });
    if(si>0 && (si===ranges.length-1 || (ranges[si][0]-ranges[si-1][1])<=(ranges[si+1][0]-ranges[si][1]))){ ranges[si-1][1]=ranges[si][1]; ranges.splice(si,1); }
    else { ranges[si][1]=ranges[si+1][1]; ranges.splice(si+1,1); }
  }
  return ranges;
}
function processIrregularVfx(id, rowCountsStr){
  const e=vfxLibrary.find(x=>x.id===id); if(!e) return;
  const rowCounts=String(rowCountsStr||'').split(',').map(s=>parseInt(s.trim(),10)).filter(n=>n>0);
  if(!rowCounts.length){ alert('Nhập số frame mỗi hàng trước, ví dụ: 6,4,4'); return; }
  const img=vfxLibImgs[id];
  if(!img || !img.complete || !img.naturalWidth){ alert('Ảnh chưa load xong, thử lại sau 1s'); return; }
  const w=img.naturalWidth, h=img.naturalHeight;
  const srcCv=document.createElement('canvas'); srcCv.width=w; srcCv.height=h;
  const srcCx=srcCv.getContext('2d'); srcCx.drawImage(img,0,0);
  let d; try{ d=srcCx.getImageData(0,0,w,h).data; }catch(err){ alert('Không đọc được ảnh (lỗi CORS?)'); return; }
  let rowRanges=_vfxMergeClose(_vfxDetectRowRanges(d,w,h), 10);
  if(rowRanges.length!==rowCounts.length){
    alert('Dò được '+rowRanges.length+' hàng có nội dung, nhưng m nhập '+rowCounts.length+' hàng. Kiểm tra lại số nhập (cách nhau bởi dấu phẩy, đúng số hàng thật trong ảnh) rồi thử lại.');
    return;
  }
  const frames=[];
  rowRanges.forEach(([y0,y1],ri)=>{
    let cols=_vfxMergeClose(_vfxDetectColRanges(d,w,y0,y1), 12);
    cols=_vfxSplitToCount(cols, rowCounts[ri]);
    cols.forEach(([x0,x1])=>frames.push({x0,y0,x1,y1}));
  });
  const total=frames.length;
  let bestCols=total, bestRows=1;
  for(let c=Math.ceil(Math.sqrt(total)); c<=total; c++){ if(total%c===0){ bestCols=c; bestRows=total/c; break; } }
  const ext=frames.map(fr=>({fw:fr.x1-fr.x0+1, fh:fr.y1-fr.y0+1, fr}));
  const maxW=Math.max(...ext.map(f=>f.fw)), maxH=Math.max(...ext.map(f=>f.fh));
  const outCv=document.createElement('canvas'); outCv.width=maxW*bestCols; outCv.height=maxH*bestRows;
  const outCx=outCv.getContext('2d');
  ext.forEach((f,i)=>{
    const col=i%bestCols, row=(i/bestCols)|0;
    const dx=col*maxW+Math.floor((maxW-f.fw)/2), dy=row*maxH+(maxH-f.fh); // canh giữa ngang, canh ĐÁY dọc
    outCx.drawImage(srcCv, f.fr.x0,f.fr.y0,f.fw,f.fh, dx,dy,f.fw,f.fh);
  });
  e.url=outCv.toDataURL('image/png');
  e.grid=bestCols+'x'+bestRows;
  _buildVfxLibImg(e); saveVfxLib(); renderVfxLib();
  alert('Đã xử lý xong: '+total+' frame → lưới đều '+bestCols+'×'+bestRows+'.');
}
function renderVfxLib(){
  const grid=document.getElementById('vfxLibGrid'); if(!grid) return;
  grid.innerHTML='';
  document.getElementById('vfxLibEmpty').style.display = vfxLibrary.length ? 'none' : 'block';
  document.getElementById('vfxLibCount').textContent = vfxLibrary.length ? (vfxLibrary.length+' hiệu ứng') : '';
  vfxLibrary.forEach(e=>{
    const card=document.createElement('div');
    card.style.cssText='width:158px;background:#fff;border:1.5px solid #e0e0e8;border-radius:14px;padding:10px;display:flex;flex-direction:column;gap:7px;box-shadow:0 2px 8px rgba(0,0,0,0.06);';
    // preview canvas (nền tối kiểu arena để thấy đúng glow)
    const cv=document.createElement('canvas'); cv.width=136; cv.height=136; cv.id='vfxcv_'+e.id;
    cv.style.cssText='width:136px;height:136px;border-radius:10px;background:#10101c;display:block;';
    card.appendChild(cv);
    // name input (tối giản: chỉ còn tên + xoá, các "setting" khác (glow/hướng bay/xử lý lưới) đã bỏ khỏi UI vì đằng nào cũng nhờ xử lý sẵn)
    const nin=document.createElement('input'); nin.type='text'; nin.value=e.name;
    nin.style.cssText='width:100%;box-sizing:border-box;padding:5px 7px;border:1.5px solid #d5d5dd;border-radius:8px;font-size:0.74rem;font-weight:600;color:#333;';
    nin.addEventListener('input',ev=>renameVfx(e.id,ev.target.value));
    card.appendChild(nin);
    // delete
    const del=document.createElement('button'); del.textContent='🗑 Xóa';
    del.style.cssText='padding:4px;border:none;border-radius:8px;background:#fde8e8;color:#d32f2f;font-size:0.68rem;cursor:pointer;';
    del.onclick=()=>deleteVfx(e.id);
    card.appendChild(del);
    grid.appendChild(card);
  });
}
function _vfxLibTick(){
  for(const e of vfxLibrary){
    const cv=document.getElementById('vfxcv_'+e.id); if(!cv) continue;
    const cx=cv.getContext('2d');
    cx.globalCompositeOperation='source-over'; cx.globalAlpha=1;
    cx.fillStyle='#10101c'; cx.fillRect(0,0,cv.width,cv.height);
    const img=vfxLibImgs[e.id];
    if(!img||!img.complete||!img.naturalWidth||!img._cols) continue;
    const cols=img._cols, rows=img._rows, frames=img._frames;
    const fw=Math.round(img.naturalWidth/cols), fh=Math.round(img.naturalHeight/rows);
    const st=_vfxLibState[e.id]||(_vfxLibState[e.id]={frame:0,ft:0,t:0});
    const scale=(Math.min(cv.width,cv.height)*0.84)/Math.max(fw,fh);
    cx.save();
    if(img._additive) cx.globalCompositeOperation='lighter';
    cx.translate(cv.width/2,cv.height/2);
    if(frames<=1){
      st.t=(st.t+1)%90;
      const p=st.t/90, a=p<0.22?p/0.22:1-(p-0.22)/0.78, sc=scale*(0.72+p*0.5);
      cx.globalAlpha=Math.max(0,a);
      cx.drawImage(img,-fw*sc/2,-fh*sc/2,fw*sc,fh*sc);
    } else {
      st.ft++; if(st.ft>=4){ st.ft=0; st.frame=(st.frame+1)%frames; }
      const sx=(st.frame%cols)*fw, sy=Math.floor(st.frame/cols)*fh;
      cx.drawImage(img,sx,sy,fw,fh,-fw*scale/2,-fh*scale/2,fw*scale,fh*scale);
    }
    cx.restore();
  }
  _vfxLibRAF=requestAnimationFrame(_vfxLibTick);
}
