// khối tên+skill dưới arena (#bottomCtaWrap) + HUD tên đội Team Battle (#tbRosterBar) phải LUÔN đúng bằng chiều rộng THẬT của arena (arena co giãn theo màn hình)
// — set trực tiếp bằng JS thay vì đoán max-width bằng CSS, để 2 lề trái/phải luôn khớp chính xác dù màn hình/tỉ lệ nào
(function _setupBottomCtaWidthSync(){
  const _aw=document.querySelector('.arena-wrap'), _bc=document.getElementById('bottomCtaWrap'), _tb=document.getElementById('tbRosterBar');
  if(!_aw) return;
  const _sync=()=>{
    const w=_aw.getBoundingClientRect().width;
    if(w>0){ if(_bc) _bc.style.width=w+'px'; if(_tb) _tb.style.width=w+'px'; }
  };
  new ResizeObserver(_sync).observe(_aw);
  _sync();
})();

// ===================== NỀN VŨ TRỤ (sao nhấp nháy + nebula + sao chổi) =====================
(function setupSpace(){
  const sc=document.getElementById('spaceCanvas'); if(!sc) return; const x=sc.getContext('2d');
  let stars=[], comets=[], cometCD=120+Math.random()*240;
  const STAR_COLS=['#ffffff','#dfeaff','#fff4d8','#ffe0e8','#d8f0ff'];
  function initStars(){
    stars=[]; const n=Math.min(520, Math.floor(sc.width*sc.height/5200));
    for(let i=0;i<n;i++) stars.push({x:Math.random()*sc.width,y:Math.random()*sc.height,r:Math.random()*1.5+0.3,ph:Math.random()*Math.PI*2,sp:0.5+Math.random()*2.2,col:STAR_COLS[(Math.random()*STAR_COLS.length)|0]});
  }
  let _bgGrad=null,_bgGW=0,_bgGH=0,_spaceLast=0;
  function resize(){ sc.width=window.innerWidth; sc.height=window.innerHeight; initStars(); _bgGrad=null; }
  resize(); window.addEventListener('resize',resize);
  function frame(){
    if(getComputedStyle(sc).display==='none') return; // đã bỏ nền galaxy → dừng vẽ, khỏi tốn CPU
    requestAnimationFrame(frame);
    const t=Date.now();
    if(t-_spaceLast < 32) return; // throttle nền ~30fps (nền trang trí, không cần 60) → đỡ tốn FPS cho game
    _spaceLast=t;
    const W2=sc.width,H2=sc.height;
    // nền vũ trụ sâu (gradient TĨNH → cache, chỉ tạo lại khi đổi kích thước)
    if(!_bgGrad || _bgGW!==W2 || _bgGH!==H2){
      _bgGrad=x.createRadialGradient(W2*0.5,H2*0.42,0, W2*0.5,H2*0.42, Math.max(W2,H2)*0.85);
      _bgGrad.addColorStop(0,'#1b1442'); _bgGrad.addColorStop(0.55,'#100b2a'); _bgGrad.addColorStop(1,'#050310');
      _bgGW=W2; _bgGH=H2;
    }
    x.fillStyle=_bgGrad; x.fillRect(0,0,W2,H2);
    // nebula trôi
    x.save(); x.globalCompositeOperation='lighter';
    const neb=[['rgba(124,52,168,',0.16],['rgba(40,110,180,',0.15],['rgba(190,60,130,',0.11]];
    for(let i=0;i<neb.length;i++){
      const a=t/13000+i*2.1;
      const nx=W2*(0.3+0.4*Math.sin(a*0.7+i)), ny=H2*(0.3+0.4*Math.cos(a*0.5+i*1.3)), nr=Math.max(W2,H2)*(0.4+0.1*Math.sin(a+i));
      const ng=x.createRadialGradient(nx,ny,0,nx,ny,nr);
      ng.addColorStop(0,neb[i][0]+neb[i][1]+')'); ng.addColorStop(1,neb[i][0]+'0)');
      x.fillStyle=ng; x.fillRect(0,0,W2,H2);
    }
    x.restore();
    // sao nhấp nháy (random)
    for(const s of stars){
      const tw=0.25+0.75*Math.pow(Math.abs(Math.sin(t/620*s.sp+s.ph)),2);
      x.globalAlpha=tw; x.fillStyle=s.col;
      const _r=s.r*(0.6+0.5*tw);
      x.beginPath(); x.arc(s.x,s.y,_r,0,Math.PI*2); x.fill();
      if(s.r>1.1 && tw>0.85){ // sao to lóe sáng có quầng
        x.globalAlpha=tw*0.3; x.beginPath(); x.arc(s.x,s.y,_r*2.6,0,Math.PI*2); x.fill();
      }
    }
    x.globalAlpha=1;
    // sao chổi thỉnh thoảng
    cometCD--;
    if(cometCD<=0 && comets.length<2){
      cometCD=300+Math.random()*420;
      const fromLeft=Math.random()<0.5;
      comets.push({ x: fromLeft?-40:W2+40, y:Math.random()*H2*0.5, vx:(fromLeft?1:-1)*(7+Math.random()*4), vy:2+Math.random()*2.5, life:0 });
    }
    for(let i=comets.length-1;i>=0;i--){
      const c=comets[i]; c.x+=c.vx; c.y+=c.vy; c.life++;
      if(c.x<-80||c.x>W2+80||c.y>H2+80){ comets.splice(i,1); continue; }
      const _ang=Math.atan2(c.vy,c.vx), _tl=70;
      const tx=c.x-Math.cos(_ang)*_tl, ty=c.y-Math.sin(_ang)*_tl;
      const lg=x.createLinearGradient(c.x,c.y,tx,ty);
      lg.addColorStop(0,'rgba(255,255,255,0.95)'); lg.addColorStop(1,'rgba(150,200,255,0)');
      x.strokeStyle=lg; x.lineWidth=2.5; x.lineCap='round';
      x.beginPath(); x.moveTo(c.x,c.y); x.lineTo(tx,ty); x.stroke();
      x.fillStyle='#fff'; x.beginPath(); x.arc(c.x,c.y,2.2,0,Math.PI*2); x.fill();
    }
  }
  frame();
})();

