function resetRoster(){
  if(!confirm('Reset to default roster? All custom characters will be lost.')) return;
  storeDel('cbs_roster');
  picks=[null,null];
  roster=[];
  loadRoster();
  renderRoster();
  document.getElementById('btnFight').classList.remove('ready');
  [0,1].forEach(s=>{
    document.getElementById('pickBar'+s).classList.remove('has-pick');
    document.getElementById('pickName'+s).textContent='— not selected —';
    document.getElementById('pickType'+s).textContent='';
    document.getElementById('pickAvatar'+s).innerHTML='<span id="pickEmoji'+s+'">❓</span>';
  });
}

function saveNewChar(){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi
  const name = document.getElementById('modalName').value.trim();
  if(!name){ alert('Please enter a name!'); return; }
  const charKey = document.getElementById('modalType').value;
  const ALL_SLOT_FIELDS = ['attackAvatarUrl','skill1AvatarUrl','skill2AvatarUrl','skill3AvatarUrl','skill4AvatarUrl','skill5AvatarUrl','rageAvatarUrl','rageAttackAvatarUrl','mouthAvatarUrl','vfxUrl','vfxUrl2'];
  if(editingIdx !== null){
    roster[editingIdx].name = name;
    roster[editingIdx].charKey = charKey;
    roster[editingIdx].idleAnim = selectedAnimKey;
    roster[editingIdx].facing = selectedFacing;
    if(modalAvatarTouched) roster[editingIdx].avatarUrl = modalAvatarUrl;
    ALL_SLOT_FIELDS.forEach(f=>{ if(modalSlotsTouched[f]){ roster[editingIdx][f] = modalSlots[f] || null; roster[editingIdx][f+'Grid'] = modalSlotGrids[f] || null; } });
    roster[editingIdx].vfxGrid = modalVfxGrid || null;
    [0,1].forEach(s=>{ if(picks[s]===editingIdx) updatePickBar(s); });
  } else {
    const id = 'c'+Date.now();
    const char = { id, name, charKey, avatarUrl: modalAvatarUrl, idleAnim: selectedAnimKey, facing: selectedFacing };
    ALL_SLOT_FIELDS.forEach(f=>{ char[f] = modalSlots[f] || null; char[f+'Grid'] = modalSlotGrids[f] || null; });
    char.vfxGrid = modalVfxGrid || null;
    roster.push(char);
  }
  saveRoster(); closeModal(); renderRoster();
}

