// ===================== 🏆 LEADERBOARD: thắng/thua/hoà theo từng nhân vật trong roster (lưu bền qua storage) =====================
let charStats = {}; // roster id -> {wins,losses,draws}
function loadCharStats(){
  try{ const raw=storeGet('cbs_char_stats'); charStats = raw ? JSON.parse(raw) : {}; }catch(e){ charStats={}; }
}
function saveCharStats(){ try{ storeSet('cbs_char_stats', JSON.stringify(charStats)); }catch(e){} }
function _csGet(id){ if(!charStats[id]) charStats[id]={wins:0,losses:0,draws:0}; return charStats[id]; }

// (đã gỡ màn Leaderboard khỏi game theo yêu cầu 2026-10-10 — chỉ còn giữ dữ liệu thắng/thua charStats)
// ===================== 📝 UPDATE NOTE: nhật ký thay đổi hàng tuần, gắn với 1 nhân vật (avatar+tên tự kèm theo) =====================
let updateNotes = []; // {id, charId, text, date}
let unSelectedId = null;
let unEditingId = null; // id của note đang sửa dở (null = đang ở chế độ thêm mới)
function loadUpdateNotes(){
  try{ const raw=storeGet('cbs_update_notes'); updateNotes = raw ? JSON.parse(raw) : []; }catch(e){ updateNotes=[]; }
}
function saveUpdateNotes(){ try{ storeSet('cbs_update_notes', JSON.stringify(updateNotes)); }catch(e){} }

function goToBattle(){
  if(picks[0]===null||picks[1]===null) return;
  document.getElementById('selectScreen').classList.remove('active');
  document.getElementById('battleScreen').classList.add('active');
  document.getElementById('vsLabel').style.display='';
  updateVsLabel();
  showVsWaitScreen(); // 🎬 màn chờ "PRESS TO START", bấm ▶ Start mới vào trận
}
function goToSelect(){
  // ⭐ Fan Battle mượn chung #battleScreen với 1vs1 → nút Back phải trả về MENU CHÍNH và dọn cờ fanCtx,
  // chứ về màn chọn nhân vật 1vs1 thì picks đang có 4 slot sẽ lệch hẳn.
  if(fanCtx){ closeFan(); return; }
  if(bossCtx){ closeBoss(); return; }
  stopAllBattleMusic();
  if(animId) cancelAnimationFrame(animId);
  animId=null;
  isPaused=false;
  document.getElementById('btnPause').textContent='⏸';
  document.getElementById('btnPause').classList.remove('paused');
  document.getElementById('pauseOverlay').classList.remove('visible');
  document.getElementById('battleScreen').classList.remove('active');
  // thoát giữa chừng 1 trận tournament/team battle → về lại main menu (nơi mở); trận thường thì về màn chọn nhân vật
  if(rtBattleCtx || tbBattleCtx){ document.getElementById('mainMenuScreen').classList.add('active'); }
  else { document.getElementById('selectScreen').classList.add('active'); }
  rtBattleCtx=null;
  tbBattleCtx=null;
  _rtHideSidePanels();
  { const _tb=document.getElementById('tbRosterBar'); if(_tb) _tb.style.display='none'; }
  _syncBattleStartBtn();
}
// nút ▶ START (restart nhanh) chỉ dành cho trận thường — ẩn đi khi đang ở trong 1 trận tournament/team battle,
// vì restart giữa chừng sẽ phá vỡ trạng thái bracket/gauntlet đang chạy dở
function _syncBattleStartBtn(){
  const b=document.querySelector('.btn-battle-start-corner');
  if(b) b.style.display = (rtBattleCtx || tbBattleCtx) ? 'none' : '';
}

// ===================== SOUND ENGINE =====================
const AC = new (window.AudioContext||window.webkitAudioContext)();
function unlockAudio(){ AC.resume(); document.removeEventListener('click',unlockAudio); }
document.addEventListener('click',unlockAudio);


