// 🎙️ Route audio qua Web Audio (bus _mixGain) để cơ chế lặn tiếng (_duckMix) áp dụng được lên mọi sound
let _mixGain=null;
function _ensureMix(){ if(_mixGain) return; try{ _mixGain=AC.createGain(); _mixGain.connect(AC.destination);
  // 💤 GIỮ BUS LUÔN THỨC: Chrome cho GainNode "ngủ" khi không có tiếng nào chạy qua — mốc hẹn giờ (ramp) rơi đúng lúc ngủ bị BỎ QUA
  //    → lặn tiếng xong không hồi, mọi sound kẹt nhỏ 22% tới tận lần lặn sau (lỗi 2026-10-09, trận A Lotta Dame Guy vs Troll Face).
  //    1 nguồn hằng số = 0 (im lặng tuyệt đối) nối vào bus để nó luôn được xử lý.
  try{ const k=AC.createConstantSource(); k.offset.value=0; k.connect(_mixGain); k.start(); }catch(e){}
}catch(e){} }
// 🧹 dọn rác AudioNode: mỗi sound 1 lần bắn tạo MediaElementSource+Gain mới nhưng KHÔNG BAO GIỜ disconnect →
// tích luỹ hàng nghìn node treo lơ lửng sau vài trận → AudioContext ì ạch rồi im bặt hẳn (phải F5). Dọn ngay khi phát xong (ended/pause).
// 🔌 SỔ NÚT ÂM THANH — QUY TẮC BẮT BUỘC: mọi nút WebAudio tạo ra cho 1 tiếng (nguồn, gain, limiter, analyser...) PHẢI ghi vào sổ
//    của chính tiếng đó bằng _auReg(el, ...nút); phát xong / dừng / tắt thì _auRelease(el) gỡ HẾT. Nút nào treo lại trên bộ trộn
//    thì trình duyệt vẫn phải xử lý nó mãi → càng chơi càng nhiều nút treo → tụt FPS dần (lỗi đã gặp 2026-10-08: mỗi tiếng có
//    limiter để lại 1 gain + 1 compressor vĩnh viễn, trận Bat Cat 40s treo 165 compressor).
const _auAll=new Set();   // mọi tiếng đang giữ nút trên bộ trộn (lưới vét an toàn)
function _auReg(el, ...nodes){ if(!el) return; (el._auNodes||(el._auNodes=[])).push(...nodes.filter(Boolean)); _auAll.add(el); }
// 🧹 lưới vét: định kỳ gỡ nút của tiếng đã PHÁT HẾT; force=true (hết trận / ra menu) gỡ luôn cả tiếng đang dừng.
//    (không đụng tiếng đang tạm dừng bởi nút ⏸ khi chưa force — để bấm tiếp tục vẫn nghe được)
function _auSweep(force){ for(const el of _auAll){ if(el.ended || (force && el.paused)) _auRelease(el); } }
setInterval(()=>_auSweep(false), 5000);
function _auRelease(el){
  if(!el) return;
  for(const n of (el._auNodes||[])){ try{ n.disconnect(); }catch(e){} }
  for(const k of ['_srcNode','_gainNode','_normNode','_limNode']){ try{ if(el[k]) el[k].disconnect(); }catch(e){} }
  el._auNodes=[]; _auAll.delete(el);
}
function _cleanupAudioNode(el){
  if(!el) return;
  const _clean=()=>_auRelease(el);
  el.addEventListener('ended', _clean, {once:true});
  el.addEventListener('pause', _clean, {once:true}); // phòng khi bị .pause() thủ công (duration timeout) mà không bắn 'ended'
}
// chuỗi nút: nguồn → gain chuẩn hoá → (limiter nếu cần) → bus trộn
function _sndConnect(s, gainVal, el){
  const gn=AC.createGain(); gn.gain.value=gainVal; s.connect(gn); _auReg(el, gn);
  if(el._sndLimit){
    const lim=AC.createDynamicsCompressor();
    lim.threshold.value=-2; lim.knee.value=0; lim.ratio.value=20; lim.attack.value=0.002; lim.release.value=0.12;
    gn.connect(lim); lim.connect(_mixGain); el._limNode=lim; _auReg(el, lim);
  } else gn.connect(_mixGain);
  return gn;
}
