const SND_MUSIC=new Set(["pain_theme", "ar_music", "sc_gas", "guitar_bluebird", "guitar_aot", "guitar_s1", "guitar_deltarune", "guitar_unravel", "guitar_jojo", "piano_giorno", "piano_takeonme", "piano_rush", "piano_stilldre", "piano_thousandmiles", "violin_sad", "violin_1", "violin_2", "violin_3", "violin_4", "violin_5", "stalin_domain", "uia_remix_hiphop", "oiia_remix", "fr_song", "maxwell_dance", "flyingcat_theme", "nyan_theme", "damdamdidi", "commander_anthem", "tribe_1", "tribe_2", "tribe_3", "naruto_intro", "ricardo_music", "sax_song", "rickroll_song", "cough_meme", "mewing_song", "fk_anthem", "hm_musicbox", "eg_bgm"]);
let _sndMusicEls=new Set();
function _sndMusicPlaying(){
  for(const e of _sndMusicEls){ if(e.ended){ _sndMusicEls.delete(e); continue; } if(!e.paused) return true; }
  return false;
}
function _sndNormGain(el){
  if(!SND_NORMALIZE || !el) return 1;
  const k=el._sndKey, m=k&&SND_LUFS[k];
  if(!m) return 1;
  let g=Math.pow(10,(SND_TARGET_LUFS-m[0])/20);
  g=Math.max(0.05, Math.min(8, g));
  // nâng lên mà đỉnh sóng vượt -1 dBFS → cần bộ chặn đỉnh (limiter) để đủ độ to mà không vỡ tiếng
  el._sndLimit = (g>1 && m[1]+20*Math.log10(g) > -1);
  if(SND_MUSIC.has(k)){ _sndMusicEls.add(el); g=g/Math.max(0.05, el.volume||1); }   // nhạc nền: bằng nhau tuyệt đối
  else if(_sndMusicPlaying()) g*=SND_SFX_DUCK;                                     // có nhạc nền → hiệu ứng còn 75%
  return g;
}
function _mixRoute(el){
  if(!el || el._routed) return;
  el._routed=true;
  try{ if(AC.state==='suspended') AC.resume(); _ensureMix(); const s=AC.createMediaElementSource(el); _auReg(el, s);
    const _ng=_sndNormGain(el);
    if(Math.abs(_ng-1)>0.01 || el._sndLimit) el._normNode=_sndConnect(s,_ng,el);
    else s.connect(_mixGain);
    el._srcNode=s; if(!el.loop) _cleanupAudioNode(el); }catch(e){}
}
// 🎚️ LẶN BỚT nhạc nền dài (Ricardo nhảy, Mechanic Cat chế tạo, Mewing, ho khói, v.v.) khi có bản KHÁC vừa bắt đầu phát cùng lúc —
// nhiều nhân vật cùng lúc (đặc biệt 4-Way Battle) dễ chồng nhiều tiếng "nhạc nền" nghe loạn. Gọi NGAY sau khi set el.loop=true; el.volume=<base>;
// và TRƯỚC _mixRoute()/play(). Chỉ lặn (nhân 0.6, không tắt hẳn) các bản ĐANG THẬT SỰ CHẠY (không paused/ended), không đụng vào bản vừa mới gọi.
let _bgMusicList = [];
function _registerBgMusic(el, baseVol){
  if(!el) return;
  _bgMusicList = _bgMusicList.filter(o=>o.el!==el && !o.el.paused && !o.el.ended);
  for(const o of _bgMusicList){ o.el.volume = Math.max(0.08, o.el.volume*0.6); }
  _bgMusicList.push({el});
  el.volume = baseVol;
}
// KHUẾCH ĐẠI vượt ngưỡng 1.0 qua gain node (loa to lên)
const _LOUD = { bat_grapple: 1.3 }; // hệ số > 1.0 cho tiếng cần to hơn max
function _playLoud(el, gainVal){
  try{ if(AC.state==='suspended') AC.resume(); _ensureMix(); if(!_mixGain) return false;
    const s=AC.createMediaElementSource(el); _auReg(el, s);
    const gn=_sndConnect(s, SND_MUSIC.has(el._sndKey) ? _sndNormGain(el) : gainVal*_sndNormGain(el), el);   // nhạc nền bỏ mức riêng, hiệu ứng giữ mức trộn
    el._routed=true; el._srcNode=s; el._gainNode=gn; if(!el.loop) _cleanupAudioNode(el); return true;
  }catch(e){ return false; }
}
// 🔇 MỌI tiếng DÀI (>3s) phát qua playSample đều được ghi sổ ở đây, để thoát ra menu / vào trận mới / bấm tạm dừng
// là tắt hoặc dừng được hết — trước đây mấy tiếng này phát xong là mất dấu, cứ thế kêu tiếp ngoài menu.
const LONG_SFX_MIN=3;            // giây
let _longSfx=new Set();
function _trackLongSfx(clip, key){
  try{
    const src=AUDIO_SAMPLES[key];
    const d=(src&&isFinite(src.duration))?src.duration:(isFinite(clip.duration)?clip.duration:0);
    if(d<LONG_SFX_MIN) return;
    _longSfx.add(clip);
    clip.addEventListener('ended', ()=>_longSfx.delete(clip), {once:true});
  }catch(e){}
}
function stopAllLongSfx(){
  for(const c of _longSfx){ try{ c.pause(); c.currentTime=0; }catch(e){} }
  _longSfx.clear();
}
function pauseAllLongSfx(on){
  for(const c of _longSfx){ try{ on ? c.pause() : c.play().catch(()=>{}); }catch(e){} }
}
const SND_NO_PITCH=new Set(['duo_win','duo_correct','duo_wrong','duo_mibombo','dp_akatsuki','ps_shinra','dp_happy','sad_cat_cry','hm_stalker','mw_gojo','mw_gojo_travel','ar_clone','dc_rage','sm_omae','sm_nani','ld_stab','ld_shout','ld_heal1','ld_heal2']);   // phát ĐÚNG tốc gốc, không biến điệu ±6%
function playSample(key, volume=1.0, duration=null, rateMul=1){
  if(key==='punch2') return; // 🔇 tắt hết tiếng "uỵch" (đòn đánh/va chạm) theo yêu cầu — xoá dòng này để bật lại
  const a = AUDIO_SAMPLES[key];
  if(!a) return;
  try{
    const clone = a.cloneNode();
    clone.volume = Math.min(1, volume);
    clone.playbackRate = (SND_NO_PITCH.has(key) ? 1 : (0.94 + Math.random()*0.12)) * rateMul; // biến điệu pitch ±6% → đỡ lặp máy móc, nhân thêm rateMul nếu cần nhanh/chậm hẳn
    const _loudGain = volume>1 ? volume : _LOUD[key]; // volume>1 (vd 1.8) tự kích hoạt khuếch đại qua gain node, không cần khai báo riêng trong _LOUD
    if(_loudGain){ if(!_playLoud(clone,_loudGain)) _mixRoute(clone); } else _mixRoute(clone);
    clone.play().catch(()=>{});
    _trackLongSfx(clone, key);     // tiếng dài thì ghi sổ để còn tắt được lúc thoát trận / tạm dừng
    if(duration) setTimeout(()=>{ try{ clone.pause(); clone.currentTime=0; }catch(e){} _longSfx.delete(clone); }, duration*1000);
  } catch(e){}
}
// ===== ƯU TIÊN SOUND ULTIMATE: phát qua bus RIÊNG (không bị lặn theo _mixGain) + tự làm lặn tạm mọi sound khác trong lúc nó phát =====
let _priorityGain=null;
function _ensurePriorityGain(){
  if(_priorityGain) return;
  try{ _priorityGain=AC.createGain(); _priorityGain.gain.value=1; _priorityGain.connect(AC.destination); }catch(e){}
}
// 🛟 lưới an toàn: hết hạn lặn tiếng (và không đang im lặng kiểu Joninn) mà bus vẫn chưa về 1 → tự kéo về 1
let _duckEndMs=0, _mixSilent=false;
setInterval(()=>{ try{ if(!_mixGain || _mixSilent || performance.now()<_duckEndMs+150) return; const g=_mixGain.gain;
  if(g.value<0.98){ const now=AC.currentTime; g.cancelScheduledValues(now); g.setValueAtTime(g.value,now); g.linearRampToValueAtTime(1,now+0.1); } }catch(e){} }, 400);
function _duckMix(durSec){
  _ensureMix(); if(!_mixGain) return; _duckEndMs=Math.max(_duckEndMs, performance.now()+durSec*1000);
  try{
    const now=AC.currentTime, g=_mixGain.gain;
    g.cancelScheduledValues(now);
    g.setValueAtTime(g.value, now);
    g.linearRampToValueAtTime(0.22, now+0.08); // lặn nhanh
    g.setValueAtTime(0.22, Math.max(now+0.08, now+durSec-0.2));
    g.linearRampToValueAtTime(1, now+durSec); // hồi dần về bình thường
  }catch(e){}
}
function playPrioritySample(key, volume=1.0, rateMul=1, duckSec=1){
  const a = AUDIO_SAMPLES[key];
  if(!a) return;
  try{
    _ensurePriorityGain();
    const clone=a.cloneNode();
    clone.volume=Math.min(1,volume);
    clone.playbackRate=SND_NO_PITCH.has(key)?rateMul:(0.94+Math.random()*0.12)*rateMul;   // giọng nói (SND_NO_PITCH) giữ đúng tốc gốc
    if(AC.state==='suspended') AC.resume();
    let _routed=false;
    if(_priorityGain){
      try{
        const s=AC.createMediaElementSource(clone);
        const gn=AC.createGain(); gn.gain.value=(volume>1?volume:1)*_sndNormGain(clone);   // 🎚️ chuẩn hoá âm lượng
        s.connect(gn); _auReg(clone, s, gn);
        if(clone._sndLimit){ const lim=AC.createDynamicsCompressor(); lim.threshold.value=-2; lim.knee.value=0; lim.ratio.value=20; lim.attack.value=0.002; lim.release.value=0.12; gn.connect(lim); lim.connect(_priorityGain); _auReg(clone, lim); }
        else gn.connect(_priorityGain);
        clone._routed=true; _routed=true; clone._srcNode=s; clone._gainNode=gn;
        if(!clone.loop) _cleanupAudioNode(clone);
      }catch(e){}
    }
    if(!_routed) _mixRoute(clone);
    clone.play().catch(()=>{});
    _duckMix(duckSec); // các sound khác lặn xuống tạm trong lúc sound ultimate này phát
  }catch(e){}
}

function playSound(type){
  if(AC.state==='suspended') AC.resume();
  const t=AC.currentTime;
  _ensureMix();
  const g=AC.createGain(); g.connect(_mixGain||AC.destination);
  setTimeout(()=>{ try{ g.disconnect(); }catch(e){} }, 4000);   // 🔌 tiếng tổng hợp ngắn: 4s sau gỡ nút khỏi bộ trộn (không thì mỗi lần gọi treo lại 1 gain)

  function osc(freq,type='square',dur=0.12,vol=0.18){
    const o=AC.createOscillator(); o.type=type;
    o.connect(g); o.frequency.setValueAtTime(freq,t);
    g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
    o.start(t); o.stop(t+dur);
  }
  function sweep(f1,f2,type='square',dur=0.15,vol=0.15){
    const o=AC.createOscillator(); o.type=type;
    o.connect(g); o.frequency.setValueAtTime(f1,t); o.frequency.linearRampToValueAtTime(f2,t+dur);
    g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
    o.start(t); o.stop(t+dur);
  }
  function noise(dur=0.1,vol=0.12){
    const buf=AC.createBuffer(1,AC.sampleRate*dur,AC.sampleRate);
    const d=buf.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1;
    const src=AC.createBufferSource(); src.buffer=buf;
    const f=AC.createBiquadFilter(); f.type='bandpass'; f.frequency.value=400;
    src.connect(f); f.connect(g);
    g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
    src.start(t); src.stop(t+dur);
  }

  const rv=Math.random();

  switch(type){
    case 'shoot':
      if(rv<0.33) sweep(700,280,'square',0.08,0.11);
      else if(rv<0.66) sweep(500,200,'sawtooth',0.1,0.1);
      else { osc(800,'square',0.03,0.1); sweep(600,100,'square',0.07,0.09); }
      break;
    case 'explode':
      playSample('vine_boom', 0.9);
      break;
    case 'bomb':  noise(0.35,0.22); sweep(120,40,'sawtooth',0.35,0.18); break;
    case 'dash':
      if(rv<0.5) sweep(200,500,'sawtooth',0.1,0.2);
      else sweep(150,600,'square',0.08,0.22);
      break;
    case 'vampire': sweep(300,150,'sine',0.18,0.14); osc(200,'sine',0.12,0.1); break;
    case 'tank':  noise(0.12,0.2); osc(80,'square',0.15,0.2); break;
    case 'hit':
      // Thicker hit — noise burst + pitched thud + high crack
      noise(0.12,0.08);
      if(rv<0.33){ sweep(300,80,'square',0.18,0.08); osc(120,'sine',0.15,0.06); }
      else if(rv<0.66){ sweep(250,60,'sawtooth',0.2,0.09); noise(0.08,0.05); }
      else { osc(200,'square',0.15,0.07); sweep(400,100,'square',0.12,0.08); }
      break;
    case 'ko':
      playSample('ko', 0.42);
      break;
    case 'huh':
      playSample('huh_sample', 0.9);
      break;
    case 'win': {
      const notes=[523,659,784,1047];
      notes.forEach((f,i)=>{ const o=AC.createOscillator(); o.type='square'; o.connect(g); o.frequency.setValueAtTime(f,t+i*0.12); g.gain.setValueAtTime(0.15,t+i*0.12); g.gain.exponentialRampToValueAtTime(0.001,t+i*0.12+0.18); o.start(t+i*0.12); o.stop(t+i*0.12+0.2); });
      break; }
    case 'fire':  sweep(300,150,'sawtooth',0.08,0.08); break;
    case 'punch':
      // Thicker punch — meaty thud
      noise(0.15,0.12);
      if(rv<0.33){ sweep(180,60,'sine',0.25,0.12); osc(100,'square',0.12,0.1); }
      else if(rv<0.66){ sweep(220,70,'sawtooth',0.22,0.14); noise(0.1,0.08); }
      else { osc(160,'square',0.2,0.1); sweep(300,80,'square',0.15,0.12); }
      break;
    case 'rage':  sweep(100,400,'sawtooth',0.3,0.25); osc(300,'square',0.15,0.2); break;
    case 'stun':  sweep(500,800,'sine',0.2,0.14); break;
    case 'disco': {
      // funky disco beat — bass + high hat + melody
      // bass thump
      const bass=AC.createOscillator(); bass.type='sine'; bass.connect(g);
      bass.frequency.setValueAtTime(80,t); bass.frequency.exponentialRampToValueAtTime(40,t+0.15);
      g.gain.setValueAtTime(0.3,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.2);
      bass.start(t); bass.stop(t+0.2);
      // hi-hat
      [0.05,0.15,0.25,0.35].forEach(d=>{ noise(0.04,0.08); });
      // melody: funky 4-note riff
      [0,0.12,0.22,0.32].forEach((d,i)=>{
        const o=AC.createOscillator(); o.type='square'; o.connect(g);
        o.frequency.setValueAtTime([440,550,494,587][i],t+d);
        g.gain.setValueAtTime(0.12,t+d); g.gain.exponentialRampToValueAtTime(0.001,t+d+0.1);
        o.start(t+d); o.stop(t+d+0.12);
      });
      break; }
    case 'intro_drum': {
      noise(0.15,0.25);
      const bd=AC.createOscillator(); bd.type='sine'; bd.connect(g);
      bd.frequency.setValueAtTime(150,t); bd.frequency.exponentialRampToValueAtTime(40,t+0.15);
      g.gain.setValueAtTime(0.3,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.18);
      bd.start(t); bd.stop(t+0.2);
      break; }
    case 'intro_vs': {
      noise(0.08,0.3);
      [0,0.05,0.12].forEach((d,i)=>{ const o=AC.createOscillator(); o.type='sawtooth'; o.connect(g); o.frequency.setValueAtTime([80,120,200][i],t+d); g.gain.setValueAtTime(0.25,t+d); g.gain.exponentialRampToValueAtTime(0.001,t+d+0.2); o.start(t+d); o.stop(t+d+0.22); });
      sweep(200,900,'square',0.28,0.18);
      break; }
    case 'intro_whoosh': {
      sweep(80,400,'sawtooth',0.2,0.15);
      sweep(100,600,'sine',0.15,0.1);
      break; }
    case 'disco_beat': {
      // hi-hat + light bass tick
      noise(0.03,0.06);
      const hh=AC.createOscillator(); hh.type='square'; hh.connect(g);
      hh.frequency.setValueAtTime(60,t);
      g.gain.setValueAtTime(0.08,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.06);
      hh.start(t); hh.stop(t+0.07);
      break; }
    case 'fight': {
      // MP3 sample + synthesis impact layer
      playSample('fight', 1.0);
      // add synthesis punch underneath
      noise(0.06,0.3);
      sweep(100,400,'sawtooth',0.15,0.2);
      break; }
  }
}

