  ctx.fillStyle='#050505'; ctx.beginPath();
  for(let i=0;i<n;i++){ const j=Math.sin(S[i]*0.17+seed*5)*wd*0.02; const x=C[i].x+N[i].x*(Wd[i]+j), y=C[i].y+N[i].y*(Wd[i]+j); i?ctx.lineTo(x,y):ctx.moveTo(x,y); }
