// ── VẼ DƯỚI MEME: cánh tay + bàn tay đang bò sát mặt sàn + bóng con mồi bị nhấc
// 🖐️ BỘ ẢNH TAY BÓNG TỐI (user gửi, ChatGPT vẽ — đã tách nền xanh): 10 tư thế, cổ tay luôn vào từ mép TRÁI ảnh, tay chĩa PHẢI.
//    grip/squeeze (bản vẽ lại KHÔNG có vật thể: ngón khép thành vòng): lúc cầm, CẢ bàn tay vẽ ĐÈ LÊN con mồi
//    (không bị meme che khuất — tay "đấm xuyên" qua meme), lỗ vòng ngón đặt đúng tâm con mồi.
//    meta: w,h = cỡ ảnh · wy = độ cao tâm cổ tay · ww = bề dày cổ tay · bx,by,brx,bry = tâm & bán kính LỖ VÒNG NGÓN (= chỗ đặt con mồi)
const HM_HAND_META={"crawlA": {"w": 391, "h": 204, "wy": 74.0, "ww": 90.0}, "crawlB": {"w": 333, "h": 203, "wy": 85.0, "ww": 86.0}, "lunge": {"w": 382, "h": 315, "wy": 167.0, "ww": 90.0}, "closing": {"w": 333, "h": 238, "wy": 107.5, "ww": 91.0}, "fist": {"w": 321, "h": 192, "wy": 103.5, "ww": 91.0, "fo": 205}, "throw": {"w": 385, "h": 320, "wy": 145.0, "ww": 88.0}, "slap": {"w": 372, "h": 178, "wy": 92.0, "ww": 92.0}, "retreat": {"w": 339, "h": 230, "wy": 90.0, "ww": 84.0}, "grip": {"w": 333, "h": 238, "wy": 107.5, "ww": 91.0, "bx": 189.5, "by": 148.0, "brx": 65.5, "bry": 56.0}, "squeeze": {"w": 308, "h": 225, "wy": 106.0, "ww": 90.0, "bx": 201.5, "by": 145.5, "brx": 42.5, "bry": 45.5}};
const HM_HAND_IMG={};
for(const k of ['crawlA','crawlB','lunge','closing','grip','squeeze','fist','throw','slap','retreat']){ HM_HAND_IMG[k]=new Image(); HM_HAND_IMG[k].src='assets/img/scaredhamster/HAND_'+k+'.webp'; }
function _hmHandK(S){ return 0.495*((S.owner?S.owner.size:40)/40); }   // tỉ lệ ảnh → sân (tay dài ~4.4× size hamster)
// tư thế tay: theo pha đòn vồ (h.pose) / rụt về / sắp chạm địch thì xoè vuốt / còn lại bò 2 khung luân phiên
function _hmPoseFor(S,h){
  if(S.retract) return 'retreat';
  if(h.pose) return h.pose;
  if((h.clS??0)<-0.15) return 'lunge';
  return Math.sin((h.cph||0)*2)>0 ? 'crawlA' : 'crawlB';
}
function _hmBlit(img,meta,wx,wy,ang,k,a,mir){   // mir=-1: lật gương qua trục cổ tay → thành tay bên kia
  if(!img || !img.complete || !img.naturalWidth) return;
  ctx.save(); ctx.globalAlpha=a; ctx.translate(wx,wy); ctx.rotate(ang); ctx.scale(k,k*(mir||1));
  ctx.drawImage(img,0,-meta.wy,meta.w,meta.h); ctx.restore();
}
// cổ tay của tay đang bò: lùi từ điểm tay (rx,ry) về sau 35% chiều dài ảnh
function _hmWristFree(h,pose,k){ const m=HM_HAND_META[pose], a=h.angS??Math.atan2(h.hy,h.hx), off=(m.fo??m.w*0.35)*k;   // fo: điểm tay rơi đúng giữa nắm đấm
  return {x:(h.rx??h.tx)-Math.cos(a)*off, y:(h.ry??h.ty)-Math.sin(a)*off, a}; }
// cổ tay của tay đang CẦM: đặt sao cho tâm quả bóng trong ảnh trùng tâm con mồi
function _hmWristGrip(w,pose,k,mir){ const m=HM_HAND_META[pose], a=Math.atan2(w.dir.y,w.dir.x), lx=m.bx*k, ly=(m.by-m.wy)*k*(mir||1);
  return {x:w.C.x-(lx*Math.cos(a)-ly*Math.sin(a)), y:w.C.y-(lx*Math.sin(a)+ly*Math.cos(a)), a}; }
// 🌑 vài vệt bóng tối thỉnh thoảng lan nhẹ từ ngoài mép vào sàn (trận có Scared Hamster), rồi rút lại
let hmWisps=[], _hmWispCD=120;
function _hmWispsDraw(){
  if(!_hmDarkOn()){ hmWisps.length=0; return; }
  if(battleFreezeTimer<=0 && --_hmWispCD<=0 && hmWisps.length<2){ _hmWispCD=180+Math.random()*240;
    hmWisps.push({side:Math.floor(Math.random()*4), u:0.15+Math.random()*0.7, t:0, T:200+Math.random()*120, len:50+Math.random()*60, w:30+Math.random()*25, seed:Math.random()*9}); }
  for(let i=hmWisps.length-1;i>=0;i--){ const w=hmWisps[i]; if(++w.t>w.T){ hmWisps.splice(i,1); continue; }
    const p=w.t/w.T, reach=Math.sin(Math.PI*p), N=[[1,0],[-1,0],[0,1],[0,-1]][w.side], B=[[0,H*w.u],[W,H*w.u],[W*w.u,0],[W*w.u,H]][w.side];
    _shadowCloud(B[0]-N[0]*w.w, B[1]-N[1]*w.w, B[0]+N[0]*w.len*reach, B[1]+N[1]*w.len*reach, w.w*1.6, w.w*0.7, 0.85*Math.min(1,reach*2), tick/60, w.seed, false); }
}
function _hmDrawUnder(){
  for(const S of hmShadows){ const a=(S.dying?Math.max(0,1-S.dying/30):1), em=Math.min(1,S.t/HM_EMERGE), k0=_hmHandK(S), A=S.act;
    S.hands.forEach((h,hi)=>{ const ha=a*Math.min(1,em*2), lift=h.lift||0;
      const hold=!!(A && A.hold && A.hi===hi && A.u && !A.u.dead);
      const kT=k0*(1+0.18*lift); h._kS=(h._kS??kT)+(kT-(h._kS??kT))*0.35;   // nhấc lên → to ra chút (gần mắt hơn)
      let pose, W0;
      if(hold && (h.pose==='grip'||h.pose==='squeeze')){ pose=h.pose; const ang=h.angS??Math.atan2(h.hy,h.hx); W0=_hmWristGrip({C:{x:A.u.x,y:A.u.y},dir:{x:Math.cos(ang),y:Math.sin(ang)}},pose,h._kS,h.mir); }   // vòng ngón ôm quanh người con mồi
      else { pose=_hmPoseFor(S,h); W0=_hmWristFree(h,pose,h._kS); }
      const up=lift*k0*90;   // độ cao khi nhấc bổng
      if(up>0.5){ ctx.save(); ctx.globalAlpha=0.3*lift*ha; ctx.fillStyle='#000'; ctx.beginPath(); ctx.ellipse(h.rx??h.tx,h.ry??h.ty,k0*130*(1-0.25*lift),k0*45*(1-0.25*lift),0,0,Math.PI*2); ctx.fill(); ctx.restore(); }
      // cổ tay trượt mượt khi đổi tư thế (mỗi ảnh có cổ tay lệch nhau chút) → cánh tay không giật
      const tx=W0.x, ty=W0.y-up, wl=h.pose?0.85:0.5; if(h._Wx===undefined){ h._Wx=tx; h._Wy=ty; } h._Wx+=(tx-h._Wx)*wl; h._Wy+=(ty-h._Wy)*wl;
      W0={x:h._Wx, y:h._Wy, a:W0.a};
      h._pose=pose; h._W0=W0; h._ha=ha; h._over=hold;
      ctx.save(); ctx.beginPath(); ctx.rect(0,0,W,H); ctx.clip();   // cánh tay mọc ra từ ĐÚNG mép sàn — không lấn ra ngoài khung đè lên chữ
      _hmArmSprite(h,W0,HM_HAND_META[pose].ww*h._kS*0.97,ha,S.seed+hi*3.1);   // cánh tay luôn nằm dưới
      ctx.restore();
      if(!hold) _hmBlit(HM_HAND_IMG[pose],HM_HAND_META[pose],W0.x,W0.y,W0.a,h._kS,ha,h.mir);   // tay đang tóm thì vẽ ở _hmDrawOver (đè lên con mồi)
    });
  }
}
// ── VẼ TRÊN MEME: tay đang TÓM con mồi vẽ đè hẳn lên nó (ngón vòng quanh người, không bị che khuất)
function _hmDrawOver(){
  for(const S of hmShadows) for(const h of S.hands) if(h._over && h._W0) _hmBlit(HM_HAND_IMG[h._pose],HM_HAND_META[h._pose],h._W0.x,h._W0.y,h._W0.a,h._kS,h._ha,h.mir);
  // 🌑 bị nuốt chửng: bóng tối trùm kín con hamster rồi tan dần
  for(const f of fighters){ if(f.type!=='scaredhamster' || !(f._hmSwallowT>0)) continue;
    const k=f._hmSwallowT/HM_SWALLOW_T, grow=Math.min(1,(1-k)*3);
    ctx.save(); _hmSmokeBlob(f.x,f.y,f.size*(1.2+0.8*grow),Math.min(1,k*1.6));
    for(let j=0;j<6;j++){ const an=j/6*Math.PI*2+f._hmSwallowT*0.08, r=f.size*(0.9+0.4*Math.sin(j+f._hmSwallowT*0.2));
      _hmSmokeBlob(f.x+Math.cos(an)*r,f.y+Math.sin(an)*r,f.size*0.6,Math.min(1,k*1.4)); }
    ctx.restore(); }
}
function _spawnDeathShards(x,y,size,color,sprite){
  // 1) MẢNH TỪ CHÍNH ẢNH MEME: cắt lưới, mỗi ô bay ra từ đúng chỗ của nó trên người → nhìn như bị xé nát
  const sheet=_buildShardSheet(sprite);
  if(sheet){
    const G=_SHARD_GRID, cw=sheet.width/G, ch=sheet.height/G;
    for(let r=0;r<G;r++) for(let c=0;c<G;c++){
      const _cx=Math.floor(c*cw), _cy=Math.floor(r*ch), _cw=Math.ceil(cw), _ch=Math.ceil(ch);
      if(!_shardCellHasInk(sheet,_cx,_cy,_cw,_ch)) continue;
      const ox=(c+0.5)*cw-sheet.width/2, oy=(r+0.5)*ch-sheet.height/2;
      const a=Math.atan2(oy,ox)+(Math.random()-0.5)*0.7, spd=Math.random()*3.4+2.4;
      deathShards.push({
        img:sheet, sx:_cx, sy:_cy, sw:_cw, sh:_ch,
        x:x+ox, y:y+oy, vx:Math.cos(a)*spd, vy:Math.sin(a)*spd-Math.random()*2.6,
        rot:0, rotSpeed:(Math.random()-0.5)*0.34,
        size:Math.max(cw,ch), color,
        life:60+Math.random()*30, gravity:0.35
      });
    }
  }
  // 2) VỤN MÀU nhỏ như cũ — rắc thêm cho dày khói bụi (và là phương án dự phòng khi không lấy được ảnh)
  const n=sheet ? 10 : 16+Math.floor(Math.random()*6);
  for(let i=0;i<n;i++){
    const a=Math.random()*Math.PI*2, spd=Math.random()*5+2;
    deathShards.push({
      x, y, vx:Math.cos(a)*spd, vy:Math.sin(a)*spd-Math.random()*3,
      rot:Math.random()*Math.PI*2, rotSpeed:(Math.random()-0.5)*0.5,
      size:Math.random()*(size*0.28)+size*0.12, color,
      life:60+Math.random()*30, gravity:0.35
    });
  }
}
// 👹 TROLL FACE LỘT XÁC: lúc hoá ác mộng, avatar THƯỜNG nứt làm ĐÚNG 3 MẢNH LỚN (2 mảnh trên trái/phải +
// 1 mảnh dưới, chung 1 điểm nứt gần giữa, đường nứt răng cưa) rồi bong ra, văng nhẹ sang 2 bên và rơi xuống —
// như cái vỏ cũ tróc ra để lộ dạng ác mộng bên dưới. Dùng lại đường vẽ/vật lý của deathShards (mảnh có img).
function _tfShedShell(f){
  let sp=f._lastSprite;
  if(!sp || !sp.img){
    const im=avatarImgs[f.slotIdx];
    if(!(im && im.complete && im.naturalWidth>0)) return;
    const d=f.size*2, asp=im.naturalWidth/im.naturalHeight;
    sp={img:im, sx:0, sy:0, sw:im.naturalWidth, sh:im.naturalHeight, dw:asp>=1?d:d*asp, dh:asp>=1?d/asp:d, fl:false};
  }
  const dw=Math.max(12,Math.round(sp.dw)), dh=Math.max(12,Math.round(sp.dh));
  // tấm ảnh gốc (lật đúng hướng đang nhìn)
  const full=document.createElement('canvas'); full.width=dw; full.height=dh;
  { const c=full.getContext('2d');
    if(sp.fl){ c.translate(dw,0); c.scale(-1,1); }
    try{ c.drawImage(_stickerMask(sp.img), sp.sx,sp.sy,sp.sw,sp.sh, 0,0, dw,dh); }catch(_e){ return; } }
  const R=Math.random;
  const C=[dw*(0.44+R()*0.12), dh*(0.40+R()*0.12)];          // điểm nứt
  const T=[dw*(0.38+R()*0.24), 0];                           // nứt lên mép trên
  const L=[0, dh*(0.58+R()*0.22)];                           // nứt sang mép trái
  const Rt=[dw, dh*(0.55+R()*0.22)];                         // nứt sang mép phải
  // đường nứt răng cưa từ C tới đích (điểm chung giữa 2 mảnh kề nhau → khớp khít)
  const jag=(a,b)=>{ const pts=[]; const n=4;
    const nx=-(b[1]-a[1]), ny=b[0]-a[0], nl=Math.hypot(nx,ny)||1;
    for(let k=1;k<n;k++){ const t=k/n, j=(R()-0.5)*Math.min(dw,dh)*0.16;
      pts.push([a[0]+(b[0]-a[0])*t+nx/nl*j, a[1]+(b[1]-a[1])*t+ny/nl*j]); }
    return pts; };
  const cT=jag(C,T), cL=jag(C,L), cR=jag(C,Rt);
  const rev=a=>a.slice().reverse();
  const pieces=[
    [C,...cT,T,[0,0],L,...rev(cL)],                // mảnh trên-trái
    [C,...cT,T,[dw,0],Rt,...rev(cR)],              // mảnh trên-phải
    [C,...cL,L,[0,dh],[dw,dh],Rt,...rev(cR)],      // mảnh dưới
  ];
  const cxW=f.x, cyW=f.y;
  pieces.forEach((poly,pi)=>{
    let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;
    for(const [px,py] of poly){ x0=Math.min(x0,px); y0=Math.min(y0,py); x1=Math.max(x1,px); y1=Math.max(y1,py); }
    x0=Math.floor(x0); y0=Math.floor(y0);
    const bw=Math.max(2,Math.ceil(x1-x0)), bh=Math.max(2,Math.ceil(y1-y0));
    const cv=document.createElement('canvas'); cv.width=bw; cv.height=bh;
    const c=cv.getContext('2d');
    c.translate(-x0,-y0);
    c.beginPath(); poly.forEach(([px,py],k)=>k?c.lineTo(px,py):c.moveTo(px,py)); c.closePath();
    c.save(); c.clip(); c.drawImage(full,0,0);
    // mép nứt tối lại 1 chút cho ra cảm giác lớp vỏ dày bị tách — CHỈ tô dọc 3 đường nứt (không tô cả viền
    // đa giác, vì cạnh đa giác chạy qua phần nền trong suốt sẽ lộ thành đường thẳng lơ lửng), rồi
    // destination-in với chính ảnh để mọi nét tô chỉ còn nằm trên phần có hình.
    c.lineWidth=Math.max(1.5,Math.min(dw,dh)*0.02); c.strokeStyle='rgba(0,0,0,0.45)'; c.lineJoin='round';
    for(const [end,mid] of [[T,cT],[L,cL],[Rt,cR]]){
      c.beginPath(); c.moveTo(C[0],C[1]); mid.forEach(q=>c.lineTo(q[0],q[1])); c.lineTo(end[0],end[1]); c.stroke();
    }
    c.globalCompositeOperation='destination-in'; c.drawImage(full,0,0);
    c.restore();
    const ox=x0+bw/2-dw/2, oy=y0+bh/2-dh/2;
    const side = pi===0 ? -1 : pi===1 ? 1 : (R()<0.5?-1:1);
    deathShards.push({
      img:cv, sx:0, sy:0, sw:bw, sh:bh,
      x:cxW+ox, y:cyW+oy,
      vx:side*(1.6+R()*1.6), vy:(pi===2 ? -1.2 : -3.2)-R()*1.4,   // 2 mảnh trên bật lên rồi rơi, mảnh dưới tuột thẳng
      rot:0, rotSpeed:side*(0.05+R()*0.07),
      size:Math.max(bw,bh), color:'#b0bec5',
      life:75+R()*20, gravity:0.35
    });
  });
}
let germanSoldiers=[]; // German Cat soldiers
let battleFreezeTimer=0; // freeze all fighters during uia transformation
let _gameTickAccum=0;   // accumulator for GAME_SPEED sub-steps
let blackHoles=[]; // The Void
const _catDreamImg=(()=>{const i=new Image();i.src='assets/img/misc/CAT_DREAM_IMG.webp';return i;})();
let bananaPeels=[]; // Banana Cat
let coughGerms=[]; // Cough Cat: mầm bệnh thả trên sàn khi ho
let coughBlobs=[]; // Cough Cat: bọc đờm độc bắn ra khi ho xong, bay 1 đoạn rồi VỠ RA thành 3 mầm bệnh (coughGerms)
let maxwellTnts=[]; // Maxwell - The Cat: bẫy TNT đã đặt
let dogeKnights=[]; // King Cheems: 2 Doge Knight triệu hồi lúc ≤50% HP
// 👻 MA VẼ TAY của Scared Dog (thay emoji): đầu trùm vải tròn, vạt áo RÁCH tua rua gợn sóng nhạt dần về đuôi, 2 vệt khói như
//    tay buông thõng; mặt: 2 HỐC MẮT dài lệch xếch + MIỆNG HÁ DÀI như đang gào. Ma trắng: thân trắng ngà lạnh, hốc đen sâu,
//    vệt nước mắt đen. Ma đen: thân đen tím, đồng tử tím nhạt phát sáng trong hốc. px = khung vẽ, t = nhịp thời gian.
// 🌫️ ảnh nạn nhân XÁM + SÁNG + MỜ dựng sẵn 1 lần rồi cache (thay cho ctx.filter blur/grayscale chạy lại mỗi khung — rất nặng).
//    Mờ = thu nhỏ rồi phóng to lại (càng nhỏ càng nhoè): 3 mức 96px / 40px / 20px.
const _soulTexCache=new WeakMap();
function _soulTex(L,lv){
  if(!L || !L.img || !(L.sw>0) || !(L.sh>0)) return null;
  let M=_soulTexCache.get(L.img); if(!M){ M=new Map(); _soulTexCache.set(L.img,M); }
  const key=L.sx+'|'+L.sy+'|'+L.sw+'|'+L.sh; let e=M.get(key);
  if(!e){
    try{
      const mk=(S)=>{ const r=Math.min(1,S/Math.max(L.sw,L.sh)), w=Math.max(2,Math.round(L.sw*r)), h=Math.max(2,Math.round(L.sh*r));
        const c=document.createElement('canvas'); c.width=w; c.height=h; const x=c.getContext('2d');
        x.drawImage(L.img,L.sx,L.sy,L.sw,L.sh,0,0,w,h);
        x.globalCompositeOperation='saturation'; x.fillStyle='rgba(128,128,128,0.7)'; x.fillRect(0,0,w,h);   // ≈ grayscale 70%
        x.globalCompositeOperation='screen'; x.fillStyle='rgb(48,48,48)'; x.fillRect(0,0,w,h);                // ≈ brightness 1.25
        x.globalCompositeOperation='destination-in'; x.drawImage(L.img,L.sx,L.sy,L.sw,L.sh,0,0,w,h);          // giữ đúng viền trong suốt
        return c; };
      e=[mk(96),mk(40),mk(20)];
    }catch(err){ e=[null,null,null]; }
    if(M.size>24) M.delete(M.keys().next().value);
    M.set(key,e);
  }
  return e[lv];
}
function _sdDrawGhost(px,black,t){
  if(black) _sdGhostReaper(px,t); else _sdGhostSheet(px,t);
}
// 🤍 MA TRẮNG kiểu TẤM VẢI MỎNG BAY (theo ảnh mẫu user): đầu tròn nhỏ, thân nở ra; tay trái là nếp vải VÕNG CONG giơ lên, tay phải buông
//    với 2-3 ngón như khói; KHÔNG vạt áo — sợi vải mọc từ TRONG thân, dài ngắn khác nhau, cong, trôi chéo xuống rồi mờ dần.
//    Mặt: 2 mắt đen nhỏ xếch sát nhau + miệng "o" nhỏ. Trắng sáng, nếp gấp thưa không đều thuôn nhọn, không viền.
function _sdGhostSheet(px,t){
  const P=v=>v*px, sw=Math.sin(t*0.06)*P(0.02), K=0.8;                                               // K: hẹp hơn 20%
  ctx.save();
  // sợi vải: mọc từ ~0.45 chiều cao (BÊN DƯỚI mép thân), dài 0.2–0.45, cong, mờ dần — vẽ trước để thân phủ lên gốc
  const L=[0.42,0.26,0.5,0.32,0.46,0.24,0.38];
  const Y0=[-0.12,-0.04,-0.15,-0.07,-0.13,-0.02,-0.1];                                             // gốc sợi so le 0.40–0.55H
  for(let i=0;i<7;i++){ const x0=P((-0.16+i*0.05)*K+0.01*Math.sin(i*3)), y0=P(Y0[i]), len=P(L[i]+0.06), dx=P(0.06+0.04*Math.sin(t*0.05+i)), wd=P(0.026-0.002*i);
    const gg=ctx.createLinearGradient(x0,y0,x0+dx,y0+len); gg.addColorStop(0,'rgba(226,226,226,0)'); gg.addColorStop(0.3,'rgba(226,226,226,0.85)'); gg.addColorStop(1,'rgba(214,214,214,0)');
    ctx.beginPath(); ctx.moveTo(x0-wd,y0); ctx.bezierCurveTo(x0-wd+dx*0.1,y0+len*0.35,x0+dx*0.9,y0+len*0.6,x0+dx,y0+len);
    ctx.bezierCurveTo(x0+dx*0.7+wd,y0+len*0.55,x0+wd+dx*0.15,y0+len*0.3,x0+wd,y0); ctx.closePath(); ctx.fillStyle=gg; ctx.fill(); }
  const body=()=>{ ctx.beginPath();
    ctx.moveTo(P(-0.05),P(-0.42)); ctx.quadraticCurveTo(P(0),P(-0.53),P(0.05),P(-0.42));
    ctx.quadraticCurveTo(P(0.09*K+0.01),P(-0.31),P(0.15*K),P(-0.23));
    ctx.quadraticCurveTo(P(0.24*K),P(-0.13),P(0.25*K)+sw,P(-0.04));                                  // tay phải buông
    ctx.quadraticCurveTo(P(0.21*K),P(0.02),P(0.2*K),P(0.06));
    // mép dưới LƯỢN không đều (không mép ngang thẳng)
    for(const [x,y] of [[0.12,0.02],[0.05,0.09],[-0.02,0.0],[-0.09,0.08],[-0.17,0.01]]) ctx.quadraticCurveTo(P(x*K+0.03),P(y+0.05),P(x*K),P(y));
    ctx.quadraticCurveTo(P(-0.23*K),P(-0.06),P(-0.16*K),P(-0.15));
    ctx.quadraticCurveTo(P(-0.3*K)-sw,P(-0.22),P(-0.32*K)-sw,P(-0.35));                             // tay trái võng cong giơ lên
    ctx.quadraticCurveTo(P(-0.22*K),P(-0.29),P(-0.12*K),P(-0.28));
    ctx.quadraticCurveTo(P(-0.07),P(-0.33),P(-0.05),P(-0.42)); ctx.closePath(); };
  const g=ctx.createLinearGradient(0,P(-0.53),0,P(0.1)); g.addColorStop(0,'#ffffff'); g.addColorStop(0.6,'#f0f0f0'); g.addColorStop(0.82,'rgba(236,236,236,0.85)'); g.addColorStop(1,'rgba(236,236,236,0)');
  body(); ctx.fillStyle=g; ctx.fill();
  ctx.shadowBlur=0;
  // ngón tay phải: 3 LỌN KHÓI thuôn — gốc dày (~P 0.05), cong, nhọn dần ở đầu
  for(const [dx,dy,w,bend] of [[0.075,0.075,0.05,0.025],[0.035,0.105,0.046,0.02],[-0.005,0.09,0.04,-0.018]]){
    const bx=P(0.25*K)+sw, by=P(-0.03), ex=bx+P(dx), ey=by+P(dy), L=Math.hypot(dx,dy), nx=-dy/L, ny=dx/L;
    const mx=bx+P(dx*0.5+nx*bend), my=by+P(dy*0.5+ny*bend), hw=P(w)/2;
    const gg=ctx.createLinearGradient(bx,by,ex,ey); gg.addColorStop(0,'rgba(240,240,240,1)'); gg.addColorStop(0.7,'rgba(236,236,236,0.8)'); gg.addColorStop(1,'rgba(236,236,236,0.15)');
    ctx.beginPath(); ctx.moveTo(bx+nx*hw,by+ny*hw);
    ctx.quadraticCurveTo(mx+nx*hw*0.7,my+ny*hw*0.7,ex,ey); ctx.quadraticCurveTo(mx-nx*hw*0.7,my-ny*hw*0.7,bx-nx*hw,by-ny*hw); ctx.closePath();
    ctx.fillStyle=gg; ctx.fill(); }
  // nếp gấp thưa, không đều, thuôn
  ctx.save(); body(); ctx.clip();
  for(const [x,y0,len,w] of [[-0.1,-0.24,0.28,0.012],[-0.03,-0.29,0.36,0.009],[0.04,-0.22,0.24,0.011],[0.1,-0.17,0.18,0.008]]){
    const gg=ctx.createLinearGradient(0,P(y0),0,P(y0+len)); gg.addColorStop(0,'rgba(150,150,150,0)'); gg.addColorStop(0.4,'rgba(150,150,150,0.45)'); gg.addColorStop(1,'rgba(150,150,150,0)');
    ctx.strokeStyle=gg; ctx.lineWidth=P(w); ctx.beginPath(); ctx.moveTo(P(x),P(y0)); ctx.quadraticCurveTo(P(x+0.02),P(y0+len*0.5),P(x+0.01)+sw,P(y0+len)); ctx.stroke(); }
  ctx.restore();
  ctx.fillStyle='#000';
  ctx.beginPath(); ctx.ellipse(P(-0.028),P(-0.39),P(0.015),P(0.029),0.35,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(P(0.028),P(-0.39),P(0.015),P(0.029),-0.35,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0,P(-0.32),P(0.011),P(0.016),0,0,Math.PI*2); ctx.fill();
  ctx.restore();
}
// 🖤 MA ĐEN kiểu TỬ THẦN TRÙM MŨ (theo ảnh mẫu user): mũ nhọn, thân LOE DẦN thành áo choàng (không gờ vai), sườn phải phồng ra từ
//    cánh tay giơ lên; bên trái 3-4 DẢI LỬA CONG dài ngắn khác nhau chếch lên-trái, phất phơ; đáy rách lởm chởm có 2-3 mũi dài.
//    Trong mũ: 2 mắt trắng giọt nước + mũi đầu lâu, KHÔNG miệng. Đen đặc, cạnh sắc, KHÔNG phát sáng; viền xám lệch mép phải + đáy.
function _sdGhostReaper(px,t){
  // 🌬️ SỐNG ĐỘNG: dải áo phần phật nhiều nhịp + co duỗi, gấu áo rách đung đưa, tay phải vẫy gọi, thân phập phồng thở,
  //    đầu nghiêng qua lại, mắt thi thoảng chớp, khói đen rơi rớt từ gấu áo
  const P=v=>v*px, fl=i=>(Math.sin(t*0.13+i*1.7)*0.055+Math.sin(t*0.29+i*2.3)*0.02)*px;
  const arm=[0.32+Math.cos(t*0.12)*0.02, -0.27+Math.sin(t*0.12)*0.05];
  ctx.save(); ctx.shadowBlur=0;
  { const br=Math.sin(t*0.08); ctx.scale(1+0.025*br, 1-0.02*br); }
  // khói đen rơi từ gấu áo (vẽ trước → nằm sau áo)
  for(let k=0;k<6;k++){ const ph=(t*0.014+k/6)%1, hx=-0.22+k*0.09, x=P(hx-0.08*ph+0.02*Math.sin(t*0.07+k)), y=P(0.4+0.28*ph), r=P(0.03+0.05*ph);
    const g=ctx.createRadialGradient(x,y,0,x,y,r); g.addColorStop(0,`rgba(20,16,16,${0.55*(1-ph)})`); g.addColorStop(1,'rgba(20,16,16,0)');
    ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill(); }
  // 🧥 ÁO CHOÀNG MỀM: viền là đường cong TRƠN (Catmull-Rom) đi qua các điểm mốc, cả áo bị "gió" uốn bằng sóng chạy dọc
  //    thân — càng xuống dưới lệch càng nhiều và trễ pha hơn (vải phần dưới bay theo sau), gấu rách gợn sóng chạy ngang.
  const wind=(x,y)=>{ const k=Math.max(0,Math.min(1,(y+0.3)/0.85));
    return [x+k*(0.04*Math.sin(t*0.09-y*6)+0.022*Math.sin(t*0.155-y*11+x*3)),
            y+(y>0.28?(0.035*Math.sin(t*0.12+x*10)+0.015*Math.sin(t*0.21-x*17)):0)]; };
  const smooth=(pts)=>{ ctx.beginPath(); const n=pts.length;
    for(let i=0;i<n;i++){ const p0=pts[(i-1+n)%n], p1=pts[i], p2=pts[(i+1)%n], p3=pts[(i+2)%n];
      if(i===0) ctx.moveTo(P(p1[0]),P(p1[1]));
      ctx.bezierCurveTo(P(p1[0]+(p2[0]-p0[0])/6),P(p1[1]+(p2[1]-p0[1])/6),P(p2[0]-(p3[0]-p1[0])/6),P(p2[1]-(p3[1]-p1[1])/6),P(p2[0]),P(p2[1])); }
    ctx.closePath(); };
  const KEY=[[0,-0.47],[0.09,-0.41],[0.13,-0.3],[0.21,-0.29+(arm[1]+0.27)*0.4],[arm[0],arm[1]],[0.36,-0.08],[0.34,0.14],[0.31,0.33],
    [0.25,0.42],[0.2,0.35],[0.12,0.52],[0.05,0.38],[-0.04,0.47],[-0.1,0.37],[-0.19,0.57],[-0.25,0.39],
    [-0.29,0.27],[-0.25,0.06],[-0.17,-0.15],[-0.11,-0.33],[-0.06,-0.44]];
  const body=KEY.map(([x,y])=>wind(x,y));
  // 🎐 dải áo phất phơ bên trái: dải lụa thon, sóng chạy dọc từ gốc ra mũi (đuôi lắc mạnh hơn gốc)
  const ribbons=()=>{ [[-0.28,0.24,-0.5,0.14,0.11],[-0.26,0.1,-0.6,-0.05,0.1],[-0.21,-0.03,-0.45,-0.19,0.085],[-0.15,-0.15,-0.31,-0.31,0.07]].forEach(([bx,by,tx,ty,w0],i)=>{
      const st=1+0.12*Math.sin(t*0.08+i*1.1), dx=(tx-bx)*st, dy=(ty-by)*st, L=Math.hypot(dx,dy), nx=-dy/L, ny=dx/L, N=12, Lp=[], Rp=[];
      for(let j=0;j<=N;j++){ const u=j/N, wave=u*(0.06*Math.sin(t*0.14-u*4.5+i*1.7)+0.025*Math.sin(t*0.27-u*8+i)), w=w0*Math.pow(1-u,0.75)*0.5+0.002;
        const [cx,cy]=wind(bx+dx*u+nx*wave, by+dy*u+ny*wave); Lp.push([cx+nx*w,cy+ny*w]); Rp.unshift([cx-nx*w,cy-ny*w]); }
      smooth(Lp.concat(Rp)); ctx.fill(); }); };
  const cloak=()=>{ smooth(body); };
  ctx.save(); ctx.translate(P(0.016),P(0.016)); ctx.fillStyle='#4e4e4e'; ribbons(); cloak(); ctx.fill(); ctx.restore();   // viền xám lệch
  ctx.fillStyle='#0e0c0c'; ribbons(); cloak(); ctx.fill();
  ctx.save(); cloak(); ctx.clip(); ctx.lineCap='round';
  for(const [x0,y0,x1,y1,w] of [[0.03,-0.2,0.07,0.36,0.009],[0.15,-0.14,0.2,0.28,0.007],[-0.08,-0.16,-0.12,0.32,0.008],[-0.2,0.02,-0.27,0.3,0.006]]){
    const A0=wind(x0,y0), A1=wind(x1,y1), M=wind((x0+x1)/2+0.025,(y0+y1)/2);
    ctx.strokeStyle='rgba(72,72,72,0.75)'; ctx.lineWidth=P(w); ctx.beginPath(); ctx.moveTo(P(A0[0]),P(A0[1])); ctx.quadraticCurveTo(P(M[0]),P(M[1]),P(A1[0]),P(A1[1])); ctx.stroke(); }
  ctx.restore();
  const hx=Math.sin(t*0.05)*P(0.012), blink=(t%170)<7 ? 0.15 : 1;   // đầu nghiêng qua lại, mắt chớp
  ctx.fillStyle='#000'; ctx.beginPath(); ctx.ellipse(hx,P(-0.33),P(0.065),P(0.075),0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#ffffff';
  ctx.save(); ctx.translate(hx,P(-0.355)); ctx.scale(1,blink); ctx.translate(0,-P(-0.355));
  for(const sd of [-1,1]){ ctx.beginPath(); const ex=sd*P(0.028), ey=P(-0.355);
    ctx.moveTo(ex+sd*P(0.012),ey-P(0.018)); ctx.quadraticCurveTo(ex-sd*P(0.024),ey-P(0.005),ex-sd*P(0.006),ey+P(0.018)); ctx.quadraticCurveTo(ex+sd*P(0.02),ey+P(0.01),ex+sd*P(0.012),ey-P(0.018)); ctx.fill(); }
  ctx.restore();
  ctx.fillStyle='#bdbdbd'; ctx.beginPath(); ctx.moveTo(hx-P(0.007),P(-0.325)); ctx.lineTo(hx+P(0.007),P(-0.325)); ctx.lineTo(hx,P(-0.31)); ctx.closePath(); ctx.fill();
  ctx.restore();
}
// 🐶👻 Scared Dog: 2 con ma triệu hồi 1s sau khi vào trận — {id,team,owner,color:'black'|'white',x,y,vx,vy,size,...}.
// KHÔNG có field hp/maxHp/takeDamage — cố tình, vì đây là summon KHÔNG THỂ BỊ TIÊU DIỆT (không đăng ký vào
// _hpSummonArrays() hay bất kỳ vòng lặp gây-dame-lên-summon nào khác). Chỉ biến mất khi Scared Dog (owner) chết.
let scaredGhosts=[];
let _soulLoop=null;   // 👻 tiếng hút hồn đang lặp (xem loop chính)
let dawaeSwarm=[];   // 🚪 Da Wae: đàn Da Wae nhỏ bay thẳng xuyên sân, KHÔNG có HP (thuần vật cản đẩy lùi, giống scaredGhosts về mặt "không thể bị diệt") — xem doAbility() (spawn) và loop() chính (update+draw)
let _dawaeRunSfx=null, _dawaeRunSfx2=null;   // 🚪 2 tiếng chạy loop CÙNG LÚC trong lúc đàn còn trên sàn (bật/tắt theo dawaeSwarm.length, xem loop() chính) — KHÔNG gắn trên fighter vì đàn là mảng toàn cục dùng chung
let mewingStatues=[]; // Mewing Cat: tượng đá triệu hồi mỗi lần mewing, lao từ mép sàn vào tấn công địch gần nhất
let mvPulses=[];       // 🦟 Mosquito Violin: xung âm hình nhịp tim chạy dọc sợi dây tới kẻ địch
let mvFx=[];           // 🩸 máu bắn tóe lúc rút + vòng đỏ lúc con muỗi nuốt máu về: {k,x,y,t,T,...}
// mỗi nhịp của bài nhạc → bắn 1 xung vào TỪNG kẻ địch đang bị nối dây
function _mvPulse(f, freq){
  const L=f._mvLinks;
  if(!L || !L.length) return;
  for(const t of L){
    if(!t || t.dead || (t.hp!==undefined && t.hp<=0)) continue;
    // 🩸 mỗi nhịp: RÚT MÁU ngay tại kẻ địch, rồi cục máu chạy NGƯỢC dọc dây về con muỗi mới hồi máu
    const _hp0=t.hp;
    t.takeDamage(15, f);   // 🦟 mỗi nhịp 15 dame (giảm từ 20)
    const _thuc=Math.max(0, _hp0-t.hp);
    _spawnMusicNoteFx(t.x,t.y,t.size);   // 🦟 Mosquito Violin: nốt nhạc trúng địch (thay hạt máu đỏ cũ)
    mvPulses.push({ owner:f, target:t, t:0, spd:0.055, seed:Math.random()*10, mau:Math.round(_thuc*0.2) });
    // 🩸 máu bắn tóe nhẹ ngay chỗ bị rút (bắn ngược về phía con muỗi)
    { const _a0=Math.atan2(f.y-t.y,f.x-t.x);
      for(let _k=0;_k<5;_k++){ const _a=_a0+(Math.random()-0.5)*1.6, _sp=0.8+Math.random()*1.6;
        mvFx.push({k:'drop', x:t.x+Math.cos(_a0)*t.size*0.5, y:t.y+Math.sin(_a0)*t.size*0.5, vx:Math.cos(_a)*_sp, vy:Math.sin(_a)*_sp, r:f.size*(0.05+Math.random()*0.05), t:0, T:18+(Math.random()*8|0)}); } }
  }
  f.actionState='attack'; f.actionTimer=10;
}
// 🐈 ẢNH TAY của Slap Cat (thò qua cổng). Toạ độ cổ tay / bàn tay ĐO TRỰC TIẾP từ ảnh (trọng tâm dải 12% trên
// cùng = cổ tay, dải 12% dưới cùng = bàn tay) chứ không ước lượng bằng mắt — nhờ vậy neo cổ tay vào miệng cổng
// và chĩa bàn tay về đúng phía địch là chuẩn theo dựng hình, không phải canh tay.
const SLAPCAT_HAND_IMG=new Image();
SLAPCAT_HAND_IMG.src='assets/img/slapcat/SLAPCAT_HAND_IMG.webp';
const _SLAP_WRIST={x:0.742,y:0.161}, _SLAP_PAW={x:0.385,y:0.844};   // tỉ lệ theo cỡ ảnh gốc
const _SLAP_IMG_ANG=Math.atan2(_SLAP_PAW.y-_SLAP_WRIST.y, _SLAP_PAW.x-_SLAP_WRIST.x); // hướng bàn tay trong ảnh (~117.6°)
const _SLAP_LEN=Math.hypot(_SLAP_PAW.x-_SLAP_WRIST.x, _SLAP_PAW.y-_SLAP_WRIST.y);     // dài cổ tay→bàn tay (~0.77 cỡ ảnh)
let fdSmoke=[];        // 💨 khói bốc lên từ sàn cháy của Fine Dog (xem _fineDogDrawFire)
// ⚠️ sprite khói nướng ĐÚNG 1 LẦN rồi phóng to tuỳ ý. KHÔNG dùng _glowDisc: nó cache theo TỪNG CỠ, mà cỡ cụm
// khói đổi liên tục mỗi khung (nở dần theo tuổi) nên gần như mỗi hạt mỗi khung lại nướng lại 1 canvas shadowBlur
// mới — đo thực tế: 17 cụm khói = 76ms/khung, trong khi cả dải lửa chỉ 0.37ms.
let _fdSmokeSprite=null;
function _fdGetSmokeSprite(){
  if(_fdSmokeSprite) return _fdSmokeSprite;
  const R=64, cv=document.createElement('canvas'); cv.width=cv.height=R*2;
  const c=cv.getContext('2d');
  const g=c.createRadialGradient(R,R,0,R,R,R);
  g.addColorStop(0,   'rgba(70,66,64,0.95)');
  g.addColorStop(0.45,'rgba(66,62,60,0.55)');
  g.addColorStop(1,   'rgba(60,56,54,0)');
  c.fillStyle=g; c.beginPath(); c.arc(R,R,R,0,Math.PI*2); c.fill();
  _fdSmokeSprite=cv; return cv;
}
