let slapPortals=[];    // 🐈 Slap Cat: cặp cổng không gian (xanh cạnh mình / đỏ sau lưng địch) + cánh tay thò qua
// mỗi cú vả sinh ĐÚNG 1 phần tử: giữ cả 2 đầu cổng + tiến độ vung tay, tự hết sau _life
function _slapOpen(f, e){
  const _d=Math.hypot(e.x-f.x, e.y-f.y);
  const _ang=Math.atan2(e.y-f.y, e.x-f.x);
  const _r=Math.max(16, f.size*0.62);
  slapPortals.push({
    // cổng XANH: ngay cạnh Slap Cat, hơi chếch về phía địch
    ax:f.x+Math.cos(_ang)*f.size*0.85, ay:f.y+Math.sin(_ang)*f.size*0.85, aAng:_ang,
    // cổng ĐỎ: SAU LƯNG địch (phía đối diện Slap Cat)
    bx:e.x+Math.cos(_ang)*(e.size*0.95), by:e.y+Math.sin(_ang)*(e.size*0.95), bAng:_ang,
    r:_r, life:30, maxLife:30, target:e, hitAt:15, daVa:false, owner:f,   // 0.5s, dame nổ ở giữa quãng
  });
}
let _idFlashes=[];     // ✨ loé vàng chói ở ĐÚNG chỗ Infinity Doge va vào địch (thuần hình ảnh)
// điểm loé nằm ở RÌA thân kẻ va, trên đường nối 2 thân — không phải giữa người địch
function _idSparkAt(u, t){
  const dx=t.x-u.x, dy=t.y-u.y, d=Math.hypot(dx,dy)||1;
  _idFlashes.push({ x:u.x+dx/d*u.size, y:u.y+dy/d*u.size, life:13, maxLife:13, r:Math.max(9,u.size*0.62), ang:Math.random()*Math.PI });
}
