// ảnh upload của 1 ô (đã nạp xong) — không có thì trả null để vẽ emoji thay
function _sdSlotImg(arr, f, def){
  const im=arr && arr[f.slotIdx]; if(im && im.complete && im.naturalWidth>0) return im;
  const d=def && SD_ART[def]; return (d && d.complete && d.naturalWidth>0) ? d : null;
}
// vẽ ảnh upload (giữ tỉ lệ, cạnh dài = sz) hoặc emoji nếu ô trống; tâm tại gốc toạ độ hiện tại
function _sdDrawArt(im, em, sz){
  if(im){ const a=im.naturalWidth/im.naturalHeight, w=a>=1?sz:sz*a, h=a>=1?sz/a:sz;
    ctx.drawImage(_stickerMask(im), 0,0,im.naturalWidth,im.naturalHeight, -w/2,-h/2, w,h); }
  else ctx.drawImage(_emojiSprite(em,200), -sz/2,-sz/2, sz, sz);
}

// ==================== 😾⚔️ BERSERK CAT ====================
// Cứ mất 3% máu = +1 CỘNG DỒN. Mỗi cộng dồn: -1% sát thương nhận vào, +3% sát thương gây ra, -1% tốc di chuyển,
// +1% tốc đánh, kiếm dài thêm 2% (chỉ hình).
// Đánh bằng thanh ĐẠI KIẾM vác sau lưng: vung 1 đường vòng cung từ sau gáy bổ về phía địch. 100 dame gốc,
// 0.6 đòn/s, tầm với ×1.2 cận chiến thường (dài ra theo cỡ kiếm), trúng là địch lùi tí ti.
// ⚠️ hồi chiêu toàn game chỉ trừ 0.85/tick (luật chung -15% tốc đánh) → muốn ĐÚNG 0.6 đòn/s thực (100 tick)
// thì đặt 100×0.85 = 85. Đo trong trận: 85 → nhát vung cách nhau đúng 100 tick.
const BK_SWING_T=16, BK_ATK_CD=85;
function _bkStacks(f){ return Math.floor(((f.maxHp-Math.max(0,f.hp))/f.maxHp*100+1e-9)/3); }
// tầm chém = ×1.2 tầm cận chiến thường, và dài ra ĐÚNG theo cỡ kiếm (+1% mỗi 3% máu mất)
const BK_UNSTOP_HP=0.30;   // 😾 dưới 30% máu: miễn mọi đẩy lùi + choáng
function _bkReach(f){ return MELEE_REACH*1.2*(1+_bkStacks(f)/100); }
// nhát nào trúng cũng đẩy địch lùi TÍ TI cho có cảm giác chém (cú húc Capybara là 21).
// ⚠️ phải ĐẶT THẲNG vận tốc, không được cộng thêm: moveLogic() tự reset mọi vận tốc < 55% tốc tối đa về hướng cũ,
// nên cộng 1 lực nhỏ vào vận tốc đang lao tới là bị xoá sạch (đo được: cộng 2.5 → địch không lùi chút nào).
const BK_KNOCK=4.5;
function _bkLost(f){ return Math.max(0,Math.min(1,1-f.hp/f.maxHp)); }
// bản phủ ĐỎ của sprite (cùng khuôn sticker) — bake 1 lần mỗi ảnh
function _bkRedMask(img){
  if(img._bkRed) return img._bkRed;
  const src=_stickerMask(img);
  const c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const g=c.getContext('2d'); g.drawImage(src,0,0);
  g.globalCompositeOperation='source-atop'; g.fillStyle='#ff1a1a'; g.fillRect(0,0,c.width,c.height);
  img._bkRed=c; return c;
}
// thanh đại kiếm: gốc toạ độ = chỗ tay cầm (ngay trên chắn kiếm), ang = hướng từ chuôi tới mũi
// ⚔️ ẢNH KIẾM do user cung cấp (sworkkrr.png, thu về 447×449). Đo bằng PCA trên pixel: kiếm nằm CHÉO, chuôi+núm ở
// góc DƯỚI-TRÁI, mũi ở góc TRÊN-PHẢI, trục chuôi→mũi nghiêng -45.5°. Chỗ tay cầm (giữa đoạn chuôi nâu sẫm) ở
// (16.4%, 83.7%) ảnh; chiều dài cả thanh dọc trục = 1239/894 bề ngang ảnh.
const BK_SWORD_IMG=new Image(); BK_SWORD_IMG.src='assets/img/berserkcat/BK_SWORD_IMG.webp';
const BK_SWORD_GRIP={x:0.164, y:0.837}, BK_SWORD_ANG=Math.atan2(44-840, 842-61), BK_SWORD_LEN_W=1239/894;
function _bkDrawSword(hx,hy,ang,L,d){
  const im=BK_SWORD_IMG;
  if(im.complete && im.naturalWidth>0){
    const w=L/BK_SWORD_LEN_W, h=w*im.naturalHeight/im.naturalWidth;
    ctx.save(); ctx.translate(hx,hy); ctx.rotate(ang);
    if(d<0) ctx.scale(1,-1);                          // vung sang trái: lật qua trục kiếm cho mặt kiếm không bị ngửa ngược
    ctx.rotate(-BK_SWORD_ANG);
    ctx.drawImage(im, -BK_SWORD_GRIP.x*w, -BK_SWORD_GRIP.y*h, w, h);
    ctx.restore();
    return;
  }
  _bkDrawSwordVec(hx,hy,ang,L);
}
// (dự phòng lúc ảnh chưa nạp xong) kiếm vẽ bằng nét
function _bkDrawSwordVec(hx,hy,ang,L){
  const w=L*0.14;
  ctx.save(); ctx.translate(hx,hy); ctx.rotate(ang);
  ctx.lineJoin='round';
  // chuôi + núm
  ctx.fillStyle='#3e2723'; ctx.fillRect(-L*0.2, -w*0.2, L*0.2, w*0.4);
  ctx.beginPath(); ctx.arc(-L*0.21, 0, w*0.3, 0, Math.PI*2); ctx.fill();
  // lưỡi — sắt xám thô, sống sẫm, mũi vát
  ctx.beginPath();
  ctx.moveTo(w*0.2, -w*0.5); ctx.lineTo(L*0.9, -w*0.5); ctx.lineTo(L, 0); ctx.lineTo(L*0.9, w*0.5); ctx.lineTo(w*0.2, w*0.5); ctx.closePath();
  ctx.fillStyle='#8a9299'; ctx.fill();
  ctx.lineWidth=Math.max(1.2,w*0.12); ctx.strokeStyle='#1c1c1c'; ctx.stroke();
  ctx.fillStyle='#cfd8dc'; ctx.fillRect(w*0.3, -w*0.5, L*0.58, w*0.16);          // ánh sáng mép lưỡi
  ctx.fillStyle='#5f676d'; ctx.fillRect(w*0.3, -w*0.06, L*0.6, w*0.12);         // rãnh giữa lưỡi
  // chắn kiếm
  ctx.fillStyle='#2b2b2b'; ctx.fillRect(0, -w*1.05, w*0.32, w*2.1);
  ctx.restore();
}
// vẽ kiếm lúc đang VUNG (vẽ sau meme, nằm trên thân) — ngoài lúc chém thì không có kiếm
function _bkDrawSwords(back){
  for(const f of fighters){
    if(f.type!=='berserkcat' || f.dead) continue;
    // ⚠️ nhát chém KẾT LIỄU: địch chết thì khối đếm lùi trong doAbility không chạy nữa (hết mục tiêu) → nhát
    // chém kẹt giữa chừng, kiếm + vệt chém đứng hình mãi trên màn. Hết địch sống thì tự vung nốt cho xong ở đây.
    if((f._bkSwingT||0)>0 && !battleFreezeTimer && !fighters.some(o=>o.team!==f.team && !o.dead)) f._bkSwingT--;
    const s=f.size, L=s*2.0*(1+2*_bkStacks(f)/100);   // mỗi 3% máu mất = kiếm DÀI thêm 2% (chỉ là hình, cả vệt chém theo cùng)
    const swinging=(f._bkSwingT||0)>0;
    if(!back && swinging){   // kiếm CHỈ xuất hiện lúc chém (không còn vác sau lưng)
      const d=f._bkDir||1, aim=f._bkAim||0;
      const a0=aim-d*2.4, a1=aim+d*0.8;
      const pr=1-f._bkSwingT/BK_SWING_T, e=1-Math.pow(1-pr,3);     // vung nhanh, chậm dần cuối nhát
      const a=a0+(a1-a0)*e;
      const px=f.x+d*s*0.1, py=f.y-s*0.1;
      // vệt chém vòng cung theo đúng quãng lưỡi kiếm vừa quét qua
      const lo=Math.min(a0,a), hi=Math.max(a0,a);
      ctx.save(); ctx.globalAlpha=0.38*(1-pr*0.6);
      ctx.fillStyle='#ff3030';
      ctx.beginPath(); ctx.arc(px,py,L*1.02,lo,hi); ctx.arc(px,py,L*0.55,hi,lo,true); ctx.closePath(); ctx.fill();
      ctx.globalAlpha=0.55*(1-pr*0.6); ctx.strokeStyle='#ffffff'; ctx.lineWidth=Math.max(1.5,s*0.05);
      ctx.beginPath(); ctx.arc(px,py,L*0.98,lo,hi); ctx.stroke();
      ctx.restore();
      _bkDrawSword(px,py,a,L,d);
    }
  }
}

// 😺💨 POP CAT — VÒNG KHÓI chữ O kiểu thổi vape, dựng từ cụm khói nhiễu thật (_gpPuff, cùng bộ khói cảnh Gary bị nhập):
//    2 lớp (bóng xám phía dưới + khói trắng), cụm khói xoay nhẹ quanh vòng, mép gợn như khói thật. Bay càng xa vòng càng
//    TO và mỏng dần; sát mép sàn thì loang rộng ra, mờ dần rồi tan biến. Trúng đích thì bung ra tan thành khói tại chỗ.
let popRingFx=[];
// ☁️ mẫu MÂY KHÓI ĐẶC cho Pop Cat (khói vape: lõi gần như đục, mép mềm, vân nhẹ) — khác khói tơi lốm đốm của _gpSmoke
const _popCloudCv=[];
function _popCloudSprite(v){
  v=((v%4)+4)%4; if(_popCloudCv[v]) return _popCloudCv[v];
  const N=96, c=document.createElement('canvas'); c.width=c.height=N; const g=c.getContext('2d'), id=g.createImageData(N,N), D=id.data;
  const hs=(i,j)=>{ let n=Math.imul(i,374761393)^Math.imul(j,668265263)^Math.imul(v*131+7,1442695041); n=Math.imul(n^(n>>>13),1274126177); n^=n>>>16; return (n>>>0)/4294967296; };
  const vn=(x,y)=>{ const xi=Math.floor(x), yi=Math.floor(y), xf=x-xi, yf=y-yi, u=xf*xf*(3-2*xf), w=yf*yf*(3-2*yf);
    const a=hs(xi,yi), b=hs(xi+1,yi), cc=hs(xi,yi+1), d=hs(xi+1,yi+1); return a+(b-a)*u+(cc-a)*w+(a-b-cc+d)*u*w; };
  for(let y=0;y<N;y++) for(let x=0;x<N;x++){
    const nx=x/N*2-1, ny=y/N*2-1, n=0.6*vn(nx*3+5,ny*3+2)+0.4*vn(nx*7+1,ny*7+9), r=Math.hypot(nx,ny)/(0.78+0.22*n);
    const fall=Math.max(0,1-r*r), a=Math.pow(fall,0.9)*(0.7+0.3*n);
    const k=(y*N+x)*4, sh=Math.round(196+26*n);   // xám bạc, vân nhẹ (không trắng tinh)
    D[k]=sh; D[k+1]=sh+3; D[k+2]=Math.min(255,sh+11); D[k+3]=Math.round(Math.min(1,a)*255);
  }
  g.putImageData(id,0,0); return _popCloudCv[v]=c;
}
function _popCloud(v,x,y,r,rot,a){
  if(!(a>0.004) || !(r>0.3)) return;
  ctx.save(); ctx.globalAlpha*=Math.min(1,a); ctx.translate(x,y); ctx.rotate(rot); ctx.drawImage(_popCloudSprite(v),-r,-r,r*2,r*2); ctx.restore();
}
function _popRingState(p){
  const tr=Math.hypot(p.x-(p.spawnX??p.x), p.y-(p.spawnY??p.y)), fade=(p._fade===undefined?1:p._fade), spread=1-fade;
  // vòng KHÔNG to dần nữa: mỗi vòng 1 cỡ riêng chốt lúc bắn (p._sz, chênh nhau 10–40%), ĐẶC suốt đường bay;
  // chỉ khi sát mép sàn mới loang ra, mờ dần rồi tan. Mới phụt khỏi mồm thì nở nhanh từ 60% → đủ cỡ trong ~0.1s.
  // bay xa thì TO dần, tối đa +50% so với cỡ lúc bắn (đạt mức đó sau ~400px); viền khói MỎNG dần khi vòng to ra
  const base=(p._sz||14), g=Math.min(1,tr/400), pop=Math.min(1,0.6+tr/40), r=base*pop*(1+0.5*g)*(1+0.35*spread);
  return { r, th:(base*0.38+1.5)*(1-0.4*g)*(1+spread*0.5), a:fade, spread, dir:Math.atan2(p.vy,p.vx) };
}
// vòng khói nhìn NGANG (như ảnh mẫu): quay vuông góc hướng bay → dẹt theo hướng bay, 2 thuỳ trên/dưới đặc nhất
function _popRingDraw(x,y,st,seed,t){
  const {r,th,a,spread,dir}=st; if(a<=0.01) return;
  const rx=r*0.72, ry=r;
  ctx.save(); ctx.translate(x,y); ctx.rotate(dir); ctx.lineCap='round';
  const ring=(lw,col,al)=>{ ctx.globalAlpha=al; ctx.strokeStyle=col; ctx.lineWidth=lw; ctx.beginPath(); ctx.ellipse(0,0,rx,ry,0,0,Math.PI*2); ctx.stroke(); };
  // (lỗ giữa để TRỐNG — phủ khói mờ vào thì vòng trông như bị lấp đầy, mất chữ O)
  // 🎨 xám bạc ngả xanh nhẹ như khói vape thật — KHÔNG trắng tinh (trắng tinh nhìn như vẽ, giả)
  ring(th*1.45,'rgb(190,196,207)',0.22*a);          // quầng khói bao ngoài
  ring(th*1.15,'rgb(203,208,218)',0.45*a);
  ring(th,'rgb(212,216,225)',0.72*a*(1-spread*0.5)); // thân vòng
  ring(th*0.5,'rgb(228,231,237)',0.55*a*(1-spread)); // lõi sáng hơn chút
  for(const sy of [-1,1]){                          // 2 thuỳ trên/dưới dày đặc nhất
    const R=th*0.85, g=ctx.createRadialGradient(0,sy*ry,0,0,sy*ry,R);
    g.addColorStop(0,`rgba(230,233,239,${0.4*a*(1-spread*0.6)})`); g.addColorStop(1,'rgba(230,233,239,0)');
    ctx.globalAlpha=1; ctx.fillStyle=g; ctx.fillRect(-R,sy*ry-R,R*2,R*2);
  }
  // khói tơi bám quanh vòng (nhiều hơn khi đang tan)
  for(let i=0;i<16;i++){   // mép cuộn như mây đặc
    const an=i/16*Math.PI*2+t*0.03+seed, w=1+0.1*Math.sin(i*2.3+t*0.07+seed)+spread*0.25*Math.sin(i*1.7+seed);
    _popCloud(i+((seed*7)|0),Math.cos(an)*rx*w*1.08,Math.sin(an)*ry*w*1.08,th*(0.6+spread*0.8),an+t*0.01,a*(0.55-0.3*spread));
  }
  ctx.restore();
}
function _popRingBurst(p){ popRingFx.push({k:'burst',x:p.x,y:p.y,st:_popRingState(p),seed:p._seed||0,t:p._t||0,n:0,max:22}); }
// khói vương ở MỒM Pop Cat mỗi lần phả vòng: vài cụm khói bám theo miệng, trôi ra trước + bay lên, tan dần
function _popMouthSmoke(f,ang){ popRingFx.push({k:'mouth',owner:f,ang,n:0,max:44,seed:Math.random()*6.28}); }
function _popRingFxDraw(){
  for(let i=popRingFx.length-1;i>=0;i--){ const f=popRingFx[i]; f.n++;
    const q=f.n/f.max; if(q>=1 || (f.owner&&f.owner.dead)){ popRingFx.splice(i,1); continue; }
    if(f.k==='wisp'){ f.x+=f.vx; f.y+=f.vy; f.vx*=0.95; f.vy*=0.95;
      _popCloud((f.seed*3)|0, f.x, f.y, f.r*(1+1.8*q), f.seed+q*0.8, f.a*Math.pow(1-q,1.6)*(q<0.1?q/0.1:1)); continue; }
    if(f.k==='burst'){ const st=Object.assign({},f.st,{r:f.st.r*(1+0.15*q),a:f.st.a*Math.pow(1-q,1.3),spread:0});   // trúng địch: giữ NGUYÊN dáng vòng, chỉ nhạt dần rồi tan
      _popRingDraw(f.x,f.y,st,f.seed,f.t+f.n); continue; }
    const o=f.owner, mx=o.x+Math.cos(f.ang)*o.size*0.48, my=o.y+Math.sin(f.ang)*o.size*0.48-o.size*0.08;
    // 😮‍💨 thở khói kiểu VAPE: từng cụm phụt THẲNG ra trước theo hướng bắn, có QUÁN TÍNH (lao nhanh rồi chậm dần),
    //    vừa trôi vừa loang rộng + tơi ra 2 bên, chỉ hơi bốc nhẹ lên ở cuối — không phải cột khói đám cháy bay thẳng lên
    const ca=Math.cos(f.ang), sa=Math.sin(f.ang);
    for(let k=0;k<10;k++){
      const del=k*1.2, qk=Math.max(0,(f.n-del)/(f.max-del)); if(qk<=0) continue;
      const sp=0.6+0.6*_gpH(k*7+f.seed*10), D=o.size*(0.8+1.0*sp);
      const dist=D*(1-Math.pow(1-qk,3)), side=Math.sin(k*2.3+f.seed)*o.size*0.3*qk;
      const px=mx+ca*dist-sa*side, py=my+sa*dist+ca*side-o.size*0.12*qk*qk;
      _popCloud(k+((f.seed*3)|0),px,py,o.size*(0.08+0.26*qk)*(0.8+0.4*sp),k+qk*1.5,0.55*Math.pow(1-qk,1.3)*(qk<0.06?qk/0.06:1));
    }
  }
}
// ==================== 🦉 DUOLINGO — HỌC MUỘN: ĐỒNG HỒ 23s, STREAK FREEZE, "LAST CHANCE!" ====================
// • Đánh thường: bắn câu chào nhiều thứ tiếng, mỗi tiếng 1 kiểu bay (_duoShoot):
//     🇪🇸 ¡Hola! thẳng nhanh 35 · 🇫🇷 Bonjour~ lượn sóng 35 · 🇯🇵 こんにちは bay rồi tách 3 chữ kana 15/chữ
//     🇩🇪 HALLO! to chậm 50 + đẩy lùi · 🇷🇺 Привет nảy tường 2 lần 30
// • ĐỒNG HỒ "HỌC MUỘN" 23s treo trên đầu: 23→12s dạng 1 (dễ thương), 12→0s dạng 2 (khoanh tay: bắn nhanh ×1.5, mỗi lần 2 tiếng),
//   hết giờ mà trận chưa xong → DẠNG TỐI THƯỢNG "LAST CHANCE!" tới hết trận: 2 tia laser từ mắt quét qua lại (120 máu/s),
//   3s/lần 1 phát laser đỏ lớn vào địch (200), đánh thường 5 tiếng cùng lúc.
// • 🧊 STREAK FREEZE: 6s rơi 1 khối xuống sàn. ĐỊCH chạm vào → đồng hồ đứng 2s VÀ Duo bị nhốt trong khối băng vuông 2s
//   (rung lắc cố thoát, băng nứt dần rồi vỡ tung). Duo chạm vào thì khối vỡ, không có tác dụng.
// Quân triệu hồi có máu ăn đủ chữ + laser như meme.
const DUO_TPS=60*GAME_SPEED*TIME_SCALE;
const DUO_TIME=23, DUO_FORM2_AT=12, DUO_FREEZE_EVERY=4, DUO_FREEZE_T=2, DUO_HIT_SEC=0.3;
const DUO_SWEEP_DPS=120, DUO_BIG_DMG=200, DUO_BIG_CD=3;
// 🖼️ CÁC DẠNG theo đồng hồ (ảnh user gửi, đã tách nền). mul = bù cỡ để THÂN Duo cùng to dù ảnh có hào quang lửa bao quanh;
//    cy = tâm thân trong ảnh (hào quang bốc lên trên → thân lệch xuống, kéo ảnh lên cho thân đứng đúng chỗ); eyes = mắt laser (u,v)
// _noMask: KHÔNG qua _stickerMask (bước đó gọt viền + vứt phần bán trong suốt → mép lởm chởm, mất hào quang lửa); ảnh đã khử răng cưa sẵn
const _duoImg=(n,mul,cy,eyes)=>{ const im=new Image(); im._noMask=true; im.src='assets/img/duolingo/'+n+'.webp'; im._duoMul=mul; return {im,mul,cy,eyes}; };
const DUO_FREEZE_IMG=new Image(); DUO_FREEZE_IMG.src='assets/img/duolingo/DUO_FREEZE.webp';   // 🧊 icon Streak Freeze của app (Duolingo wiki)
const DUO_F={
  st1:_duoImg('DUO_ST1',1,0.47), st2:_duoImg('DUO_ST2',1.06,0.47), talk:_duoImg('DUO_TALK',1.05,0.5), cross:_duoImg('DUO_CROSS',1.05,0.5),
  wings:_duoImg('DUO_WINGS',1.15,0.5),   // 🔴 giơ 2 cánh, mắt sao — thân của dạng LAST CHANCE
};
// 🔴 dạng LAST CHANCE: dựng từ ảnh Duo giơ 2 cánh — thân sẫm lại, mép hắt đỏ lửa (như bị lửa giận bao trùm), mắt sao trắng nhói (vẽ thêm),
//    aura lửa nhọn kiểu Super Saiyan vẽ bằng code (_duoAuraDraw) — chỉ bật ở dạng này
DUO_F.ult={im:null, mul:1.15, cy:0.5, eyes:[[0.353,0.349],[0.643,0.344]]};
let _duoUltGlowCv=null;
function _duoUltBuild(){
  const src=DUO_F.wings.im; if(DUO_F.ult.im || !src.naturalWidth) return DUO_F.ult.im;
  const w=src.naturalWidth, h=src.naturalHeight, c=document.createElement('canvas'); c.width=w; c.height=h; const g=c.getContext('2d');
  g.drawImage(src,0,0); g.globalCompositeOperation='multiply'; g.fillStyle='#b4c88c'; g.fillRect(0,0,w,h);
  { const rg=g.createRadialGradient(w/2,h*0.5,w*0.2,w/2,h*0.5,w*0.62); rg.addColorStop(0,'rgba(255,40,10,0)'); rg.addColorStop(0.45,'rgba(255,40,10,0.12)'); rg.addColorStop(1,'rgba(255,30,10,0.9)'); g.globalCompositeOperation='source-atop'; g.fillStyle=rg; g.fillRect(0,0,w,h); }   // mép thân hắt đỏ lửa
  g.globalCompositeOperation='destination-in'; g.drawImage(src,0,0);
  c._noMask=true; c._duoMul=DUO_F.ult.mul; c.naturalWidth=w; c.naturalHeight=h; DUO_F.ult.im=c;
  // viền sáng rực quanh thân (bóng mờ màu cam của chính hình Duo)
  const P=Math.round(w*0.18), gc=document.createElement('canvas'); gc.width=w+P*2; gc.height=h+P*2; const gg=gc.getContext('2d');
  const sil=document.createElement('canvas'); sil.width=w; sil.height=h; const sg=sil.getContext('2d'); sg.drawImage(src,0,0); sg.globalCompositeOperation='source-in'; sg.fillStyle='#ff3c18'; sg.fillRect(0,0,w,h);
  gg.filter=`blur(${Math.round(w*0.035)}px)`; gg.drawImage(sil,P,P); gg.drawImage(sil,P,P); gg.filter='none';
  gc._pad=P/w; _duoUltGlowCv=gc;
  return c;
}
// dạng đang hiện: dễ thương → khó chịu → nổi giận (tới 12s) · khoanh tay → bốc lửa → mắt đỏ rực (tới 0s) · LAST CHANCE
function _duoPick(f){
  const D=f._duo; if(!D) return DUO_F.st1;
  const sec=D.clock/DUO_TPS, form=_duoForm(f);
  if(form===3){ _duoUltBuild(); return DUO_F.ult.im ? DUO_F.ult : DUO_F.wings; }
  if(form===2) return DUO_F.cross;
  if(f.actionState==='attack' && f.actionTimer>0) return DUO_F.talk;   // đang "giảng bài" bắn chữ
  return sec>17 ? DUO_F.st1 : DUO_F.st2;
}
const DUO_LANGS=[
  {k:'es', txt:'¡Hola!',  col:'#ff4b4b', spd:7.5, dmg:35},
  {k:'fr', txt:'Bonjour~',col:'#1cb0f6', spd:6,   dmg:35, wave:1},
  {k:'ja', txt:'こんにちは', col:'#ce82ff', spd:6.5, dmg:15, split:1},
  {k:'de', txt:'HALLO!',  col:'#ffc800', spd:4.5, dmg:50, big:1, push:1},
  {k:'ru', txt:'Привет',  col:'#58cc02', spd:6.5, dmg:30, bounce:2},
];
let duoWords=[], duoFreezes=[], duoFx=[];
function _duoReset(){ duoWords=[]; duoFreezes=[]; duoFx=[]; }
function _duoForm(f){ const D=f._duo; return !D?1:D.clock<=0?3:D.clock<=DUO_FORM2_AT*DUO_TPS?2:1; }
function _duoShoot(f,L,ang){
  duoWords.push({x:f.x+Math.cos(ang)*f.size*0.8, y:f.y+Math.sin(ang)*f.size*0.8, a:ang, L, owner:f, team:f.team, t:0, bounce:L.bounce||0, txt:L.txt, dmg:L.dmg, spd:L.spd, r:L.big?16:11});
}
// mắt Duo (toạ độ thế giới) — theo đúng ảnh đang vẽ
function _duoEyes(f){
  const S=f._lastSprite, E=(_duoPick(f).eyes)||DUO_F.ult.eyes; if(!S || !S.dw) return [[f.x-f.size*0.3,f.y-f.size*0.3],[f.x+f.size*0.3,f.y-f.size*0.3]];
  const X=f._duoXf; if(X) return E.map(([u,v])=>{ const lx=(u-0.5)*X.dw*X.sx, ly=(v-0.5)*X.dh*X.sy; return [X.cx+lx*X.c-ly*X.s, X.cy+lx*X.s+ly*X.c]; });   // 👁️ đúng phép biến đổi lúc vẽ thân (xoay/nhún/lệch/lật) → laser bám đúng mắt
  const oy=f._duoOffY||0; return E.map(([u,v])=>[f.x+(S.fl?-1:1)*(u-0.5)*S.dw, f.y-oy+(v-0.5)*S.dh]);
}
function _duoSegDist(px,py,ax,ay,bx,by){ const dx=bx-ax, dy=by-ay, l2=dx*dx+dy*dy||1, t=Math.max(0,Math.min(1,((px-ax)*dx+(py-ay)*dy)/l2)); return Math.hypot(px-ax-dx*t,py-ay-dy*t); }
function _duoHitUnit(u,dmg,owner,isBurn){ if(fighters.includes(u)) u.takeDamage(dmg,owner,false,!!isBurn); else _summonTakeDamage(u,dmg,owner,false,!!isBurn); }
let _duoLzSfx=null;   // 🔴 tiếng laser mắt quét (lặp suốt lúc LAST CHANCE đang chiếu)
function _duoLzSound(){ const on=fighters.some(f=>f.type==='duolingo' && !f.dead && f._duo && f._duo.beams);
  if(on && !_duoLzSfx){ const a=AUDIO_SAMPLES['duo_eye_laser']; if(a){ try{ const c=a.cloneNode(); c.loop=true; c.volume=0.85; _mixRoute(c); c.play().catch(()=>{}); _duoLzSfx=c; }catch(e){} } }
  else if(!on && _duoLzSfx){ _stopLoopAudio(_duoLzSfx); _duoLzSfx=null; } }
function _duoTick(){
  _duoLzSound();
  for(const f of fighters){
    if(f.type!=='duolingo' || f.dead) continue;
    const D=f._duo||(f._duo={clock:Math.round(DUO_TIME*DUO_TPS), shot:30, frz:Math.round(DUO_FREEZE_EVERY*DUO_TPS), ice:0, big:Math.round(DUO_BIG_CD*DUO_TPS), sweep:0, form:1});
    if(f._introLock>0) continue;
    // 🧊 đang bị nhốt trong băng: đứng im, đồng hồ đứng
    if(D.ice>0){ D.ice--; f.vx=0; f.vy=0; f.stun=Math.max(f.stun||0,2);
      if(D.ice===0){ playSample('duo_ice_break',1.0); addShake(5,8);   /* 🧊 tiếng băng vỡ riêng (myinstants), không dùng tiếng tượng Mewing */
        for(let k=0;k<18;k++){ const a=Math.random()*Math.PI*2, sp=1.5+Math.random()*3.5; duoFx.push({k:'shard',x:f.x+(Math.random()-0.5)*f.size,y:f.y+(Math.random()-0.5)*f.size,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-2,r:3+Math.random()*6,rot:Math.random()*6,vr:(Math.random()-0.5)*0.4,t:0,T:40+Math.random()*20}); } }
      continue; }
    if(D.clock>0) D.clock--;
    const form=_duoForm(f);
    if(form!==D.form){ D.form=form;
      if(form===2){ floatTexts.push({x:f.x,y:f.y-f.size-40,text:'⏰ Your streak is about to end…',color:'#ff9600',life:90,big:true}); playSample('vine_boom',0.5); }
      if(form===3){ floatTexts.push({x:f.x,y:f.y-f.size-40,text:'🔴 LAST CHANCE!',color:'#ff4b4b',life:120,big:true}); playSample('duo_mibombo',1.0);   /* 💣 meme "mi bombo" của Duo (không dùng tiếng sấm) */ addShake(12,20); D.sweep=0; } }
    // 🧊 rơi Streak Freeze mỗi 4s (chỉ khi đồng hồ còn chạy, tối đa 1 khối trên sàn)
    if(form<3 && --D.frz<=0){ D.frz=Math.round(DUO_FREEZE_EVERY*DUO_TPS);
      if(duoFreezes.filter(z=>z.owner===f).length<1){ let x,y,n=0; do{ x=40+Math.random()*(W-80); y=40+Math.random()*(H-80); }while(++n<20 && Math.hypot(x-f.x,y-f.y)<120);
        duoFreezes.push({x,y,owner:f,team:f.team,t:0}); } }
    // 🗣️ đánh thường: câu chào nhiều thứ tiếng
    const e=_sdFoe(f);
    if(--D.shot<=0 && e && !f._isHardCC()){
      D.shot=Math.round(DUO_TPS*(form===1?1:form===2?0.67:0.8));
      const a=Math.atan2(e.y-f.y,e.x-f.x), n=form===1?1:form===2?2:5;
      const pool=[...DUO_LANGS].sort(()=>Math.random()-0.5);
      for(let i=0;i<n;i++) _duoShoot(f,pool[i%pool.length],a+(i-(n-1)/2)*(n>2?0.22:0.16));
      f.actionState='attack'; f.actionTimer=12;
    }
    // 🔴 DẠNG TỐI THƯỢNG: laser mắt quét + laser lớn
    if(form===3){
      D.sweep++;
      const base=e?Math.atan2(e.y-f.y,e.x-f.x):0, sw=Math.sin(D.sweep*0.045)*0.9;
      D.beams=_duoEyes(f).map(([ex,ey],i)=>{ const ang=base+sw*(i?1:-1)*0.6+sw*0.4; return [ex,ey,ex+Math.cos(ang)*900,ey+Math.sin(ang)*900]; });
      const step=Math.round(DUO_TPS/6);
      for(const u of [...fighters.filter(o=>!o.dead && o.team!==f.team), ..._summonFoes(f.team)]){
        if((u._duoLzCD||0)>0){ u._duoLzCD--; continue; }
        if(D.beams.some(([ax,ay,bx,by])=>_duoSegDist(u.x,u.y,ax,ay,bx,by)<(u.size||20)*0.6+5)){ u._duoLzCD=step; _duoHitUnit(u,Math.round(DUO_SWEEP_DPS/6),f,true); u.flash=8; }
      }
      if(e && --D.big<=0){ D.big=Math.round(DUO_BIG_CD*DUO_TPS); D.bigT={t:0,tx:e.x,ty:e.y,tgt:e}; }
      if(D.bigT){ const B=D.bigT; B.t++;
        if(B.t<Math.round(DUO_TPS*0.5) && B.tgt && !B.tgt.dead){ B.tx=B.tgt.x; B.ty=B.tgt.y; }   // ngắm 0.5s (bám theo) rồi bắn
        if(B.t===Math.round(DUO_TPS*0.5)){ playSample('duo_big_laser',1.0); addShake(9,10);   /* 🔴 tiếng laser lớn riêng (myinstants beam-magnum — tiếng sáng, loa nhỏ vẫn nghe rõ) */
          const [mx,my]=_duoEyes(f).reduce((s,p)=>[s[0]+p[0]/2,s[1]+p[1]/2],[0,0]), ang=Math.atan2(B.ty-my,B.tx-mx); B.seg=[mx,my,mx+Math.cos(ang)*900,my+Math.sin(ang)*900];
          for(const u of [...fighters.filter(o=>!o.dead && o.team!==f.team), ..._summonFoes(f.team)])
            if(_duoSegDist(u.x,u.y,...B.seg)<(u.size||20)*0.7+14) _duoHitUnit(u,DUO_BIG_DMG,f); }
        if(B.t>Math.round(DUO_TPS*0.85)) D.bigT=null; }
    } else D.beams=null;
  }
  // 🧊 nhặt Streak Freeze (Duo KHÔNG phá được — chỉ địch nhặt)
  for(let i=duoFreezes.length-1;i>=0;i--){ const z=duoFreezes[i]; z.t++;
    const o=z.owner; if(!o || o.dead || _duoForm(o)===3){ duoFreezes.splice(i,1); continue; }
    const g=[...fighters.filter(u=>!u.dead && u.team!==z.team), ..._summonFoes(z.team)].find(u=>!u.dead && (u.hp===undefined||u.hp>0) && Math.hypot(u.x-z.x,u.y-z.y)<(u.size||20)+28);   // khối to x2 → tầm chạm cũng x2 · quân triệu hồi có máu (2 mèo phụ Crying Cat, bản sao Doge...) cũng nhặt được
    if(g){ duoFreezes.splice(i,1); o._duo.ice=Math.round(DUO_FREEZE_T*DUO_TPS); o._duo.iceMax=o._duo.ice;
      playSample('duo_wrong',1.0); addShake(4,6);   // ❌ tiếng sai của app Duolingo
      floatTexts.push({x:o.x,y:o.y-o.size-40,text:'🧊 STREAK FREEZE!',color:'#84d8ff',life:70,big:true}); }
  }
  // 🗣️ chữ bay
  for(let i=duoWords.length-1;i>=0;i--){ const w=duoWords[i]; w.t++;
    const L=w.L; let vx=Math.cos(w.a)*w.spd, vy=Math.sin(w.a)*w.spd;
    if(L.wave){ const p=Math.cos(w.t*0.22)*2.4; vx+=-Math.sin(w.a)*p; vy+=Math.cos(w.a)*p; }
    w.x+=vx; w.y+=vy;
    if(w.bounce>0){ if(w.x<w.r||w.x>W-w.r){ w.a=Math.PI-w.a; w.bounce--; w.x=Math.max(w.r,Math.min(W-w.r,w.x)); } if(w.y<w.r||w.y>H-w.r){ w.a=-w.a; w.bounce--; w.y=Math.max(w.r,Math.min(H-w.r,w.y)); } }
    if(L.split && !w.kana && w.t===20){ duoWords.splice(i,1);
      for(const [k,da] of [['こ',-0.32],['に',0],['ち',0.32]]) duoWords.push({...w, a:w.a+da, txt:k, kana:true, r:9, t:21, spd:w.spd*1.1});
      continue; }
    let hit=null;
    for(const u of [...fighters.filter(o=>!o.dead && o.team!==w.team), ..._summonFoes(w.team)]) if(Math.hypot(u.x-w.x,u.y-w.y)<(u.size||20)+w.r){ hit=u; break; }
    if(hit){ _duoHitUnit(hit,w.dmg,w.owner);
      if(tick-(_duoTick._snd||-99)>=6){ _duoTick._snd=tick; playSample('duo_correct',0.9); }   // ✅ tiếng "correct" của app mỗi đòn trúng (cùng nhịp chỉ 1 tiếng)
      { const D=w.owner && w.owner._duo; if(D && D.clock>0 && !w.owner.dead){ D.clock=Math.max(0,D.clock-Math.round(DUO_TPS*DUO_HIT_SEC)); D.tickFx=12; } }   // ⏰ mỗi lần trúng: đồng hồ tụt 0.3s
      if(L.push){ const a=Math.atan2(hit.y-w.y,hit.x-w.x); hit.vx=(hit.vx||0)+Math.cos(a)*6; hit.vy=(hit.vy||0)+Math.sin(a)*6; }
      duoFx.push({k:'pop',x:w.x,y:w.y,col:L.col,t:0,T:14}); duoWords.splice(i,1); continue; }
    if(w.t>200 || w.x<-60||w.x>W+60||w.y<-60||w.y>H+60) duoWords.splice(i,1);
  }
}
// 🔥 AURA LỬA DUO (vẽ bằng code, sống động thay cho aura vẽ cứng trong ảnh): lưỡi lửa liếm lên quanh mép thân + tàn lửa bay,
//    lập loè liên tục. pal = bảng màu theo nấc giận; k = độ dữ (0..1). (cx,cy) tâm thân, rx/ry bán kính thân.
const DUO_AURA_PAL={
  green: {core:[235,255,170], mid:[140,225,70],  tip:[60,170,30],  glow:[120,230,80]},
  gold:  {core:[255,250,200], mid:[255,205,60],  tip:[255,140,20], glow:[255,200,70]},
  orange:{core:[255,240,180], mid:[255,150,30],  tip:[240,70,10],  glow:[255,140,40]},
  red:   {core:[255,225,190], mid:[255,70,30],   tip:[170,0,0],    glow:[255,40,30]},
  ult:   {core:[255,205,90],  mid:[255,62,16],   tip:[210,0,0],    glow:[255,30,20]},   // 🔴 LAST CHANCE: lửa nhọn bao kín người
};
const _duoRGBA=(c,a)=>`rgba(${c[0]},${c[1]},${c[2]},${a})`;
function _duoAuraDraw(st,cx,cy,rx,ry,pal,k,tm){
  const P=DUO_AURA_PAL[pal]; if(!P || k<=0.01) return;
  st.parts=st.parts||[];
  const ULT=pal==='ult';
  ctx.save();
  if(ULT){   // quầng ĐỎ đậm bao ngoài (màu thật, không cộng sáng)
    const R=Math.max(rx,ry)*1.75, gr=ctx.createRadialGradient(cx,cy,Math.min(rx,ry)*0.7,cx,cy,R);
    gr.addColorStop(0,'rgba(255,40,20,0.55)'); gr.addColorStop(0.6,'rgba(230,20,10,0.28)'); gr.addColorStop(1,'rgba(200,0,0,0)');
    ctx.fillStyle=gr; ctx.beginPath(); ctx.ellipse(cx,cy,R,R*0.95,0,0,Math.PI*2); ctx.fill(); }
  ctx.globalCompositeOperation='lighter';
  // ① quầng sáng mờ quanh thân, "thở" theo nhịp
  const br=1+0.05*Math.sin(tm*6)+0.03*Math.sin(tm*13.7);
  const g=ctx.createRadialGradient(cx,cy,Math.min(rx,ry)*0.6,cx,cy,Math.max(rx,ry)*1.5*br);
  g.addColorStop(0,_duoRGBA(P.glow,0.35*k)); g.addColorStop(0.55,_duoRGBA(P.glow,0.16*k)); g.addColorStop(1,_duoRGBA(P.glow,0));
  ctx.fillStyle=g; ctx.beginPath(); ctx.ellipse(cx,cy,rx*1.5*br,ry*1.4*br,0,0,Math.PI*2); ctx.fill();
  ctx.globalCompositeOperation='source-over';   // lửa: màu THẬT (cộng sáng lên nền xanh sẽ ra trắng/hồng, không ra lửa)
  // ② lưỡi lửa lớn: gốc bám mép thân (nửa trên + 2 bên), liếm hướng lên, mỗi lưỡi dài/ngắn + uốn theo nhiễu riêng
  const N=ULT?30:Math.round(13+9*k);
  for(let i=0;i<N;i++){
    const u=i/(N-1), a=ULT ? Math.PI*(0.72+u*1.56)+Math.sin(i*7.3)*0.04       // ULT: bao kín từ dưới-trái, qua đỉnh, xuống dưới-phải
                           : Math.PI*(1.08+u*0.84)+Math.sin(i*7.3)*0.05;          // từ trái-dưới vòng qua đỉnh sang phải-dưới
    const bx=cx+Math.cos(a)*rx*0.92, by=cy+Math.sin(a)*ry*0.92;
    const side=Math.cos(a), up=0.35+0.65*(1-Math.abs(side));                // lưỡi ở đỉnh dài hơn ở hai bên
    const fl=0.55+0.45*Math.sin(tm*(7+i%5)+i*1.9)*Math.sin(tm*(3.1+i%3)+i);   // lập loè
    const fl2=ULT?0.55+0.45*Math.sin(tm*(13+i%7)+i*2.7):fl;                  // ULT: giật nhanh, gắt hơn
    const L=ULT ? ry*(0.6+0.65*up)*(0.55+0.6*fl2)*(0.8+0.45*(i%3===0)) *k : ry*(0.45+0.75*up)*(0.6+0.6*fl)*(0.55+0.75*k);
    const w=ULT ? rx*(0.15+0.08*up) : rx*(0.2+0.12*up)*(0.85+0.3*k);
    const sway=Math.sin(tm*(ULT?9:5)+i*2.3)*w*(ULT?0.6:0.9);
    const dx=ULT?Math.cos(a)*0.9:side*0.55, dy=ULT?Math.min(-0.35,Math.sin(a)*0.7-0.75):-1, dl=Math.hypot(dx,dy);   // ULT: toả ra mọi phía rồi vút lên
    const tx=bx+dx/dl*L+sway, ty=by+dy/dl*L;
    const nx=-dy/dl, ny=dx/dl;
    const gr=ctx.createLinearGradient(bx,by,tx,ty);
    gr.addColorStop(0,_duoRGBA(P.mid,0.95)); gr.addColorStop(0.45,_duoRGBA(P.mid,0.85)); gr.addColorStop(0.8,_duoRGBA(P.tip,0.55)); gr.addColorStop(1,_duoRGBA(P.tip,0));
    ctx.fillStyle=gr; ctx.beginPath();
    ctx.moveTo(bx+nx*w,by+ny*w);
    ctx.quadraticCurveTo(bx+nx*w*0.9+(tx-bx)*0.5+sway*0.3,by+ny*w*0.9+(ty-by)*0.5,tx,ty);
    ctx.quadraticCurveTo(bx-nx*w*0.9+(tx-bx)*0.5+sway*0.3,by-ny*w*0.9+(ty-by)*0.5,bx-nx*w,by-ny*w);
    ctx.closePath(); ctx.fill();
    const ix=bx+(tx-bx)*0.55, iy=by+(ty-by)*0.55, gi=ctx.createLinearGradient(bx,by,ix,iy);   // lõi sáng vàng
    gi.addColorStop(0,_duoRGBA(P.core,0.95)); gi.addColorStop(1,_duoRGBA(P.core,0));
    ctx.fillStyle=gi; ctx.beginPath(); ctx.moveTo(bx+nx*w*0.5,by+ny*w*0.5); ctx.quadraticCurveTo(bx+(ix-bx)*0.5+sway*0.15,by+(iy-by)*0.5,ix,iy); ctx.quadraticCurveTo(bx+(ix-bx)*0.5+sway*0.15,by+(iy-by)*0.5,bx-nx*w*0.5,by-ny*w*0.5); ctx.closePath(); ctx.fill();
  }
  ctx.globalCompositeOperation='lighter';
  // ③ đốm lửa / tàn lửa bốc lên từ mép thân
  const want=Math.round(26*k);
  for(let n=0;n<3 && st.parts.length<want;n++){ const a=Math.PI*(1.05+Math.random()*0.9);
    st.parts.push({x:cx+Math.cos(a)*rx*0.9, y:cy+Math.sin(a)*ry*0.9, vx:Math.cos(a)*0.4+(Math.random()-0.5)*0.4, vy:-(0.8+Math.random()*1.3), r:rx*(0.08+Math.random()*0.1), t:0, T:22+Math.random()*20}); }
  for(let i=st.parts.length-1;i>=0;i--){ const p=st.parts[i]; p.t++; if(p.t>p.T){ st.parts.splice(i,1); continue; }
    p.x+=p.vx+Math.sin(p.t*0.3+i)*0.3; p.y+=p.vy; const q=p.t/p.T, r=p.r*(1-q*0.7);
    const c=q<0.3?P.core:q<0.65?P.mid:P.tip, rg=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,r);
    rg.addColorStop(0,_duoRGBA(c,0.7*k*(1-q))); rg.addColorStop(1,_duoRGBA(c,0)); ctx.fillStyle=rg; ctx.beginPath(); ctx.arc(p.x,p.y,r,0,Math.PI*2); ctx.fill(); }
  ctx.restore();
}
// ✨ mắt laser lấp lánh (sao 4 cánh trắng + quầng đỏ), xoay/nhói theo nhịp — vẽ TRÊN thân
function _duoEyeStar(x,y,R,tm,seed){
  const p=1+0.18*Math.sin(tm*14+seed)+0.1*Math.sin(tm*31+seed*2);
  ctx.save();
  { const e=ctx.createRadialGradient(x,y,0,x,y,R*1.15); e.addColorStop(0,'rgba(255,235,225,1)'); e.addColorStop(0.7,'rgba(255,120,100,0.95)'); e.addColorStop(1,'rgba(255,60,40,0)');   // che con ngươi cũ: cả hốc mắt sáng rực
    ctx.fillStyle=e; ctx.beginPath(); ctx.arc(x,y,R*1.15,0,Math.PI*2); ctx.fill(); }
  ctx.globalCompositeOperation='lighter';
  const g=ctx.createRadialGradient(x,y,0,x,y,R*1.6*p); g.addColorStop(0,'rgba(255,255,255,0.95)'); g.addColorStop(0.25,'rgba(255,120,110,0.75)'); g.addColorStop(1,'rgba(255,0,0,0)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,R*1.6*p,0,Math.PI*2); ctx.fill();
  ctx.translate(x,y); ctx.rotate(Math.sin(tm*2+seed)*0.08); ctx.fillStyle='rgba(255,255,255,0.95)';
  for(const [lx,ly] of [[R*0.22*p,R*1.55*p],[R*1.1*p,R*0.2*p]]){ ctx.beginPath(); ctx.moveTo(0,-ly); ctx.quadraticCurveTo(lx*0.25,-lx*0.25,lx,0); ctx.quadraticCurveTo(lx*0.25,lx*0.25,0,ly); ctx.quadraticCurveTo(-lx*0.25,lx*0.25,-lx,0); ctx.quadraticCurveTo(-lx*0.25,-lx*0.25,0,-ly); ctx.fill(); }
  ctx.restore();
}

// 🔴 sàn đỏ rực dưới chân (dạng tối thượng) + khối Streak Freeze nằm trên sàn
function _duoDrawUnder(){
  if(fighters.some(f=>f.type==='duolingo' && !f.dead && _duoForm(f)===3)){ const C=_fxCoverRect(1.1), p=0.16+0.05*Math.sin(performance.now()/180);
    ctx.save(); ctx.fillStyle=`rgba(200,20,30,${p})`; ctx.fillRect(C[0],C[1],C[2],C[3]); ctx.restore(); }
  // 🔥 aura Super Saiyan quanh Duo LAST CHANCE (sau lưng thân)
  for(const f of fighters){ if(f.type!=='duolingo' || f.dead || _duoForm(f)!==3 || !f._lastSprite) continue;
    const S=f._lastSprite, cx=f.x, cy=f.y-(f._duoOffY||0), tm=performance.now()/1000, D=f._duo, boost=(D.bigT && D.bigT.t>=Math.round(DUO_TPS*0.35))?1.25:1;
    _duoAuraDraw(f._duoAura||(f._duoAura={}),cx,cy,S.dw*0.47,S.dh*0.45,'ult',boost,tm);
    if(_duoUltGlowCv){ const P=_duoUltGlowCv._pad, k=1.12+0.05*Math.sin(tm*11), w=S.dw*(1+2*P)*k, h=S.dh*(1+2*P)*k;
      ctx.save(); ctx.globalAlpha=0.9+0.1*Math.sin(tm*17); ctx.translate(cx,cy); if(S.fl) ctx.scale(-1,1); ctx.drawImage(_duoUltGlowCv,-w/2,-h/2,w,h); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=0.5; ctx.drawImage(_duoUltGlowCv,-w/2,-h/2,w,h); ctx.restore(); } }
  for(const z of duoFreezes){ const bob=Math.sin(z.t*0.08)*3, h=68, x=z.x, y=z.y+bob-20, pop=Math.min(1,z.t/12);   // 🧊 to gấp đôi (34 → 68)
    ctx.save(); ctx.fillStyle='rgba(0,0,0,0.18)'; ctx.beginPath(); ctx.ellipse(x,z.y+h*0.45,26*pop,8*pop,0,0,Math.PI*2); ctx.fill();
    if(DUO_FREEZE_IMG.naturalWidth){ const w=h*DUO_FREEZE_IMG.naturalWidth/DUO_FREEZE_IMG.naturalHeight;
      ctx.translate(x,y); ctx.scale(pop,pop); ctx.rotate(Math.sin(z.t*0.05)*0.08); ctx.drawImage(DUO_FREEZE_IMG,-w/2,-h/2,w,h);
      ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=0.25+0.2*Math.sin(z.t*0.15); ctx.drawImage(DUO_FREEZE_IMG,-w/2,-h/2,w,h); }   // lấp lánh
    ctx.restore(); }
}
// 🗣️ chữ bay + laser + khối băng nhốt Duo + đồng hồ trên đầu — vẽ TRÊN meme
function _duoDrawOver(){
  ctx.save(); ctx.textAlign='center'; ctx.textBaseline='middle';
  for(const w of duoWords){
    const fs=w.L.big?17:w.kana?14:12; ctx.font=`900 ${fs}px "Nunito","Arial Rounded MT Bold",sans-serif`;
    const tw=ctx.measureText(w.txt).width+12, th=fs+8;
    ctx.save(); ctx.translate(w.x,w.y); ctx.rotate(Math.sin(w.t*0.3)*0.08);
    ctx.fillStyle='#fff'; ctx.strokeStyle=w.L.col; ctx.lineWidth=2.5;
    ctx.beginPath(); ctx.roundRect?ctx.roundRect(-tw/2,-th/2,tw,th,th/2):ctx.rect(-tw/2,-th/2,tw,th); ctx.fill(); ctx.stroke();
    ctx.fillStyle='#3c3c3c'; ctx.fillText(w.txt,0,1); ctx.restore();
  }
  ctx.restore();
  for(let i=duoFx.length-1;i>=0;i--){ const e=duoFx[i]; e.t++; if(e.t>=e.T){ duoFx.splice(i,1); continue; } const u=e.t/e.T;
    if(e.k==='pop'){ ctx.strokeStyle=e.col; ctx.globalAlpha=1-u; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(e.x,e.y,6+u*16,0,Math.PI*2); ctx.stroke(); ctx.globalAlpha=1; }
    else if(e.k==='shard'){ e.x+=e.vx; e.y+=e.vy; e.vy+=0.2; e.rot+=e.vr; ctx.save(); ctx.globalAlpha=1-u; ctx.translate(e.x,e.y); ctx.rotate(e.rot);
      ctx.fillStyle='rgba(190,235,255,0.9)'; ctx.strokeStyle='rgba(255,255,255,0.9)'; ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(-e.r,-e.r*0.4); ctx.lineTo(e.r*0.6,-e.r); ctx.lineTo(e.r,e.r*0.5); ctx.lineTo(-e.r*0.3,e.r); ctx.closePath(); ctx.fill(); ctx.stroke(); ctx.restore(); } }
  for(const f of fighters){
    if(f.type!=='duolingo' || f.dead || !f._duo) continue;
    const D=f._duo, form=_duoForm(f);
    if(form===3 && f._lastSprite){ const tm=performance.now()/1000; _duoEyes(f).forEach(([ex,ey],i)=>_duoEyeStar(ex,ey,f._lastSprite.dw*0.085,tm,i*2.1)); }   // ✨ mắt sao trắng rực
    // 🔴 laser
    if(D.beams){ ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.lineCap='round';
      const _ey=_duoEyes(f); for(const [i,[,, bx,by]] of D.beams.entries()){ const [ax,ay]=_ey[i]||D.beams[i]; for(const [lw,c] of [[14,'rgba(255,40,40,0.25)'],[6,'rgba(255,90,90,0.7)'],[2.2,'rgba(255,240,240,1)']]){ ctx.lineWidth=lw; ctx.strokeStyle=c; ctx.beginPath(); ctx.moveTo(ax,ay); ctx.lineTo(bx,by); ctx.stroke(); } }   // gốc tia = mắt ở khung đang vẽ (không trễ 1 nhịp)
      for(const [ex,ey] of _ey){ const g=ctx.createRadialGradient(ex,ey,0,ex,ey,16); g.addColorStop(0,'rgba(255,255,255,0.95)'); g.addColorStop(1,'rgba(255,60,60,0)'); ctx.fillStyle=g; ctx.beginPath(); ctx.arc(ex,ey,16,0,Math.PI*2); ctx.fill(); }
      ctx.restore(); }
    if(D.bigT){ const B=D.bigT, aim=Math.round(DUO_TPS*0.5);
      ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.lineCap='round';
      if(B.t<aim){ const [mx,my]=_duoEyes(f).reduce((s,p)=>[s[0]+p[0]/2,s[1]+p[1]/2],[0,0]); ctx.setLineDash([6,6]); ctx.lineWidth=1.5; ctx.strokeStyle=`rgba(255,60,60,${0.4+0.5*Math.sin(B.t*0.6)**2})`; ctx.beginPath(); ctx.moveTo(mx,my); ctx.lineTo(B.tx,B.ty); ctx.stroke(); }
      else if(B.seg){ const k=1-(B.t-aim)/(DUO_TPS*0.35); for(const [lw,c] of [[34,`rgba(255,30,30,${0.35*k})`],[16,`rgba(255,110,110,${0.8*k})`],[6,`rgba(255,255,255,${k})`]]){ ctx.lineWidth=lw; ctx.strokeStyle=c; ctx.beginPath(); ctx.moveTo(B.seg[0],B.seg[1]); ctx.lineTo(B.seg[2],B.seg[3]); ctx.stroke(); } }
      ctx.restore(); }
    // 🧊 khối băng vuông nhốt Duo: nứt dần, rung theo cú giãy
    if(D.ice>0){ const S=f._lastSprite, K=(S&&S.img&&S.img._duoMul)||1, w=(S&&S.dw?S.dw/K:f.size*2)*1.15, h=(S&&S.dh?S.dh/K:f.size*2)*1.12, u=1-D.ice/(D.iceMax||1), jx=Math.sin(tick*1.9)*(1+u*3), jy=Math.cos(tick*2.3)*u*1.5;
      ctx.save(); ctx.translate(f.x+jx,f.y+jy);
      const g=ctx.createLinearGradient(-w/2,-h/2,w/2,h/2); g.addColorStop(0,'rgba(210,245,255,0.55)'); g.addColorStop(1,'rgba(90,190,240,0.45)');
      ctx.fillStyle=g; ctx.strokeStyle='rgba(235,250,255,0.95)'; ctx.lineWidth=3;
      ctx.beginPath(); ctx.roundRect?ctx.roundRect(-w/2,-h/2,w,h,6):ctx.rect(-w/2,-h/2,w,h); ctx.fill(); ctx.stroke();
      ctx.fillStyle='rgba(255,255,255,0.55)'; ctx.fillRect(-w/2+5,-h/2+5,w*0.35,4); ctx.fillRect(-w/2+5,-h/2+12,4,h*0.3);
      ctx.strokeStyle='rgba(255,255,255,0.9)'; ctx.lineWidth=1.3; ctx.beginPath();   // vết nứt mọc dần theo thời gian
      const nC=Math.floor(u*7); for(let k=0;k<nC;k++){ const a=k*2.4+0.6; let x=Math.cos(a)*w*0.08, y=Math.sin(a)*h*0.08; ctx.moveTo(x,y);
        for(let j=1;j<=3;j++){ x+=Math.cos(a+Math.sin(k*7+j)*0.6)*w*0.13; y+=Math.sin(a+Math.sin(k*7+j)*0.6)*h*0.13; ctx.lineTo(x,y); } } ctx.stroke();
      ctx.restore(); }
    // ⏰ đồng hồ "học muộn" trên đầu
    if(form<3){ const sec=Math.ceil(D.clock/DUO_TPS), frozen=D.ice>0, col=frozen?'#84d8ff':form===2?'#ff9600':'#58cc02';
      const S=f._lastSprite, K=(S&&S.img&&S.img._duoMul)||1, top=f.y-(S&&S.dh?S.dh/2/K:f.size)-46;
      ctx.save(); ctx.font='900 15px "Nunito",sans-serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      const txt=(frozen?'🧊 ':'⏰ ')+'0:'+String(sec).padStart(2,'0'), tw=ctx.measureText(txt).width+14;
      if((D.tickFx||0)>0){ D.tickFx--; ctx.fillStyle=`rgba(255,75,75,${D.tickFx/12})`; ctx.fillText('-1s',f.x+tw/2+14,top-6-(12-D.tickFx)); }
      ctx.fillStyle='rgba(255,255,255,0.92)'; ctx.strokeStyle=col; ctx.lineWidth=2.5;
      ctx.beginPath(); ctx.roundRect?ctx.roundRect(f.x-tw/2,top-11,tw,22,11):ctx.rect(f.x-tw/2,top-11,tw,22); ctx.fill(); ctx.stroke();
      ctx.fillStyle=col; ctx.fillText(txt,f.x,top+1); ctx.restore(); }
  }
}

// ==================== 🎧🍳 AZEL — DUBSTEP NẤU ĂN, MỖI NHỊP 1 BƯỚC ====================
// Meme gốc: Azel làm dubstep bằng miệng, tay giật cục đều tăm tắp theo nhịp, hay bị ghép với clip nấu ăn / Minecraft —
// mỗi động tác tay khớp ĐÚNG 1 bước trong clip. Trong game: nhạc wub chạy nhịp ĐỀU (AZ_BEAT), mỗi nhịp Azel giật sang 1 tư
// thế mới và đúng nhịp đó trên sàn xảy ra 1 bước nấu. Vòng 8 nhịp = 1 công thức:
//   1–3 🔪 thái: dao giáng xuống ĐÚNG chỗ địch sắp tới (đoán theo hướng đang chạy), 25 dame/nhát (trúng cả quân triệu hồi)
//   4   🧂 rắc muối: địch bị chậm 2s
//   5   🍳 đặt chảo nóng ở chỗ địch sắp tới; chảo tự trượt theo địch tới nhịp sau
//   6–7 🔄 lật chảo: địch bị hất vào chảo, tung lên rồi rơi lại đúng vào chảo (20 dame/lần, bị giữ trong chảo)
//   8   🍽️ DROP — dọn món: 150 dame, Azel hồi 50% số đó; rồi sang vòng mới
// Không có đòn đánh thường. Dưới 50% máu nhịp nhanh hơn (vẫn đều).
const AZ_TPS=60*GAME_SPEED*TIME_SCALE;
const AZ_BEAT=0.5, AZ_BEAT_RAGE=0.35;             // giây / nhịp
const AZ_CHOP_DMG=25, AZ_CHOP_R=24, AZ_FLIP_DMG=20, AZ_SERVE_DMG=150, AZ_SERVE_HEAL=0.5, AZ_SALT_T=2, AZ_PAN_REACH=55;
const AZ_STEP_ICON=['🔪','🔪','🔪','🧂','🍳','🔄','🔄','🍽️'];
const AZ_FR=Array.from({length:30},(_,n)=>{ const im=new Image(); im._noMask=true; im.onload=()=>{ im._crop={sx:0,sy:0,sw:im.naturalWidth,sh:im.naturalHeight}; }; im.src='assets/img/azel/AZ_FR_'+String(n+1).padStart(2,'0')+'.webp'; return im; });   // 🎧 30 khung múa tay beatbox (video phông xanh của Azel, 25 khung/giây, vòng 1.2s) — đã tách nền sẵn
const AZ_FR_K=2.19;   // khung rộng (tay vươn xa, đầu ở giữa) → phóng phần HÌNH cho người cao bằng avatar cũ
const _azImg=n=>{ const im=new Image(); im.src='assets/img/azel/'+n+'.webp'; return im; };
const AZ_KNIFE=_azImg('AZ_KNIFE'), AZ_SALT=_azImg('AZ_SALT'), AZ_PAN=_azImg('AZ_PAN'), AZ_PLATE=_azImg('AZ_PLATE');
// tư thế giật theo nhịp (ảnh avatar chỉ có 1 khung → giật bằng nghiêng/lệch/co giãn, đổi ĐỘT NGỘT đúng nhịp như robot)
const AZ_POSES=[{r:-0.13,x:-0.05,y:0,sx:1,sy:1},{r:0.1,x:0.06,y:-0.03,sx:1.03,sy:0.97},{r:-0.04,x:0,y:0.04,sx:0.96,sy:1.05},{r:0.15,x:0.04,y:0,sx:1,sy:1},
                 {r:-0.09,x:-0.07,y:-0.04,sx:1.04,sy:0.96},{r:0.06,x:0.03,y:0.03,sx:0.97,sy:1.03},{r:-0.15,x:-0.03,y:0,sx:1,sy:1},{r:0,x:0,y:-0.06,sx:1.12,sy:1.12}];
let azFx=[];   // dao / muối / chảo / đĩa đang hiện
function _azReset(){ azFx=[]; }
// đoán chỗ địch sẽ đứng sau `ahead` tick (theo vận tốc đo được), kẹp trong sàn
function _azPredict(A,o,ahead){
  const vx=A.tvx||0, vy=A.tvy||0, m=(o.size||20)*0.6;
  return { x:Math.max(m,Math.min(W-m,o.x+vx*ahead)), y:Math.max(m,Math.min(H-m,o.y+vy*ahead)) };
}
// 🔊 nhạc dubstep tổng hợp NGAY theo nhịp game (nên luôn khớp tuyệt đối): bass wobble + trống kick, nhịp 8 là cú drop to
function _azWub(beatS, drop){
  try{
    if(AC.state==='suspended') AC.resume(); _ensureMix();
    const t=AC.currentTime, out=AC.createGain(); out.connect(_mixGain||AC.destination);
    out.gain.setValueAtTime(drop?0.5:0.32,t); out.gain.exponentialRampToValueAtTime(0.001,t+beatS*(drop?1.8:0.98));
    const lp=AC.createBiquadFilter(); lp.type='lowpass'; lp.Q.value=9; lp.connect(out);
    const f0=drop?41.2:55, nW=drop?4:2;            // wobble: 2 nhịp "wub" mỗi phách (drop: 4 nhịp, trầm hơn)
    for(const [type,mul,v] of [['sawtooth',1,0.6],['square',0.5,0.5],['sawtooth',1.005,0.4]]){
      const o=AC.createOscillator(), g=AC.createGain(); o.type=type; o.frequency.setValueAtTime(f0*mul,t); g.gain.value=v; o.connect(g); g.connect(lp);
      o.start(t); o.stop(t+beatS*(drop?1.8:1)); }
    const dur=beatS*(drop?1.8:1);
    lp.frequency.setValueAtTime(120,t);
    for(let i=0;i<nW*(drop?1.8:1);i++){ const a=t+i*beatS/nW; lp.frequency.linearRampToValueAtTime(drop?1800:1300,a+beatS/nW*0.35); lp.frequency.linearRampToValueAtTime(110,a+beatS/nW*0.95); }
    // kick
    const k=AC.createOscillator(), kg=AC.createGain(); k.type='sine'; k.frequency.setValueAtTime(150,t); k.frequency.exponentialRampToValueAtTime(42,t+0.12);
    kg.gain.setValueAtTime(drop?0.9:0.6,t); kg.gain.exponentialRampToValueAtTime(0.001,t+0.25); k.connect(kg); kg.connect(out);
    k.start(t); k.stop(t+0.26);
    setTimeout(()=>{ try{ out.disconnect(); kg.disconnect(); }catch(e){} }, (dur+0.5)*1000);
  }catch(e){}
}
function _azTick(f){
  const A=f._az||(f._az={t:0,beat:-1,pose:0,hit:0,tgt:null,pan:null,lx:null,ly:null});
  if(A.hit>0) A.hit--;
  // đo vận tốc mục tiêu (để đoán trước chỗ nó sắp tới)
  let o=A.tgt;
  if(!o || o.dead){ o=A.tgt=_sdFoe(f); A.lx=null; }
  if(o){ if(A.lx!=null){ A.tvx=(A.tvx||0)*0.8+(o.x-A.lx)*0.2; A.tvy=(A.tvy||0)*0.8+(o.y-A.ly)*0.2; } A.lx=o.x; A.ly=o.y; }
  if(f._introLock>0) return;
  const beatS=f.hp<=f.maxHp*0.5?AZ_BEAT_RAGE:AZ_BEAT, BT=Math.max(1,Math.round(beatS*AZ_TPS));
  // chảo trượt theo mục tiêu giữa nhịp 5 và 6 (chưa bắt được)
  const P=A.pan;
  if(P && !P.caught && o && !o.dead){ const g=_azPredict(A,o,BT-A.t); const dx=g.x-P.x, dy=g.y-P.y, d=Math.hypot(dx,dy), sp=7; if(d>0.5){ P.x+=dx/d*Math.min(d,sp); P.y+=dy/d*Math.min(d,sp); } }
  // địch đang nằm trong chảo: giữ chặt ở lòng chảo
  if(P && P.caught){ const c=P.caught;
    if(c.dead){ P.caught=null; c._azLift=0; }
    else { c.x=P.x; c.y=P.y; c.vx=0; c.vy=0; c.stun=Math.max(c.stun||0,3);
      const u=A.t/BT; c._azLift=(A.beat===5||A.beat===6)?Math.sin(Math.min(1,u*1.15)*Math.PI)*c.size*1.6:0; } }
  if(++A.t<BT && A.beat>=0) return;
  // ===== sang nhịp mới =====
  A.t=0; A.beat=(A.beat+1)%8; A.pose=(A.pose+1)%AZ_POSES.length; A.hit=6;
  const b=A.beat, drop=b===7;
  if(drop) A.pose=7; else if(A.pose===7) A.pose=0;
  _azWub(beatS, drop);
  if(b===0){ A.tgt=o=_sdFoe(f); }
  if(!o || o.dead) return;
  const sz=o.size||20;
  floatTexts.push({x:f.x,y:f.y-f.size-22,text:AZ_STEP_ICON[b]+' '+(b+1),color:'#80deea',life:Math.round(BT*0.9)});
  if(b<=2){   // 🔪 thái
    const p=_azPredict(A,o,6);
    azFx.push({k:'knife',x:p.x,y:p.y,t:0,T:Math.round(BT*1.2),sz:Math.max(34,sz*0.9),flip:b%2});
    playSample('sm_slash',0.5,null,1.3);
    if(Math.hypot(o.x-p.x,o.y-p.y)<sz+AZ_CHOP_R) o.takeDamage(AZ_CHOP_DMG,f);
    _hitSummonsArea(f.team,p.x,p.y,AZ_CHOP_R,AZ_CHOP_DMG,f,o);
    addShake(3,4);
  } else if(b===3){   // 🧂 muối
    azFx.push({k:'salt',x:o.x,y:o.y-sz*1.3,tgt:o,t:0,T:Math.round(BT*1.4),sz:Math.max(30,sz*0.8)});
    playSample('az_salt',0.8);   // 🧂 tiếng lắc lọ muối
    const ST=Math.round(AZ_SALT_T*AZ_TPS);
    o._slowTimer=Math.max(o._slowTimer||0,ST);
    for(const u of _summonFoes(f.team)) if(Math.hypot(u.x-o.x,u.y-o.y)<sz+60) u._slowTimer=Math.max(u._slowTimer||0,ST);
  } else if(b===4){   // 🍳 đặt chảo ở chỗ địch sẽ tới vào nhịp sau
    const p=_azPredict(A,o,BT);
    A.pan={x:p.x,y:p.y,r:Math.max(46,sz*1.35),t:0,caught:null,flip:0,tgt:o};
    azFx.push({k:'pan',pan:A.pan,owner:f,t:0});
    playSample('cn_pan_hit',0.6);
  } else if(b===5 || b===6){   // 🔄 lật chảo
    const P2=A.pan; if(!P2) return;
    if(!P2.caught && Math.hypot(o.x-P2.x,o.y-P2.y)<P2.r*0.5+sz*0.5+AZ_PAN_REACH){ P2.caught=o; }
    P2.flip++;
    playSample('cn_pan_hit',0.8,null,b===5?1:1.15);
    if(P2.caught){ P2.caught.takeDamage(AZ_FLIP_DMG,f); addShake(4,6); }
    _hitSummonsArea(f.team,P2.x,P2.y,P2.r,AZ_FLIP_DMG,f);   // quân triệu hồi lỡ đứng trong chảo cũng bị hất
  } else if(drop){   // 🍽️ DROP — dọn món
    const P2=A.pan; A.pan=null;
    addShake(10,14);
    if(P2) _hitSummonsArea(f.team,P2.x,P2.y,P2.r,AZ_SERVE_DMG,f);   // dọn luôn cả quân triệu hồi trong chảo
    if(P2 && P2.caught && !P2.caught.dead){ const c=P2.caught; c._azLift=0; c.stun=0;
      azFx.push({k:'plate',x:c.x,y:c.y,t:0,T:Math.round(AZ_TPS*1.1),sz:P2.r});
      const h0=c.hp; c.takeDamage(AZ_SERVE_DMG,f); const got=Math.max(0,h0-Math.max(0,c.hp));
      const heal=Math.round(got*AZ_SERVE_HEAL), f0=f.hp; f.hp=Math.min(f.maxHp,f.hp+heal);
      if(f.hp>f0){ _matchStats[f.team].healed+=f.hp-f0; _healFloat(f.x,f.y,f.size,f.hp-f0,f); }
      floatTexts.push({x:c.x,y:c.y-c.size-30,text:'🍽️ SERVED!',color:'#ffd54f',life:60,big:true});
      playSample('vine_boom',0.7);
    } else if(P2) floatTexts.push({x:P2.x,y:P2.y-30,text:'🍳 empty pan…',color:'#b0bec5',life:45});
  }
}
// 🍳 vẽ DƯỚI meme: chảo nằm trên sàn (địch đứng trong lòng chảo), đĩa lúc dọn món
function _azDrawUnder(){
  for(const e of azFx){
    if(e.k==='pan'){ const P=e.pan; if(!AZ_PAN.naturalWidth) continue;
      const Db=P.r*2.3, k=Db/AZ_PAN.naturalHeight, tilt=(P.caught && P.flip)?Math.sin(Math.min(1,(e.owner?._az?.t||0)/12)*Math.PI)*0.25:0;
      ctx.save(); ctx.translate(P.x,P.y+P.r*0.1); ctx.scale(1,0.62*(1-tilt*0.5)); ctx.rotate(tilt);
      ctx.drawImage(AZ_PAN,-Db/2,-Db/2,AZ_PAN.naturalWidth*k,Db);   // ảnh chảo nhìn từ trên: lòng chảo tròn bên trái (đường kính = chiều cao ảnh), cán chĩa lên phải
      ctx.restore();
      // khói nóng bốc lên
      const tm=performance.now()/1000;
      for(let i=0;i<3;i++){ const u=((tm*0.9+i/3)%1), x=P.x+(i-1)*P.r*0.35+Math.sin(tm*3+i)*3, y=P.y-u*P.r*1.2;
        ctx.fillStyle=`rgba(240,240,250,${0.28*(1-u)})`; ctx.beginPath(); ctx.arc(x,y,P.r*(0.12+u*0.18),0,Math.PI*2); ctx.fill(); }
    } else if(e.k==='plate' && AZ_PLATE.naturalWidth){ const u=e.t/e.T, Dw=e.sz*3.6, Dh=Dw*AZ_PLATE.naturalHeight/AZ_PLATE.naturalWidth, a=u<0.8?1:1-(u-0.8)/0.2;
      ctx.save(); ctx.globalAlpha=a; ctx.translate(e.x,e.y+e.sz*0.3); ctx.scale(1,0.6); ctx.drawImage(AZ_PLATE,-Dw/2,-Dh/2,Dw,Dh); ctx.restore(); }
  }
}
// 🔪🧂 vẽ TRÊN meme: dao giáng xuống, lọ muối lắc rắc muối
function _azDrawOver(){
  for(let i=azFx.length-1;i>=0;i--){ const e=azFx[i]; e.t++;
    if(e.k==='pan'){ if(!e.owner || e.owner.dead || e.owner._az?.pan!==e.pan){ if(e.pan.caught) e.pan.caught._azLift=0; azFx.splice(i,1); } continue; }
    if(e.t>=e.T){ azFx.splice(i,1); continue; }
    if(e.k==='knife' && AZ_KNIFE.naturalWidth){ const u=e.t/e.T, fall=Math.min(1,e.t/3), Hk=e.sz*2, Wk=Hk*AZ_KNIFE.naturalWidth/AZ_KNIFE.naturalHeight, a=u<0.7?1:1-(u-0.7)/0.3;
      ctx.save(); ctx.globalAlpha=a; ctx.translate(e.x,e.y+e.sz*0.25-(1-fall)*e.sz*2.2); if(e.flip) ctx.scale(-1,1); ctx.rotate(e.flip?0.12:-0.12);
      ctx.drawImage(AZ_KNIFE,-Wk/2,-Hk,Wk,Hk); ctx.restore();   // ảnh dao dựng đứng, mũi chĩa xuống: mũi cắm đúng điểm chặt
      if(e.t>=3 && e.t<10){ ctx.strokeStyle=`rgba(255,255,255,${0.8*(1-(e.t-3)/7)})`; ctx.lineWidth=2;
        ctx.beginPath(); ctx.ellipse(e.x,e.y+e.sz*0.25,e.sz*0.9*(e.t-2)/7,e.sz*0.3*(e.t-2)/7,0,0,Math.PI*2); ctx.stroke(); }
    } else if(e.k==='salt' && AZ_SALT.naturalWidth){ const o=e.tgt, x=o&&!o.dead?o.x:e.x, y=(o&&!o.dead?o.y:e.y+e.sz*1.3)-(o?.size||20)*1.5, u=e.t/e.T, a=u<0.75?1:1-(u-0.75)/0.25, D=e.sz*1.4;
      const Ws=D*AZ_SALT.naturalWidth/AZ_SALT.naturalHeight;
      ctx.save(); ctx.globalAlpha=a; ctx.translate(x,y); ctx.rotate(Math.PI*0.85+Math.sin(e.t*0.9)*0.35); ctx.drawImage(AZ_SALT,-Ws/2,-D/2,Ws,D); ctx.restore();
      ctx.fillStyle=`rgba(255,255,255,${0.9*a})`;
      for(let k=0;k<14;k++){ const q=((e.t*0.06+k/14)%1), gx=x+Math.sin(k*12.9898)*e.sz*0.5, gy=y+D*0.3+q*(o?.size||20)*2.2; ctx.fillRect(gx,gy,2,2); }
    }
  }
}

// ==================== 🤤💧 DROOLING CAT — DÃI NHỎ TỪ MỒM, ĐỌNG THÀNH VŨNG NƯỚC (piranha → cá mập) ====================
// (skill vũng dãi cũ của Wet Cat chuyển hẳn sang đây rồi sửa lại; Wet Cat giờ là mưa + sét — xem khối WET CAT bên dưới)
// • Dãi nhỏ giọt từ MỒM rơi thẳng xuống đất ngay dưới chân, nhịp nhanh dần (×DL_RATE_UP mỗi giọt, trần DL_RATE_MAX giọt/s);
//   nhỏ đủ nhanh (≥ DL_STREAM_RATE giọt/s) thì thành DÒNG liền từ mồm xuống đất, dòng càng lâu càng to.
// • Giọt / dòng KHÔNG gây dame — rơi xuống đất rồi CHẢY về GIỮA SÀN, dồn thành 1 vũng nước xanh trong ở giữa, to dần (cộng DIỆN TÍCH).
// • Trong vũng: địch mất 10 máu/s; Drooling Cat hồi 10 máu/s.
// • Từ giây 8: piranha — địch ngâm nước LIÊN TỤC 3s thì 1 con nhảy lên cắn thêm 80 (ngâm tiếp 3s nữa lại 1 con).
// • Từ giây 15: piranha đổi thành cá mập — vây cá bơi chậm trong vũng; địch chạm vây thì cá ngoi lên cắn 200
//   và khoét mất miếng thịt ĐÚNG chỗ bị cắn (cùng cơ chế vết gặm Friend: _biteHoles / _biteMask).
// Quân triệu hồi có máu ăn đủ y như meme (dame vũng, piranha, cá mập).
const DL_TPS=60*GAME_SPEED*TIME_SCALE;            // tick logic mỗi GIÂY THẬT (≈72, không phải 60)
const DL_RATE0=1.0, DL_RATE_UP=1.09, DL_RATE_MAX=10, DL_STREAM_RATE=5, DL_FALL_T=13;   // 🤤 lúc đầu nhỏ từng sợi dãi dài · ~10s thành dòng · từ giây 13 chảy như THÁC
// 🌊 NHỊP NƯỚC DÂNG: diện tích vũng bám theo đường cong A(t) = A_đầy·(t/DL_FULL_T)^DL_FULL_POW — lúc đầu dâng chậm, càng về sau
//    nước chảy càng nhiều, tới đúng giây DL_FULL_T thì phủ KÍN cả sàn; đầy rồi thì Drooling Cat thôi nhỏ dãi.
//    Mỗi giọt mang đúng phần nước còn thiếu so với đường cong (tính trước DL_FLOW_LEAD giây — thời gian giọt chảy từ chân tới giữa),
//    nên dù mèo bị choáng / nhịp nhỏ lệch đi thì vũng vẫn đầy đúng hẹn, không vọt quá.
const DL_FULL_T=20, DL_FULL_POW=2.5, DL_FLOW_LEAD=1.2, DL_DROP_MIN=150, DL_VOL_DROP=110, DL_VOL_STREAM=550, DL_VOL_FALL=2600;   // 💧 nước mỗi giọt (diện tích): giọt · dòng · thác
function _dlFullR(){ return Math.hypot(W/2,(H/2)/DL_POOL_SQ)*1.08; }      // bán kính vũng phủ kín 4 góc sàn (trừ hao mép gợn)
function _dlFullA(){ const R=_dlFullR(); return Math.PI*R*R; }
const DL_POOL_SQ=0.6;                             // vũng nằm trên MẶT SÀN → dẹt theo chiều dọc (phối cảnh)
const DL_POOL_DMG=10, DL_POOL_HEAL=10;            // mỗi giây
const DL_PIRANHA_AT=1e9, DL_SHARK_AT=10,   // (đã bỏ piranha) · cá mập từ giây 10
 /*cũ*/ DL_PIRANHA_OLD=8, DL_SOAK=3, DL_PIRANHA_DMG=80, DL_SHARK_DMG=200;
const DL_FIN_SPD=1.5, DL_FIN_K=4.2, DL_FIN_REACH=58, DL_FIN_AGGRO=170, DL_FIN_CD=2, DL_SHARK_HOLD=1.5, DL_SHARK_TICK=0.5, DL_SHARK_TICK_DMG=70;   // 🦈 ngoạm rồi GIẰNG CO 1.5s, mỗi 0.5s −70             // vây bơi chậm; cắn xong 2.5s sau mới có vây mới
// 👄 vị trí 2 MỒM (2 con mèo trong ảnh: xám bên trái, kem bên phải) theo khung ảnh đang vẽ (u,v: 0..1)
const DL_MOUTH=[0.5,0.68], DL_MOUTHS=[[0.26,0.215],[0.69,0.235]];
// 👄 vị trí 2 mồm THEO TỪNG KHUNG (đo bằng dò ảnh: 2 con lắc lư thở nên mồm xê dịch tới ~13px giữa các khung)
const DL_MOUTH_FR=[[[0.2597,0.2143],[0.6878,0.2327]],[[0.2376,0.2143],[0.6519,0.2442]],[[0.2762,0.2212],[0.6796,0.2442]],[[0.2597,0.212],[0.6768,0.2396]],[[0.2486,0.2143],[0.6657,0.2442]],[[0.2569,0.212],[0.6768,0.235]]];
// 🦈 cá mập thật (spritesheet user gửi): 1 vây · 2 ngoi lên · 3 HÁ MỒM · 4 NGOẠM · 5–8 lặn xuống (1–4 cùng khung: đáy ảnh = mặt nước, mõm hướng PHẢI)
const SHK=[1,2,3,4,5,6,7,8].map(n=>{ const im=new Image(); im.src='assets/img/droolingcat/SHK_'+n+'.webp'; return im; });
function _dlSpray(x,y,R,a,t,seed){   // 💦 bọt nước tung kiểu ảnh minh hoạ: vòng bọt trắng trên mặt nước + tia nước + giọt bắn
  if(a<=0.01) return; ctx.save(); ctx.globalAlpha=a;
  for(let i=0;i<26;i++){ const an=i/26*Math.PI*2+seed, rr=R*(0.7+0.3*Math.sin(t*0.3+i*2.1)); ctx.fillStyle=i%3?'rgba(245,252,255,0.7)':'rgba(200,235,250,0.6)'; ctx.beginPath(); ctx.ellipse(x+Math.cos(an)*rr,y+Math.sin(an)*rr*DL_POOL_SQ*0.55,R*0.1,R*0.045,an,0,Math.PI*2); ctx.fill(); }   // vòng bọt
  ctx.strokeStyle='rgba(250,254,255,0.9)'; ctx.lineCap='round';
  for(let i=0;i<9;i++){ const an=-Math.PI*(0.12+0.76*((i*0.37+seed*0.1)%1)), h=R*(0.5+0.7*((i*0.61+seed)%1))*(0.7+0.3*Math.sin(t*0.4+i)), bx=x+Math.cos(an)*R*0.9, by=y+Math.sin(an)*R*0.2;
    ctx.lineWidth=0.8+R*0.018; ctx.beginPath(); ctx.moveTo(bx,by); ctx.quadraticCurveTo(bx+Math.cos(an)*h*0.4,by-h*0.7,bx+Math.cos(an)*h*0.7,by-h*0.55); ctx.stroke(); }   // tia nước bắn cong
  ctx.fillStyle='rgba(235,250,255,0.95)'; for(let i=0;i<28;i++){ const u=((t*0.035+i*0.173+seed)%1), an=-Math.PI*(0.1+0.8*((i*0.29+seed)%1)), d=R*(0.6+1.1*u); ctx.beginPath(); ctx.arc(x+Math.cos(an)*d, y+Math.sin(an)*d*0.9+u*u*R*0.9, Math.max(0.6,R*0.028*(1-u)), 0, Math.PI*2); ctx.fill(); }   // giọt bắn
  ctx.restore(); }
// 🐱🐱 6 khung (spritesheet user gửi, cắt đúng ô lưới) — 2 con mèo đứng thở
const DL_FR=[1,2,3,4,5,6].map(n=>{ const im=new Image(); im.onload=()=>{ im._crop={sx:0,sy:0,sw:im.naturalWidth,sh:im.naturalHeight}; }; im.src='assets/img/droolingcat/DL_FR_'+n+'.webp'; return im; });
let dlDrops=[], dlPools=[], dlFx=[], dlFish=[], dlFins=[], dlSharks=[];
function _dlReset(){ dlDrops=[]; dlPools=[]; dlFx=[]; dlFish=[]; dlFins=[]; dlSharks=[]; }
function _dlKeepWin(team){ dlPools=dlPools.filter(p=>p.team===team); dlFins=dlFins.filter(p=>p.team===team); dlDrops=[]; dlFx=[]; dlFish=[]; dlSharks=[]; }
function _dlPoolR(p){ return Math.sqrt(p.A/Math.PI); }
// mồm / mặt đất ngay dưới chân — theo đúng ảnh đang vẽ (lật trái/phải), chưa có ảnh thì ước theo size
function _dlMouth(f,i){
  if(f._dlXf && f._dlBase && f._dlTick!=null && tick-f._dlTick<=3){   // 👄 CHUẨN: lấy đúng điểm mồm trên ảnh đang vẽ (theo khung + mọi phép nhún/lắc/lật)
    const M=(DL_MOUTH_FR[f._dlFr||0]||DL_MOUTHS)[i?1:0], d=f._dlXf.transformPoint(new DOMPoint((M[0]-0.5)*f._dlDW,(M[1]-0.5)*f._dlDH)), w=f._dlBase.inverse().transformPoint(d);
    return {x:w.x, y:w.y}; }
  const L=f._lastSprite;
  if(!L || !L.dw) return {x:f.x+(i?1:-1)*f.size*0.4, y:f.y-f.size*0.55};
  const M=DL_FR[0].naturalWidth?DL_MOUTHS[i?1:0]:DL_MOUTH;
  return {x:f.x+(L.fl?-1:1)*(M[0]-0.5)*L.dw, y:f.y+(M[1]-0.5)*L.dh};
}
function _dlFeetY(u){ const L=u._lastSprite; return u.y+((L && L.dh) ? L.dh*0.46 : (u.size||20)*0.85); }
// (x,y) trên mặt sàn có nằm trong vũng nào của phe KHÁC `team` không (team=null → vũng bất kỳ). pad = chạm mép cũng tính.
function _dlPoolAt(x,y,pad,team,own){
  for(const p of dlPools){
    if(own!==undefined ? p.team!==own : (team!=null && p.team===team)) continue;
    if(p.R<3) continue;
    const dx=x-p.x, dy=(y-p.y)/DL_POOL_SQ;
    if(dx*dx+dy*dy < (p.R+pad)*(p.R+pad)) return p;
  }
  return null;
}
function _dlDrip(f){
  f._dlRate=Math.min(DL_RATE_MAX,DL_RATE0*Math.pow(DL_STREAM_RATE/DL_RATE0,((f._dlAge||0)/DL_TPS)/DL_FALL_T));   // ⏱️ nhịp nhỏ dãi theo THỜI GIAN: giọt rơi NHANH DẦN liên tục, tới giây 13 thì liền thành THÁC
  f.cooldown=Math.max(1,Math.round(DL_TPS/f._dlRate));
  f._dlMi=f._dlMi?0:1; const m=_dlMouth(f,f._dlMi), stream=f._dlRate>=DL_STREAM_RATE;   // 2 mồm thay phiên nhỏ dãi
  if(!stream && tick-(f._dlDripSnd??-99)>=12){ f._dlDripSnd=tick; playSample('dl_drip',0.45); }   // 💧 còn nhỏ GIỌT: tiếng tách từng giọt (thành dòng thì chuyển sang tiếng nước chảy lặp, xem _dlTick)
  // 💧 THỂ TÍCH THẬT: mỗi giọt mang đúng lượng nước theo độ to của nó — giọt nhỏ chỉ làm vũng to thêm chút xíu,
  //    thành dòng thì mỗi nhịp nhiều nước hơn, thành THÁC thì đổ ào ào (không còn ép vũng theo đường cong thời gian)
  const tS=(f._dlAge||0)/DL_TPS, fall=Math.max(0,Math.min(1,(tS-DL_FALL_T)/3));
  const A=stream ? DL_VOL_STREAM+(DL_VOL_FALL-DL_VOL_STREAM)*fall : DL_VOL_DROP*Math.pow(f._dlRate,0.6);   /* giọt càng dồn dập càng to */ f._dlEmit=(f._dlEmit||0)+A;
  const big=Math.min(1,Math.sqrt(A)/90); f._dlBig=big;   // nước càng nhiều → giọt / dòng càng to
  dlDrops.push({ x:m.x+(stream?0:(Math.random()-0.5)*2), y:m.y, vy:0.5, gy:Math.max(m.y+6,_dlFeetY(f)), A,
    r:(stream?1.6+Math.random()*0.8:2.4+Math.random()*1.2)*(1+big*1.3), owner:f, team:f.team });
}
// 🌀 giọt chảy tới GIỮA SÀN: nhập vào vũng giữa sàn của chủ (cộng DIỆN TÍCH → vũng to dần, nhanh lúc đầu rồi chậm lại)
function _dlAddWater(f,x,y,A){
  let p=dlPools.find(q=>q.owner===f);
  if(p) p.A=Math.min(_dlFullA(),p.A+A); else dlPools.push(p={x:W/2, y:H/2, A:A*2, R:2, owner:f, team:f.team, sd:Math.random()*9});
  dlFx.push({k:'ring',x,y,t:0,max:30,r:2});
}
// mọi mục tiêu sống (meme + quân triệu hồi có máu) không cùng phe
function _dlFoes(team){ return [...fighters.filter(o=>!o.dead && o.team!==team), ..._summonFoes(team)]; }
function _dlBiteHole(o,x,y){
  // 🦈 khoét đúng CHỖ bị cắn: quy điểm cắn (x,y) về toạ độ khung ảnh (0..1) theo đúng ảnh đang vẽ (có lật ngang)
  const L=o._lastSprite; if(!L || !L.dw || !fighters.includes(o)) return;
  const hs=(o._biteHoles||(o._biteHoles=[])); if(hs.length>=7) return;
  const u=0.5+(L.fl?-1:1)*(x-o.x)/L.dw, v=0.5+(y-o.y)/L.dh;
  hs.push({ x:Math.max(0.08,Math.min(0.92,u)), y:Math.max(0.2,Math.min(0.88,v)), r:0.24+Math.random()*0.05, sd:Math.random()*99 });
}
// 🩸 máu loang dưới nước sau cú cắn: vài đám đỏ sẫm nở rộng, trôi đi chậm, mờ dần trong ~2s rồi tan
function _dlBlood(x,y,sz){ const a=Math.random()*Math.PI*2; for(let j=0;j<5;j++){ const aj=a+(Math.random()-0.5)*1.2, sp=0.25+Math.random()*0.35;
  dlFx.push({k:'blood', x:x+(Math.random()-0.5)*sz*0.5, y:y+(Math.random()-0.5)*sz*0.25, vx:Math.cos(aj)*sp, vy:Math.sin(aj)*sp*DL_POOL_SQ, r:sz*(0.12+Math.random()*0.12), t:-j*3, max:Math.round(DL_TPS*2)}); } }
function _dlPickInPool(p,k){ const a=Math.random()*Math.PI*2, d=Math.sqrt(Math.random())*p.R*(k||0.75);   // (vũng tràn quá sàn thì kẹp lại trong sàn)
  return {x:Math.max(24,Math.min(W-24,p.x+Math.cos(a)*d)), y:Math.max(24,Math.min(H-24,p.y+Math.sin(a)*d*DL_POOL_SQ))}; }
// chạy trong vòng tick của loop() (kể cả lúc Drooling Cat bị choáng)
let _dlPourSfx=null;   // 🌊 tiếng nước chảy lặp khi dãi đã thành dòng
function _dlTick(){
  { const on=fighters.some(f=>f.type==='droolingcat' && !f.dead && (f._dlRate||0)>=DL_STREAM_RATE);
    if(on && !_dlPourSfx){ const a=AUDIO_SAMPLES['dl_pour']; if(a){ try{ const c=a.cloneNode(); c.loop=true; c.volume=0.4; _mixRoute(c); c.play().catch(()=>{}); _dlPourSfx=c; }catch(e){} } }
    else if(!on && _dlPourSfx){ _stopLoopAudio(_dlPourSfx); _dlPourSfx=null; } }
  // giọt nhả ra rơi thẳng xuống đất, chạm đất thì CHẢY trên sàn về GIỮA SÀN (bị hút cong vào, càng gần càng nhanh —
  // y kiểu giọt bị hút của skill cũ), tới mép vũng giữa sàn thì nhập vào làm vũng to thêm
  for(let i=dlDrops.length-1;i>=0;i--){ const d=dlDrops[i];
    if(!d.owner || d.owner.dead){ dlDrops.splice(i,1); continue; }
    if(!d.ground){
      d.vy+=0.32; d.y+=d.vy;
      if(d.y>=d.gy){ d.y=d.gy; d.ground=true; d.age=0; d.r=Math.max(d.r,2.6); dlFx.push({k:'ring',x:d.x,y:d.y,t:0,max:18,r:1});
        const toC=Math.atan2(H/2-d.y, W/2-d.x), side=Math.random()<0.5?-1:1;
        d.vx=Math.cos(toC)*0.8+Math.cos(toC+side*Math.PI/2)*1.2; d.vy=Math.sin(toC)*0.8+Math.sin(toC+side*Math.PI/2)*1.2; d.trail=[]; }
      continue;
    }
    d.age++;
    const dx=W/2-d.x, dy=H/2-d.y, dd=Math.hypot(dx,dy)||1, k=0.03+Math.min(0.4,d.age*0.005);
    d.vx=(d.vx+dx/dd*k)*0.985; d.vy=(d.vy+dy/dd*k)*0.985;
    const sp=Math.hypot(d.vx,d.vy); if(sp>6){ d.vx*=6/sp; d.vy*=6/sp; }
    d.x+=d.vx; d.y+=d.vy;
    d.trail.push(d.x,d.y); if(d.trail.length>14) d.trail.splice(0,2);
    const p=dlPools.find(q=>q.owner===d.owner), R=p?p.R:0;
    if(Math.hypot(W/2-d.x,(H/2-d.y)/DL_POOL_SQ) < Math.max(5,R) || d.age>600){ _dlAddWater(d.owner,d.x,d.y,d.A||DL_DROP_MIN); dlDrops.splice(i,1); }
  }
  for(const p of dlPools){
    const dead=!p.owner || p.owner.dead;
    if(dead){ p.A*=0.985; }   // chủ gục → vũng rút dần rồi khô hẳn
    const Rt=_dlPoolR(p); p.R+=(Rt-p.R)*0.06;   // vũng nở ra MƯỢT, không giật từng nấc
  }
  for(let i=dlPools.length-1;i>=0;i--) if(dlPools[i].A<60 && dlPools[i].owner?.dead) dlPools.splice(i,1);
  for(const f of fighters){
    if(f.type!=='droolingcat' || f.dead) continue;
    f._dlAge=(f._dlAge||0)+1;
    { const p=dlPools.find(q=>q.owner===f); f._dlFull=!!(p && p.A>=_dlFullA()*0.999); }   // 🌊 nước đã phủ kín sàn → thôi nhỏ dãi
    const sec=f._dlAge/DL_TPS, T1=Math.round(DL_TPS);
    // 💚 Drooling Cat đứng trong vũng của mình: hồi 10 máu/s
    if(_dlPoolAt(f.x,_dlFeetY(f),f.size*0.35,null,f.team)){
      f._dlHealT=(f._dlHealT||0)+1;
      if(f._dlHealT>=T1){ f._dlHealT=0; const h0=f.hp; f.hp=Math.min(f.maxHp,f.hp+DL_POOL_HEAL);
        if(f.hp>h0){ _matchStats[f.team].healed+=f.hp-h0; _healFloat(f.x,f.y,f.size,f.hp-h0,f); } }
    } else f._dlHealT=0;
    for(const o of _dlFoes(f.team)){
      const isF=fighters.includes(o), sz=o.size||20;
      const p=_dlPoolAt(o.x,_dlFeetY(o),sz*0.35,null,f.team);
      if(!p){ o._dlSoak=0; o._dlDotT=0; continue; }
      // 🌊 lội nước: chậm đi 30% (trả lại 30% quãng vừa đi mỗi nhịp — áp dụng được cho cả meme lẫn quân triệu hồi) + đánh dấu để vẽ lún người
      if(_dlPoolAt(o.x,_dlFeetY(o),-sz*0.7,null,f.team)){   // chỉ khi đã bước HẲN vào trong hồ (cả thân), đứng mép thì chưa
        if(o._dlWadeTick==null || tick-o._dlWadeTick>2) o._dlSplashT=18;   // 💦 vừa lội xuống: nước bắn lên
        o._dlWadeTick=tick; if(!isF){ o.x-=(o.vx||0)*0.3; o.y-=(o.vy||0)*0.3; } }   // quân triệu hồi: trả lại 30% quãng đi (meme chính chậm qua slowMult)
      // 💧 10 máu/s khi đứng trong nước
      o._dlDotT=(o._dlDotT||0)+1;
      if(o._dlDotT>=Math.round(DL_TPS*0.5)){ o._dlDotT=0;   // 💧 10 dame mỗi 0.5s
        if(isF) o.takeDamage(DL_POOL_DMG, f, false, true); else _summonTakeDamage(o, DL_POOL_DMG, f, false, true); }
      // 🐟 từ giây 8 (tới giây 15): ngâm liên tục 3s → piranha nhảy lên cắn
      o._dlSoak=(o._dlSoak||0)+1;
      if(sec>=DL_PIRANHA_AT && sec<DL_SHARK_AT && o._dlSoak>=DL_SOAK*DL_TPS){
        o._dlSoak=0;
        const a=Math.random()*Math.PI*2, sp=_dlPickInPool(p,0.9), fy=_dlFeetY(o);
        const sx=Math.abs(sp.x-o.x)<sz*1.6 ? sp.x : o.x+Math.cos(a)*sz*1.3, sy=Math.abs(sp.y-fy)<sz ? sp.y : fy+Math.sin(a)*sz*0.4;
        dlFish.push({k:'bite', x0:sx, y0:sy, tgt:o, owner:f, t:0, dir:sx<o.x?1:-1, hit:false});
      }
    }
    // 🐟 piranha nhảy lên khỏi mặt nước cho thấy "trong nước có cá" (chỉ để nhìn, không gây dame)
    if(sec>=DL_PIRANHA_AT && sec<DL_SHARK_AT){
      const big=dlPools.filter(p=>p.owner===f && p.R>22);
      if(big.length && Math.random()<0.02*Math.min(3,big.length)){ const p=big[(Math.random()*big.length)|0], s=_dlPickInPool(p,0.7);
        dlFish.push({k:'hop', x0:s.x, y0:s.y, dx:(Math.random()<0.5?-1:1)*(14+Math.random()*16), t:0, T:28+Math.random()*10}); }
    }
    // 🦈 từ giây 15: 1 con cá mập TO bơi vòng nhanh trong vũng
    const _dlPoolA=dlPools.filter(p=>p.owner===f).reduce((a,p)=>a+p.A*DL_POOL_SQ,0);
    if(_dlPoolA>=W*H/4 || f._dlSharkOn){   // 🦈 hồ đủ to (chiếm ≥ 1/4 sàn) thì cá mập mới xuất hiện — không theo thời gian
      if(!f._dlSharkOn){ f._dlSharkOn=true; f._dlFinCD=0; floatTexts.push({x:f.x,y:f.y-f.size-28,text:'🦈 SHARKS!',color:'#4fc3f7',life:70,big:true}); }
      const mine=dlPools.filter(p=>p.owner===f && p.R>=22), area=mine.reduce((s,p)=>s+p.A,0);
      const want=(mine.length && !dlSharks.some(q=>q.owner===f))?1:0;   // 🦈 chỉ 1 con cá mập duy nhất (đang ngoạm thì không có vây mới)
      if((f._dlFinCD||0)>0) f._dlFinCD--;
      else if(dlFins.filter(n=>n.owner===f).length<want){
        const p=mine[(Math.random()*mine.length)|0], foes=_dlFoes(f.team); let s=_dlPickInPool(p,0.6);
        if(foes.length){ let best=-1; for(let k=0;k<28;k++){ const c=_dlPickInPool(p,0.85), d=Math.min(...foes.map(o=>Math.hypot(o.x-c.x,(_dlFeetY(o)-c.y)/DL_POOL_SQ))); if(d>best){ best=d; s=c; } } }   // ngoi lên ở chỗ XA địch nhất trong hồ
        dlFins.push({x:s.x, y:s.y, pool:p, owner:f, team:f.team, ang:Math.random()*6.28, t:0, tgt:null, wake:[]});
        f._dlFinCD=Math.round(DL_TPS*0.8);
      }
    }
  }
  // vây cá: bơi về 1 điểm ngẫu nhiên trong vũng, tới nơi thì chọn điểm khác — chạm địch thì cá ngoi lên cắn
  for(let i=dlFins.length-1;i>=0;i--){ const n=dlFins[i];
    if(!n.owner || n.owner.dead || !dlPools.includes(n.pool)){ dlFins.splice(i,1); continue; }
    n.t++;
    let prey=null, pd=DL_FIN_AGGRO; for(const o of _dlFoes(n.team)){ const fy=_dlFeetY(o), d=Math.hypot(o.x-n.x,(fy-n.y)/DL_POOL_SQ); if(d<pd && _dlPoolAt(o.x,fy,(o.size||20)*0.35,null,n.team)){ pd=d; prey={x:o.x,y:fy}; } }   // 🦈 địch lội vào bán kính → lao tới
    if(prey) n.tgt=prey; else if(!n.tgt || n.tgt.prey || Math.hypot(n.tgt.x-n.x,n.tgt.y-n.y)<6) n.tgt=_dlPickInPool(n.pool,0.72);
    if(prey) n.tgt.prey=true;
    const ta=Math.atan2((n.tgt.y-n.y)/DL_POOL_SQ, n.tgt.x-n.x);
    let da=ta-n.ang; while(da>Math.PI) da-=Math.PI*2; while(da<-Math.PI) da+=Math.PI*2;
    const tr=prey?0.16:0.075, sp=prey?DL_FIN_SPD*3:DL_FIN_SPD;
    n.ang+=Math.max(-tr,Math.min(tr,da));                  // quay đầu từ từ → đường bơi lượn vòng (đuổi mồi thì quay gắt + bơi nhanh)
    n.x+=Math.cos(n.ang)*sp; n.y+=Math.sin(n.ang)*sp*DL_POOL_SQ;
    if(n.t%6===0){ n.wake.push({x:n.x,y:n.y,t:0}); }
    for(const w of n.wake) w.t++; while(n.wake.length && n.wake[0].t>40) n.wake.shift();
    if(n.t<20) continue;   // vừa trồi lên, chưa cắn
    for(const o of _dlFoes(n.team)){
      const sz=o.size||20, fy=_dlFeetY(o);
      if(Math.hypot(o.x-n.x,(fy-n.y)/DL_POOL_SQ) < sz*0.6+DL_FIN_REACH){
        dlSharks.push({x:n.x, y:n.y, ox:n.x-o.x, oy:n.y-o.y, tgt:o, owner:n.owner, t:0, dir:n.x<o.x?1:-1, hit:false, sz:Math.max(62,sz*1.6)});
        dlFx.push({k:'ring',x:n.x,y:n.y,t:0,max:34,r:6}); dlFx.push({k:'ring',x:n.x,y:n.y,t:-6,max:34,r:3});
        n.owner._dlFinCD=Math.round(DL_TPS*DL_FIN_CD);
        dlFins.splice(i,1); break;
      }
    }
  }
  // piranha cắn: lao vòng cung từ mặt nước lên người địch, đớp 1 phát rồi rơi lại xuống nước
  for(let i=dlFish.length-1;i>=0;i--){ const q=dlFish[i]; q.t++;
    if(q.k==='hop'){ if(q.t>=q.T){ dlFx.push({k:'ring',x:q.x0+q.dx,y:q.y0,t:0,max:24,r:2}); dlFish.splice(i,1); } continue; }
    if(q.t===14 && !q.hit){ q.hit=true; const o=q.tgt;
      if(o && !o.dead && o.hp>0){ playSample('fr_bite',0.9);
        if(fighters.includes(o)) o.takeDamage(DL_PIRANHA_DMG, q.owner); else _summonTakeDamage(o, DL_PIRANHA_DMG, q.owner); } }
    if(q.t>=46){ dlFx.push({k:'ring',x:q.x1??q.x0,y:q.y1??q.y0,t:0,max:26,r:3}); dlFish.splice(i,1); }
  }
  // cá mập: ngoi lên há mồm (0→16) → NGOẠM (16) → GIẰNG CO giữ chặt con mồi 1.5s (mỗi 0.5s −70) → nhả, chìm xuống
  for(let i=dlSharks.length-1;i>=0;i--){ const s=dlSharks[i]; s.t++;
    const o=s.tgt, HOLD=Math.round(DL_TPS*DL_SHARK_HOLD), TK=Math.round(DL_TPS*DL_SHARK_TICK); s.H=16+HOLD;
    if(s.t===16 && !s.hit){ s.hit=true; if(o && !o.dead && o.hp>0){ playSample('dl_shark_bite',1.0); addShake(9,12); } }   // 🦈 tiếng cá mập đớp   // (đã bỏ khoét mất mảng thịt khi cắn)
    if(s.t>16 && s.t<=s.H && o && !o.dead && o.hp>0){
      if(o.stun!==undefined) o.stun=Math.max(o.stun||0,2); o.vx=0; o.vy=0;   // bị ghì chặt, giằng co qua lại
      const tug=Math.sin(s.t*0.55)*(o.size||20)*0.18; o.x+= (s.ox0===undefined?0:(s.ax+tug)-o.x)*0.35; if(s.ox0===undefined){ s.ox0=1; s.ax=o.x; }
      if((s.t-16)%TK===0){ playSample(s.t%2?'vamp_bite1':'vamp_bite2',0.8); addShake(6,8); _dlBlood(s.x,s.y,s.sz);
        if(fighters.includes(o)) o.takeDamage(DL_SHARK_TICK_DMG, s.owner); else _summonTakeDamage(o, DL_SHARK_TICK_DMG, s.owner); } }
    if(s.t<s.H && o && !o.dead && s.ox!==undefined){ s.x=o.x+s.ox; s.y=o.y+s.oy; }   // ngoạm trúng rồi thì bám theo con mồi tới lúc nhả
    if(s.t===s.H) _dlBlood(s.x,s.y,s.sz*1.3);   // nhả mồi: vũng máu to hơn
    if(s.t>=s.H+26){ dlFx.push({k:'ring',x:s.x,y:s.y,t:0,max:34,r:8}); dlSharks.splice(i,1); }
  }
}

// ==================== 🌧️⚡ WET CAT — MƯA THEO CHÂN + SÉT ====================
// Vào trận là trời đổ mưa quanh chỗ Wet Cat đứng; nó đi tới đâu vùng mưa lan tới đó (để lại VĨNH VIỄN — cùng kiểu vệt
// dãi Wet Cat đời đầu, giờ là đám mưa). Thỉnh thoảng sét giáng xuống trong vùng mưa cho có không khí.
// • Địch đứng trong mưa: mất 30 máu/s.
// • Cứ ở trong mưa đủ 4s (cộng dồn) là 1 lần tung xúc xắc 25%: trúng thì bị SÉT ĐÁNH — 100 dame + choáng điện 1s,
//   người giật đùng đùng sáng loé lòi xương (kiểu hoạt hình, theo đúng hình avatar của con bị đánh — xem _wcXray).
// Quân triệu hồi có máu ăn y hệt (mưa + sét).
const WC_TPS=60*GAME_SPEED*TIME_SCALE;
const WC_RAIN_R=92;                       // bán kính mỗi đốm mưa dọc đường đi
const WC_RAIN_DMG=20;                     // mỗi 0.5s → 40 máu/s
const WC_ZAP_EVERY=4, WC_ZAP_P=0.25, WC_ZAP_DMG=100, WC_ZAP_STUN=1;
const WC_CELL=32;
let wcRain=[];          // {x,y,r,team,owner}
let wcRainCells=[];     // ô lưới đã có mưa {x,y,team} — rải hạt mưa/gợn nước đều theo DIỆN TÍCH thay vì theo số đốm
let _wcCellKeys=new Set(), _wcRainCache=null;
let wcRainFx=[];        // hạt mưa đang rơi {x,gy,h,v,L}
let wcRipples=[];       // gợn nước dưới đất
let wcBolts=[];         // tia sét {pts,x,y,t0,big}
let _wcRainSfx=null;
function _wcRainReset(){ wcRain=[]; wcRainCells=[]; _wcCellKeys=new Set(); _wcRainCache=null; wcRainFx=[]; wcRipples=[]; wcBolts=[]; }
function _wcRainKeepWin(team){ const keep=wcRain.filter(c=>c.team===team); _wcRainReset(); for(const c of keep) _wcRainAdd(c); }
function _wcRainAdd(c){
  wcRain.push(c);
  // ô lưới mới phủ mưa
  const r=c.r;
  for(let gx=Math.floor((c.x-r)/WC_CELL); gx<=Math.floor((c.x+r)/WC_CELL); gx++)
    for(let gy=Math.floor((c.y-r)/WC_CELL); gy<=Math.floor((c.y+r)/WC_CELL); gy++){
      const cx=(gx+0.5)*WC_CELL, cy=(gy+0.5)*WC_CELL; if(Math.hypot(cx-c.x,cy-c.y)>r) continue;
      const k=gx+','+gy+','+c.team; if(_wcCellKeys.has(k)) continue; _wcCellKeys.add(k); wcRainCells.push({x:cx,y:cy,team:c.team}); }
  _wcRainStamp(c);
}
// 🖌️ đóng dấu đốm mưa vào bitmap nền ướt (1 lần / đốm; mỗi frame chỉ blit 1 lần — cùng cách vệt dãi cũ _drlStampPuddle)
function _wcRainStamp(c){
  if(!_wcRainCache){ _wcRainCache=document.createElement('canvas'); _wcRainCache.width=Math.ceil(W*_ARENA_SS); _wcRainCache.height=Math.ceil(H*_ARENA_SS); }
  const g=_wcRainCache.getContext('2d');
  g.save(); g.scale(_ARENA_SS,_ARENA_SS);
  g.shadowColor='#0a1428'; g.shadowBlur=c.r*0.5; g.fillStyle='#0a1428';   // ĐỤC 1 màu → chồng nhau không lộ mối nối (độ trong lấy lúc blit)
  g.beginPath(); g.arc(c.x,c.y,c.r*0.8,0,Math.PI*2); g.fill();
  g.restore();
}
function _wcRainRebuild(){ const all=wcRain; _wcRainReset(); for(const c of all) _wcRainAdd(c); }
// đốm mưa (phe KHÁC team) chứa điểm (x,y) — pad = chạm mép cũng tính
function _wcRainAt(team,x,y,pad){
  for(const c of wcRain){ if(c.team===team) continue; const dx=x-c.x, dy=y-c.y, rr=c.r+pad; if(dx*dx+dy*dy<rr*rr) return c; }
  return null;
}
function _wcRainAny(x,y){ for(const c of wcRain){ const dx=x-c.x, dy=y-c.y; if(dx*dx+dy*dy<c.r*c.r) return c; } return null; }
// ⚡ tia sét gấp khúc từ trời giáng xuống (x,y)
function _wcBolt(x,y,big){
  const top=y-460, pts=[[x+(Math.random()-0.5)*90, top]];
  let px=pts[0][0];
  for(let yy=top+16; yy<y; yy+=14+Math.random()*18){ px+=(Math.random()-0.5)*30+(x-px)*0.18; pts.push([px,yy]); }
  pts.push([x,y]);
  const br=[];   // nhánh rẽ phụ
  for(let k=0;k<(big?3:2);k++){ const i=2+((Math.random()*(pts.length-4))|0); if(!pts[i]) continue; let bx=pts[i][0], by=pts[i][1]; const b=[[bx,by]], s=Math.random()<0.5?-1:1;
    for(let j=0;j<4;j++){ bx+=s*(8+Math.random()*14); by+=10+Math.random()*12; b.push([bx,by]); } br.push(b); }
  wcBolts.push({pts, br, x, y, t0:performance.now(), big:!!big});
}
function _wcZap(o, owner){
  const isF=fighters.includes(o), sz=o.size||20;
  _wcBolt(o.x, o.y+sz*0.2, true);
  playSample('holy_thunder',0.9); addShake(9,14);
  o._wcZapT=Math.round(WC_TPS*WC_ZAP_STUN); o._wcZapSd=Math.random()*99;
  if(isF) o.takeDamage(WC_ZAP_DMG, owner); else _summonTakeDamage(o, WC_ZAP_DMG, owner);
  if(isF || o.stun!==undefined) o.stun=Math.max(o.stun||0, Math.round(WC_TPS*WC_ZAP_STUN));   // ⚡ choáng điện 1s
  floatTexts.push({x:o.x,y:o.y-sz-30,text:'⚡ ZAP!',color:'#80d8ff',life:50,big:true});
}
function _wcTick(){
  // chủ gục → mưa tạnh (bỏ đốm mưa của nó)
  if(wcRain.some(c=>!c.owner || c.owner.dead)){ const keep=wcRain.filter(c=>c.owner && !c.owner.dead); _wcRainReset(); for(const c of keep) _wcRainAdd(c); }
  let anyWet=false;
  for(const f of fighters){
    if(f.type!=='wetcat' || f.dead) continue;
    anyWet=true;
    f._wcAge=(f._wcAge||0)+1;
    // 🌧️ mưa lan theo chân: cách đốm gần nhất ≥ 45% bán kính thì đóng thêm 1 đốm mới
    if(!f._wcLast || Math.hypot(f.x-f._wcLast.x,f.y-f._wcLast.y)>WC_RAIN_R*0.45){
      f._wcLast={x:f.x,y:f.y}; _wcRainAdd({x:f.x,y:f.y,r:WC_RAIN_R,team:f.team,owner:f}); }
    // 🌩️ thỉnh thoảng sét đánh xuống chỗ ngẫu nhiên trong vùng mưa (chỉ cho có không khí — dame là phần tung xúc xắc bên dưới)
    if(f._wcAmbCD===undefined) f._wcAmbCD=Math.round(WC_TPS*2);
    if(--f._wcAmbCD<=0){
      f._wcAmbCD=Math.round(WC_TPS*(2.5+Math.random()*3));
      const mine=wcRainCells.filter(c=>c.team===f.team);
      if(mine.length){ const c=mine[(Math.random()*mine.length)|0], x=c.x+(Math.random()-0.5)*WC_CELL, y=c.y+(Math.random()-0.5)*WC_CELL;
        if(_wcRainAny(x,y)){ _wcBolt(x,y,false); playSample('holy_thunder',0.4); addShake(3,6); } }
    }
  }
  // 🔊 tiếng mưa rả rích suốt lúc có Wet Cat trên sàn
  if(anyWet && !_wcRainSfx){ const a=AUDIO_SAMPLES['dp_rain'];
    if(a){ try{ const c=a.cloneNode(); c.loop=true; c.volume=0.45; _mixRoute(c); c.play().catch(()=>{}); _wcRainSfx=c; }catch(e){} } }
  else if(!anyWet && _wcRainSfx){ _stopLoopAudio(_wcRainSfx); _wcRainSfx=null; }
  // địch (+ quân triệu hồi có máu) trong mưa
  const half=Math.round(WC_TPS*0.5), zapT=Math.round(WC_TPS*WC_ZAP_EVERY);
  const units=[...fighters.filter(o=>!o.dead)];
  for(const arr of _hpSummonArrays()) for(const u of arr) if(u && !u.dead && u.hp>0) units.push(u);
  for(const o of units){
    if((o._wcZapT||0)>0) o._wcZapT--;
    if(!wcRain.length) continue;
    const c=_wcRainAt(o.team,o.x,o.y,(o.size||20)*0.5);
    if(!c){ o._wcRainDot=0; continue; }
    const isF=fighters.includes(o);
    o._wcRainDot=(o._wcRainDot||0)+1;
    if(o._wcRainDot>=half){ o._wcRainDot=0;
      if(isF) o.takeDamage(WC_RAIN_DMG, c.owner, false, true); else _summonTakeDamage(o, WC_RAIN_DMG, c.owner, false, true); }
    o._wcZapAcc=(o._wcZapAcc||0)+1;
    if(o._wcZapAcc>=zapT){ o._wcZapAcc=0; if(Math.random()<WC_ZAP_P && !o.dead && o.hp>0) _wcZap(o, c.owner); }
  }
}
// ===================== 🎷 EPIC SAX GUY =====================
// Chu kỳ: trước mỗi lần thổi 1s có 1 con Squirtle TỪ TỪ chui lên khỏi sàn ở chỗ ngẫu nhiên (không đè lên con nào
// đã có, không bao giờ biến mất, không giới hạn số con) → cả bọn cùng thổi sax hết bài → nghỉ lấy hơi 2s → lặp lại.
// Lúc đang thổi: Epic Sax Guy chỉ còn 80% tốc chạy và chịu ít hơn 35% sát thương.
// Mỗi nhịp thổi, MỖI con Squirtle nện ra một luồng sóng âm gợn vòng đồng tâm trên mặt sàn, địch đứng trong vùng
// ăn 20→40 dame tuỳ khoảng cách (sát chân Squirtle là ăn đủ 40).
const ESG_SAX_VOL=0.9*1.3;     // nhạc sax: 0.9 → +30% = 1.17 (>1 nên phải khuếch đại qua gain node)
// ⏱️ MỌI mốc thời gian ở đây tính theo GIÂY THẬT: game chạy 60×GAME_SPEED×TIME_SCALE ≈ 72 tick mỗi giây thật
// (không phải 60) — tính nhầm 60 thì bài sax bị cắt cụt, nhịp sóng âm nhanh hơn nhạc.
const ESG_TPS=60*GAME_SPEED*TIME_SCALE;
const ESG_SAX_RATE=1.1;        // 🎷 nhạc sax phát nhanh ×1.1 (nhịp + độ dài bài co lại theo)
const ESG_BREATH_T=Math.round(1.0*ESG_TPS);   // 1s thật lấy hơi (3 khung thở chạy gọn trong đó, tiếng thở tăng tốc cho vừa)
const ESG_BREATH_RATE=1.4;                    // tiếng thở gốc dài 1.4s → phát nhanh ×1.4 cho khít đúng 1s
const ESG_PRE_T=Math.round(1.0*ESG_TPS);      // 1s thật: Squirtle nhô lên trước khi vào bài
const ESG_PLAY_T=Math.round(4*ESG_TPS);       // dài mặc định 1 lần thổi khi chưa có file nhạc (4s)
const ESG_BEAT=0.464/ESG_SAX_RATE*ESG_TPS;    // 1 nhịp nhạc (bài ~129 BPM = 0.464s, đã chia tốc phát) tính ra tick — số lẻ
// 🎷 GIF thổi sax của user đã cắt sẵn thành sprite sheet (mỗi 3 khung gốc lấy 1). Canvas không tự chạy được GIF
// nên phải tự lật khung. Cả vòng GIF ép vừa ĐÚNG 14 nhịp nhạc (6.5s) — nhanh hơn tốc gốc một chút cho khớp nhịp.
const ESG_SAX_IMG=new Image(); ESG_SAX_IMG.src='assets/img/epicsaxguy/ESG_SAX_IMG.webp';
// ESG_SAX_BEATS: đo trên chính GIF — động tác nhún lặp lại mỗi ~6 khung ⇒ 1 cú nhún = 1 nhịp nhạc ⇒ cả vòng 64 khung = 64/6 nhịp
const ESG_SAX_COLS=10, ESG_SAX_ROWS=7, ESG_SAX_N=64, ESG_SAX_BEATS=64/6;
// 🐢 GIF Squirtle thổi sax của user, cũng cắt sẵn thành sheet, cả vòng chạy vừa 12 nhịp nhạc cho khớp với ông chủ
const ESG_SQ_IMG=new Image(); ESG_SQ_IMG.src='assets/img/epicsaxguy/ESG_SQ_IMG.webp';
const ESG_SQ_COLS=10, ESG_SQ_ROWS=5, ESG_SQ_N=43, ESG_SQ_BEATS=12;
ESG_SAX_IMG._cols=ESG_SAX_COLS; ESG_SAX_IMG._rows=ESG_SAX_ROWS; ESG_SAX_IMG._frames=ESG_SAX_N;
// ⚠️ ảnh user gửi ĐÃ xoá nền sẵn → phải chặn _stickerMask: hàm đó erosion r=4 rồi chỉ giữ mảng liền lớn nhất,
// nên nó cắn đứt cây kèn rời ra và viền sáng quanh người (đúng lỗi mất nửa cây đàn của Electric Guitar Cat).
ESG_SAX_IMG._noMask=true; ESG_SQ_IMG._noMask=true;   // dùng luôn đường vẽ sprite-sheet sẵn có của engine
const ESG_R=143;               // bán kính vùng dư âm quanh mỗi Squirtle (130 → 143: nới 10%)
const ESG_DMG_NEAR=46, ESG_DMG_FAR=23;   // 20-40 → +15%
const ESG_SHOW_WAVE_VFX=true;    // hình sóng âm của Squirtle (bản nhẹ: 2 vòng nét mảnh, không tô mảng)
let saxSquirtles=[];           // {x,y,owner,team,rise} — mọc rồi là ở lại tới hết trận
let saxWaves=[];               // vòng gợn sóng âm: {x,y,t}
let esgNotes=[];               // ♪ nốt nhạc bật ra chỗ địch ăn dame: {x,y,vx,vy,t,big}
// 🎨 CÂN MÀU giữa các bộ ảnh: 3 ảnh THỞ user up lệch màu so với GIF thổi sax → đổi qua lại nhìn "nhảy màu". Đo trung bình +
// độ lệch chuẩn từng kênh R,G,B trên phần có hình của ảnh THAM CHIẾU (GIF), rồi kéo ảnh cần chỉnh về đúng các chỉ số đó
// (chuyển màu kiểu Reinhard, làm trong RGB). Tính 1 lần cho mỗi bộ ảnh tham chiếu, trả về canvas đã chỉnh để vẽ thay.
// thống kê tông màu trên phần có hình: độ sáng (trung bình + độ lệch = tương phản) và độ đậm màu trung bình
function _pxStats(list){
  let n=0, sL=0, sL2=0, sS=0;
  for(const im of list){
    const w=im.naturalWidth||im.width, h=im.naturalHeight||im.height; if(!w||!h) continue;
    const sc=Math.min(1, 240/Math.max(w,h)), cw=Math.max(1,Math.round(w*sc)), ch=Math.max(1,Math.round(h*sc));
    const c=document.createElement('canvas'); c.width=cw; c.height=ch; const g=c.getContext('2d'); g.drawImage(im,0,0,cw,ch);
    let d; try{ d=g.getImageData(0,0,cw,ch).data; }catch(e){ continue; }
    for(let i=0;i<d.length;i+=4){ if(d[i+3]<200) continue;
      const r=d[i],gg=d[i+1],bb=d[i+2], L=0.299*r+0.587*gg+0.114*bb, mx=Math.max(r,gg,bb), mn=Math.min(r,gg,bb);
      n++; sL+=L; sL2+=L*L; sS+=(mx-mn); }
  }
  if(n<50) return null;
  const mL=sL/n; return { mL, sdL:Math.sqrt(Math.max(1,sL2/n-mL*mL)), mC:Math.max(1,sS/n) };
}
// kéo ảnh về CÙNG TÔNG với ảnh tham chiếu: khớp độ sáng + tương phản (trên kênh sáng) và độ đậm màu (co/giãn phần
// màu quanh mức xám). Không dịch sắc độ nên áo trắng vẫn trắng, găng đỏ vẫn đỏ — chỉ bớt rực / bớt gắt.
function _esgColorMatched(sheet, refs){
  refs=refs.filter(im=>im && im.complete && im.naturalWidth>0);
  if(!sheet || !refs.length || !(sheet.complete && sheet.naturalWidth)) return sheet;
  const key=refs.map(im=>(im.src||'').length+':'+(im.src||'').slice(-24)).join('|');
  if(!sheet._ccMap) sheet._ccMap=new Map();
  if(sheet._ccMap.has(key)) return sheet._ccMap.get(key);
  const R=_pxStats(refs), T=_pxStats([sheet]);
  if(!R || !T){ sheet._ccMap.set(key,sheet); return sheet; }
  const kL=Math.max(0.6,Math.min(1.4,R.sdL/T.sdL));          // tương phản
  const kC=Math.max(0.45,Math.min(1.3,R.mC/T.mC));           // độ đậm màu
  const cv=document.createElement('canvas'); cv.width=sheet.naturalWidth; cv.height=sheet.naturalHeight;
  const g=cv.getContext('2d'); g.drawImage(sheet,0,0);
  const id=g.getImageData(0,0,cv.width,cv.height), d=id.data;
  for(let i=0;i<d.length;i+=4){ if(d[i+3]<8) continue;
    const r=d[i],gg=d[i+1],bb=d[i+2], L=0.299*r+0.587*gg+0.114*bb;
    const L2=(L-T.mL)*kL+R.mL;
    let o0=L2+(r-L)*kC, o1=L2+(gg-L)*kC, o2=L2+(bb-L)*kC;
    d[i]=o0<0?0:o0>255?255:o0; d[i+1]=o1<0?0:o1>255?255:o1; d[i+2]=o2<0?0:o2>255?255:o2; }
  g.putImageData(id,0,0);
  // cho canvas "giả làm" ảnh gốc: đường vẽ của engine đọc các thuộc tính này
  cv.naturalWidth=cv.width; cv.naturalHeight=cv.height; cv.complete=true;
  cv._cols=sheet._cols; cv._rows=sheet._rows; cv._frames=sheet._frames; cv._ccOf=sheet;
  if(sheet._noMask) cv._noMask=true;
  if(sheet._crop===undefined && !((sheet._frames||1)>1)) sheet._crop=computeCropBox(sheet)||null;
  cv._crop=sheet._crop;
  sheet._ccMap.set(key,cv); return cv;
}
function _esgSquirtleR(f){ return (f?f.size:40)/3*1.44; }   // 1/3 một con meme thường, rồi +20% hai lần (1.2×1.2)
// chỗ mọc ngẫu nhiên, không trùng chỗ mấy con đã có
function _esgSpawnSpot(f){
  const r=_esgSquirtleR(f), pad=Math.max(r+18, W*0.16);   // chừa lề ~16% sàn: hạn chế mọc sát tường
  let best=null, bestD=-1;
  for(let k=0;k<40;k++){
    const x=pad+Math.random()*(W-pad*2), y=pad+Math.random()*(H-pad*2);
    let d=Infinity;
    for(const s of saxSquirtles) d=Math.min(d, Math.hypot(s.x-x, s.y-y));
    if(d===Infinity) return {x,y};
    if(d>r*3) return {x,y};                 // đủ xa mọi con cũ → lấy luôn
    if(d>bestD){ bestD=d; best={x,y}; }     // không thì giữ chỗ xa nhất tìm được
  }
  return best||{x:W/2,y:H/2};
}
function _esgTick(f){
  if(f.dead) return;
  if(f._esgPhase===undefined){ f._esgPhase='pre'; f._esgT=ESG_PRE_T; f._esgBeat=0; }
  // 💫 dính choáng thật → cả Sax Guy lẫn đàn rùa NGỪNG thổi: nhạc tạm dừng, không nện sóng, không mọc rùa,
  // mọi đồng hồ đứng yên. Hết choáng thì bài chạy tiếp đúng chỗ dở.
  if(f._isHardCC()){
    if(f._esgMusic && !f._esgMusic.paused){ try{ f._esgMusic.pause(); }catch(e){} f._esgCcPaused=true; }
    f._esgStunned=true;
    return;
  }
  if(f._esgStunned){
    f._esgStunned=false;
    if(f._esgCcPaused && f._esgMusic) f._esgMusic.play().catch(()=>{});
    f._esgCcPaused=false;
  }
  if(f._esgPhase==='pre'){
    if(f._esgT===ESG_PRE_T){                 // đầu pha: cắm 1 con Squirtle mới, nó nhô lên dần trong 1s
      const sp=_esgSpawnSpot(f);
      saxSquirtles.push({ x:sp.x, y:sp.y, owner:f, team:f.team, rise:0, sd:Math.random()*99 });
    }
    f._esgT--;
    if(f._esgT<=0){
      f._esgPhase='play'; f._esgBeat=0;
      const a=AUDIO_SAMPLES['sax_song']?.cloneNode();
      if(a){ _esgRouteSax(a); a.playbackRate=ESG_SAX_RATE; a.play().catch(()=>{}); f._esgMusic=a; f._esgPulseN=-1;
        const _d=(isFinite(AUDIO_SAMPLES['sax_song'].duration)&&AUDIO_SAMPLES['sax_song'].duration>0) ? AUDIO_SAMPLES['sax_song'].duration : 4;
        f._esgT=Math.max(60, Math.round(_d/ESG_SAX_RATE*ESG_TPS)); }   // độ dài bài THẬT (đã tăng tốc) đổi ra tick
      else f._esgT=ESG_PLAY_T;
    }
  } else if(f._esgPhase==='play'){
    f._esgT--;
    if(f._esgMusic && f._esgMusic.ended) f._esgT=0;
    else _esgEnsureMusic(f,false);
    { const _n=Math.floor((f._esgBeat++)/ESG_BEAT);         // 🎵 mỗi nhịp: mọi Squirtle cùng nện 1 luồng sóng âm
      if(_n!==f._esgPulseN){ f._esgPulseN=_n; _esgPulse(f); } }
    if(f._esgT<=0){ f._esgPhase='breath'; f._esgT=ESG_BREATH_T; _esgStopMusic(f);
      const _br=AUDIO_SAMPLES['sax_breath']?.cloneNode();                      // 😮‍💨 thở hổn hển — tăng tốc vừa khít 1s lấy hơi
      if(_br){ _br.volume=1; _mixRoute(_br); _br.playbackRate=ESG_BREATH_RATE; _br.play().catch(()=>{}); } }   // 😮‍💨 thở hổn hển lúc lấy hơi
  } else {
    f._esgT--;
    if(f._esgT<=0){ f._esgPhase='pre'; f._esgT=ESG_PRE_T; }
  }
  for(const s of saxSquirtles){ if(s.rise<1) s.rise=Math.min(1, s.rise+1/ESG_PRE_T); }
}
// âm lượng >1 → khuếch đại qua gain node (_playLoud), không được thì chịu mức tối đa 1.0
function _esgRouteSax(a){ a.volume=Math.min(1,ESG_SAX_VOL); if(!(ESG_SAX_VOL>1 && _playLoud(a,ESG_SAX_VOL))) _mixRoute(a); }
// 🛟 CANH NHẠC: đang ở pha thổi mà bài sax bị dừng (không phải hết bài) hoặc bị chiêu khác xoá mất (vd dính
// Rick Roll → _stopFighterSfx) thì tự phát lại ĐÚNG đoạn đang dở — trước đây hết choáng là câm luôn tới hết lượt.
function _esgEnsureMusic(f, loop){
  const src=AUDIO_SAMPLES['sax_song']; if(!src) return;
  let a=f._esgMusic;
  if(a && a.ended && !loop) return;                 // hết bài thật → để pha thổi tự kết thúc như thường
  if(!a){
    a=src.cloneNode(); a.loop=!!loop; _esgRouteSax(a); a.playbackRate=ESG_SAX_RATE;
    const dur=(isFinite(src.duration)&&src.duration>0)?src.duration:7.25;
    const pos=((f._esgBeat||0)/ESG_TPS*ESG_SAX_RATE)%dur;   // _esgBeat = số tick đã thổi từ đầu bài → giây trong bài
    try{ a.currentTime=pos; }catch(e){}
    f._esgMusic=a; f._esgLastTime=pos;
  }
  if(a.paused) a.play().catch(()=>{});
}
function _esgStopMusic(f){ if(f._esgMusic){ try{ f._esgMusic.pause(); f._esgMusic.currentTime=0; }catch(e){} f._esgMusic=null; } }
// 🌊 1 nhịp sóng âm: mỗi Squirtle bung 1 vùng dư âm, địch trong vùng ăn 20→40 dame tuỳ cự ly tới chính con đó
function _esgPulse(f){
  for(const s of saxSquirtles){
    if(s.owner!==f || s.rise<1) continue;
    saxWaves.push({ x:s.x, y:s.y, t:0, bars:Array.from({length:16},()=>0.35+Math.random()*0.65), rot:Math.random()*Math.PI });
    s.pulse=1;          // 🐢 nện nhịp: rùa nảy người lên một nhịp (chỉ là phép nhân lúc vẽ, không tốn gì)
    const _dmgAt=d=>Math.round(ESG_DMG_FAR + (ESG_DMG_NEAR-ESG_DMG_FAR)*(1-Math.min(1,d/ESG_R)));
    for(const _arr of _hpSummonArrays()) for(const u of _arr){     // ⚠️ summon trước, fighter sau (quy tắc chung của mọi AOE)
      if(u.dead||u.hp<=0||u.team===s.team) continue;
      const d=Math.hypot(u.x-s.x,u.y-s.y); if(d>ESG_R+(u.size||0)*0.5) continue;
      _summonTakeDamage(u, _dmgAt(d), f, false, false, null, true);
    }
    for(const o of fighters){
      if(o.dead||o.team===s.team) continue;
      const d=Math.hypot(o.x-s.x,o.y-s.y); if(d>ESG_R+o.size*0.5) continue;
      o.takeDamage(_dmgAt(d), f);
      esgNotes.push({ x:o.x+(Math.random()-0.5)*o.size, y:o.y-o.size*0.6, vy:-(0.9+Math.random()*0.5),
        vx:(Math.random()-0.5)*0.7, t:0, sd:Math.random()*99, big:d<ESG_R*0.45 });   // ♪ bay lên chỗ vừa trúng
    }
  }
}
// 🐢 Squirtle: chui lên từ dưới sàn (cắt phần còn nằm dưới mặt đất) — có ảnh upload thì dùng ảnh, chưa có thì vẽ tạm
function _esgDrawSquirtles(){
  for(const s of saxSquirtles){
    const f=s.owner, i=f?f.slotIdx:0, r=_esgSquirtleR(f);
    const _still=(i!==undefined && rageAvatarImgs[i] && rageAvatarImgs[i].complete && rageAvatarImgs[i].naturalWidth) ? rageAvatarImgs[i] : null;
    const _playing=!!(f && f._esgPhase==='play' && !f._esgStunned);   // ông chủ đang choáng → rùa cũng ngừng thổi
    // đang thổi → GIF nhún theo nhịp; đứng yên → ảnh tĩnh user up vào ô "Squirtle (đứng yên)"
    const im = (_playing && ESG_SQ_IMG.complete && ESG_SQ_IMG.naturalWidth) ? ESG_SQ_IMG
             : _still ? _still
             : (ESG_SQ_IMG.complete && ESG_SQ_IMG.naturalWidth) ? ESG_SQ_IMG : null;
    if(s.pulse>0) s.pulse=Math.max(0, s.pulse-0.09);
    const _pk=Math.sin(s.pulse*Math.PI)*0.16;                    // nện nhịp: phình lên rồi về, đỉnh +16%
    const h=r*2*(1+_pk), bob=(f && f._esgPhase==='play' && !f._esgStunned) ? Math.sin((Date.now()/120)+s.sd)*r*0.12 : 0;
    ctx.save();
    ctx.beginPath(); ctx.rect(s.x-r*2, s.y-h*2, r*4, h*2+r*0.35); ctx.clip();   // chỉ thấy phần đã nhô khỏi mặt sàn
    const top=s.y+ (1-s.rise)*h - h + bob;
    if(im===ESG_SQ_IMG){
      const _fw=ESG_SQ_IMG.naturalWidth/ESG_SQ_COLS, _fh=ESG_SQ_IMG.naturalHeight/ESG_SQ_ROWS;
      const _k=(f && f._esgPhase==='play' && !f._esgStunned)
        ? Math.floor((f._esgBeat||0)/(ESG_BEAT*ESG_SQ_BEATS/ESG_SQ_N))%ESG_SQ_N : 0;   // lật khung theo đúng nhịp nhạc
      const w=h*_fw/_fh;
      ctx.drawImage(ESG_SQ_IMG, (_k%ESG_SQ_COLS)*_fw, Math.floor(_k/ESG_SQ_COLS)*_fh, _fw,_fh, s.x-w/2, top, w, h);
    } else if(im){
      // ⚠️ ảnh tĩnh user up thường có viền trống quanh con vật, trong khi mỗi ô của GIF đã cắt sát người → vẽ
      // thẳng cả tấm thì lúc đứng yên nhìn BÉ hơn hẳn lúc thổi kèn. Cắt đúng phần có hình rồi mới vẽ cho bằng nhau.
      if(im._crop===undefined) im._crop=computeCropBox(im)||null;
      const _c=im._crop, _cw=_c?_c.sw:im.naturalWidth, _ch=_c?_c.sh:im.naturalHeight;
      const _cx=_c?_c.sx:0, _cy=_c?_c.sy:0;
      // 🫁 đứng yên thì thở nhẹ: phình/xẹp rất khẽ quanh chân cho đỡ cứng như ảnh dán
      const _br=Math.sin(Date.now()/620 + s.sd), _sy=1+_br*0.035, _sx2=1-_br*0.018;
      const w=h*_cw/_ch, _hh=h*_sy, _ww=w*_sx2;
      ctx.drawImage(im, _cx,_cy,_cw,_ch, s.x-_ww/2, top+h-_hh, _ww, _hh);
    }
    else {
      ctx.translate(s.x, top+h*0.5);
      ctx.fillStyle='#4fc3f7'; ctx.beginPath(); ctx.ellipse(0,0,r*0.78,r*0.62,0,0,Math.PI*2); ctx.fill();   // thân
      ctx.fillStyle='#ffb74d'; ctx.beginPath(); ctx.ellipse(0,r*0.05,r*0.5,r*0.36,0,0,Math.PI*2); ctx.fill(); // mai bụng
      ctx.fillStyle='#4fc3f7'; ctx.beginPath(); ctx.arc(-r*0.62,-r*0.42,r*0.34,0,Math.PI*2); ctx.fill();      // đầu
      ctx.fillStyle='#d4a017'; ctx.fillRect(-r*0.2,-r*0.75,r*0.16,r*0.95);                                    // kèn sax
      ctx.beginPath(); ctx.arc(-r*0.12,r*0.2,r*0.24,Math.PI*0.9,Math.PI*2.1); ctx.fill();
    }
    ctx.restore();
  }
}
// 🌊 sóng âm lúc gây dame — kiểu "EQUALIZER": 16 cột nhạc xếp thành vòng quanh Squirtle, bung ra theo nhịp như
// thanh sóng nhạc rồi tan, cộng 1 vòng mảnh đánh dấu đúng mép vùng dame. Toàn nét vẽ (stroke) — không tô mảng,
// không gradient, không shadow → rẻ như 2 vòng tròn cũ.
function _esgDrawWaves(){
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  ctx.lineCap='round';
  for(let i=saxWaves.length-1;i>=0;i--){
    const w=saxWaves[i]; w.t++;
    const k=w.t/24; if(k>=1){ saxWaves.splice(i,1); continue; }
    const ek=1-Math.pow(1-k,3);                              // bung nhanh rồi chậm lại
    const a=1-k;
    // 🎚️ 16 cột equalizer: gốc cột trôi ra xa dần, độ dài mỗi cột theo "âm lượng" ngẫu nhiên của nhịp đó.
    // 🚀 GỘP nét: cột vàng 1 path, cột xanh 1 path, chấm sáng đầu cột 1 path → 3 lệnh vẽ thay vì 32
    const r0=ESG_R*(0.18+0.62*ek);
    ctx.lineWidth=Math.max(1.5, ESG_R*0.045*(1-k*0.5));
    ctx.globalAlpha=a*0.85;
    const pY=new Path2D(), pC=new Path2D(), pD=new Path2D(), dr=Math.max(1.2,ESG_R*0.02*(1-k*0.5));
    for(let j=0;j<16;j++){
      const ang=w.rot+j/16*Math.PI*2, ca=Math.cos(ang), sa=Math.sin(ang)*0.42;   // dẹt theo phối cảnh mặt sàn
      const len=ESG_R*0.26*w.bars[j]*(1-k*0.4), pp=(j%2)?pY:pC;
      pp.moveTo(w.x+ca*r0, w.y+sa*r0); pp.lineTo(w.x+ca*(r0+len), w.y+sa*(r0+len));
      const ex=w.x+ca*(r0+len), ey=w.y+sa*(r0+len); pD.moveTo(ex+dr,ey); pD.arc(ex,ey,dr,0,Math.PI*2);
    }
    ctx.strokeStyle='#ffd54f'; ctx.stroke(pY);
    ctx.strokeStyle='#4dd0e1'; ctx.stroke(pC);
    ctx.globalAlpha=a*0.9; ctx.fillStyle='#ffffff'; ctx.fill(pD);          // ✨ chấm sáng ở đỉnh mỗi cột
    // 💥 nhịp nện: 1 quầng sáng dẹt loé dưới chân rùa đúng lúc phát sóng
    if(k<0.35){ const q=k/0.35;
      ctx.globalAlpha=0.3*(1-q); ctx.fillStyle='#ffd54f';
      ctx.beginPath(); ctx.ellipse(w.x, w.y+ESG_R*0.03, ESG_R*0.28*(1+q*0.8), ESG_R*0.11*(1+q*0.8), 0, 0, Math.PI*2); ctx.fill(); }
    // 🔊 vòng cung "((( )))" bắn ra 2 bên như sóng loa
    ctx.lineWidth=Math.max(1.2, ESG_R*0.022);
    for(let m=0;m<3;m++){
      const kk=k*1.25-m*0.18; if(kk<=0||kk>=1) continue;
      const rr=ESG_R*(0.2+0.55*kk);
      ctx.globalAlpha=(1-kk)*0.75; ctx.strokeStyle= m===1 ? '#80deea' : '#e0f7fa';
      ctx.beginPath();
      ctx.ellipse(w.x, w.y-ESG_R*0.12, rr, rr*0.7, 0, -0.55, 0.55);
      ctx.moveTo(w.x+Math.cos(Math.PI-0.55)*rr, w.y-ESG_R*0.12+Math.sin(Math.PI-0.55)*rr*0.7);
      ctx.ellipse(w.x, w.y-ESG_R*0.12, rr, rr*0.7, 0, Math.PI-0.55, Math.PI+0.55);
      ctx.stroke();
    }
    // vòng mảnh ở ĐÚNG mép vùng dame (cho biết đứng đâu thì dính)
    ctx.globalAlpha=a*0.45; ctx.lineWidth=1.5; ctx.strokeStyle='#ffe082';
    ctx.beginPath(); ctx.ellipse(w.x, w.y, ESG_R*ek, ESG_R*ek*0.42, 0, 0, Math.PI*2); ctx.stroke();
  }
  ctx.restore();
  // ♪ nốt nhạc: chỉ là fillText, bay lên rồi mờ dần
  if(esgNotes.length){
    ctx.save(); ctx.textAlign='center'; ctx.textBaseline='middle';
    for(let i=esgNotes.length-1;i>=0;i--){
      const q=esgNotes[i]; q.t++;
      const k=q.t/40; if(k>=1){ esgNotes.splice(i,1); continue; }
      q.x+=q.vx+Math.sin((q.t+q.sd)/9)*0.35; q.y+=q.vy; q.vy*=0.985;
      ctx.globalAlpha=(1-k)*0.95;
      ctx.fillStyle=q.big?'#ffd54f':'#fff3c4';
      ctx.font=`${Math.round((q.big?15:11)*(W/480))}px serif`;
      ctx.fillText((q.sd|0)%2 ? '♪' : '♫', q.x, q.y);
    }
    ctx.restore();
  }
}

// ===================== 🍳 CORNELIUS =====================
// Phi chảo liên tục (50 dame/cái). Con địch nào ăn đủ 8 chảo → mở khoá "sẵn sàng bị nấu" (có dấu 🍳 trên đầu).
// Lần tới Cornelius áp sát nó: 1 cái CHẢO KHỔNG LỒ hiện ra ngay dưới chân nó + chữ "LET HIM COOK" bật lên, địch
// đứng trong chảo bị lắc tới lắc lui theo quán tính của chảo, trong chảo có đồ ăn và lửa cháy, nấu trong 2.5s
// rồi ăn 300 dame.
// ⚠️ chữ LET HIM COOK KHÔNG đẩy qua floatTexts: loop() xoá sạch mọi floatText không phải số dame mỗi frame.
const CN_THROW_CD=78;          // 1.3s / 1 chảo (1.1s → chậm thêm 0.2s)
const CN_PAN_SPD=7.5, CN_PAN_DMG=60, CN_UNLOCK_HITS=8;
const CN_COOK_T=150;           // 2.5s nấu
const CN_COOK_DMG=300;
const CN_NEAR=46;              // "tới gần": khoảng hở giữa 2 thân dưới mức này là bắt đầu nấu
const CN_FOODS=['🥓','🍅','🧅','🥕','🍄','🌶️','🍖','🥚'];
let cnPans=[];                 // chảo đang bay: {x,y,vx,vy,rot,owner,team,life}
let cnCooks=[];                // chảo khổng lồ đang nấu: {f,e,t,x,y,R,sway}
let cnTexts=[];                // chữ LET HIM COOK: {x,y,t,life,scl}
// 🍳 ảnh chảo user gửi (489×360, đã xoá nền). Số đo đo thẳng trên pixel của chính ảnh:
//   • khung có hình: x 42→406, y 76→259 (cán nằm góc trên-trái)
//   • MIỆNG CHẢO (elip): tâm (259,153), bán trục ngang 141, dọc 35 — lòng chảo sáng từ y=118 tới ~188 ở cột giữa
// Chảo khổng lồ: vẽ nguyên ảnh DƯỚI meme, rồi vẽ lại đúng phần nằm dưới mép trước của miệng chảo ĐÈ LÊN meme
// → con bị nấu (và đồ ăn) nhìn như đang nằm TRONG lòng chảo.
const CN_WOK_IMG=new Image(); CN_WOK_IMG.src='assets/img/cornelius/CN_WOK_IMG.webp';
// 🍳 chảo NÉM riêng (user gửi pan.png 148×148, phần có hình x 9→138, y 7→138)
const CN_PAN_IMG=new Image(); CN_PAN_IMG.src='assets/img/cornelius/CN_PAN_IMG.webp';
const CN_PAN_BOX={ x:9, y:7, w:129, h:131 };
const CN_WOK={ W:489, H:360, bx0:42, by0:76, bx1:406, by1:259, cx:259, cy:153, rx:141, ry:35, hx:52, hy:82 };   // hx,hy = đầu cán chảo (chỗ cầm)
function _cnPanImg(f){
  return (CN_WOK_IMG.complete && CN_WOK_IMG.naturalWidth) ? CN_WOK_IMG : null;
}
const CN_THROW_LEAN_T=16;       // ~0.27s: ngả tới rồi hồi lại mỗi lần ném chảo
function _cnTick(f){
  if(f.dead) return;
  if(f._cnThrowT>0) f._cnThrowT--;
  // đang nấu ai thì thôi không phi thêm (đứng nấu)
  if(cnCooks.some(c=>c.f===f)) return;
  // 🍳 địch đã mở khoá + mình áp sát → dựng chảo khổng lồ ngay dưới chân nó
  for(const e of fighters){
    if(e.dead || e.team===f.team || !e._cnReady) continue;
    const gap=Math.hypot(e.x-f.x,e.y-f.y)-f.size-e.size;
    if(gap<=CN_NEAR){ _cnStartCook(f,e); return; }
  }
  f._cnCD=(f._cnCD===undefined?30:f._cnCD)-1;
  if(f._cnCD>0 || f.stun>2) return;
  const tg=_findClosestEnemy(f.team, f.x, f.y);
  if(!tg) return;
  f._cnCD=CN_THROW_CD;
  const ang=Math.atan2(tg.y-f.y, tg.x-f.x);
  cnPans.push({ x:f.x+Math.cos(ang)*f.size*0.7, y:f.y+Math.sin(ang)*f.size*0.7,
    vx:Math.cos(ang)*CN_PAN_SPD, vy:Math.sin(ang)*CN_PAN_SPD, rot:0, owner:f, team:f.team, life:140 });
  f.actionState='attack'; f.actionTimer=14; f.attackAvatarTimer=14;
  f._cnThrowT=CN_THROW_LEAN_T;                  // 🍳 ngả người tới trước theo cú ném
}
// 🍳 CHẢO XÓC có vật lý thật: mọi thứ trong chảo (đồ ăn + chính con meme địch) là HẠT, sống trong hệ toạ độ
// gắn với chảo. Chảo đẩy tới / giật lên theo nhịp xóc → trong hệ đó mọi hạt chịu thêm lực quán tính = −gia tốc
// của chảo, nên đồ ăn bị hất văng lên trễ nhịp rồi rơi lại vào lòng chảo (va vào mặt cong, nảy nhẹ, trượt về giữa).
// Con meme nặng hơn nên văng ít hơn đồ ăn.
// Toạ độ trong chảo: gốc = tâm miệng chảo, x sang phải, y hướng XUỐNG. Mặt lòng chảo: y = _cnBowl(x).
const CN_FOOD_KIND=[                       // [màu, kiểu vẽ, số lượng]
  ['#e8a24a','rice',46], ['#d9913a','rice',20], ['#66bb6a','pea',9], ['#ffd54f','corn',9],
  ['#ff7043','cube',7],  ['#c0604a','bacon',5], ['#ffffff','egg',1] ];
function _cnBowl(c,lx){ const u=lx/c.R; return c.D*(1-u*u); }
function _cnStartCook(f,e){
  e._cnReady=false; e._cnHits=0;
  const R=Math.max(e.size*1.7, 64);
  // 🍳 cán chảo quay về PHÍA Cornelius đang đứng (ảnh gốc cán nằm bên TRÁI → Cornelius ở bên phải thì lật chảo)
  const c={ f, e, t:0, x:e.x, y:e.y+e.size*0.35, R, D:R*0.2, ox:0, oy:0, pox:0, poy:0, ppox:0, ppoy:0, tilt:0, fl:(f.x>e.x?-1:1),
            sd:Math.random()*99, parts:[] };
  for(const [col,kind,n] of CN_FOOD_KIND) for(let k=0;k<n;k++){
    const lx=(Math.random()*2-1)*R*0.72;
    c.parts.push({ lx, ly:_cnBowl(c,lx)-Math.random()*R*0.1, vx:0, vy:0, col, kind,
      sz:(kind==='egg'?0.3:kind==='bacon'?0.11:kind==='cube'?0.065:kind==='rice'?0.045:0.05)*R, rot:Math.random()*6, heavy:kind==='egg'?0.7:1 });
  }
  c.meme={ lx:0, ly:c.D*0.55, vx:0, vy:0 };    // chính con meme địch — hạt nặng
  cnCooks.push(c);
  _cnHold(c);                                   // ⚡ dịch chuyển tức thì ra đúng chỗ cầm cán chảo
  { const _ck=AUDIO_SAMPLES['cn_cook']?.cloneNode();   // 🔥 tiếng nấu — file đã tăng tốc sẵn vừa đúng 2.5s, phát đúng tốc 1.0
    if(_ck){ _ck.volume=1; _ck.playbackRate=1; _mixRoute(_ck); _ck.play().catch(()=>{}); c.sfx=_ck; } }
  cnTexts.push({ x:e.x, y:e.y-R*1.15, t:0, life:96, seed:Math.random()*Math.PI*2 });
  addShake(6,10);
}
// 1 bước vật lý cho 1 hạt trong hệ toạ độ chảo
// toạ độ thế giới của ĐẦU CÁN chảo — theo đúng chảo đang xóc/nghiêng, Cornelius đứng đó cầm chảo
function _cnHandlePos(c){
  const k=c.R/CN_WOK.rx, sc=0.6+0.4*Math.min(1,c.t/8);
  const lx=(CN_WOK.hx-CN_WOK.cx)*k*sc, ly=(CN_WOK.hy-CN_WOK.cy)*k*sc;
  const cs=Math.cos(c.tilt||0), sn=Math.sin(c.tilt||0);
  const fl=c.fl||1;
  return { x:c.x+fl*((c.ox||0)+lx*cs-ly*sn), y:c.y+(c.oy||0)+lx*sn+ly*cs };
}
// Cornelius đứng yên ở đầu cán, tay giữ chảo → xóc theo chảo (thân lắc nhẹ theo nhịp)
function _cnHold(c){
  const f=c.f, h=_cnHandlePos(c);
  const fl=c.fl||1;
  f.x=h.x-fl*f.size*0.55; f.y=h.y+f.size*0.35; f.vx=0; f.vy=0;   // đứng ngay sau cán, về phía mình
  f._cnHold=2; f._cnHoldTilt=fl*(c.tilt||0)*0.8;
}
function _cnStep(c, q, ax, ay, mass){
  const g=0.34;
  q.vx += (-ax)*mass; q.vy += g + (-ay)*mass;       // trọng lực + lực quán tính do chảo tăng tốc
  q.lx += q.vx; q.ly += q.vy;
  const lim=c.R*1.25; if(q.lx>lim){ q.lx=lim; q.vx*=-0.3; } else if(q.lx<-lim){ q.lx=-lim; q.vx*=-0.3; }
  const by=_cnBowl(c,q.lx);
  if(q.ly>by){                                        // chạm lòng chảo → đẩy ra mặt cong, nảy nhẹ, ma sát
    const nx=2*c.D*q.lx/(c.R*c.R), nl=Math.hypot(nx,1), ux=nx/nl, uy=1/nl;
    const vn=q.vx*ux+q.vy*uy;
    if(vn>0){ q.vx-=1.25*vn*ux; q.vy-=1.25*vn*uy; }
    q.vx*=0.94; q.vy*=0.94; q.ly=by;
  }
}
// chạy mỗi tick ở loop() (cả khi Cornelius đang bị choáng: chảo đã phi ra / đang nấu vẫn phải chạy tiếp)
function _cnWorldTick(){
  // chảo bay
  for(let i=cnPans.length-1;i>=0;i--){
    const p=cnPans[i];
    if(!p.owner || p.owner.dead){ cnPans.splice(i,1); continue; }
    p.x+=p.vx; p.y+=p.vy; p.rot+=0.42; p.life--;
    let hit=false;
    const pr=p.owner.size*0.42;
    for(const _arr of _hpSummonArrays()){                       // ⚠️ summon trước, fighter sau (quy tắc chung)
      for(const u of _arr){
        if(u.dead||u.hp<=0||u.team===p.team) continue;
        if(Math.hypot(u.x-p.x,u.y-p.y) < (u.size||20)+pr){ _summonTakeDamage(u, CN_PAN_DMG, p._smBy||p.owner, false, false, null, true); hit=true; break; }
      }
      if(hit) break;
    }
    if(!hit) for(const o of fighters){
      if(o.dead||o.team===p.team) continue;
      if(Math.hypot(o.x-p.x,o.y-p.y) < o.size+pr){
        if(!p._smBy && _smCanParry(o)){   // ⚔️ Cheems gạt bật chảo → bay ngược về Cornelius, đổi sang phe Cheems
          const _b=_smAimBack(o,p.owner,p.x,p.y,Math.hypot(p.vx,p.vy)*1.15); p.vx=_b.vx; p.vy=_b.vy; p._smBy=o; p.team=o.team; p.life=Math.max(p.life,90);
          _smParryFx(o,p.x,p.y); break;
        }
        o.takeDamage(CN_PAN_DMG, p._smBy||p.owner);
        if(!p._smBy && !cnCooks.some(c=>c.e===o)){
          o._cnHits=(o._cnHits||0)+1;
          if(o._cnHits>=CN_UNLOCK_HITS && !o._cnReady){ o._cnReady=true; playSample('cn_ready',1.0); }   // 🍳 đủ 8 chảo → sẵn sàng bị nấu + "let him cook"
        }
        hit=true; break;
      }
    }
    if(hit){ playSample('cn_pan_hit',1.0); _hitParticles(p.x,p.y,'#9e9e9e',6); cnPans.splice(i,1); continue; }   // 🍳 BOONG! tiếng chảo PUBG
    if(p.life<=0 || p.x<-60||p.x>W+60||p.y<-60||p.y>H+60) cnPans.splice(i,1);
  }
  // chảo khổng lồ đang nấu
  for(let i=cnCooks.length-1;i>=0;i--){
    const c=cnCooks[i], e=c.e;
    if(!e || e.dead || !c.f || c.f.dead){ if(e){ e._cnCookT=0; e._cnTilt=0; } cnCooks.splice(i,1); continue; }
    c.t++;
    // 🍳 động tác xóc: đẩy chảo tới rồi GIẬT ngược về + hất lên thật nhanh (đúng kiểu đảo cơm rang), 0.67s/lần
    const T=40, ph=(c.t%T)/T, ramp=Math.min(1,c.t/14);
    c.ppox=c.pox; c.ppoy=c.poy; c.pox=c.ox; c.poy=c.oy;
    c.ox = Math.sin(ph*Math.PI*2)*c.R*0.16*ramp;
    c.oy = -Math.exp(-Math.pow((ph-0.55)/0.07,2))*c.R*0.26*ramp;
    c.tilt = Math.sin(ph*Math.PI*2-0.6)*0.16*ramp;
    const ax=c.ox-2*c.pox+c.ppox, ay=c.oy-2*c.poy+c.ppoy;   // gia tốc chảo (sai phân bậc 2)
    for(const q of c.parts){ _cnStep(c,q,ax,ay,q.heavy); q.rot+=q.vx*0.08; }
    _cnHold(c);                                 // Cornelius cầm cán, xóc theo chảo
    _cnStep(c,c.meme,ax,ay,0.75);
    // con meme địch nằm đúng chỗ hạt của nó (chân ở mặt hạt), nghiêng theo vận tốc ngang
    e.x=c.x+(c.fl||1)*(c.ox+c.meme.lx); e.y=c.y+c.oy+c.meme.ly-e.size*0.55; e.vx=0; e.vy=0;
    e.stun=Math.max(e.stun||0,2); e._cnCookT=2;
    e._cnTilt=(c.fl||1)*Math.max(-0.55,Math.min(0.55, c.meme.vx*0.09 + c.tilt*0.8));
    if(c.t>=CN_COOK_T){
      e._cnCookT=0; e._cnTilt=0; e.y=c.y-e.size*0.35;
      e.takeDamage(CN_COOK_DMG, c.f);
      addShake(8,12);
      cnCooks.splice(i,1);
    }
  }
  for(const o of fighters){ if(o._cnCookT>0 && !cnCooks.some(c=>c.e===o)) o._cnCookT--; }
}
// cái chảo (vẽ tay, hoặc ảnh user up ở ô "Chảo")
function _cnDrawPanShape(x,y,R,rot,im){
  ctx.save(); ctx.translate(x,y); ctx.rotate(rot);
  if(im===CN_WOK_IMG){
    const sw=CN_WOK.bx1-CN_WOK.bx0, sh=CN_WOK.by1-CN_WOK.by0, w=R*2.6, h=w*sh/sw;
    ctx.drawImage(im, CN_WOK.bx0,CN_WOK.by0,sw,sh, -w/2,-h/2, w,h); ctx.restore(); return; }
  if(im){ const w=R*2.6, h=w*im.naturalHeight/im.naturalWidth; ctx.drawImage(im,-w*0.38,-h/2,w,h); ctx.restore(); return; }
  ctx.fillStyle='#3e2723'; ctx.fillRect(R*0.85,-R*0.13,R*1.25,R*0.26);           // cán gỗ
  ctx.fillStyle='#212121'; ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.fill(); // lòng chảo
  ctx.strokeStyle='#616161'; ctx.lineWidth=Math.max(1.5,R*0.12); ctx.stroke();      // vành
  ctx.fillStyle='rgba(255,255,255,0.08)'; ctx.beginPath(); ctx.arc(-R*0.25,-R*0.25,R*0.45,0,Math.PI*2); ctx.fill();
  ctx.restore();
}
// vẽ 1 hạt đồ ăn (toàn hình khối đơn giản, không gradient/shadow → rẻ)
function _cnDrawFood(q,x,y){
  ctx.save(); ctx.translate(x,y); ctx.rotate(q.rot); ctx.fillStyle=q.col;
  const z=q.sz;
  if(q.kind==='rice'){ ctx.beginPath(); ctx.ellipse(0,0,z*1.4,z*0.55,0,0,Math.PI*2); ctx.fill(); }
  else if(q.kind==='pea'||q.kind==='corn'){ ctx.beginPath(); ctx.arc(0,0,z,0,Math.PI*2); ctx.fill(); }
  else if(q.kind==='cube'){ ctx.fillRect(-z,-z,z*2,z*2); }
  else if(q.kind==='bacon'){ ctx.fillRect(-z*1.3,-z*0.55,z*2.6,z*1.1); ctx.fillStyle='#f3c7b6'; ctx.fillRect(-z*1.3,-z*0.1,z*2.6,z*0.25); }
  else if(q.kind==='egg'){ ctx.beginPath(); ctx.ellipse(0,0,z,z*0.7,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#ffb300'; ctx.beginPath(); ctx.arc(z*0.1,0,z*0.36,0,Math.PI*2); ctx.fill(); }
  ctx.restore();
}
// dưới chân meme: lửa dưới đáy + lòng chảo + đồ ăn
function _cnDrawUnder(){
  const now=Date.now();
  for(const c of cnCooks){
    const R=c.R, X=c.x+(c.fl||1)*c.ox, Y=c.y+c.oy, ap=Math.min(1,c.t/8), sc=0.6+0.4*ap;
    // 🔥 lửa bốc lên quanh đáy chảo
    ctx.save(); ctx.globalCompositeOperation='lighter';
    for(let j=0;j<16;j++){
      const t=((now/360)+j/16)%1, u=(j/16)*2-1;
      const fx=c.x+u*R*0.8, fy=c.y+c.D+R*0.34 - t*R*0.55;
      ctx.globalAlpha=(1-t)*0.75;
      ctx.fillStyle= t<0.3 ? '#fff59d' : t<0.65 ? '#ff9800' : '#e53935';
      ctx.beginPath(); ctx.arc(fx+Math.sin(now/140+j)*R*0.05, fy, R*0.15*(1-t*0.6)*sc, 0, Math.PI*2); ctx.fill();
    }
    ctx.restore();
    ctx.save(); ctx.translate(X,Y); ctx.scale(c.fl||1,1); ctx.rotate(c.tilt); ctx.scale(sc,sc);   // lật ngang nếu Cornelius đứng bên phải
    const _wk=_cnPanImg(c.f);
    if(_wk){                                       // nguyên cái chảo (ảnh), miệng chảo trùng gốc toạ độ
      const k=R/CN_WOK.rx;
      ctx.drawImage(_wk, -CN_WOK.cx*k, -CN_WOK.cy*k, CN_WOK.W*k, CN_WOK.H*k);
    } else {                                       // lòng chảo phía sau (vẽ tay, khi ảnh chưa nạp)
      ctx.fillStyle='#161616'; ctx.beginPath(); ctx.ellipse(0,0,R,R*0.3,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#262626'; ctx.beginPath(); ctx.ellipse(0,R*0.02,R*0.9,R*0.24,0,0,Math.PI*2); ctx.fill();
    }
    // đồ ăn (hạt nào đang bay khỏi chảo vẫn vẽ bình thường)
    for(const q of c.parts) _cnDrawFood(q, q.lx, q.ly);
    ctx.restore();
  }
}
// trên meme: thành chảo PHÍA TRƯỚC che bớt nửa dưới đồ ăn + con meme → nhìn như đang nằm TRONG chảo
function _cnDrawFront(){
  for(const c of cnCooks){
    const R=c.R, X=c.x+(c.fl||1)*c.ox, Y=c.y+c.oy, sc=0.6+0.4*Math.min(1,c.t/8);
    ctx.save(); ctx.translate(X,Y); ctx.scale(c.fl||1,1); ctx.rotate(c.tilt); ctx.scale(sc,sc);
    const _wk=_cnPanImg(c.f);
    if(_wk){
      const k=R/CN_WOK.rx, ry=CN_WOK.ry*k;
      ctx.save();
      ctx.beginPath(); ctx.moveTo(-R*1.6,0);
      ctx.ellipse(0,0,R,ry,0,Math.PI,0,true);          // mép trước của miệng chảo (nửa elip phía dưới)
      ctx.lineTo(R*1.6,0); ctx.lineTo(R*1.6,R*2); ctx.lineTo(-R*1.6,R*2); ctx.closePath(); ctx.clip();
      ctx.drawImage(_wk, -CN_WOK.cx*k, -CN_WOK.cy*k, CN_WOK.W*k, CN_WOK.H*k);
      ctx.restore(); ctx.restore(); continue;
    }
    // quai tròn bên trái + cán gỗ dài bên phải
    ctx.strokeStyle='#111'; ctx.lineWidth=R*0.07;
    ctx.beginPath(); ctx.ellipse(-R*1.08,R*0.12,R*0.16,R*0.11,0,0,Math.PI*2); ctx.stroke();
    ctx.fillStyle='#111'; ctx.save(); ctx.translate(R*0.95,R*0.05); ctx.rotate(-0.55);
    ctx.fillRect(0,-R*0.05,R*0.45,R*0.1); ctx.fillStyle='#6d4c41'; ctx.fillRect(R*0.42,-R*0.07,R*0.62,R*0.14); ctx.restore();
    // thành chảo phía trước: nửa dưới miệng chảo nối xuống đáy cong
    ctx.fillStyle='#1b1b1b';
    ctx.beginPath(); ctx.moveTo(-R,0);
    ctx.ellipse(0,0,R,R*0.3,0,Math.PI,0,true);                 // mép miệng phía trước
    ctx.quadraticCurveTo(R*0.9,R*0.95, 0,R*0.98);
    ctx.quadraticCurveTo(-R*0.9,R*0.95, -R,0);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle='#4a4a4a'; ctx.lineWidth=Math.max(1.5,R*0.035);
    ctx.beginPath(); ctx.ellipse(0,0,R,R*0.3,0,0,Math.PI); ctx.stroke();   // vành sáng
    ctx.fillStyle='rgba(255,255,255,0.07)'; ctx.beginPath(); ctx.ellipse(-R*0.45,R*0.5,R*0.28,R*0.12,-0.3,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }
}
// trên meme: chảo đang bay, dấu 🍳 trên đầu con đã mở khoá, chữ LET HIM COOK
function _cnDrawOver(){
  for(const p of cnPans){
    if(CN_PAN_IMG.complete && CN_PAN_IMG.naturalWidth){
      const d=p.owner.size*1.14;               // chảo ném (0.95 → +20%)
      ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.rot);
      ctx.drawImage(CN_PAN_IMG, CN_PAN_BOX.x,CN_PAN_BOX.y,CN_PAN_BOX.w,CN_PAN_BOX.h, -d/2,-d/2, d, d*CN_PAN_BOX.h/CN_PAN_BOX.w);
      ctx.restore();
    } else _cnDrawPanShape(p.x,p.y,p.owner.size*0.36,p.rot,_cnPanImg(p.owner));
  }
  // 🍳 thanh tích chảo trên đầu địch: trúng chảo nào là icon 🍳 đầy thêm 1/8 (lấp dần từ dưới lên); đủ 8 thì
  // icon đầy hẳn, phát sáng và rung nhẹ = sẵn sàng bị nấu
  const _sp=_emojiSprite('🍳',64), now=Date.now();
  if(_sp) for(const o of fighters){
    if(o.dead) continue;
    const n=o._cnReady ? CN_UNLOCK_HITS : Math.min(CN_UNLOCK_HITS, o._cnHits||0);
    if(n<=0 || cnCooks.some(c=>c.e===o)) continue;
    const d=o.size*0.7, full=n>=CN_UNLOCK_HITS;
    let x=o.x-d/2, y=o.y-o.size*1.75-d/2;
    if(full){ x+=Math.sin(now/38)*d*0.05; y+=Math.cos(now/47)*d*0.04; }        // rung nhẹ
    ctx.save();
    if(full){                                                                // quầng sáng vàng phập phồng
      const pr=0.75+0.25*Math.sin(now/160);
      ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=0.55*pr; ctx.fillStyle='#ffca28';
      ctx.beginPath(); ctx.arc(x+d/2, y+d/2, d*0.62, 0, Math.PI*2); ctx.fill();
      ctx.globalAlpha=0.3*pr; ctx.beginPath(); ctx.arc(x+d/2, y+d/2, d*0.85, 0, Math.PI*2); ctx.fill();
      ctx.globalCompositeOperation='source-over';
    }
    ctx.globalAlpha=0.25; ctx.drawImage(_sp, x, y, d, d);                    // phần còn trống: icon mờ
    ctx.globalAlpha=1;
    const fh=d*n/CN_UNLOCK_HITS;                                             // phần đã đầy: lấp từ dưới lên
    ctx.beginPath(); ctx.rect(x, y+d-fh, d, fh); ctx.clip();
    ctx.drawImage(_sp, x, y, d, d);
    ctx.restore();
  }
  for(let i=cnTexts.length-1;i>=0;i--){
    const t=cnTexts[i]; t.t++;
    if(t.t>=t.life){ cnTexts.splice(i,1); continue; }
    const p=t.t/t.life;
    let scale, alpha=1;
    if(p<0.15) scale=(p/0.15)*1.3;
    else if(p<0.28) scale=1.3-((p-0.15)/0.13)*0.3;
    else if(p<0.75) scale=1.0;
    else { const q=(p-0.75)/0.25; scale=1+q*0.4; alpha=1-q; }
    ctx.save();
    ctx.globalAlpha=alpha; ctx.translate(t.x, t.y); ctx.rotate(Math.sin(t.seed)*0.12); ctx.scale(scale,scale);
    const fs=Math.round(26*(W/480));
    ctx.font=`900 ${fs}px Impact, 'Arial Black', sans-serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.lineJoin='round'; ctx.lineWidth=fs*0.22; ctx.strokeStyle='#1a1a1a'; ctx.strokeText('LET HIM COOK', 0, 0);
    ctx.fillStyle='#ffca28'; ctx.fillText('LET HIM COOK', 0, 0);
    ctx.restore();
  }
}

// ===================== ☠️🟢 ADOLF CATLER — VAN KHÍ ĐỘC =====================
// Tụt XUỐNG DƯỚI 70% máu: Catler đứng nghiêm GIƠ TAY, hát quốc ca, đứng im tới hết bài — trong 2.5s đầu bài hát
// thì 2 cái van gắn ở GIỮA tường trái + phải TỪ TỪ nhô ra (camera lùi ra cho thấy cả 2 bên tường) (thân van đen, vô-lăng đỏ, y kiểu van
// công nghiệp) và xả khí độc: cả sàn phủ sương xanh lá mỏng, thỉnh thoảng cuộn lên từng đám như mây, thỉnh
// thoảng có đầu lâu bay lên. Khí làm MỌI meme + summon trong sàn (trừ chính Catler) ăn 10 dame mỗi 0.5s, và
// mỗi giây địch có 15% đứng hình + ho 1s (rung người y Cough Cat, không có sao choáng trên đầu).
const FK_GAS_DMG=10, FK_GAS_CD=30, FK_COUGH_P=0.15, FK_COUGH_T=60;
const FK_CAT_IMG=new Image(); FK_CAT_IMG.src='assets/img/feuerkatze/FK_CAT_IMG.webp';   // 🐈 2 con mèo đứng ngoài sân mở van (ảnh gốc quay sang PHẢI)
let _fkGasSfx=null, _fkAnthemSfx=null, _fkSalute=0, _fkExtend=0, _fkCatA=0;
const FK_EXTEND_T=150;   // 2.5s = 150 tick: thời gian 2 cái vòi nhô hẳn ra khỏi tường
let fkPuffs=[], fkWisps=[], fkSkulls=[], _fkDmgT=0, _fkSecT=0, _fkCoughSfxCD=0, _fkGasA=0;
// 🔫 CATLER TỰ SÁT: đòn lẽ ra giết nó KHÔNG giết được — nó khựng lại, về tư thế giơ tay, khẩu Luger P08 (trước là ảnh súng của
// Sus Dog) đưa lên chĩa thẳng vào thái dương, "ĐOÀNG", rồi vỡ vụn thành từng mảnh như chết thường. Cả màn gói gọn
// 1.5s, camera zoom sát vào nó; vỡ xong camera tự quay về con thắng (luồng kết trận bình thường).
// Ảnh súng (Luger): nòng chĩa sang TRÁI, đầu nòng ≈ (2,40), khung ảnh 538×339.
// ⏱️ game chạy nhanh hơn giờ thật 1.2× (GAME_SPEED×TIME_SCALE) → 1.5s thật = 108 tick
const FK_SUI_T=108, FK_SUI_RAISE=30, FK_SUI_SHOT=100, FK_SUI_DIE=108;
// 🔫 súng = khẩu LUGER P08 (ảnh user gửi, đã tách nền + lật cho nòng chĩa sang TRÁI): khung 538×339, đầu nòng ≈ (2,40)
const FK_GUN_IMG=new Image(); FK_GUN_IMG.src='assets/img/feuerkatze/FK_LUGER_IMG.webp';
const FK_GUN_MUZZLE={x:2,y:40}, FK_GUN_W=538, FK_GUN_H=339;
let _fkSuicideF=null;
// Catler đã ăn đòn chí mạng, đang tự sát = trận coi như đã phân thắng bại → phe kia thôi ra đòn/tung chiêu
function _fkDoomedFoe(u){ return !!(_fkSuicideF && !_fkSuicideF.dead && u!==_fkSuicideF && u.team!==_fkSuicideF.team); }
function _fkStartSuicide(f, killer){
  f._fkSuicideT=0; f._fkKiller=killer||null; f.hp=1; f.vx=0; f.vy=0;
  const e=fighters.find(o=>o.team!==f.team && !o.dead);
  f._fkSuiDir = e ? (e.x>=f.x?1:-1) : 1;                  // quay mặt về phía địch như lúc đang đánh
  _fkSuicideF=f;
}
function _fkSuicideTick(){
  const f=_fkSuicideF; if(!f) return;
  if(f.dead){ _fkSuicideF=null; return; }
  f._fkSuicideT++;
  f.vx=0; f.vy=0; f.stun=Math.max(f.stun||0,2); f._fkSaluteNow=2;     // đứng im, tư thế giơ tay, không sao choáng
  if(f._fkSuicideT===FK_SUI_SHOT){
    playSample('gunshot',1.0);
    addShake(10,12);
    f._fkShotT=8;                                                      // loé lửa đầu nòng + giật đầu
  }
  if(f._fkShotT>0) f._fkShotT--;
  if(f._fkSuicideT>=FK_SUI_DIE){
    f._fkSuicideDone=true; _fkSuicideF=null;
    _forceKill(f, f._fkKiller);                                        // vỡ vụn y như chết thường (không nảy số dame)
  }
}
// 🔫 ĐẶT SÚNG THEO 2 ĐIỂM NEO trên ảnh giơ tay của Catler (đo theo ảnh chụp màn hình user gửi, tính theo size con meme,
//    toạ độ ghi theo lúc ảnh ĐANG LẬT ngang: tay giơ ở phía PHẢI-trên, đầu ở giữa lệch trái; ảnh gốc thì ngược lại):
//      • THÁI DƯƠNG  (0.13, −0.50)·s  ← nòng súng chĩa thẳng vào đây
//      • TAY ĐANG GIƠ (0.50, −0.78)·s  ← báng súng nằm đè lên đây (tay cầm súng)
//    Trên ảnh súng Luger: đầu nòng (2,40), giữa báng (400,180). Báng đặt đúng tay, góc súng xoay cho nòng chĩa đúng thái
//    dương, cỡ súng cố định FK_GUN_SIZE. Ảnh đang lật ngang thì lật luôn cả bộ neo.
const FK_GUN_GRIP={x:400,y:180}, FK_GUN_SIZE=0.75;   // FK_GUN_SIZE: bề ngang súng = 0.75 × size con meme (Luger nòng dài hơn Glock cũ)
const FK_ANCHOR_TEMPLE={x:0.03,y:-0.48}, FK_ANCHOR_HAND={x:0.45,y:-0.85};   // đo lại trên 2 ảnh chụp user gửi
function _fkDrawSuicide(){
  const f=_fkSuicideF; if(!f || f.dead) return;
  const im=FK_GUN_IMG; if(!(im && im.complete && im.naturalWidth)) return;
  const s=f.size*1.1;                                              // tư thế giơ tay đang to thêm 10%
  const flip = f._lastFacingLeft ? 1 : -1;                         // bộ neo đo lúc ảnh ĐANG LẬT (tay giơ bên phải); ảnh không lật → tay giơ bên trái
  const tx=FK_ANCHOR_TEMPLE.x*s, ty=FK_ANCHOR_TEMPLE.y*s, hx=FK_ANCHOR_HAND.x*s, hy=FK_ANCHOR_HAND.y*s;
  const gdx=FK_GUN_GRIP.x-FK_GUN_MUZZLE.x, gdy=FK_GUN_GRIP.y-FK_GUN_MUZZLE.y;
  const k=(s*FK_GUN_SIZE)/FK_GUN_W;                                // súng nhỏ cố định (~0.6 size con meme)
  const rot=Math.atan2(ty-hy,tx-hx)-Math.atan2(-gdy,-gdx);        // báng ở tay, NÒNG xoay chĩa thẳng vào thái dương
  const t=f._fkSuicideT||0, raise=Math.min(1,t/FK_SUI_RAISE), e=1-Math.pow(1-raise,3);
  const tremble=(t>FK_SUI_RAISE && t<FK_SUI_SHOT) ? Math.sin(t*1.7)*s*0.012 : 0;
  const kick=(f._fkShotT||0)>0 ? s*0.06 : 0;
  ctx.save();
  ctx.translate(f.x, f.y); ctx.scale(flip,1);
  ctx.globalAlpha=Math.min(1,raise*2);
  // báng súng đè lên tay đang giơ (lúc đầu súng trồi lên từ dưới tay rồi vào đúng chỗ)
  ctx.translate(hx+tremble, hy+(1-e)*s*0.25+tremble);
  ctx.rotate(rot);
  ctx.scale(k,k);
  ctx.translate(kick/k,0);                                                         // giật súng lúc bắn
  ctx.drawImage(im, -FK_GUN_GRIP.x, -FK_GUN_GRIP.y, FK_GUN_W, FK_GUN_H);        // giữa báng đúng gốc = tay
  if((f._fkShotT||0)>0){                                                          // 💥 loé lửa ngay đầu nòng
    ctx.translate(FK_GUN_MUZZLE.x-FK_GUN_GRIP.x, FK_GUN_MUZZLE.y-FK_GUN_GRIP.y);
    const a=f._fkShotT/8, r=(s*0.3/k)*(1.2-a*0.4);   // cỡ loé tính theo cỡ con meme (đang ở hệ toạ độ ảnh súng đã thu nhỏ k)
    ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=a;
    ctx.fillStyle='#fff59d'; ctx.beginPath();
    for(let i=0;i<10;i++){ const an=i/10*Math.PI*2, rr=i%2?r*0.45:r; ctx.lineTo(Math.cos(an)*rr-r*0.2, Math.sin(an)*rr); }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle='#ff9800'; ctx.beginPath(); ctx.arc(-r*0.2,0,r*0.35,0,Math.PI*2); ctx.fill();
  }
  ctx.restore();
}
function _fkOwner(){
  for(const f of fighters){ if(f.type==='feuerkatze' && !f.dead && f.hp<f.maxHp*0.70) return f; }
  return null;
}
// vị trí miệng van (chỗ khí phun ra) của 2 cạnh trái/phải
function _fkGasOn(){ return _fkGasA>0.35; }   // sàn đang ngập khí độc → lửa bén khí, cháy dữ dội gấp đôi
function _fkPorts(){ const L=W*0.085*Math.max(0.001,_fkExtend); return [ {x:L, y:H/2, sd:1}, {x:W-L, y:H/2, sd:-1} ]; }
function _fkTick(){
  _fkSuicideTick();   // 🔫 màn tự sát của Catler (nếu đang diễn)
  const f=_fkOwner();
  // 🫡 LẦN ĐẦU tụt dưới 70%: đứng im giơ tay + phát quốc ca, đứng tới khi hết bài mới đánh tiếp
  if(f && !f._fkSaluted){
    f._fkSaluted=true; _fkExtend=0;
    const src=AUDIO_SAMPLES['fk_anthem'], a=src?.cloneNode();
    // độ dài bài lấy từ chính thẻ audio gốc (bản cloneNode chưa nạp metadata nên duration còn NaN)
    const _dur=[src&&src.duration, a&&a.duration].find(d=>isFinite(d)&&d>0) || 5;
    const _tps=60*GAME_SPEED*TIME_SCALE;                    // game chạy ~72 tick/giây thật
    _fkSalute=Math.max(Math.round(2.5*_tps), Math.round(_dur*_tps));   // 🫡 giơ tay ÍT NHẤT 2.5s thật (hoặc tới hết bài nếu bài dài hơn)
    if(a){ a.volume=1; _mixRoute(a); a.play().catch(()=>{}); _fkAnthemSfx=a; }
  }
  // 🫡 đứng im ở tư thế giơ tay BÁM ĐÚNG THEO BÀI NHẠC: nhạc còn chạy thì còn đứng, hết bài mới về ảnh thường.
  // (đồng hồ tick chỉ là phương án dự phòng khi trình duyệt chặn không cho phát tiếng)
  if(_fkAnthemSfx && !_fkAnthemSfx.ended && !_fkAnthemSfx.paused) _fkSalute=Math.max(_fkSalute,2);
  if(_fkSalute>0){
    _fkSalute--;
    if(_fkAnthemSfx && _fkAnthemSfx.ended) _fkSalute=0;   // hết bài là thôi đứng nghiêm
    if(_fkSalute<=0 && _fkAnthemSfx){ _fkAnthemSfx=null; }
    if(f){ f.stun=2; f.vx=0; f.vy=0; f._fkSaluteNow=2; }   // khoá chân kiểu German Cat (không có sao choáng)
  }
  // 2 cái vòi nhô dần ra khỏi tường trong 2.5s đầu, thụt lại khi hết khí
  _fkExtend = Math.max(0, Math.min(1, _fkExtend + (f ? 1/FK_EXTEND_T : -2/FK_EXTEND_T)));
  _fkCatA += ((_fkSalute>0?1:0)-_fkCatA)*0.12;   // 🐈 2 con mèo chỉ đứng đó trong lúc bài quốc ca đang phát
  _fkGasA += ((f && _fkExtend>0.95 ?1:0)-_fkGasA)*0.06;   // vòi nhô hẳn ra rồi mới bắt đầu xì khí
  // 💨 tiếng xì gas loop suốt lúc van đang xả (đã giảm 40% âm lượng theo yêu cầu)
  if(f && !_fkGasSfx){
    _fkGasSfx=AUDIO_SAMPLES['gas_leak']?.cloneNode()||null;
    if(_fkGasSfx){ _fkGasSfx.loop=true; _fkGasSfx.volume=0.6; _mixRoute(_fkGasSfx); _fkGasSfx.play().catch(()=>{}); }
  } else if(!f && _fkGasSfx){ _stopLoopAudio(_fkGasSfx); _fkGasSfx=null; }          // khí lên/tan dần chứ không bật tắt cái rụp
  if(_fkCoughSfxCD>0) _fkCoughSfxCD--;
  // cơn ho: đếm lùi cho mọi đơn vị đang ho
  for(const o of fighters){ if(o._fkCough>0) o._fkCough--; if(o._fkSaluteNow>0) o._fkSaluteNow--; }
  for(const _arr of _hpSummonArrays()) for(const u of _arr) if(u._fkCough>0) u._fkCough--;
  if(!f){ if(_fkGasA<0.02){ fkPuffs.length=0; fkWisps.length=0; } _fkDmgT=0; _fkSecT=0; }
  if(f){
    // 💨 đám khí cuộn ra từ 2 miệng van rồi loang khắp sàn
    if(fkPuffs.length<14 && Math.random()<0.3){
      const p=_fkPorts()[Math.random()<0.5?0:1];
      fkPuffs.push({ x:p.x+p.sd*W*0.02, y:p.y+(Math.random()-0.5)*H*0.08,
        vx:p.sd*(0.5+Math.random()*0.7), vy:(Math.random()-0.5)*0.5,
        r:W*(0.05+Math.random()*0.06), gr:1+Math.random()*1.4, life:0, max:170+Math.random()*120,
        sd:Math.random()*99 });
    }
    // 🌫️ dải khói xanh LƯỠN LỜ bốc lên khắp sàn (kiểu sương độc trong ảnh mẫu) — luôn có vài dải đang uốn
    if(fkWisps.length<6 && Math.random()<0.1){
      fkWisps.push({ x:W*(0.06+Math.random()*0.88), y:H*(0.55+Math.random()*0.5),
        h:H*(0.4+Math.random()*0.45), w:W*(0.016+Math.random()*0.022),
        sd:Math.random()*99, vy:-(0.12+Math.random()*0.22), life:0, max:230+Math.random()*180 });
    }
    // ☠️ thỉnh thoảng một cái đầu lâu xanh nhỏ phát sáng bay lên trong khí độc (thưa thôi)
    if(fkSkulls.length<3 && Math.random()<0.012){
      fkSkulls.push({ x:W*(0.12+Math.random()*0.76), y:H*(0.55+Math.random()*0.42),
        r:W*(0.045+Math.random()*0.03), sd:Math.random()*99, life:0, max:110+Math.random()*50 });
    }
    // ☠️ 10 dame mỗi 0.5s lên TẤT CẢ (trừ chính Catler)
    if(++_fkDmgT>=FK_GAS_CD){
      _fkDmgT=0;
      for(const o of fighters){ if(o.dead||o===f) continue; o.takeDamage(FK_GAS_DMG, f, false, true, '☠️', null, true); }
      for(const _arr of _hpSummonArrays()) for(const u of _arr){ if(u.dead||u.hp<=0) continue; _summonTakeDamage(u, FK_GAS_DMG, f, false, true, '☠️', true); }
    }
    // 😷 mỗi 1s: địch 15% đứng hình + ho 1s
    if(++_fkSecT>=60){
      _fkSecT=0;
      const _vic=[];
      for(const o of fighters){ if(!o.dead && o.team!==f.team) _vic.push(o); }
      for(const _arr of _hpSummonArrays()) for(const u of _arr){ if(!u.dead && u.hp>0 && u.team!==f.team && u.stun!==undefined) _vic.push(u); }
      for(const o of _vic){
        if(Math.random()>=FK_COUGH_P) continue;
        o.stun=Math.max(o.stun||0, FK_COUGH_T); o._fkCough=FK_COUGH_T;
        spawnPoisonParticles(o.x, o.y-(o.size||20)*0.4, 5);
        if(_fkCoughSfxCD<=0){
          _fkCoughSfxCD=22;
          const a=AUDIO_SAMPLES['cough_meme']?.cloneNode();
          if(a){ a.volume=0.9; _mixRoute(a); a.currentTime=0; a.play().catch(()=>{});
            setTimeout(()=>{ try{ a.pause(); }catch(_e){} }, 1000); }   // cắt còn đúng 1s tiếng ho
        }
      }
    }
  }
  for(let i=fkSkulls.length-1;i>=0;i--){
    const k2=fkSkulls[i]; k2.life++; k2.y-=0.55; k2.x+=Math.sin((k2.life+k2.sd)/30)*0.35;
    if(k2.life>=k2.max) fkSkulls.splice(i,1);
  }
  for(let i=fkWisps.length-1;i>=0;i--){
    const q=fkWisps[i]; q.life++; q.y+=q.vy; q.x+=Math.sin((q.life+q.sd)/55)*0.28;
    if(q.life>=q.max) fkWisps.splice(i,1);
  }
  // đám khí trôi + nở ra rồi tan
  for(let i=fkPuffs.length-1;i>=0;i--){
    const p=fkPuffs[i];
    p.life++; p.x+=p.vx; p.y+=p.vy; p.r=Math.min(W*0.3, p.r+p.gr);
    p.vx*=0.985; p.vy=p.vy*0.985+Math.sin((p.life+p.sd)/38)*0.035;
    if(p.life>=p.max) fkPuffs.splice(i,1);
  }
}
// 🚀 ĐỐM KHÓI bake sẵn 1 lần: trước đây mỗi đốm mỗi frame đều gọi createRadialGradient (đo được ~290 lần/frame,
// tụt từ 41 xuống 12 FPS). Giờ chỉ vẽ lại đúng 1 ảnh này với globalAlpha khác nhau.
let _fkBlobCv=null, _fkFogCv=null, _fkFogFrame=0;
function _fkBlobImg(){
  if(_fkBlobCv) return _fkBlobCv;
  const S=128, cv=document.createElement('canvas'); cv.width=cv.height=S;
  const g=cv.getContext('2d');
  const rg=g.createRadialGradient(S/2,S/2,0,S/2,S/2,S/2);
  rg.addColorStop(0,'rgba(150,255,110,1)'); rg.addColorStop(0.5,'rgba(86,200,60,0.5)'); rg.addColorStop(1,'rgba(60,150,40,0)');
  g.fillStyle=rg; g.fillRect(0,0,S,S);
  _fkBlobCv=cv; return cv;
}
// 💀 đầu lâu XANH LÁ phát sáng: fillText không đổi được màu emoji, nên vẽ 💀 ra canvas phụ rồi nhuộm xanh
// bằng source-in, bake 1 lần rồi dùng lại.
let _fkSkullCv=null;
function _fkSkullImg(){
  if(_fkSkullCv) return _fkSkullCv;
  const S=128, cv=document.createElement('canvas'); cv.width=cv.height=S;
  const g=cv.getContext('2d');
  g.font=`${Math.round(S*0.86)}px serif`; g.textAlign='center'; g.textBaseline='middle';
  g.fillText('💀', S/2, S*0.54);
  g.globalCompositeOperation='source-in';
  const lg=g.createLinearGradient(0,0,0,S); lg.addColorStop(0,'#eaffc0'); lg.addColorStop(0.45,'#9cff3d'); lg.addColorStop(1,'#4caf28');
  g.fillStyle=lg; g.fillRect(0,0,S,S);
  // quầng sáng xanh bake luôn vào ảnh: vẽ lại chính nó qua shadow 1 lần ở đây, khỏi phải bật shadowBlur mỗi frame
  const cv2=document.createElement('canvas'); cv2.width=cv2.height=S;
  const g2=cv2.getContext('2d');
  g2.shadowColor='#76ff03'; g2.shadowBlur=S*0.16; g2.drawImage(cv,0,0); g2.drawImage(cv,0,0);
  _fkSkullCv=cv2; return cv2;
}
// 🌫️ sương xanh phủ sàn — vẽ SAU meme nên nó trùm hẳn lên người (đứng trong khí chứ không phải đứng trên khí)
function _fkDrawFog(){
  if(_fkGasA<0.02 && !fkPuffs.length) return;
  ctx.save();
  ctx.beginPath(); ctx.rect(0,0,W,H); ctx.clip();
  // dải khói uốn lượn bốc lên — thân dải vẽ bằng nhiều đốt tròn lệch nhau theo sóng sin, nên nó ngoằn ngoèo như khói thật
  // 🚀 TOÀN BỘ lớp khí vẽ vào canvas phụ CHỈ 1/4 độ phân giải rồi phóng to: khí là mấy mảng mờ loang rất to,
  // vẽ thẳng lên canvas thật thì diện tích tô gấp 16 lần (đo được tụt từ 41 xuống 12 FPS). Mắt không phân biệt
  // được vì nó vốn đã nhoè.
  const _fq=0.18, _fw=Math.max(8,Math.round(W*_fq)), _fh=Math.max(8,Math.round(H*_fq));
  if(!_fkFogCv){ _fkFogCv=document.createElement('canvas'); }
  if(_fkFogCv.width!==_fw || _fkFogCv.height!==_fh){ _fkFogCv.width=_fw; _fkFogCv.height=_fh; _fkFogCv._blank=true; }
  const fx=_fkFogCv.getContext('2d');
  // 🚀 lớp khí chỉ VẼ LẠI mỗi 2 frame (khí trôi rất chậm, mắt không thấy khác), frame còn lại dùng lại ảnh cũ
  const _redraw = (_fkFogFrame++ % 2)===0 || _fkFogCv._blank;
  if(_redraw){
  _fkFogCv._blank=false;
  fx.setTransform(1,0,0,1,0,0); fx.clearRect(0,0,_fw,_fh); fx.setTransform(_fq,0,0,_fq,0,0);
  fx.fillStyle=`rgba(118,255,3,${0.14*_fkGasA})`; fx.fillRect(0,0,W,H);   // lớp xanh nhạt phủ toàn sàn
  const _bl=_fkBlobImg();
  fx.globalCompositeOperation='lighter';
  for(const q of fkWisps){
    const k=q.life/q.max, fade=Math.sin(Math.min(1,k*4)*Math.PI*0.5)*(1-k);
    const N=9;
    for(let j=0;j<N;j++){
      const t=j/N, yy=q.y-t*q.h;
      const xx=q.x+Math.sin((q.life*0.9+q.sd*7)/26 + t*3.4)*q.w*2.6*(0.35+t);
      const rr=q.w*(1.3-t*0.45)*(0.75+0.35*Math.sin(t*6+q.sd));
      const a=fade*0.34*(1-t*0.7);
      if(a<=0.006) continue;
      fx.globalAlpha=a; fx.drawImage(_bl, xx-rr, yy-rr, rr*2, rr*2);
    }
  }
  fx.globalCompositeOperation='source-over';
  for(const p of fkPuffs){
    const k=p.life/p.max, a=Math.sin(Math.min(1,k*3.2)*Math.PI*0.5)*(1-k)*0.4;
    if(a<=0.006) continue;
    fx.globalAlpha=a; fx.drawImage(_bl, p.x-p.r, p.y-p.r, p.r*2, p.r*2);
  }
  }
  { const _q=ctx.imageSmoothingQuality; ctx.imageSmoothingQuality='low';
    ctx.drawImage(_fkFogCv, 0,0,_fw,_fh, 0,0,W,H);   // phóng lớp khí lên đúng cỡ sàn
    ctx.imageSmoothingQuality=_q; }
  // 💀 đầu lâu xanh bay lên
  for(const k2 of fkSkulls){
    const t=k2.life/k2.max, a=Math.sin(Math.min(1,t*5)*Math.PI*0.5)*(1-t)*0.85*Math.max(0.2,_fkGasA);
    if(a<=0.01) continue;
    const im=_fkSkullImg(), d=k2.r*2*(0.9+0.12*Math.sin((k2.life+k2.sd)/16));
    ctx.globalAlpha=a; ctx.drawImage(im, k2.x-d/2, k2.y-d/2, d, d); ctx.globalAlpha=1;
  }
  ctx.restore();
}
// 🔧 2 cái van gắn vào giữa tường trái/phải: ống đen nối từ tường vào, mặt bích có bu lông, vô-lăng ĐỎ trên nóc
function _fkDrawValves(){
  if(_fkExtend<0.02 && _fkCatA<0.01) return;
  const u=W/480, al=Math.min(1,_fkExtend*1.4);
  for(const p of _fkPorts()){
    const wallX = p.sd>0 ? 0 : W;                       // gốc ống nằm ở mép tường
    const pipeR=8*u, x0=wallX, x1=p.x;
    ctx.save(); ctx.globalAlpha=al;
    // ống đen chạy từ tường ra
    const gp=ctx.createLinearGradient(0,p.y-pipeR,0,p.y+pipeR);
    gp.addColorStop(0,'#4a4a4a'); gp.addColorStop(0.35,'#1c1c1c'); gp.addColorStop(1,'#050505');
    ctx.fillStyle=gp; ctx.fillRect(Math.min(x0,x1), p.y-pipeR, Math.abs(x1-x0), pipeR*2);
    // bầu van phình ở giữa ống
    ctx.beginPath(); ctx.ellipse(p.x-p.sd*pipeR*0.2, p.y, pipeR*1.5, pipeR*1.45, 0, 0, Math.PI*2); ctx.fillStyle='#161616'; ctx.fill();
    // 2 mặt bích + bu lông
    for(const fx of [x0+p.sd*pipeR*1.6, p.x-p.sd*pipeR*2.1]){
      ctx.fillStyle='#232323'; ctx.fillRect(fx-2.2*u, p.y-pipeR*1.7, 4.4*u, pipeR*3.4);
      ctx.fillStyle='#8d8d8d';
      for(let b=-1;b<=1;b++) ctx.fillRect(fx-1.4*u, p.y+b*pipeR*1.05-1.3*u, 2.8*u, 2.6*u);
    }
    // cổ van dựng lên + vô-lăng đỏ
    const stemX=p.x-p.sd*pipeR*0.2, topY=p.y-pipeR*3.4;
    ctx.fillStyle='#101010'; ctx.fillRect(stemX-pipeR*0.42, topY, pipeR*0.84, pipeR*3.2);
    ctx.fillStyle='#262626'; ctx.fillRect(stemX-pipeR*0.95, topY+pipeR*0.9, pipeR*1.9, pipeR*0.5);
    ctx.save(); ctx.translate(stemX, topY);
    ctx.scale(1, 0.34);                                  // vô-lăng nhìn hơi nghiêng
    ctx.lineWidth=pipeR*0.55; ctx.strokeStyle='#c62828';
    ctx.beginPath(); ctx.arc(0,0,pipeR*1.75,0,Math.PI*2); ctx.stroke();
    ctx.strokeStyle='#e53935'; ctx.lineWidth=pipeR*0.34;
    for(let s2=0;s2<4;s2++){ const a2=s2*Math.PI/4; ctx.beginPath(); ctx.moveTo(-Math.cos(a2)*pipeR*1.75,-Math.sin(a2)*pipeR*1.75); ctx.lineTo(Math.cos(a2)*pipeR*1.75,Math.sin(a2)*pipeR*1.75); ctx.stroke(); }
    ctx.fillStyle='#b71c1c'; ctx.beginPath(); ctx.arc(0,0,pipeR*0.6,0,Math.PI*2); ctx.fill();
    ctx.restore();
    // 🐈 con mèo đứng NGOÀI sân, sát ngay cạnh van — chính nó là đứa vặn van mở khí
    if(_fkCatA>0.01 && FK_CAT_IMG.complete && FK_CAT_IMG.naturalWidth){
      const ch=H*0.34, cw=ch*FK_CAT_IMG.naturalWidth/FK_CAT_IMG.naturalHeight;
      const cxp = p.sd>0 ? -cw*0.55 : W+cw*0.55;      // đứng ngoài mép tường, sát ngay cái van
      const _boss=fighters.find(x=>x.type==='feuerkatze' && !x.dead);
      const _faceRight = _boss ? _boss.x>cxp : p.sd>0;  // luôn quay MẶT về phía Catler
      ctx.save(); ctx.globalAlpha=_fkCatA;
      ctx.translate(cxp, p.y+ch*0.16);
      if(!_faceRight) ctx.scale(-1,1);                // ảnh gốc quay sang PHẢI → muốn nhìn sang trái thì lật
      ctx.drawImage(FK_CAT_IMG, -cw/2, -ch, cw, ch);
      ctx.restore();
    }
    // tia khí phun ra khỏi miệng van (chỉ khi van đã mở xì khí)
    ctx.globalCompositeOperation='lighter';
    ctx.globalAlpha=al*Math.min(1,_fkGasA*1.4);
    for(let j=0;j<4;j++){
      const t=((Date.now()/430)+j*0.25)%1, jx=p.x+p.sd*t*W*0.1, jr=pipeR*(0.8+t*2.6);
      const g2=ctx.createRadialGradient(jx,p.y,0,jx,p.y,jr);
      g2.addColorStop(0,`rgba(160,255,110,${0.3*(1-t)*al})`); g2.addColorStop(1,'rgba(90,200,60,0)');
      ctx.fillStyle=g2; ctx.beginPath(); ctx.arc(jx,p.y,jr,0,Math.PI*2); ctx.fill();
    }
    ctx.restore();
  }
}
