  const jawClip=new Path2D(); DL_SHK_MOUTH.forEach(([x,y],i)=>i?jawClip.lineTo(x,y):jawClip.moveTo(x,y)); jawClip.lineTo(-1,23.4); jawClip.lineTo(23,23.4); jawClip.lineTo(22,19.6); jawClip.closePath();
