const SC_LEAN=0.6, SC_VIB=0.012, SC_EXH=[0.037,0.778], SC_REAR=[0.15,0.86];   // SC_REAR: chỗ bánh sau chạm đất   // SC_EXH: miệng ống xả trên ảnh (tỉ lệ khung ảnh đã cắt sát)
