function _drvSfxTick(){ for(let i=_drvFadeSfx.length-1;i>=0;i--){ const c=_drvFadeSfx[i]; try{ c.volume=Math.max(0,c.volume-0.03); if(c.volume<=0.001){ c.pause(); _longSfx.delete(c); _drvFadeSfx.splice(i,1); } }catch(e){ _drvFadeSfx.splice(i,1); } } }
// 🎲 tỉ lệ gốc: xe con 70 · bus 25 · tàu 5. Mỗi lần ra XE CON → lượt sau tàu +5% (lấy bớt phần xe con, bus giữ nguyên);
//    ra TÀU thì tỉ lệ tàu về lại 5%. Cộng dồn riêng cho từng Driver Cat (f._drvTrainUp).
const DRV_TRAIN_STEP=0.05;
function _drvPickKind(f){
  const up=(f&&f._drvTrainUp)||0, pT=Math.min(1-DRV_KIND.bus.p, DRV_KIND.train.p+up), pB=DRV_KIND.bus.p, pC=Math.max(0,1-pT-pB);
  const r=Math.random(), k = r<pC?'car' : r<pC+pB?'bus' : 'train';
  if(f){ if(k==='car') f._drvTrainUp=up+DRV_TRAIN_STEP; else if(k==='train') f._drvTrainUp=0; }
  return k;
}
function _drvRR(g,x,y,w,h,r){ g.beginPath(); g.moveTo(x+r,y); g.arcTo(x+w,y,x+w,y+h,r); g.arcTo(x+w,y+h,x,y+h,r); g.arcTo(x,y+h,x,y,r); g.arcTo(x,y,x+w,y,r); g.closePath(); }
