  g.strokeStyle='#d9d9d9'; g.lineWidth=7; g.beginPath(); g.moveTo(138,186); g.lineTo(262,186); g.stroke();      // thanh nối bánh
  g.strokeStyle='#b0b0b0'; g.lineWidth=6; g.beginPath(); g.moveTo(96,156); g.lineTo(200,186); g.stroke();       // thanh truyền từ xi lanh
  g.fillStyle='#e0e0e0'; for(const wx of [138,200,262]){ g.beginPath(); g.arc(wx,186,5,0,Math.PI*2); g.fill(); }
  // ===== TOA THAN (330..460)
