          const gl=ctx.createLinearGradient(fx-dx*L,fy-dy*L,fx+dx*L,fy+dy*L); gl.addColorStop(0,'rgba(200,140,255,0)'); gl.addColorStop(0.5,`rgba(255,255,255,${0.9*pu})`); gl.addColorStop(1,'rgba(200,140,255,0)');
