  // 🗡️ kiếm (vẽ TRƯỚC thân để chuôi khuất sau nắm tay)
  const px=(AR_MINI_PAW[0]-0.5)*bw, py=(AR_MINI_PAW[1]-0.5)*bh;
  const sh=bh/AR_MINI_VIS*0.46*AR_MINI_SWORD_VIS, swd=sh*Sw.naturalWidth/Sw.naturalHeight;
