function _arIsChick(u){ return (u._arChickT||0)>0 && (u.stun||0)>0; }
function _arLocked(u){ return !!u && !u.dead && ((u._arStoneT||0)>0 || (u._arChickT||0)>0 || _pdSprawled(u)); }   // 🍌 ngã sõng soài (Poor Dog) cũng khoá hẳn mọi chiêu
