    ctx.textBaseline='middle'; ctx.font='bold 8px "Press Start 2P",monospace'; ctx.textAlign='left'; ctx.fillStyle='#f3d98a'; ctx.fillText('🪷 KARMA',-w/2+10,1);
    ctx.textAlign='right'; ctx.font='bold 11px "Press Start 2P",monospace'; ctx.lineWidth=3; ctx.strokeStyle='#1a0b05'; ctx.strokeText('-'+K,w/2-10,1); ctx.fillStyle='#ff5b4f'; ctx.fillText('-'+K,w/2-10,1);
