  projectiles.push({ x:sx, y:sy, vx:dx/L*NJ_KUNAI_SPD, vy:dy/L*NJ_KUNAI_SPD, team:f.team, owner:f, dmg:NJ_KUNAI_DMG, life:150, maxLife:150, size:7, isKunai:true, hitFx:'Blood Batch 1_Sprite' });
  f._njKunaiCD=NJ_KUNAI_CD; f.actionState='attack'; f.actionTimer=8; f._njThrow0=tick; f._njThrowDir=d;
  playSample('ninja_kunai',0.9);
