  ctx.fillStyle='#e8e8e8'; for(let i=0;i<5;i++){ const cx=-hl+hl*(i+0.5)/5; ctx.beginPath(); ctx.moveTo(cx-hl*0.07,0); ctx.lineTo(cx,-bw*0.5); ctx.lineTo(cx+hl*0.07,0); ctx.lineTo(cx,bw*0.5); ctx.closePath(); ctx.fill(); }
  ctx.fillStyle='#111'; for(let i=0;i<5;i++){ const cx=-hl+hl*(i+0.5)/5; ctx.beginPath(); ctx.arc(cx,0,bw*0.13,0,Math.PI*2); ctx.fill(); }
  ctx.fillStyle='#3a3a40'; ctx.fillRect(-hl-bw*0.35,-bw*0.7,bw*0.4,bw*1.4);
