  ctx.fillStyle='#2b2b30'; ctx.fillRect(-bw*0.25,-bw*1.15,bw*0.5,bw*2.3); ctx.fillStyle='#8d8d96'; ctx.fillRect(bw*0.25,-bw*0.55,bw*0.6,bw*1.1);
