  ctx.globalAlpha=0.3; ctx.strokeStyle='#cfd8e6'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(-34,0); ctx.lineTo(-12,0); ctx.stroke(); ctx.globalAlpha=1;   // vệt gió
