  const g=ctx.createLinearGradient(0,-5,0,5); g.addColorStop(0,'#5d6470'); g.addColorStop(0.5,'#c9d1db'); g.addColorStop(1,'#3a3f48');
  ctx.fillStyle=g; ctx.beginPath(); ctx.moveTo(-1.5,0); ctx.lineTo(4,-5); ctx.lineTo(15,0); ctx.lineTo(4,5); ctx.closePath(); ctx.fill();   // lưỡi lá
