// danh sách bài + thứ bắn ra. Danh sách guitar hiện TRỐNG → tự lùi về dùng nhạc piano cho cơ chế vẫn chạy đúng;
// khi có file guitar thì chỉ cần nhúng vào AUDIO_SAMPLES rồi thêm key vào đây, không phải sửa gì thêm.
const GUITAR_SONGS = ['guitar_jojo','guitar_aot','guitar_s1','guitar_unravel','guitar_deltarune','guitar_bluebird'];   // guitar_bluebird = Blue Bird (Naruto Shippuden OP3) cover
// 😈 vệt vẽ của Evil Larry — cùng CƠ CHẾ với vệt dãi Wet Cat (đóng dấu từng đoạn ngắn vào 1 bitmap cache rồi
// mỗi frame chỉ blit 1 lần), nhưng KHÁC hẳn về hình thức: Wet Cat là dải cyan mềm nhoè; đây là nét MÁU KHÔ
// đỏ thẫm, mảnh và sắc hơn, có lõi đỏ tươi.
// ⚠️ Cùng bài học của Wet Cat: trong cache phải vẽ ĐỤC HOÀN TOÀN (alpha=1) và CHỈ 1 màu 1 bề rộng cho mỗi lớp —
// vệt ghép từ hàng trăm đoạn chồng mép nhau, vẽ trong suốt là chỗ chồng cộng dồn alpha thành từng khoanh.
function _elStamp(f){
  if(!_elTrailCache){ _elTrailCache=document.createElement('canvas');
    _elTrailCache.width=Math.ceil(W*_ARENA_SS); _elTrailCache.height=Math.ceil(H*_ARENA_SS); }
  const c=_elTrailCache.getContext('2d');
  const px=(f._elPrevX===undefined)?f.x:f._elPrevX, py=(f._elPrevY===undefined)?f.y:f._elPrevY;
  const _w=Math.max(6, f.size*0.62);
  c.save(); c.scale(_ARENA_SS,_ARENA_SS);
  c.lineJoin='round'; c.lineCap='round';
  c.shadowColor='#5b0000'; c.shadowBlur=_w*0.42;      // rìa se lại, không nhoè mềm như Wet Cat
  c.strokeStyle='#5b0000'; c.lineWidth=_w;
  c.beginPath(); c.moveTo(px,py); c.lineTo(f.x,f.y); c.stroke();
  c.shadowBlur=0;
  c.strokeStyle='#c62828'; c.lineWidth=_w*0.42;       // lõi đỏ tươi chạy giữa nét
  c.beginPath(); c.moveTo(px,py); c.lineTo(f.x,f.y); c.stroke();
  c.restore();
  f._elPrevX=f.x; f._elPrevY=f.y;
}
// 😈 Dạng MẮT ĐỎ của Evil Larry — avatar thường sẽ chuyển dần sang dạng này theo tiến độ vẽ ngôi sao.
// Toạ độ 2 con mắt đo TRỰC TIẾP từ ảnh (lọc pixel đỏ rồi lấy trọng tâm 2 cụm trái/phải), theo tỉ lệ cỡ ảnh.
const EVILLARRY_RED_IMG=new Image();
EVILLARRY_RED_IMG.src='assets/img/evillarry/EVILLARRY_RED_IMG.webp';
const _EL_EYE_L={x:0.407,y:0.219}, _EL_EYE_R={x:0.680,y:0.232};
// 😈 EVIL LARRY — NGÔI SAO QUỶ vẽ trên sàn. Đường vẽ = 5 nét sao (vẽ 1 nét liền: 0→2→4→1→3→0) rồi tới vòng tròn
// bao quanh. Larry chỉ đi dọc đường này, không đánh ai; đi hết đường là nghi lễ hoàn tất.
function _elBuildPath(sz){
  // ôm SÁT cả sàn: dùng ellipse theo đúng tỉ lệ sàn, chỉ chừa đúng bán kính thân Larry + 4px —
  // chừa ít hơn thì bounceWalls() sẽ đẩy ngược lại, Larry không bao giờ tới được điểm nằm ngoài mép.
  const cx=W/2, cy=H/2, m=(sz||44)+4;
  const rx=Math.max(20, W/2-m), ry=Math.max(20, H/2-m);
  const V=[];
  for(let i=0;i<5;i++){ const a=Math.PI/2 + i*(Math.PI*2/5); V.push({x:cx+Math.cos(a)*rx, y:cy+Math.sin(a)*ry}); }
  const path=[];
  for(const i of [0,2,4,1,3,0]) path.push(V[i]);      // ngôi sao 1 nét liền
  const N=44;                                          // vòng bao quanh
  for(let i=0;i<=N;i++){ const a=Math.PI/2 + (i/N)*Math.PI*2; path.push({x:cx+Math.cos(a)*rx, y:cy+Math.sin(a)*ry}); }
  return path;
}
