      // lỗ + viền kim loại
      ctx.fillStyle='#0c0d10'; ctx.strokeStyle='#5d6470'; ctx.lineWidth=Math.max(1.5,w*0.06);
      ctx.beginPath(); ctx.roundRect(f.x-w/2,f.y-hh/2,w,hh,hh*0.25); ctx.fill(); ctx.stroke();
