      if(t<8){ ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=1-t/8; ctx.strokeStyle='#ff2a2a'; ctx.lineWidth=3; ctx.beginPath(); ctx.arc(0,0,f.s*(0.5+t/8*0.9),0,Math.PI*2); ctx.stroke(); }
