// ⚡ giáng 1 tia sét từ đỉnh sàn xuống đúng điểm (x,y) — mảng lightningBolts đã có sẵn hệ thống vẽ (4 lớp glow tím
// + nhánh phụ + nhấp nháy), trước giờ chưa chỗ nào push vào nên dùng lại được nguyên vẹn.
let _LIGHT_RED=false;   // bật lên trước khi gọi _strikeLightning để ra tia sét ĐỎ (Evil Larry) thay vì tím
function _strikeLightning(x, y, life){
  const _seed=Array.from({length:48},()=>Math.random());
  const _pts=_genLightPts(x+(Math.random()-0.5)*40, -20, x, y, _seed, 5, 0);
  const _branches=[];
  for(let b=0;b<3;b++){
    const _bi=Math.floor(_pts.length*(0.25+Math.random()*0.5));
    const _p=_pts[Math.min(_pts.length-1,_bi)];
    _branches.push({ pts:_genLightPts(_p[0], _p[1], _p[0]+(Math.random()-0.5)*130, _p[1]+40+Math.random()*70,
                     Array.from({length:24},()=>Math.random()), 3, 0) });
  }
  lightningBolts.push({ pts:_pts, branches:_branches, life:life||34, maxLife:life||34, red:!!_LIGHT_RED });
}
// Lightning bolt point generation (midpoint displacement)
function _genLightPts(x1,y1,x2,y2,seed,depth,si){
  if(depth<=0) return [[x1,y1],[x2,y2]];
  const len=Math.sqrt((x2-x1)**2+(y2-y1)**2)||1;
  const mx=(x1+x2)/2, my=(y1+y2)/2;
  const disp=(seed[si%seed.length]-0.5)*len*0.48;
  const nx=-(y2-y1)/len, ny=(x2-x1)/len;
  const bx=mx+nx*disp, by=my+ny*disp;
  const L=_genLightPts(x1,y1,bx,by,seed,depth-1,si+1);
  const R=_genLightPts(bx,by,x2,y2,seed,depth-1,si+7);
  return [...L.slice(0,-1),...R];
}
function updateShake(){
  if(_cdgQuake>0) _cdgQuake--;
  if(screenShake.dur>0){
    screenShake.dur--;
    const s=screenShake.str*(screenShake.dur/10);
    screenShake.x=(Math.random()-0.5)*s;
    screenShake.y=(Math.random()-0.5)*s;
  } else { screenShake.x=0; screenShake.y=0; }
  if(hitStopCD>0) hitStopCD--;
  if(koZoom>0) koZoom=Math.max(0, koZoom-0.04);
  _flowerSeqTick(); // tick chuỗi Siêu Việt Flower Cat — chạy độc lập khỏi battleFreezeTimer (xem định nghĩa hàm)
  _slChargeTick(); // ☭ tick nạp sáng 2s Stalin Cat — chạy độc lập khỏi battleFreezeTimer (xem định nghĩa hàm)
  _frSeqTick();    // 🐈‍⬛ chuỗi bóng đêm Friend — chạy độc lập khỏi battleFreezeTimer
  if(frSeq) for(const _f of fighters) if(_f.type==='depressedcat' && !_f.dead && _f!==frSeq.owner) _f._dpLamentTick();   // 😿 trận đứng hình vì Friend tắt đèn: kêu than vẫn chạy tiếp
  _smPreTick();    // 💧 màn đứng hình + giọt nước trước khi kết liễu
  _egAwakenTick(); // 😈 Evil Gary đủ 5 cánh sao: đứng hình, quỷ bung cánh, lãnh địa lan ra
  _psTick();       // 🌀 Depressed Cat — Shinra Tensei
  _mwPurpleTick(); // 🟣 Mewing Cat — Hollow Purple: dừng thời gian + cầu tím xoá sổ mọi thứ trên đường bay
  _smCineTick();   // ⚔️🎬 cảnh kết liễu Samurai Cheems — chạy độc lập khỏi battleFreezeTimer
  _susVoteTick();  // 📮 tick chuỗi họp khẩn + bỏ phiếu Sus Cat — cũng phải chạy độc lập khỏi battleFreezeTimer
}
