// 🖼️ avatar thật cho LƯỚI ROSTER (màn chờ) — lazy-load theo charKey, cache lại, fallback null nếu chưa có ảnh upload
const _rosterThumbCache={};
function _getRosterThumb(charKey){
  if(_rosterThumbCache[charKey]!==undefined) return _rosterThumbCache[charKey];
  const entry=roster.find(r=>r.charKey===charKey && r.avatarUrl);
  if(!entry){ _rosterThumbCache[charKey]=null; return null; }
  const img=new Image();
  img.onload=()=>{ img._crop=computeCropBox(img); };
  img.src=entry.avatarUrl;
  _rosterThumbCache[charKey]=img;
  return img;
}

// 🪄 Ảnh/GIF upload là ẢNH CHỤP THẬT (nền đặc 1 màu, không có alpha) → hệ thống cắt viền theo silhouette
// (computeCropBox/_stickerMask) không cắt được, hiện nguyên khối vuông nền trắng/đặc xấu.
// Hàm này TỰ ĐỘNG xoá nền: lan (flood-fill) từ toàn bộ viền ngoài ảnh qua các pixel màu gần giống màu nền,
// biến chúng thành trong suốt — CHỈ chạy khi ảnh CHƯA có alpha thật (tránh đụng vào ảnh đã cắt sẵn/VFX có alpha).
// dataUrl vào → dataUrl ra (đã xoá nền) hoặc null nếu không cần/không xử lý được (giữ nguyên ảnh gốc).
function _autoKeyBackgroundDataUrl(dataUrl, cb){
  const img=new Image();
  img.onload=()=>{
    try{
      const w=img.naturalWidth, h=img.naturalHeight;
      if(!w||!h){ cb(null); return; }
      const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
      const c=cv.getContext('2d'); c.drawImage(img,0,0);
      const id=c.getImageData(0,0,w,h); const d=id.data;
      const N=w*h;
      // 1) đã có transparency thật (>2% pixel mờ/trong) → coi như đã tự cắt sẵn, không đụng vào
      let transp=0;
      for(let i=3;i<d.length;i+=4) if(d[i]<250) transp++;
      if(transp > N*0.02){ cb(null); return; }
      // 2) màu nền = trung bình các pixel VIỀN NGOÀI CÙNG
      let br=0,bg=0,bb=0,bn=0;
      for(let x=0;x<w;x++){ for(const y of [0,h-1]){ const idx=(y*w+x)*4; br+=d[idx];bg+=d[idx+1];bb+=d[idx+2]; bn++; } }
      for(let y=1;y<h-1;y++){ for(const x of [0,w-1]){ const idx=(y*w+x)*4; br+=d[idx];bg+=d[idx+1];bb+=d[idx+2]; bn++; } }
      br/=bn; bg/=bn; bb/=bn;
      // 3) flood-fill từ viền qua các pixel gần màu nền (ngưỡng khoảng cách màu)
      const THRESH=34;
      const visited=new Uint8Array(N);
      const within=(idx)=>{ const p=idx*4, dr=d[p]-br, dg=d[p+1]-bg, db=d[p+2]-bb; return Math.sqrt(dr*dr+dg*dg+db*db)<THRESH; };
      const stack=new Int32Array(N); let sp=0;
      const seed=(idx)=>{ if(!visited[idx] && within(idx)){ visited[idx]=1; stack[sp++]=idx; } };
      for(let x=0;x<w;x++){ seed(x); seed((h-1)*w+x); }
      for(let y=0;y<h;y++){ seed(y*w); seed(y*w+w-1); }
      while(sp>0){
        const idx=stack[--sp]; const cx=idx%w, cy=(idx/w)|0;
        if(cx>0) seed(idx-1); if(cx<w-1) seed(idx+1);
        if(cy>0) seed(idx-w); if(cy<h-1) seed(idx+w);
      }
      let removed=0;
      for(let i=0;i<N;i++) if(visited[i]){ d[i*4+3]=0; removed++; }
      if(removed < N*0.01){ cb(null); return; } // không có nền đặc đáng kể để xoá → giữ nguyên ảnh gốc
      c.putImageData(id,0,0);
      cb(cv.toDataURL('image/png'));
    }catch(e){ cb(null); }
  };
  img.onerror=()=>cb(null);
  img.src=dataUrl;
}

// Phân tích bounding box pixel thực của PNG (loại bỏ vùng trong suốt)
function computeCropBox(img){
  const cw=img.naturalWidth, ch=img.naturalHeight;
  const tmp=document.createElement('canvas'); tmp.width=cw; tmp.height=ch;
  const tc=tmp.getContext('2d'); tc.drawImage(img,0,0);
  let data;
  try{ data=tc.getImageData(0,0,cw,ch).data; } catch(e){ return null; }
  let minX=cw,minY=ch,maxX=0,maxY=0;
  for(let y=0;y<ch;y++) for(let x=0;x<cw;x++){
    const a=data[(y*cw+x)*4+3];
    if(a>8){ // alpha > 8 = visible
      if(x<minX) minX=x; if(x>maxX) maxX=x;
      if(y<minY) minY=y; if(y>maxY) maxY=y;
    }
  }
  if(minX>maxX||minY>maxY) return null; // fully transparent
  // add 2px padding
  const pad=2;
  minX=Math.max(0,minX-pad); minY=Math.max(0,minY-pad);
  maxX=Math.min(cw-1,maxX+pad); maxY=Math.min(ch-1,maxY+pad);
  return { sx:minX, sy:minY, sw:maxX-minX+1, sh:maxY-minY+1, iw:cw, ih:ch };
}

// ===== Gán VFX từ KHO (VFX Library) cho nhân vật theo TÊN =====
// vfx  = hiệu ứng skill chính (Evil Larry: Evil Mode). vfx2 = hiệu ứng đòn thường.
