    this._rrNextAt = 0;        // hộp ĐẦU TIÊN thả ngay khi hết _introLock (=1s vào trận), từ hộp thứ 2 mới tính CD 4s
    this._rrDanceT = 0;        // còn bao nhiêu tick đang bị khoá nhảy theo nhạc (0 = không dính)
    this._rrIsRick = false;    // true = đây là Rick đang nhảy cùng nạn nhân (lật vòng 3 ảnh tư thế nhảy, xem draw())
    this.popcatMouthOpen = false;
    this.popcatMouthTimer = 0;
