  if(!keepFr && _frSongSfx){ _stopLoopAudio(_frSongSfx); for(const f of fighters) if(f._frMusic===_frSongSfx) f._frMusic=null; _frSongSfx=null; }
  if(_frThunderSfx){ try{ _frThunderSfx.pause(); _frThunderSfx.currentTime=0; }catch(e){} _frThunderSfx=null; }   // ⚡ sét cảnh chân thân Friend
  _fanStopRoulette(); _fanStopSlot(); _susStopSpinSfx();                                                 // 🎰 tiếng vòng quay (Commenter + vòng bỏ phiếu Sus Cat)
  if(_ccMeow){ try{ _ccMeow.pause(); _ccMeow.currentTime=0; }catch(e){} _ccMeow=null; }   // 😿 tiếng mèo buồn Crying Cat
  if(_wcMeow){ try{ _wcMeow.pause(); _wcMeow.currentTime=0; }catch(e){} _wcMeow=null; }   // 🤤 tiếng mèo buồn Wet Cat lúc thắng/thua
