  if(_dawaeRunSfx2){ _stopLoopAudio(_dawaeRunSfx2); _dawaeRunSfx2=null; }      // 🚪 tiếng chạy loop thứ 2 (bước chân) của đàn Da Wae
  // ricardo music (stored on fighter objects)
