        if(f.type==='samuraicheems' && !f.dead && !p._smReflected && _smRoll(f)){ f._smParryOpen=!((f._smParryT||0)>0); if(f._smParryOpen) f._smParryT=Math.round(SM_PARRY_S*_egTps()); _smReflect(f,p); _smRef=true; break; }
