      if(p.isGojoRed){ const _grAng=Math.atan2(p.vy,p.vx); f.vx=Math.cos(_grAng)*26; f.vy=Math.sin(_grAng)*20; f._slammed=true; _hitParticles(f.x,f.y,'#e53935',8,false,true); }
      if(p.isPgWave){ f._pakistanSlowTimer=60; addShake(8,12); airCracks.push({x:f.x,y:f.y,angle:Math.atan2(p.vy,p.vx),life:26,maxLife:26,size:f.size*3.2,seed:Array.from({length:32},()=>Math.random())}); _hitParticles(f.x,f.y,'#01411c',10); }
