      if(p.isRbWave){ const _rwAng=Math.atan2(p.vy,p.vx); f.vx=Math.cos(_rwAng)*12; f.vy=Math.sin(_rwAng)*12; f._slammed=true; addShake(3,5); _hitParticles(f.x,f.y,'#8e24aa',6,false,true); }
