        const _sstk = Math.max(1, s._slipStacks||1);
        const _saccel = 1.2 + 0.4*(_sstk-1);
        const slipSpd = sTopSpeed * (1.3 + 0.5*(_sstk-1));
        s.vx+=Math.cos(s._slipDir||0)*_saccel; s.vy+=Math.sin(s._slipDir||0)*_saccel;
        const ssp3=Math.sqrt(s.vx*s.vx+s.vy*s.vy);
        if(ssp3>slipSpd){ s.vx=s.vx/ssp3*slipSpd; s.vy=s.vy/ssp3*slipSpd; }
        if(s._slipTimer===0){ s._slipStacks=0; s._slipDir=null; }
