const _scPropCache={};
function _scPropImg(key){
  if(_scPropCache[key]) return _scPropCache[key];
  const P=SC_PROPS[key]; if(!P) return null;
  const cv=document.createElement('canvas'); cv.width=P.w; cv.height=P.h;
  const g=cv.getContext('2d'); P.paint(g,P.w,P.h);
  const im=new Image(); im.src=cv.toDataURL('image/png');
  _scPropCache[key]=im; return im;
}

const SC_GROUPS={
  anim: ['move','suck','scale','rotate','fade','pose','shatter'],
  film: ['bg','garypossess','portal','firegate','bridge','discolight','corridor','doorpush','hellfire','crowd','stagelights','eye','pentagram','larryrise','lightning','dark','flash','shake','text'],
};

// 🎨 Bóng đặc 1 màu của 1 ảnh — dùng để vẽ VIỀN quanh diễn viên. Bake 1 lần rồi cache theo (ảnh, màu):
// vẽ ảnh đã cắt nền rồi tô đè bằng source-in, ra đúng cái silhouette. Vẽ silhouette đó lệch ra 8 hướng
// quanh ảnh thật là thành đường viền ôm sát hình, không phải khung chữ nhật.
const _scSilCache=new Map();
function _scSilhouette(img, color){
  let m=_scSilCache.get(img);
  if(!m){ m=new Map(); _scSilCache.set(img,m); }
  if(m.has(color)) return m.get(color);
  const src=_stickerMask(img);
  const c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const g=c.getContext('2d');
  g.drawImage(src,0,0);
  g.globalCompositeOperation='source-in';
  g.fillStyle=color; g.fillRect(0,0,c.width,c.height);
  m.set(color,c); return c;
}
// ===================== TRẠNG THÁI DIỄN VIÊN TẠI THỜI ĐIỂM t =====================
// Đi tuần tự qua các clip đã sắp theo mốc bắt đầu: clip 'move' dời vị trí, 'pose' đổi ô ảnh, 'shatter' ẩn thân.
// Nhờ tính lại từ đầu mỗi khung hình nên kéo thanh thời gian tới đâu cũng ra đúng trạng thái tới đó.
function _scActorAt(a,t){
  let x=_scX(a.x), y=_scY(a.y), size=a.size, slot=0, hidden=false, hop=0, lean=0;
  let rot=(a.rot||0)*Math.PI/180, alpha=1;
  const _ez=k=>k<0.5?2*k*k:1-Math.pow(-2*k+2,2)/2;   // vào/ra mượt, dùng chung cho mọi lệnh animation
  const cs=SCENE.clips.filter(c=>c.p && c.p.who===a.id).sort((m,n)=>m.t0-n.t0);
  for(const c of cs){
    if(c.type==='scale'||c.type==='rotate'||c.type==='fade'){
      const from = c.type==='scale' ? size : c.type==='rotate' ? rot : alpha;
      const to   = c.type==='scale' ? c.p.to : c.type==='rotate' ? c.p.to*Math.PI/180 : c.p.to/100;
      let v=from;
      if(t>=c.t0+c.len) v=to;
      else if(t>=c.t0) v=from+(to-from)*_ez((t-c.t0)/c.len);
      if(c.type==='scale') size=v; else if(c.type==='rotate') rot=v; else alpha=v;
      continue;
    }
    if(c.type==='suck'){
      // xoáy vào tâm: bán kính co dần về 0, vừa xoay quanh tâm vừa thu nhỏ và mờ đi
      const tx=_scX(c.p.x), ty=_scY(c.p.y);
      if(t>=c.t0+c.len){ x=tx; y=ty; size=Math.max(1,size*0.05); alpha=0; }
      else if(t>=c.t0){
        const k=(t-c.t0)/c.len;
        const dx=x-tx, dy=y-ty;
        const r0=Math.hypot(dx,dy), a0=Math.atan2(dy,dx);
        const ang=k*Math.PI*2*(c.p.turns||0);
        const rr=r0*(1-k)*(1-k);            // hút chậm lúc đầu, ngoặm rất nhanh ở cuối
        x=tx+Math.cos(a0+ang)*rr; y=ty+Math.sin(a0+ang)*rr;
        size=Math.max(1,size*(1-k*0.95));
        rot=rot+ang;
        alpha=Math.max(0,1-k*0.9);
      }
      continue;
    }
    if(c.type==='move'){
      const tx=_scX(c.p.x), ty=_scY(c.p.y);
      if(t>=c.t0+c.len){ x=tx; y=ty; }
      else if(t>=c.t0){
        const k=(t-c.t0)/c.len, e=k<0.5?2*k*k:1-Math.pow(-2*k+2,2)/2;   // vào/ra mượt
        const fx=x, fy=y; x=fx+(tx-fx)*e; y=fy+(ty-fy)*e;
        if(c.p.gait==='hop'){
          const ph=(t-c.t0)*0.20;
          hop=Math.abs(Math.sin(ph))*size*0.17; lean=Math.sin(ph*0.5)*0.20;
        }
      }
    } else if(c.type==='pose'){
      if(t>=c.t0 && t<c.t0+c.len) slot=+c.p.slot||0;
    } else if(c.type==='shatter'){
      if(t>=c.t0) hidden=true;
    }
  }
  return {x,y,size,slot,hidden,hop,lean,rot,alpha};
}
function _scDrawActor(a,t){
  const st=_scActorAt(a,t);
  if(st.hidden) return;
  let im=null, _rr=null;
  if(a.propKey){                                  // 🧱 đạo cụ: ảnh vẽ bằng code, không có trong roster
    im=_scPropImg(a.propKey);
  } else {
    const r=roster[a.rosterIdx]; if(!r) return;
    _rr=r;
    const url=[r.avatarUrl, r.skill1AvatarUrl, r.skill2AvatarUrl, r.skill3AvatarUrl][st.slot] || r.avatarUrl;
    if(url){ if(!_scImgCache[url]){ const q=new Image(); q.src=url; _scImgCache[url]=q; } im=_scImgCache[url]; }
  }
  if(st.alpha<=0.01) return;
  ctx.save();
  ctx.globalAlpha=st.alpha;
  ctx.translate(st.x, st.y-st.hop);
  ctx.rotate(st.lean+st.rot);
  if(a.flip) ctx.scale(-1,1);
  if(a.flipY) ctx.scale(1,-1);
  if(im && im.complete && im.naturalWidth){
    const cr=im._crop||(im._crop=computeCropBox(im));
    const sx=cr?cr.sx:0, sy=cr?cr.sy:0, sw=cr?cr.sw:im.naturalWidth, sh=cr?cr.sh:im.naturalHeight;
    const asp=sw/sh; let dw,dh;
    if(asp>=1){ dw=st.size; dh=st.size/asp; } else { dh=st.size; dw=st.size*asp; }
    if(a.outline){
      const _ow=a.outlineW||3, _sil=_scSilhouette(im, a.outline);
      for(let _k=0;_k<8;_k++){
        const _ang=_k*Math.PI/4;
        ctx.drawImage(_sil, sx,sy,sw,sh, -dw/2+Math.cos(_ang)*_ow, -dh/2+Math.sin(_ang)*_ow, dw,dh);
      }
    }
    ctx.drawImage(_stickerMask(im), sx,sy,sw,sh, -dw/2,-dh/2, dw,dh);
  } else {
    // dự phòng khi ảnh chưa nạp: meme thì vẽ emoji, đạo cụ thì vẽ ô mờ (đạo cụ không nằm trong CHAR_DEFS,
    // trước đây chỗ này còn dùng biến `r` của nhánh meme nên đạo cụ làm văng lỗi "r is not defined")
    if(a.propKey){
      ctx.fillStyle='rgba(255,255,255,0.10)';
      ctx.fillRect(-st.size*0.5, -st.size*0.5, st.size, st.size);
    } else {
      ctx.font=Math.round(st.size*0.9)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText((_rr&&CHAR_DEFS[_rr.charKey]&&CHAR_DEFS[_rr.charKey].emoji)||'❓',0,0);
    }
  }
  ctx.restore();
  // 🖱️ KHUNG CHỌN KIỂU SLIDE: viền đứt + 4 nút góc để kéo phóng to/thu nhỏ + 1 nút trên đầu để xoay.
}
const SC_HANDLE=9, SC_ROT_ARM=22;
// ===================== 🖱️ TƯƠNG TÁC KIỂU TRÌNH SỬA SLIDE (Canva / Google Slides) =====================
// Bộ quy ước chuẩn của trình sửa đồ hoạ, áp cho CẢ diễn viên lẫn khối cảnh đặt trên sàn:
//   • 8 nút: 4 góc (phóng giữ tỉ lệ) + 4 cạnh (kéo dãn 1 chiều) — neo ở ĐIỂM ĐỐI DIỆN, không phải ở tâm
//   • 1 nút xoay phía trên; giữ Shift để bắt nấc 15°
//   • kéo thân để dời; bám dính (snap) vào tâm sàn / mép sàn / tâm các vật khác, có VẠCH DẪN hiện ra
//   • phím mũi tên nhích 1px, Shift+mũi tên nhích 10px
//   • Ctrl/Cmd+D nhân bản, Delete xoá, Esc bỏ chọn
//   • con trỏ chuột đổi theo nút đang rê tới
const SC_SNAP=6;            // ngưỡng bám dính (px)
let _scGuides=[];           // vạch dẫn đang hiện: {ngang:bool, v:toạ độ}

// Bọc diễn viên / khối cảnh thành CÙNG một giao diện {x,y,h,rot} để phần điều khiển chỉ viết 1 lần.
function _scObj(sel){
  if(!sel) return null;
  if(sel.k==='actor'){
    const a=SCENE.actors.find(z=>z.id===sel.id); if(!a) return null;
    return {
      kind:'actor', ref:a, pad:5, coSize:true, coRot:true, tiLe:true,
      get x(){ return _scX(a.x); },       set x(v){ a.x=Math.round(v/W*1000)/10; },
      get y(){ return _scY(a.y); },       set y(v){ a.y=Math.round(v/H*1000)/10; },
      get w(){ return a.size/2; },        set w(v){ a.size=Math.round(Math.max(10,v*2)); },
      get h(){ return a.size/2; },        set h(v){ a.size=Math.round(Math.max(10,v*2)); },
      get rot(){ return (a.rot||0)*Math.PI/180; },
      set rot(v){ a.rot=Math.round(v*180/Math.PI*10)/10; },
    };
  }
  const c=SCENE.clips.find(z=>z.id===sel.id); if(!c) return null;
  const B=SC_BLOCKS[c.type]; if(!B) return null;
  const has=k=>B.params.some(q=>q.k===k);
  if(!has('x')||!has('y')) return null;
  const coSize=has('size'), coRot=has('ang');
  const half=()=> c.type==='vfx' ? W*(c.p.size/100)/2
                : c.type==='text' ? Math.max(14,c.p.size*0.8)
                : Math.max(16,W*0.05);
  const setHalf=v=>{
    if(c.type==='vfx')       c.p.size=Math.max(2, Math.round(v*2/W*1000)/10);
    else if(c.type==='text') c.p.size=Math.max(8, Math.round(v/0.8));
  };
  return {
    kind:'clip', ref:c, pad:4, coSize, coRot, tiLe:true,
    get x(){ return _scX(c.p.x); },  set x(v){ c.p.x=Math.round(v/W*1000)/10; },
    get y(){ return _scY(c.p.y); },  set y(v){ c.p.y=Math.round(v/H*1000)/10; },
    get w(){ return half(); },       set w(v){ setHalf(v); },
    get h(){ return half(); },       set h(v){ setHalf(v); },
    get rot(){ return coRot ? c.p.ang*Math.PI/180 : 0; },
    set rot(v){ if(coRot) c.p.ang=Math.round(v*180/Math.PI); },
  };
}
// vật đang chọn có nằm trên sàn không
function _scSelObj(){ return _scObj(_scSel); }

// 8 nút quanh hộp: [tên, hệ số x, hệ số y]
const SC_HANDLES=[['nw',-1,-1],['n',0,-1],['ne',1,-1],['e',1,0],['se',1,1],['s',0,1],['sw',-1,1],['w',-1,0]];
const SC_CURSOR={nw:'nwse-resize',se:'nwse-resize',ne:'nesw-resize',sw:'nesw-resize',
                 n:'ns-resize',s:'ns-resize',e:'ew-resize',w:'ew-resize',rot:'grab',body:'move'};

function _scDrawBox(o){
  const hw=o.w+o.pad, hh=o.h+o.pad;
  ctx.save();
  ctx.translate(o.x,o.y); ctx.rotate(o.rot||0);
  ctx.strokeStyle='#f0c040'; ctx.lineWidth=1.5; ctx.setLineDash([5,4]);
  ctx.strokeRect(-hw,-hh,hw*2,hh*2);
  ctx.setLineDash([]);
  if(o.coRot){
    ctx.strokeStyle='#f0c040'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.moveTo(0,-hh); ctx.lineTo(0,-hh-SC_ROT_ARM); ctx.stroke();
    ctx.fillStyle='#f0c040'; ctx.strokeStyle='#1a1a2e'; ctx.lineWidth=1.3;
    ctx.beginPath(); ctx.arc(0,-hh-SC_ROT_ARM,SC_HANDLE*0.62,0,Math.PI*2); ctx.fill(); ctx.stroke();
  }
  if(o.coSize){
    ctx.fillStyle='#fff'; ctx.strokeStyle='#f0c040'; ctx.lineWidth=1.6;
    for(const [,sx,sy] of SC_HANDLES){
      const hx=sx*hw, hy=sy*hh;
      ctx.beginPath(); ctx.rect(hx-SC_HANDLE/2,hy-SC_HANDLE/2,SC_HANDLE,SC_HANDLE); ctx.fill(); ctx.stroke();
    }
  }
  ctx.restore();
}
// điểm sàn (px,py) đang chạm nút nào: tên nút | 'rot' | 'body' | null
function _scHitObj(o, px, py){
  const dx=px-o.x, dy=py-o.y;
  const ca=Math.cos(-(o.rot||0)), sa=Math.sin(-(o.rot||0));
  const lx=dx*ca-dy*sa, ly=dx*sa+dy*ca;
  const hw=o.w+o.pad, hh=o.h+o.pad, r=SC_HANDLE*0.9;
  if(o.coRot && Math.abs(lx)<r && Math.abs(ly+hh+SC_ROT_ARM)<r) return 'rot';
  if(o.coSize) for(const [nm,sx,sy] of SC_HANDLES)
    if(Math.abs(lx-sx*hw)<r && Math.abs(ly-sy*hh)<r) return nm;
  if(Math.abs(lx)<hw && Math.abs(ly)<hh) return 'body';
  return null;
}
// mọi vật trên sàn theo thứ tự vẽ (dưới → trên), để bấm trúng cái NẰM TRÊN trước
function _scPickables(){
  const out=[];
  for(const a of SCENE.actors) out.push({k:'actor',id:a.id});
  for(const c of SCENE.clips) if(_scT>=c.t0 && _scT<c.t0+c.len && _scObj({k:'clip',id:c.id})) out.push({k:'clip',id:c.id});
  return out;
}
// bám dính khi kéo: tâm sàn, 4 mép sàn, và tâm mọi vật khác
function _scSnap(o, nx, ny){
  const mocX=[W/2, 0, W], mocY=[H/2, 0, H];
  for(const s of _scPickables()){
    if(_scSel && s.k===_scSel.k && s.id===_scSel.id) continue;
    const q=_scObj(s); if(!q) continue;
    mocX.push(q.x); mocY.push(q.y);
  }
  _scGuides=[];
  let bx=nx, by=ny, dbx=SC_SNAP, dby=SC_SNAP;
  for(const m of mocX){ const d=Math.abs(nx-m); if(d<dbx){ dbx=d; bx=m; } }
  for(const m of mocY){ const d=Math.abs(ny-m); if(d<dby){ dby=d; by=m; } }
  if(dbx<SC_SNAP) _guidePush(false,bx);
  if(dby<SC_SNAP) _guidePush(true,by);
  return {x:bx,y:by};
}
function _guidePush(ngang,v){ _scGuides.push({ngang,v}); }
function _scDrawGuides(){
  if(!_scGuides.length) return;
  ctx.save();
  ctx.strokeStyle='#ff4da6'; ctx.lineWidth=1; ctx.setLineDash([4,3]);
  for(const g of _scGuides){
    ctx.beginPath();
    if(g.ngang){ ctx.moveTo(-40,g.v); ctx.lineTo(W+40,g.v); }
    else       { ctx.moveTo(g.v,-40); ctx.lineTo(g.v,H+40); }
    ctx.stroke();
  }
  ctx.restore();
}
// ── chuột trên sàn: chọn / kéo / phóng theo nút / xoay ──
function _scStageDown(e){
  const pt=_scPtFromEvent(e); if(!pt) return;
  const px=pt.x/100*W, py=pt.y/100*H;

  // 1) đang chọn sẵn → thử bắt nút của chính nó trước (nút nằm ngoài thân nên phải xét trước)
  let o=_scSelObj(), mode=o?_scHitObj(o,px,py):null;

  // 2) không trúng nút nào → chọn vật NẰM TRÊN CÙNG dưới con trỏ
  if(!mode){
    const ds=_scPickables();
    let got=null;
    for(let i=ds.length-1;i>=0;i--){
      const q=_scObj(ds[i]); if(!q) continue;
      if(_scHitObj(q,px,py)==='body'){ got=ds[i]; break; }
    }
    if(!got){ _scSel=null; _scRenderTimeline(); _scRenderProps(); return; }
    _scSelect(got.k,got.id);
    o=_scSelObj(); mode='body';
  }

  const x0=o.x, y0=o.y, w0=o.w, h0=o.h, rot0=o.rot||0;
  const ang0=Math.atan2(py-y0, px-x0);
  const off={x:x0-px, y:y0-py};

  const mv=ev=>{
    const q=_scPtFromEvent(ev); if(!q) return;
    const qx=q.x/100*W, qy=q.y/100*H;
    if(mode==='body'){
      const s=_scSnap(o, qx+off.x, qy+off.y);   // dời + bám dính
      o.x=s.x; o.y=s.y;
    } else if(mode==='rot'){
      let r=rot0+(Math.atan2(qy-y0, qx-x0)-ang0);
      if(ev.shiftKey) r=Math.round(r/(Math.PI/12))*(Math.PI/12);   // Shift: bắt nấc 15°
      o.rot=r;
    } else {
      // PHÓNG THEO NÚT, neo ở điểm ĐỐI DIỆN — kéo góc phải thì mép trái đứng im, đúng như Canva/Slides.
      const H2=SC_HANDLES.find(z=>z[0]===mode); if(!H2) return;
      const sx=H2[1], sy=H2[2];
      const ca=Math.cos(-rot0), sa=Math.sin(-rot0);
      const lx=(qx-x0)*ca-(qy-y0)*sa, ly=(qx-x0)*sa+(qy-y0)*ca;   // về hệ toạ độ riêng của vật
      let nw=w0, nh=h0;
      if(sx) nw=Math.max(6,(sx*lx+w0)/2);
      if(sy) nh=Math.max(6,(sy*ly+h0)/2);
      if(o.tiLe){ const k=Math.max(sx?nw/w0:0, sy?nh/h0:0)||1; nw=w0*k; nh=h0*k; }
      o.w=nw; o.h=nh;
      // dịch tâm sao cho cạnh đối diện đứng yên
      const dw=(o.w-w0)*sx, dh=(o.h-h0)*sy;
      const cw=Math.cos(rot0), sw=Math.sin(rot0);
      o.x=x0+(dw*cw-dh*sw); o.y=y0+(dw*sw+dh*cw);
    }
  };
  const up=()=>{
    document.removeEventListener('mousemove',mv); document.removeEventListener('mouseup',up);
    _scGuides=[]; _scRenderProps();
  };
  document.addEventListener('mousemove',mv); document.addEventListener('mouseup',up);
}
// con trỏ đổi hình theo nút đang rê tới — dấu hiệu quen thuộc của trình sửa slide
function _scStageMove(e){
  const st=document.getElementById('scStage'); if(!st) return;
  const pt=_scPtFromEvent(e); if(!pt) return;
  const px=pt.x/100*W, py=pt.y/100*H;
  let cur='default';
  const o=_scSelObj();
  const m=o?_scHitObj(o,px,py):null;
  if(m) cur=SC_CURSOR[m]||'move';
  else {
    const ds=_scPickables();
    for(let i=ds.length-1;i>=0;i--){ const q=_scObj(ds[i]); if(q && _scHitObj(q,px,py)==='body'){ cur='move'; break; } }
  }
  st.style.cursor=cur;
}
// nhân bản vật đang chọn (Ctrl/Cmd+D), lệch xuống 1 chút như mọi trình sửa
function _scDuplicate(){
  if(!_scSel) return;
  if(_scSel.k==='actor'){
    const a=SCENE.actors.find(z=>z.id===_scSel.id); if(!a) return;
    const b=Object.assign({},a,{id:SCENE.nid++, x:a.x+3, y:a.y+3});
    SCENE.actors.push(b); _scSelect('actor',b.id);
  } else {
    const c=SCENE.clips.find(z=>z.id===_scSel.id); if(!c) return;
    const d={id:SCENE.nid++, type:c.type, lane:_scFreeLane(c.t0,c.len), t0:c.t0, len:c.len, p:Object.assign({},c.p)};
    SCENE.clips.push(d); SCENE.dur=Math.max(SCENE.dur,d.t0+d.len+60);
    _scSelect('clip',d.id);
  }
}
// mũi tên nhích vật đang chọn
function _scNudge(dx,dy){
  const o=_scSelObj(); if(!o) return;
  o.x=Math.round(o.x+dx); o.y=Math.round(o.y+dy);
  _scRenderProps();
}

// 🎞️ Animation áp lên 1 KHỐI CẢNH (VFX / sét / chữ...) — cùng bộ khối Đi tới / Phóng-Thu / Xoay / Hiện-Mờ
// dùng cho diễn viên, chỉ khác là giá trị tính theo ĐƠN VỊ RIÊNG của khối đó (vfx: cỡ tính %, chữ: cỡ tính px).
// Trả về null nếu khối này không bị animation nào nhắm tới → khỏi tốn công ở khung hình đó.
function _scClipAnim(c,t){
  const cs=SCENE.clips.filter(z=>z.p && z.p.who===c.id).sort((m,n)=>m.t0-n.t0);
  if(!cs.length) return null;
  const _ez=k=>k<0.5?2*k*k:1-Math.pow(-2*k+2,2)/2;
  let x=c.p.x, y=c.p.y, size=c.p.size, ang=c.p.ang, alpha=1;
  for(const z of cs){
    if(z.type==='move'){
      if(t>=z.t0+z.len){ x=z.p.x; y=z.p.y; }
      else if(t>=z.t0){ const e=_ez((t-z.t0)/z.len); const fx=x, fy=y; x=fx+(z.p.x-fx)*e; y=fy+(z.p.y-fy)*e; }
    } else if(z.type==='scale'||z.type==='rotate'||z.type==='fade'){
      const from = z.type==='scale' ? size : z.type==='rotate' ? ang : alpha;
      const to   = z.type==='scale' ? z.p.to : z.type==='rotate' ? z.p.to : z.p.to/100;
      if(from===undefined) continue;
      let v=from;
      if(t>=z.t0+z.len) v=to;
      else if(t>=z.t0) v=from+(to-from)*_ez((t-z.t0)/z.len);
      if(z.type==='scale') size=v; else if(z.type==='rotate') ang=v; else alpha=v;
    }
  }
  return {x,y,size,ang,alpha};
}
// ===================== 🎨 NỀN THEO THỜI GIAN =====================
// Nền KHÔNG còn là 1 thiết lập cho cả cảnh nữa. Nút trên thanh công cụ chỉ đặt nền MẶC ĐỊNH (từ tick 0),
// còn muốn đổi nền giữa phim thì thả khối 'Đổi nền' lên timeline — mỗi khối là 1 mốc chuyển, có mờ chồng.

// 📐 Sàn là 480x460 (gần vuông) còn khung nhìn dọc 9:16 cao gần gấp đôi. Khối nào tô "toàn màn"
//    bằng fillRect(0,0,W,H) thì chỉ phủ đúng ô sàn, chừa trống trên dưới → hiện ra một HÌNH VUÔNG.
//    Dùng hàm này để tô tràn hẳn ra ngoài mọi phía.
// 👿 SPRITESHEET bóng quỷ user gửi (08406507…, 4×2 = 8 khung) cho khối "Quỷ trỗi dậy". Đã căn chung ĐÁY + TÂM thân
// để đổi khung không giật, và thêm 2 bản NHẮM MẮT (tô tối pixel mắt đỏ) của khung 3, 4 để làm pha chớp chớp.
// Thứ tự trong dải: 0-1 nhô lên · 2/3 khung 3 mở/nhắm · 4/5 khung 4 mở/nhắm · 6-8 bung cánh · 9 bay đi.
const SC_DEMON_IMG=new Image(); SC_DEMON_IMG.src='assets/img/screamcat/SC_DEMON_IMG.webp';
const SC_DEMON_FW=494, SC_DEMON_FH=320;
const GP_EVIL_IMG=new Image(); GP_EVIL_IMG.src='assets/img/evilgary/GP_EVIL_IMG.webp'; GP_EVIL_IMG._noMask=true;   // 😈 ảnh Evil Gary (user gửi, đã cắt sát viền, nền đã trong suốt → không qua hàm xoá nền)
const GP_LAUGH_CUT=1.25;   // Gary bị nhập: chỉ phát nửa đầu tràng cười sc_laugh (bản gốc 2.5s)
const GP_HP=920, GP_HP_FRAC=0.43;   // máu Gary lúc vừa thắng Cornelius (ảnh chụp trận thật): 920, ~43% thanh (đã hút thêm máu tối đa)
const GP_F=60;                      // Scene Builder chạy 60 khung/giây
// ⏱️ kịch bản (giây) — xem khối 'garypossess'
const GP_T={ walkEnd:1.2, stop:1.7, portal:1.7, riseA:2.1, riseB:3.6, laugh:3.8, dissolve:5.1, flyA:5.3, hit:6.3,
             convA:6.55, sphA:8.1, sphB:8.9, boom:9.9, evLaugh:10.7, end:13.3 };
const GP_C={ dark:'#050308', mid:'#141023', haze:'#2d3350', soul:'#46507a' };
const _gpH=i=>{ const v=Math.sin(i*127.1+311.7)*43758.5453; return v-Math.floor(v); };
const _gpSS=(a,b,x)=>{ const t=Math.max(0,Math.min(1,(x-a)/(b-a))); return t*t*(3-2*t); };
const _gpS=()=>((CHAR_DEFS.gary&&CHAR_DEFS.gary.size)||40)*MEME_SIZE_MUL;   // cỡ Gary y như trong trận 1vs1
function _gpZ(){ const m=ctx.getTransform(); return Math.hypot(m.a,m.b); }   // 1 đơn vị world = ? điểm ảnh canvas
function _gpScreenPt(x,y){ const m=ctx.getTransform(); return [m.a*x+m.c*y+m.e, m.b*x+m.d*y+m.f]; }
function _gpScreen(fn){ ctx.save(); ctx.setTransform(1,0,0,1,0,0); fn(ctx.canvas.width, ctx.canvas.height); ctx.restore(); }

// 🌫️ KHÓI THẬT: 6 mẫu cụm khói dựng từ nhiễu fractal (mép loang lổ, có vân) — tô màu rồi xếp chồng hàng trăm cụm
//    thành khói linh hồn / sương / hắc ám. Dựng 1 lần, cache theo màu.
let _gpSmokeBase=null; const _gpSmokeTint={};
function _gpSmokeSprites(){
  if(_gpSmokeBase) return _gpSmokeBase;
  const N=128, out=[];
  for(let v=0;v<6;v++){
    const seed=v*977+13;
    const hs=(i,j)=>{ let n=Math.imul(i,374761393)^Math.imul(j,668265263)^Math.imul(seed,1442695041); n=Math.imul(n^(n>>>13),1274126177); n^=n>>>16; return (n>>>0)/4294967296; };
    const vn=(x,y)=>{ const xi=Math.floor(x), yi=Math.floor(y), xf=x-xi, yf=y-yi, u=xf*xf*(3-2*xf), w=yf*yf*(3-2*yf);
      const a=hs(xi,yi), b=hs(xi+1,yi), c=hs(xi,yi+1), d=hs(xi+1,yi+1); return a+(b-a)*u+(c-a)*w+(a-b-c+d)*u*w; };
    const cv=document.createElement('canvas'); cv.width=cv.height=N;
    const g=cv.getContext('2d'), id=g.createImageData(N,N), D=id.data;
    for(let y=0;y<N;y++) for(let x=0;x<N;x++){
      const nx=x/N*2-1, ny=y/N*2-1, r=Math.hypot(nx,ny);
      let f=0, amp=0.5, fr=2.2;
      for(let o=0;o<5;o++){ f+=vn(nx*fr+10+v*3.7, ny*fr+7-v*1.3)*amp; amp*=0.5; fr*=2.03; }
      const fall=Math.max(0,1-Math.pow(r/(0.62+0.38*f),2.2));
      const a=Math.pow(fall*Math.min(1,Math.max(0,(f-0.22)*1.7)),1.15);
      const k=(y*N+x)*4; D[k]=D[k+1]=D[k+2]=255; D[k+3]=Math.round(a*255);
    }
    g.putImageData(id,0,0); out.push(cv);
  }
  return _gpSmokeBase=out;
}
function _gpSmoke(v,col){
  let arr=_gpSmokeTint[col];
  if(!arr){ arr=_gpSmokeSprites().map(b=>{ const c=document.createElement('canvas'); c.width=b.width; c.height=b.height;
      const g=c.getContext('2d'); g.drawImage(b,0,0); g.globalCompositeOperation='source-in'; g.fillStyle=col; g.fillRect(0,0,c.width,c.height); return c; });
    _gpSmokeTint[col]=arr; }
  return arr[((v%6)+6)%6];
}
// ⚡ 1 cụm khói linh hồn (3 lớp) được DỰNG SẴN thành 1 ảnh → mỗi cụm chỉ 1 lệnh vẽ thay vì 3. Độ đậm được bù lại
//    đúng bằng lúc vẽ 3 lớp chồng nhau (xem _gpSoulA) nên nhìn y hệt.
const _gpSoulBake=[];
function _gpSoulSprite(v){
  v=((v%6)+6)%6; if(_gpSoulBake[v]) return _gpSoulBake[v];
  const N=320, r=128, c=document.createElement('canvas'); c.width=c.height=N; const g=c.getContext('2d');
  const L=(spr,x,y,rr,rot,a)=>{ g.save(); g.globalAlpha=a; g.translate(N/2+x,N/2+y); g.rotate(rot); g.drawImage(spr,-rr,-rr,rr*2,rr*2); g.restore(); };
  L(_gpSmoke(v,GP_C.dark),0,0,r,0,0.8); L(_gpSmoke(v+2,GP_C.mid),r*0.12,-r*0.1,r*0.85,1.3,0.55); L(_gpSmoke(v+4,GP_C.soul),-r*0.15,-r*0.2,r*0.7,-0.9,0.28);
  return _gpSoulBake[v]=c;
}
const _gpSoulA=(a,k1,k2,k3)=>Math.min(1,(1-(1-k1*a)*(1-k2*a)*(1-k3*a))/0.9352);   // độ đậm 3 lớp chồng → alpha của ảnh dựng sẵn
let _gpC=ctx;   // context mà 3 hàm vẽ khói (_gpPuff/_gpSoul/_gpStreak) đang vẽ vào — bình thường là ctx
// ⚡ LỚP KHÓI NỬA ĐỘ PHÂN GIẢI: khói vốn mềm, mờ → vẽ các đám khói lớn vào canvas phụ bằng 1/2 cạnh (ít điểm ảnh phải tô
//    đi 4 lần) rồi phóng lên phủ lại — mắt không phân biệt được. Chỉ dùng cho khói thường (source-over); mấy thứ
//    cộng sáng ('lighter') vẫn vẽ thẳng lên canvas chính để giữ độ rực.
let _gpLayerCv=null;
function _gpLayer(fn){
  const cw=ctx.canvas.width, ch=ctx.canvas.height, lw=Math.ceil(cw/2), lh=Math.ceil(ch/2);
  if(!_gpLayerCv) _gpLayerCv=document.createElement('canvas');
  const L=_gpLayerCv; if(L.width!==lw||L.height!==lh){ L.width=lw; L.height=lh; }
  const g=L.getContext('2d'); g.setTransform(1,0,0,1,0,0); g.globalAlpha=1; g.globalCompositeOperation='source-over'; g.clearRect(0,0,lw,lh);
  const m=ctx.getTransform(); g.setTransform(m.a*lw/cw,m.b*lh/ch,m.c*lw/cw,m.d*lh/ch,m.e*lw/cw,m.f*lh/ch);
  _gpC=g; try{ fn(); } finally{ _gpC=ctx; }
  ctx.save(); ctx.setTransform(1,0,0,1,0,0); ctx.imageSmoothingEnabled=true; ctx.drawImage(L,0,0,cw,ch); ctx.restore();
}
let _gpView=null;   // khung nhìn (world) của khung hình đang vẽ → bỏ qua cụm khói nằm hẳn ngoài khung
const _gpOff=(x,y,r)=>_gpView && (x+r<_gpView[0]||x-r>_gpView[2]||y+r<_gpView[1]||y-r>_gpView[3]);
function _gpPuff(v,col,x,y,r,rot,a,sy){
  if(!(a>0.003) || !(r>0.2)) return;
  _gpC.save(); _gpC.globalAlpha*=Math.min(1,a); _gpC.translate(x,y); _gpC.rotate(rot); if(sy) _gpC.scale(1,sy);
  _gpC.drawImage(_gpSmoke(v,col),-r,-r,r*2,r*2); _gpC.restore();
}
function _gpStreak(i,x,y,r,dir,a,st){   // cụm khói bị kéo dài theo hướng bay
  if(!(a>0.003) || _gpOff(x,y,r*1.3*st)) return; _gpC.save(); _gpC.translate(x,y); _gpC.rotate(dir); _gpC.scale(st,1/Math.sqrt(st));
  _gpC.globalAlpha*=_gpSoulA(a,0.75,0.5,0.3); _gpC.drawImage(_gpSoulSprite(i),-r*1.25,-r*1.25,r*2.5,r*2.5);
  _gpC.restore();
}
// 1 cụm khói linh hồn = lõi đen đặc + lớp sương xanh xám mờ phủ lệch → có khối, có vân, không phẳng lì
function _gpSoul(i,x,y,r,rot,a){
  if(!(a>0.003) || !(r>0.2) || _gpOff(x,y,r*1.3)) return;
  _gpC.save(); _gpC.globalAlpha*=_gpSoulA(a,0.8,0.55,0.28); _gpC.translate(x,y); _gpC.rotate(rot);
  _gpC.drawImage(_gpSoulSprite(i),-r*1.25,-r*1.25,r*2.5,r*2.5); _gpC.restore();
}
// 🌑 tối dần mép khung hình (vẽ theo toạ độ MÀN HÌNH, tâm sáng đặt ở (x,y) world)
function _gpVignette(x,y,amt,rgb){
  if(amt<=0.003) return; const [sx,sy]=_gpScreenPt(x,y), c=rgb||'6,3,12';
  _gpScreen((cw,ch)=>{ const R=Math.hypot(cw,ch);
    const g=ctx.createRadialGradient(sx,sy,R*0.07,sx,sy,R*0.6);
    g.addColorStop(0,`rgba(${c},0)`); g.addColorStop(0.4,`rgba(${c},${0.5*amt})`); g.addColorStop(1,`rgba(${c},${0.95*amt})`);
    ctx.fillStyle=g; ctx.fillRect(0,0,cw,ch); });
}
function _gpFlash(rgb,a){ if(a<=0.003) return; _gpScreen((cw,ch)=>{ ctx.globalCompositeOperation='lighter'; ctx.fillStyle=`rgba(${rgb},${a})`; ctx.fillRect(0,0,cw,ch); }); }

// 👁 tách riêng các điểm ảnh ĐỎ (mắt) của 1 ảnh + tâm 2 mắt — dùng cho mắt quỷ và mắt Evil Gary
function _gpRedMask(im){
  if(im._redMask) return im._redMask;
  const c=document.createElement('canvas'); c.width=im.naturalWidth; c.height=im.naturalHeight;
  const g=c.getContext('2d'); g.drawImage(im,0,0);
  const d=g.getImageData(0,0,c.width,c.height), a=d.data;
  for(let i=0;i<a.length;i+=4){ const r=a[i],gg=a[i+1],b=a[i+2];
    if(!(a[i+3]>60 && r>110 && r>gg*1.8 && r>b*1.8)) a[i+3]=0; }
  g.putImageData(d,0,0); im._redMask=c; return c;
}
function _scDemonEyes(){ return _gpRedMask(SC_DEMON_IMG); }
function _gpEyeCenters(im, sx,sy,sw,sh){   // tâm 2 mắt trong vùng (sx,sy,sw,sh), toạ độ chuẩn hoá 0..1
  const key=sx+'_'+sy; im._eyeC=im._eyeC||{}; if(im._eyeC[key]) return im._eyeC[key];
  const m=_gpRedMask(im), d=m.getContext('2d').getImageData(sx,sy,sw,sh).data, pts=[];
  for(let y=0;y<sh;y+=2) for(let x=0;x<sw;x+=2) if(d[(y*sw+x)*4+3]>0) pts.push([x,y]);
  if(!pts.length) return im._eyeC[key]=[];
  const mx=pts.reduce((s,p)=>s+p[0],0)/pts.length, cl=[[],[]];
  for(const p of pts) cl[p[0]<mx?0:1].push(p);
  return im._eyeC[key]=cl.filter(c=>c.length>2).map(c=>[c.reduce((s,p)=>s+p[0],0)/c.length/sw, c.reduce((s,p)=>s+p[1],0)/c.length/sh]);
}
function _gpEyeGlow(X,Y,R,a){
  ctx.save(); ctx.globalCompositeOperation='lighter';
  const g=ctx.createRadialGradient(X,Y,0,X,Y,R); g.addColorStop(0,`rgba(255,90,80,${0.95*a})`); g.addColorStop(0.25,`rgba(255,20,40,${0.45*a})`); g.addColorStop(1,'rgba(255,0,30,0)');
  ctx.fillStyle=g; ctx.fillRect(X-R,Y-R,R*2,R*2); ctx.restore();
}

// 🔥 CỔNG ĐỊA NGỤC nhỏ trên sàn: nứt sàn rực lửa, quầng đỏ, miệng vực đen xoáy đỏ, vành lửa + lưỡi lửa liếm lên
function _gpPortalBack(px,py,R,op,lt){
  if(op<=0) return;
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  ctx.save(); ctx.translate(px,py); ctx.scale(1,0.42);
  let g=ctx.createRadialGradient(0,0,0,0,0,R*2.8); g.addColorStop(0,`rgba(255,80,20,${0.5*op})`); g.addColorStop(0.35,`rgba(210,20,10,${0.25*op})`); g.addColorStop(1,'rgba(120,0,0,0)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,R*2.8,0,Math.PI*2); ctx.fill(); ctx.restore();
  ctx.lineCap='round'; ctx.lineJoin='round';
  for(let i=0;i<11;i++){
    const a0=_gpH(i+500)*Math.PI*2, L=R*(0.8+1.1*_gpH(i+510))*_gpSS(0.1,1,op);
    if(L<=0.5) continue;
    let x=px+Math.cos(a0)*R, y=py+Math.sin(a0)*R*0.34, a=a0; const pts=[[x,y]];
    for(let j=1;j<=6;j++){ a+=(_gpH(i*7+j+520)-0.5)*1.0; x+=Math.cos(a)*L/6; y+=Math.sin(a)*L/6*0.42; pts.push([x,y]); }
    for(const [lw,col,al] of [[R*0.1,'255,40,10',0.3],[R*0.04,'255,130,40',0.85],[R*0.014,'255,240,200',0.95]]){
      ctx.strokeStyle=`rgba(${col},${al*op})`; ctx.lineWidth=lw; ctx.beginPath();
      pts.forEach((p,j)=>j?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.stroke(); }
  }
  ctx.globalCompositeOperation='source-over';
  ctx.save(); ctx.translate(px,py); ctx.scale(1,0.34);
  ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.clip();
  g=ctx.createRadialGradient(0,0,0,0,0,R); g.addColorStop(0,'#000'); g.addColorStop(0.55,'#14000a'); g.addColorStop(1,'#5a0608');
  ctx.fillStyle=g; ctx.fillRect(-R,-R,2*R,2*R);
  ctx.globalCompositeOperation='lighter';
  for(let k=0;k<5;k++){ ctx.beginPath();
    for(let j=0;j<=30;j++){ const q=j/30, rr=R*q, an=k*Math.PI*2/5+q*3.4-lt*0.06; const X=Math.cos(an)*rr, Y=Math.sin(an)*rr; j?ctx.lineTo(X,Y):ctx.moveTo(X,Y); }
    ctx.strokeStyle=`rgba(255,40,20,${0.3*op})`; ctx.lineWidth=R*0.16; ctx.stroke();
    ctx.strokeStyle=`rgba(255,150,70,${0.35*op})`; ctx.lineWidth=R*0.035; ctx.stroke(); }
  ctx.restore();
  _gpPortalRim(px,py,R,op,lt,true);
  ctx.restore();
}
function _gpPortalRim(px,py,R,op,lt,back){
  if(op<=0) return;
  ctx.save(); ctx.globalCompositeOperation='lighter';
  ctx.save(); ctx.translate(px,py); ctx.scale(1,0.34);
  const a0=back?Math.PI:0, a1=back?Math.PI*2:Math.PI;
  for(const [lw,col] of [[R*0.24,`rgba(255,40,0,${0.35*op})`],[R*0.09,`rgba(255,120,30,${0.85*op})`],[R*0.03,`rgba(255,245,210,${0.95*op})`]]){
    ctx.strokeStyle=col; ctx.lineWidth=lw; ctx.beginPath(); ctx.arc(0,0,R,a0,a1); ctx.stroke(); }
  ctx.restore();
  for(let i=0;i<18;i++){
    const an=i/18*Math.PI*2+_gpH(i+600)*0.3, sn=Math.sin(an);
    if(back ? sn>0 : sn<=0) continue;
    const X=px+Math.cos(an)*R, Y=py+sn*R*0.34;
    const fh=R*(0.3+0.45*_gpH(i+610))*(0.65+0.35*Math.sin(lt*0.37+i*2.1))*op, fw=R*0.1;
    const lg=ctx.createLinearGradient(X,Y,X,Y-fh);
    lg.addColorStop(0,`rgba(255,150,50,${0.85*op})`); lg.addColorStop(0.45,`rgba(255,50,15,${0.5*op})`); lg.addColorStop(1,'rgba(120,0,0,0)');
    ctx.fillStyle=lg; ctx.beginPath(); ctx.moveTo(X-fw,Y);
    ctx.quadraticCurveTo(X-fw*0.5+Math.sin(lt*0.3+i)*fw, Y-fh*0.6, X+Math.sin(lt*0.25+i)*fw*0.9, Y-fh);
    ctx.quadraticCurveTo(X+fw*0.6, Y-fh*0.45, X+fw, Y); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}
function _gpEmbers(px,py,R,a,lt,n,spread,rise,seed){
  if(a<=0) return;
  ctx.save(); ctx.globalCompositeOperation='lighter';
  for(let i=0;i<n;i++){
    const k=i+(seed||0), sp=0.006+0.009*_gpH(k+700), ph=(lt*sp+_gpH(k+710))%1;
    const X=px+(_gpH(k+720)-0.5)*R*spread+Math.sin(lt*0.05+i)*R*0.12, Y=py-ph*rise;
    const al=a*Math.sin(ph*Math.PI), r=R*(0.022+0.02*_gpH(k+730));
    ctx.fillStyle=`rgba(255,60,20,${al*0.25})`; ctx.beginPath(); ctx.arc(X,Y,r*3.2,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=`rgba(255,${130+Math.round(110*_gpH(k+740))},60,${al})`; ctx.beginPath(); ctx.arc(X,Y,r,0,Math.PI*2); ctx.fill();
  }
  ctx.restore();
}

// 👻 QUỶ kiểu GIÁM NGỤC: thân áo choàng xanh-đen có vân khói, phần dưới TAN thành khói tả tơi, chỉ đôi mắt đỏ rực.
//    dis 0→1: tan hẳn thành khói (từ dưới lên, mắt tắt sau cùng). Dựng trên canvas phụ ở độ phân giải màn hình.
let _gpDemCv=null;
function _gpDrawDemon(k,x,yB,h,alpha,dis,lt,eyeBoost){
  const im=SC_DEMON_IMG; if(!(im.complete&&im.naturalWidth)) return;
  const FW=SC_DEMON_FW, FH=SC_DEMON_FH, w=h*FW/FH, Z=_gpZ();
  const ow=Math.max(8,Math.min(1600,Math.ceil(w*Z))), oh=Math.max(8,Math.ceil(ow*h/w));
  if(!_gpDemCv) _gpDemCv=document.createElement('canvas');
  const c=_gpDemCv, key=k+'|'+Math.round(dis*60)+'|'+(lt>>1)+'|'+ow+'x'+oh;
  if(c._key!==key){ c._key=key;
  if(c.width!==ow||c.height!==oh){ c.width=ow; c.height=oh; }
  const g=c.getContext('2d'); g.setTransform(1,0,0,1,0,0); g.globalAlpha=1; g.globalCompositeOperation='source-over'; g.clearRect(0,0,ow,oh);
  g.drawImage(im,k*FW,0,FW,FH,0,0,ow,oh);
  g.globalCompositeOperation='source-atop';
  const lg=g.createLinearGradient(0,0,0,oh);
  lg.addColorStop(0,'rgba(96,108,146,0.62)'); lg.addColorStop(0.35,'rgba(40,44,68,0.62)'); lg.addColorStop(1,'rgba(10,10,18,0.8)');
  g.fillStyle=lg; g.fillRect(0,0,ow,oh);
  for(let i=0;i<16;i++){   // vân khói / nếp áo choàng loang lổ
    const px=_gpH(i+1)*ow, py=_gpH(i+40)*oh*0.85+Math.sin(lt*0.02+i)*oh*0.01, r=ow*(0.1+0.12*_gpH(i+80));
    g.globalAlpha=0.36; g.save(); g.translate(px,py); g.rotate(i+lt*0.004); g.drawImage(_gpSmoke(i,i%3?GP_C.soul:'#8a96bc'),-r,-r,2*r,2*r); g.restore(); }
  g.globalAlpha=1; g.globalCompositeOperation='destination-in';
  const f0=Math.max(0,Math.min(0.98,0.55-0.7*dis)), f1=Math.max(f0+0.02,Math.min(1,0.93-0.7*dis));
  const top=1-_gpSS(0.55,1,dis);
  const mg=g.createLinearGradient(0,0,0,oh);
  mg.addColorStop(0,`rgba(0,0,0,${top})`); mg.addColorStop(f0,`rgba(0,0,0,${top})`); mg.addColorStop(f1,'rgba(0,0,0,0)'); mg.addColorStop(1,'rgba(0,0,0,0)');
  g.fillStyle=mg; g.fillRect(0,0,ow,oh);
  g.globalCompositeOperation='destination-out';   // đục mép dưới tả tơi bằng chính khói
  for(let i=0;i<14;i++){ const px=_gpH(i+200)*ow, py=oh*(f0+(f1-f0+0.1)*_gpH(i+230)), r=ow*(0.06+0.07*_gpH(i+260));
    g.globalAlpha=0.75; g.save(); g.translate(px,py); g.rotate(lt*0.012+i); g.drawImage(_gpSmokeSprites()[i%6],-r,-r,2*r,2*r); g.restore(); }
  g.globalAlpha=1; g.globalCompositeOperation='source-over';
  }
  ctx.save(); ctx.globalAlpha=alpha*(1-dis);   // sương lạnh xanh xám toả sau lưng cho tách khỏi nền tối
  const hz=ctx.createRadialGradient(x,yB-h*0.55,0,x,yB-h*0.55,h*0.6);
  hz.addColorStop(0,'rgba(110,125,170,0.32)'); hz.addColorStop(1,'rgba(110,125,170,0)');
  ctx.fillStyle=hz; ctx.fillRect(x-h*0.6,yB-h*1.15,h*1.2,h*1.2); ctx.restore();
  ctx.save(); ctx.globalAlpha=alpha;
  ctx.drawImage(c, x-w/2, yB-h, w, h);
  ctx.restore();
  const ea=alpha*(1-_gpSS(0.6,1,dis));
  if(ea>0.01){
    const e=_gpRedMask(im);
    ctx.save(); ctx.globalAlpha=ea;
    ctx.drawImage(e,k*FW,0,FW,FH,x-w/2,yB-h,w,h);
    ctx.globalCompositeOperation='lighter'; ctx.drawImage(e,k*FW,0,FW,FH,x-w/2,yB-h,w,h);
    ctx.restore();
    for(const [ex,ey] of _gpEyeCenters(im,k*FW,0,FW,FH))
      _gpEyeGlow(x-w/2+ex*w, yB-h+ey*h, h*0.075*(1+0.15*Math.sin(lt*0.2))*(eyeBoost||1), ea);
  }
}
// khói cuồn cuộn quanh chân + làn khói mảnh cuộn lên hai bên như vạt áo choàng rách
function _gpDemonSmoke(x,yB,h,lt,a,front){
  if(a<=0) return;
  for(let i=0;i<40;i++){ if((i%3===0)!==front) continue;
    const sp=0.004+0.005*_gpH(i+300), ph=(lt*sp+_gpH(i+310))%1;
    const bx=x+(_gpH(i+320)-0.5)*h*0.6, by=yB-h*0.04-_gpH(i+330)*h*0.34;
    const X=bx+(_gpH(i+320)-0.5)*h*0.55*ph+Math.sin(lt*0.02+i)*h*0.03, Y=by-ph*h*0.2;
    _gpSoul(i,X,Y,h*(0.08+0.13*ph+0.05*_gpH(i+340)),lt*0.006*(i%2?1:-1)+i,a*Math.sin(ph*Math.PI)*0.75);
  }
  if(!front) for(let t=0;t<5;t++){ const side=t%2?1:-1;
    for(let j=0;j<10;j++){ const q=j/10, ph=(lt*0.009+t*0.21+q*0.3)%1;
      const X=x+side*h*(0.18+0.16*q)+Math.sin(lt*0.03+j*0.6+t)*h*0.07, Y=yB-h*(0.15+0.6*ph);
      _gpPuff(j+t*9,GP_C.soul,X,Y,h*(0.05+0.035*q),lt*0.01+j,a*0.3*Math.sin(ph*Math.PI)); } }
}

// 🐌 vẽ 1 meme y như trong trận: cạnh dài = 2·size, cắt sát (_crop), viền màu dựng ở ĐỘ PHÂN GIẢI MÀN HÌNH
//    (viền cache ở cỡ gốc rồi bị zoom 2.5× sẽ vỡ răng cưa — đúng lỗi "viền vỡ").
function _gpSticker(img,x,y,s,o){
  o=o||{};
  if(img._crop===undefined) img._crop=computeCropBox(img)||null;
  const src=_stickerMask(img), c=img._crop||{sx:0,sy:0,sw:src.width,sh:src.height}, asp=c.sw/c.sh;
  let dw,dh; if(asp>=1){dw=s*2;dh=dw/asp;}else{dh=s*2;dw=dh*asp;}
  ctx.save(); ctx.globalAlpha*=(o.alpha==null?1:o.alpha);
  ctx.translate(x,y); ctx.rotate(o.rot||0); ctx.scale((o.flip?-1:1)*(o.sx||1), o.sy||1);
  if(o.ol){ const Z=Math.max(1,Math.round(_gpZ()*4)/4);
    ctx.save(); ctx.scale(1/Z,1/Z); ctx.shadowColor=o.ol; ctx.shadowBlur=(o.glow||4)*Z/2;
    _drawStickerOutline(img,c.sx,c.sy,c.sw,c.sh,dw*Z,dh*Z,(o.olW||Math.max(1.2,s*0.036))*Z,o.ol); ctx.restore(); }
  ctx.drawImage(src,c.sx,c.sy,c.sw,c.sh,-dw/2,-dh/2,dw,dh);
  if(o.tint>0){ ctx.globalAlpha*=o.tint; ctx.drawImage(_scEvilTint(img),c.sx,c.sy,c.sw,c.sh,-dw/2,-dh/2,dw,dh); }
  if(o.eyes>0){   // mắt đỏ phát sáng (Evil Gary)
    const m=_gpRedMask(img); ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=o.eyes;
    ctx.drawImage(m,c.sx,c.sy,c.sw,c.sh,-dw/2,-dh/2,dw,dh); ctx.restore();
    for(const [ex,ey] of _gpEyeCenters(img,c.sx,c.sy,c.sw,c.sh)) _gpEyeGlow(-dw/2+ex*dw,-dh/2+ey*dh,s*0.2*o.eyes,o.eyes);
  }
  ctx.restore(); return {dw,dh};
}
// kích thước vẽ (dw,dh) của 1 ảnh theo luật trong trận (cạnh dài = 2·size, cắt sát)
function _gpDims(img,s){
  if(img._crop===undefined) img._crop=computeCropBox(img)||null;
  const c=img._crop||{sw:img.naturalWidth||1,sh:img.naturalHeight||1}, asp=c.sw/c.sh;
  return asp>=1 ? [s*2,s*2/asp] : [s*2*asp,s*2];
}
// ❤️ thanh máu + 🍳 icon chảo y như trong trận (cùng công thức cỡ/vị trí với Fighter.draw và _cnDrawOver)
function _gpHpBar(x,y,s,alpha){
  if(alpha<=0.01) return;
  const bw=s*3.12, bh=9, bx=x-bw/2, by=y-s-22, br=bh/2, fw=bw*GP_HP_FRAC;
  ctx.save(); ctx.globalAlpha*=alpha;
  ctx.fillStyle='#1a1a2a'; ctx.beginPath(); ctx.roundRect(bx-1,by-1,bw+2,bh+2,br+1); ctx.fill();
  ctx.fillStyle='#2a2a3a'; ctx.beginPath(); ctx.roundRect(bx,by,bw,bh,br); ctx.fill();
  ctx.fillStyle='#f59e0b'; ctx.beginPath(); ctx.roundRect(bx,by,fw,bh,br); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.18)'; ctx.beginPath(); ctx.roundRect(bx+2,by+1,Math.max(0,fw-4),Math.floor(bh*0.4),2); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.6)'; ctx.lineWidth=1; ctx.beginPath(); ctx.roundRect(bx-1,by-1,bw+2,bh+2,br+1); ctx.stroke();
  ctx.font='bold 8.4px "Press Start 2P",monospace'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.lineJoin='round'; ctx.strokeStyle='rgba(0,0,0,0.85)'; ctx.lineWidth=2.5;
  ctx.strokeText(GP_HP,x,by+bh/2+0.5); ctx.fillStyle='#fff'; ctx.fillText(GP_HP,x,by+bh/2+0.5);
  const sp=_emojiSprite('🍳',64);
  if(sp){ const d=s*0.7, ix=x-d/2, iy=y-s*1.75-d/2, n=3;
    ctx.globalAlpha=alpha*0.25; ctx.drawImage(sp,ix,iy,d,d); ctx.globalAlpha=alpha;
    const fh=d*n/CN_UNLOCK_HITS; ctx.beginPath(); ctx.rect(ix,iy+d-fh,d,fh); ctx.clip(); ctx.drawImage(sp,ix,iy,d,d); }
  ctx.restore();
}

// 🕯️ NGHI THỨC: ngôi sao 5 cánh + vòng tròn vẽ dần bằng CÁT VÀNG CHÁY RỰC trên sàn (phối cảnh nằm nghiêng), sàn quanh
//    đó sẫm lại như đất; vòng NẾN TEALIGHT hiện ra và thắp lần lượt. prog 0→1 = vẽ tới đâu, lit 0→1 = thắp tới cây nào,
//    fl = loé sáng (lúc nổ). part: 'floor' (sàn + sao + nến phía sau) | 'front' (nến phía trước, đè lên nhân vật).
const GP_CANDLES=12;
function _gpCandlePos(i,cx,fy,Rc){ const an=-Math.PI/2+i/GP_CANDLES*Math.PI*2+0.13; return [cx+Math.cos(an)*Rc, fy+Math.sin(an)*Rc*0.5]; }
function _gpCandle(x,y,c,lit,lt,i,al,fl){
  ctx.save(); ctx.globalAlpha*=al;
  const fk=0.85+0.15*Math.sin(lt*0.5+i*1.7)*Math.sin(lt*0.23+i);
  if(lit>0){   // quầng sáng ấm hắt xuống sàn
    ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.translate(x,y); ctx.scale(1,0.5);
    const R=c*(3.2+1.5*fl)*fk, g=ctx.createRadialGradient(0,0,0,0,0,R);
    g.addColorStop(0,`rgba(255,170,70,${0.42*lit})`); g.addColorStop(0.4,`rgba(230,110,30,${0.16*lit})`); g.addColorStop(1,'rgba(160,60,0,0)');
    ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.fill(); ctx.restore(); }
  const w=c*1.15, h=c*0.6, ry=w*0.26;
  let g=ctx.createLinearGradient(x-w/2,0,x+w/2,0);            // thân nến sáp kem, tối dần hai bên
  g.addColorStop(0,'#b58f55'); g.addColorStop(0.35,'#f4e3bb'); g.addColorStop(0.7,'#e9cf98'); g.addColorStop(1,'#a3793f');
  ctx.fillStyle=g; ctx.beginPath(); ctx.moveTo(x-w/2,y-h); ctx.lineTo(x-w/2,y); ctx.ellipse(x,y,w/2,ry,0,Math.PI,0,true); ctx.lineTo(x+w/2,y-h); ctx.closePath(); ctx.fill();
  ctx.fillStyle='rgba(60,40,20,0.55)'; ctx.fillRect(x-w/2,y-h*0.32,w,h*0.07);   // vành cốc
  ctx.fillStyle='#fff3d2'; ctx.beginPath(); ctx.ellipse(x,y-h,w/2,ry,0,0,Math.PI*2); ctx.fill();
  if(lit>0){ ctx.save(); ctx.globalCompositeOperation='lighter';   // sáp sáng rực quanh bấc
    const gg=ctx.createRadialGradient(x,y-h,0,x,y-h,w/2); gg.addColorStop(0,`rgba(255,200,110,${0.7*lit})`); gg.addColorStop(1,'rgba(255,150,40,0)');
    ctx.fillStyle=gg; ctx.beginPath(); ctx.ellipse(x,y-h,w/2,ry,0,0,Math.PI*2); ctx.fill(); ctx.restore(); }
  ctx.strokeStyle='#2a1a0e'; ctx.lineWidth=Math.max(0.5,c*0.05); ctx.beginPath(); ctx.moveTo(x,y-h); ctx.lineTo(x,y-h-c*0.14); ctx.stroke();
  if(lit>0){   // ngọn lửa lung linh
    const fh=c*(0.75+0.35*fl)*fk*lit, fw=c*0.2, sw=Math.sin(lt*0.3+i)*fw*0.3, by=y-h-c*0.08;
    ctx.save(); ctx.globalCompositeOperation='lighter';
    let hg=ctx.createRadialGradient(x,by-fh*0.45,0,x,by-fh*0.45,fh*1.4); hg.addColorStop(0,`rgba(255,200,110,${0.5*lit})`); hg.addColorStop(1,'rgba(255,140,40,0)');
    ctx.fillStyle=hg; ctx.fillRect(x-fh*1.4,by-fh*1.85,fh*2.8,fh*2.8);
    const fg=ctx.createLinearGradient(x,by,x,by-fh); fg.addColorStop(0,`rgba(255,120,30,${0.9*lit})`); fg.addColorStop(0.35,`rgba(255,220,120,${lit})`); fg.addColorStop(1,'rgba(255,250,230,0)');
    ctx.fillStyle=fg; ctx.beginPath(); ctx.moveTo(x-fw,by); ctx.quadraticCurveTo(x-fw*1.1,by-fh*0.45,x+sw,by-fh); ctx.quadraticCurveTo(x+fw*1.1,by-fh*0.45,x+fw,by);
    ctx.quadraticCurveTo(x,by+fw*0.8,x-fw,by); ctx.fill();
    ctx.fillStyle=`rgba(255,255,245,${0.9*lit})`; ctx.beginPath(); ctx.ellipse(x+sw*0.3,by-fh*0.3,fw*0.35,fh*0.22,0,0,Math.PI*2); ctx.fill();
    ctx.restore(); }
  ctx.restore();
}
function _gpRitual(cx,fy,s,prog,lit,lt,part,fl){
  const Rs=s*1.75, Rc=s*2.35, c=s*0.3;
  if(part==='floor'){
    const ga=_gpSS(0,0.25,prog);
    if(ga>0){ ctx.save(); ctx.translate(cx,fy); ctx.scale(1,0.5);   // đất sẫm quanh vòng nghi thức
      const g=ctx.createRadialGradient(0,0,0,0,0,Rc*1.5); g.addColorStop(0,`rgba(26,16,10,${0.8*ga})`); g.addColorStop(0.7,`rgba(20,12,8,${0.6*ga})`); g.addColorStop(1,'rgba(20,12,8,0)');
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,Rc*1.5,0,Math.PI*2); ctx.fill(); ctx.restore(); }
    // ngôi sao + vòng tròn vẽ dần
    const P=[]; for(let k=0;k<5;k++){ const an=-Math.PI/2+k*Math.PI*2/5; P.push([Math.cos(an)*Rs,Math.sin(an)*Rs]); }
    const order=[0,2,4,1,3,0], segs=[];
    const cp=_gpSS(0,0.35,prog); if(cp>0) segs.push(['arc',cp]);
    for(let k=0;k<5;k++){ const q=Math.max(0,Math.min(1,(prog-0.35-k*0.13)/0.13)); if(q>0) segs.push(['ln',q,P[order[k]],P[order[k+1]]]); }
    if(segs.length){
      ctx.save(); ctx.translate(cx,fy); ctx.scale(1,0.5); ctx.globalCompositeOperation='lighter'; ctx.lineCap='round'; ctx.lineJoin='round';
      const path=()=>{ ctx.beginPath(); for(const sg of segs){
        if(sg[0]==='arc'){ ctx.moveTo(0,-Rs*0.92); ctx.arc(0,0,Rs*0.92,-Math.PI/2,-Math.PI/2+Math.PI*2*sg[1]); }
        else { const [,q,a,b]=sg; ctx.moveTo(a[0]*1.08,a[1]*1.08); ctx.lineTo(a[0]*1.08+(b[0]-a[0])*1.08*q, a[1]*1.08+(b[1]-a[1])*1.08*q); } } };
      const pu=0.85+0.15*Math.sin(lt*0.08)+0.6*fl;
      for(const [lw,col] of [[s*0.26,`rgba(255,120,30,${0.16*pu})`],[s*0.11,`rgba(255,160,60,${0.4*pu})`],[s*0.045,`rgba(255,215,130,${0.85*pu})`],[s*0.016,`rgba(255,250,225,${Math.min(1,0.95*pu)})`]]){
        ctx.strokeStyle=col; ctx.lineWidth=lw; path(); ctx.stroke(); }
      // hạt cát lấp lánh rải dọc nét vẽ
      for(const sg of segs){ const n=sg[0]==='arc'?60:26;
        for(let j=0;j<n;j++){ const f=j/n*sg[1], hh=_gpH(j*3+(sg[0]==='arc'?7:sg[2][0]|0)+2100); let X,Y;
          if(sg[0]==='arc'){ const an=-Math.PI/2+Math.PI*2*f; X=Math.cos(an)*Rs*0.92; Y=Math.sin(an)*Rs*0.92; }
          else { const [,,a,b]=sg; X=(a[0]+(b[0]-a[0])*f)*1.08; Y=(a[1]+(b[1]-a[1])*f)*1.08; }
          X+=(hh-0.5)*s*0.12; Y+=(_gpH(j+2200)-0.5)*s*0.12;
          ctx.fillStyle=`rgba(255,230,160,${(0.35+0.5*Math.abs(Math.sin(lt*0.1+j)))*pu*0.7})`; ctx.fillRect(X,Y,s*0.03,s*0.03); } }
      ctx.restore();
    }
  }
  for(let i=0;i<GP_CANDLES;i++){
    const [x,y]=_gpCandlePos(i,cx,fy,Rc), front=y>fy;
    if((part==='front')!==front) continue;
    const al=_gpSS(i/GP_CANDLES*0.5,i/GP_CANDLES*0.5+0.12,prog), li=_gpSS(i/GP_CANDLES,i/GP_CANDLES+0.06,lit);
    if(al>0) _gpCandle(x,y,c,li,lt,i,al,fl);
  }
}
// ⚫ KHỐI CẦU HẮC ÁM: lõi đen sâu, khói linh hồn cuộn xoáy bên trong, viền sáng lạnh; q>0 = đỏ ngầu âm ỉ sắp vỡ
function _gpSphere(cx,cy,R,a,lt,q){
  if(a<=0) return;
  ctx.save(); ctx.globalAlpha*=a;
  let g=ctx.createRadialGradient(cx-R*0.25,cy-R*0.3,R*0.05,cx,cy,R);
  g.addColorStop(0,'#1c1230'); g.addColorStop(0.5,'#08050f'); g.addColorStop(1,'#010003');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.fill();
  ctx.save(); ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.clip();
  for(let i=0;i<18;i++){ const rr=R*(0.15+0.8*_gpH(i+900)), an=_gpH(i+910)*6.28+lt*(0.025+0.035*_gpH(i+920))*(i%2?1:-1);
    _gpPuff(i,i%3?GP_C.soul:GP_C.haze,cx+Math.cos(an)*rr,cy+Math.sin(an)*rr*0.85,R*(0.35+0.25*_gpH(i+930)),an*1.5,0.22); }
  if(q>0){ ctx.globalCompositeOperation='lighter'; const pu=0.6+0.4*Math.sin(lt*(0.25+0.7*q));
    g=ctx.createRadialGradient(cx,cy,0,cx,cy,R); g.addColorStop(0,`rgba(255,50,30,${0.55*q*pu})`); g.addColorStop(0.55,`rgba(160,0,20,${0.25*q*pu})`); g.addColorStop(1,'rgba(80,0,0,0)');
    ctx.fillStyle=g; ctx.fillRect(cx-R,cy-R,2*R,2*R); }
  ctx.restore();
  ctx.globalCompositeOperation='lighter';
  g=ctx.createRadialGradient(cx,cy,R*0.74,cx,cy,R); g.addColorStop(0,'rgba(90,80,150,0)'); g.addColorStop(1,'rgba(125,115,200,0.4)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.fill();
  g=ctx.createRadialGradient(cx-R*0.38,cy-R*0.42,0,cx-R*0.38,cy-R*0.42,R*0.42); g.addColorStop(0,'rgba(210,200,255,0.18)'); g.addColorStop(1,'rgba(210,200,255,0)');
  ctx.fillStyle=g; ctx.fillRect(cx-R,cy-R,R*2,R*2);
  ctx.restore();
}
function _gpCrackPts(i,cx,cy,R){
  let a=_gpH(i+950)*6.283, r=R*0.1*_gpH(i+951), x=cx+Math.cos(a)*r, y=cy+Math.sin(a)*r; const pts=[[x,y]];
  for(let j=1;j<=9;j++){ a+=(_gpH(i*17+j+960)-0.5)*1.1; const st=R*(0.1+0.07*_gpH(i*13+j+970)); x+=Math.cos(a)*st; y+=Math.sin(a)*st; pts.push([x,y]);
    if(Math.hypot(x-cx,y-cy)>R*1.05) break; }
  return pts;
}
// vết nứt đỏ rực lan dần (3 lớp: quầng đỏ / đỏ cam / lõi trắng nóng) + tia sáng rò qua khe nứt lúc sắp vỡ
function _gpCracks(cx,cy,R,q,lt){
  if(q<=0) return; const Z=_gpZ();
  ctx.save(); ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.clip();
  ctx.globalCompositeOperation='lighter'; ctx.lineCap='round'; ctx.lineJoin='round';
  for(let i=0;i<12;i++){ const cp=_gpSS(i*0.05,0.5+i*0.04,q); if(cp<=0) continue;
    const pts=_gpCrackPts(i,cx,cy,R), n=Math.max(2,Math.ceil(pts.length*cp));
    for(const [lw,col] of [[R*0.2,'rgba(255,20,20,0.1)'],[R*0.12,'rgba(255,30,20,0.18)'],[R*0.07,'rgba(255,30,20,0.35)'],[R*0.03,'rgba(255,110,50,0.9)'],[R*0.011,'rgba(255,245,225,1)']]){
      ctx.strokeStyle=col; ctx.lineWidth=lw; ctx.beginPath();
      for(let j=0;j<n;j++){ const p=pts[j]; j?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]); } ctx.stroke(); }
  }
  ctx.restore();
  const lk=_gpSS(0.55,1,q); if(lk<=0) return;
  ctx.save(); ctx.globalCompositeOperation='lighter';
  for(let i=0;i<12;i++){ const pts=_gpCrackPts(i,cx,cy,R), p=pts[pts.length-1], an=Math.atan2(p[1]-cy,p[0]-cx), L=R*(0.8+1.2*_gpH(i+990))*lk, w=0.07;
    const g=ctx.createLinearGradient(cx,cy,cx+Math.cos(an)*(R+L),cy+Math.sin(an)*(R+L));
    g.addColorStop(0,'rgba(255,60,40,0)'); g.addColorStop(R/(R+L),`rgba(255,70,50,${0.4*lk})`); g.addColorStop(1,'rgba(255,0,0,0)');
    ctx.fillStyle=g; ctx.beginPath(); ctx.moveTo(cx,cy);
    ctx.lineTo(cx+Math.cos(an-w)*(R+L),cy+Math.sin(an-w)*(R+L)); ctx.lineTo(cx+Math.cos(an+w)*(R+L),cy+Math.sin(an+w)*(R+L)); ctx.closePath(); ctx.fill(); }
  ctx.restore();
}
// mảnh vỡ: 12 múi ngoài + 12 mảnh trong, mép gấp khúc (toạ độ quanh tâm cầu)
function _gpShards(R){
  if(_gpShards._R===R) return _gpShards._c;
  const N=12, A=[], out=[];
  for(let i=0;i<N;i++) A.push((i+(_gpH(i+1000)-0.5)*0.5)/N*6.283); A.push(A[0]+6.283);
  const mid=i=>R*(0.42+0.22*_gpH((i%N)+1010));
  for(let i=0;i<N;i++){
    const a0=A[i], a1=A[i+1], m0=mid(i), m1=mid(i+1), am=(a0+a1)/2, mm=(m0+m1)/2*(0.85+0.2*_gpH(i+1020));
    const outer=[]; for(let j=0;j<=6;j++){ const a=a0+(a1-a0)*j/6; outer.push([Math.cos(a)*R,Math.sin(a)*R]); }
    outer.push([Math.cos(a1)*m1,Math.sin(a1)*m1],[Math.cos(am)*mm,Math.sin(am)*mm],[Math.cos(a0)*m0,Math.sin(a0)*m0]);
    const inner=[[Math.cos(am)*R*0.06,Math.sin(am)*R*0.06],[Math.cos(a0)*m0,Math.sin(a0)*m0],[Math.cos(am)*mm,Math.sin(am)*mm],[Math.cos(a1)*m1,Math.sin(a1)*m1]];
    for(const [poly,isOut,id] of [[outer,true,i],[inner,false,i+N]]){
      const ctr=poly.reduce((s,p)=>[s[0]+p[0]/poly.length,s[1]+p[1]/poly.length],[0,0]);
      out.push({poly,ctr,am,isOut,id});
    }
  }
  _gpShards._R=R; _gpShards._c=out; return out;
}
// 😈 thân nhuộm tím-đen u ám (Gary đang bị chiếm xác) — cache 1 lần/ảnh
function _scEvilTint(img){
  if(img._scEvil) return img._scEvil;
  const src=_stickerMask(img);
  const c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const g=c.getContext('2d'); g.drawImage(src,0,0);
  g.globalCompositeOperation='source-atop'; g.fillStyle='rgba(22,6,34,0.88)'; g.fillRect(0,0,c.width,c.height);
  img._scEvil=c; return c;
}
function _scDrawDemonFrame(k, x, yBottom, hDraw, alpha, sc){
  const im=SC_DEMON_IMG; if(!(im.complete && im.naturalWidth>0)) return false;
  const h=hDraw*sc, w=h*SC_DEMON_FW/SC_DEMON_FH;
  ctx.save(); ctx.globalAlpha=Math.max(0,alpha);
  ctx.drawImage(im, k*SC_DEMON_FW,0,SC_DEMON_FW,SC_DEMON_FH, x-w/2, yBottom-h, w, h);
  ctx.restore(); return true;
}
// 👿 (dự phòng lúc ảnh chưa nạp) bóng quỷ vẽ tay cho khối "Quỷ trỗi dậy": thân đen có sừng + viền đỏ âm ỉ, 2 mắt đỏ, đôi cánh dơi.
//    wing 0→1 = cánh từ khép sát lưng tới bung hết cỡ. sc = thu nhỏ khi bay xa.
function _scDrawDemon(x, y, h, wing, eyeOn, alpha, sc){
  ctx.save(); ctx.translate(x,y); ctx.scale(sc,sc); ctx.globalAlpha=Math.max(0,alpha);
  const w=h*0.62;
  // đôi cánh (vẽ trước, nằm sau thân)
  if(wing>0.01){
    for(const sd of [-1,1]){
      ctx.save(); ctx.scale(sd,1);
      ctx.translate(w*0.28,-h*0.12);
      ctx.rotate(-0.9+0.9*wing); ctx.scale(0.25+0.75*wing, 0.4+0.6*wing);
      const L=h*1.25;
      ctx.beginPath(); ctx.moveTo(0,0);
      ctx.quadraticCurveTo(L*0.45,-h*0.62, L,-h*0.42);                  // mép trên cánh
      ctx.lineTo(L*0.92,h*0.02); ctx.quadraticCurveTo(L*0.8,-h*0.08, L*0.7,h*0.12);   // 3 móng cánh
      ctx.quadraticCurveTo(L*0.55,-h*0.02, L*0.42,h*0.2); ctx.quadraticCurveTo(L*0.28,h*0.02, L*0.12,h*0.22);
      ctx.closePath();
      ctx.fillStyle='#050005'; ctx.fill();
      ctx.lineWidth=Math.max(1,h*0.018); ctx.strokeStyle='rgba(183,28,28,0.85)'; ctx.stroke();
      ctx.restore();
    }
  }
  // thân + đầu có sừng
  ctx.beginPath();
  ctx.moveTo(-w*0.5,h*0.5); ctx.quadraticCurveTo(-w*0.62,-h*0.05,-w*0.3,-h*0.18);   // vai trái
  ctx.lineTo(-w*0.3,-h*0.38); ctx.lineTo(-w*0.42,-h*0.72); ctx.lineTo(-w*0.14,-h*0.47);   // sừng trái
  ctx.quadraticCurveTo(0,-h*0.56, w*0.14,-h*0.47); ctx.lineTo(w*0.42,-h*0.72); ctx.lineTo(w*0.3,-h*0.38);  // sừng phải
  ctx.lineTo(w*0.3,-h*0.18); ctx.quadraticCurveTo(w*0.62,-h*0.05, w*0.5,h*0.5); ctx.closePath();
  ctx.fillStyle='#030003'; ctx.fill();
  ctx.lineWidth=Math.max(1,h*0.02); ctx.strokeStyle='rgba(255,23,68,0.7)'; ctx.stroke();
  // mắt đỏ
  if(eyeOn){
    ctx.globalCompositeOperation='lighter';
    for(const sd of [-1,1]){ const ex=sd*w*0.13, ey=-h*0.33;
      const g=ctx.createRadialGradient(ex,ey,0,ex,ey,h*0.09); g.addColorStop(0,'rgba(255,90,90,1)'); g.addColorStop(1,'rgba(255,0,0,0)');
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(ex,ey,h*0.09,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#ffebee'; ctx.beginPath(); ctx.ellipse(ex,ey,h*0.035,h*0.015,sd*0.35,0,Math.PI*2); ctx.fill(); }
  }
  ctx.restore();
}
// 💥 mảnh vỡ cho khối "Quỷ trỗi dậy": cắt lưới avatar Evil Larry + Gary thành mảnh (y cách game cắt mảnh lúc meme chết).
//    Larry đứng bên trái, Gary bên phải — như vừa hết trận 1vs1 giữa 2 con. Ảnh chưa nạp xong thì báo pending để dựng lại.
function _scBuildLarryShards(){
  const out={ list:[], pending:null }; const waits=[];
  const srcs=[['evillarry',0.3,0.6],['gary',0.7,0.45]];
  let si=0;
  for(const [key,px,py] of srcs){
    const r=roster.find(x=>x && x.charKey===key); if(!r || !r.avatarUrl) continue;
    const im=_scImgCache[r.avatarUrl] || (()=>{ const i=new Image(); i.src=r.avatarUrl; _scImgCache[r.avatarUrl]=i; return i; })();
    if(!(im.complete && im.naturalWidth>0)){ waits.push(im); continue; }
    const d=W*0.22, asp=im.naturalWidth/im.naturalHeight;
    const sheet=_buildShardSheet({img:im, sx:0, sy:0, sw:im.naturalWidth, sh:im.naturalHeight, dw:asp>=1?d:d*asp, dh:asp>=1?d/asp:d});
    if(!sheet) continue;
    const G=_SHARD_GRID, cw=sheet.width/G, ch=sheet.height/G;
    for(let rr=0;rr<G;rr++) for(let cc=0;cc<G;cc++){
      const _cx=Math.floor(cc*cw), _cy=Math.floor(rr*ch), _cw=Math.ceil(cw), _ch=Math.ceil(ch);
      if(!_shardCellHasInk(sheet,_cx,_cy,_cw,_ch)) continue;
      const n=out.list.length;
      out.list.push({ img:sheet, sx:_cx, sy:_cy, sw:_cw, sh:_ch,
        x0:W*px+(cc+0.5)*cw-sheet.width/2, y0:H*py+(rr+0.5)*ch-sheet.height/2,
        dl:_scSeed(n+si*97,3)*0.35, rot:(_scSeed(n,5)-0.5)*0.6, spin:(_scSeed(n,6)-0.5)*9 });
    }
    si++;
  }
  if(waits.length) out.pending=()=>waits.some(i=>i.complete && i.naturalWidth>0);
  return out;
}
// ⛧ bake NGÔI SAO VỆT MÁU của Evil Larry ra 1 bitmap cỡ sàn — nét y hệt _elStamp() trong trận (đỏ thẫm dày có quầng
//    + lõi đỏ tươi chạy giữa), đi đúng đường _elBuildPath() mà Larry bò theo.
function _scBakeLarryStar(lsz){
  const cv=document.createElement('canvas'); cv.width=Math.ceil(W*_ARENA_SS); cv.height=Math.ceil(H*_ARENA_SS);
  const g=cv.getContext('2d'); g.scale(_ARENA_SS,_ARENA_SS); g.lineJoin='round'; g.lineCap='round';
  const P=_elBuildPath(lsz), w=Math.max(6, lsz*0.62);
  const path=()=>{ g.beginPath(); g.moveTo(P[0].x,P[0].y); for(let i=1;i<P.length;i++) g.lineTo(P[i].x,P[i].y); };
  g.shadowColor='#5b0000'; g.shadowBlur=w*0.42; g.strokeStyle='#5b0000'; g.lineWidth=w; path(); g.stroke();
  g.shadowBlur=0; g.strokeStyle='#c62828'; g.lineWidth=w*0.42; path(); g.stroke();
  return cv;
}
function _scFillAll(){ ctx.fillRect(-W, -H*1.5, W*3, H*4); }
function _scPaintBg(kind, vw, vh){
  ctx.fillStyle = (kind==='arena') ? PAPER_BG : '#000000';
  ctx.fillRect(0,0,vw,vh);
  if(kind==='blackhole' && BLACKHOLE_IMG.complete && BLACKHOLE_IMG.naturalWidth){
    // khung ăn theo _scT nên tua tới đâu ra đúng khung đó — quay lại nhiều lần vẫn khớp nhau
    const _bhI=((Math.floor(_scT/BH_LOOP_TICKS*BH_N)%BH_N)+BH_N)%BH_N;
    const _bhSx=(_bhI%BH_COLS)*BH_FW, _bhSy=Math.floor(_bhI/BH_COLS)*BH_FH;
    // phủ KÍN khung (cover) rồi cắt bớt 2 mép — tâm hố đen nằm giữa ảnh nên không mất gì
    const _bhK=Math.max(vw/BH_FW, vh/BH_FH);
    const _bhW=BH_FW*_bhK, _bhH=BH_FH*_bhK;
    ctx.drawImage(BLACKHOLE_IMG, _bhSx,_bhSy,BH_FW,BH_FH, (vw-_bhW)/2,(vh-_bhH)/2,_bhW,_bhH);
  }
}
// nền đang hiệu lực tại tick t: {tu, toi, mix} — mix 0→1 là đang mờ chồng từ nền cũ sang nền mới
function _scBgAt(t){
  const cs=SCENE.clips.filter(c=>c.type==='bg' && c.t0<=t).sort((m,n)=>m.t0-n.t0);
  let tu=SCENE.bg||'arena', toi=tu, mix=1;
  for(const c of cs){
    tu=toi; toi=c.p.kind||'black';
    const f=Math.max(1, c.p.fade|0);
    mix=Math.min(1,(t-c.t0)/f);
  }
  return {tu, toi, mix};
}

// ===================== VẼ 1 KHUNG HÌNH =====================
// 🗣️ tiếng quỷ xì xầm nhỏ (mẫu larry_whisper của Evil Larry) chạy nền, lặp, CHỈ khi đang phát phim và có khối
//    'Quỷ trỗi dậy' đang chiếu. Hết khối / dừng phim / thoát Scene Builder là tắt.
let _scWhisperSfx=null;
let _scLaughSfx=null;   // tiếng cười bóng quỷ — dài hơn phần bay nên phải tắt được khi dừng/thoát
function _scStopLaugh(){ if(_scLaughSfx){ try{ _scLaughSfx.pause(); _scLaughSfx.currentTime=0; }catch(e){} _scLaughSfx=null; } _gpStopSouls(); }
let _gpSoulSfx=null;   // 👻 Gary bị nhập: tiếng linh hồn bị hút (kênh riêng để không cắt tiếng meow đang kêu dở)
function _gpStopSouls(){ if(_gpSoulSfx){ try{ _gpSoulSfx.pause(); _gpSoulSfx.currentTime=0; }catch(e){} _gpSoulSfx=null; } }
function _scStopWhisper(){ if(_scWhisperSfx){ _stopLoopAudio(_scWhisperSfx); _scWhisperSfx=null; } }
function _scSyncWhisper(act){
  const lr=act.find(c=>c.type==='larryrise'), gp=act.find(c=>c.type==='garypossess');
  const gt=gp ? (_scT-gp.t0)/GP_F : -1;   // 😈 Gary bị nhập: xì xầm lúc quỷ còn hiện diện, nền ghê rợn từ lúc cổng mở tới hết
  const on = _scPlaying && (!!lr || (!!gp && gt>=GP_T.portal && gt<GP_T.hit));
  if(on && !_scWhisperSfx){
    const a=AUDIO_SAMPLES['larry_whisper']?.cloneNode();
    if(a){ a.loop=true; a.volume=0.35; _mixRoute(a); a.play().catch(()=>{}); _scWhisperSfx=a; }
  } else if(!on) _scStopWhisper();
  // 🎻 NỀN GHÊ RỢN: bắt đầu đúng lúc zoom vào tâm sao (u=0.22) → chạy nền tới HẾT khối cảnh. Nhỏ đi 30% (mức 0.7).
  const onT = _scPlaying && ((!!lr && (_scT-lr.t0) >= Math.floor(0.22*lr.len)) || (!!gp && gt>=GP_T.portal));
  if(onT && !_scTerrorSfx){
    const a=AUDIO_SAMPLES['sc_terror']?.cloneNode();
    if(a){ a.volume=0.7; _mixRoute(a); a.play().catch(()=>{}); _scTerrorSfx=a; }
  } else if(!onT) _scStopTerror();
}
let _scTerrorSfx=null;
function _scStopTerror(){ if(_scTerrorSfx){ _stopLoopAudio(_scTerrorSfx); _scTerrorSfx=null; } }
function _scRenderFrame(){
  const t=_scT;
  ctx.save(); ctx.setTransform(_ARENA_SS,0,0,_ARENA_SS,0,0);
  const _scVW=_viewW||W, _scVH=_viewH||H;
  const _bg=_scBgAt(t);
  _scPaintBg(_bg.tu, _scVW, _scVH);
  if(_bg.mix<1){ ctx.save(); ctx.globalAlpha=_bg.mix; _scPaintBg(_bg.toi,_scVW,_scVH); ctx.restore(); }
  else _scPaintBg(_bg.toi, _scVW, _scVH);
  ctx.restore();
  updateShake();
  ctx.save();
  ctx.translate((_viewW||W)/2+(screenShake.x||0), (_viewH||H)/2+(screenShake.y||0));
  ctx.translate(-W/2,-H/2);
  const act=SCENE.clips.filter(c=>t>=c.t0 && t<c.t0+c.len).sort((m,n)=>m.lane-n.lane);
  // 🎥 CAMERA CẢNH: khối nào có hàm cam(c,lt,u) thì cả sàn, tường, diễn viên, hiệu ứng đều zoom/lia theo
  for(const c of act){ const B=SC_BLOCKS[c.type]; if(!B||!B.cam) continue;
    const cm=B.cam(c, t-c.t0, (t-c.t0)/c.len); if(!cm) continue;
    ctx.translate(W/2,H/2); ctx.scale(cm.z,cm.z); ctx.translate(-cm.x,-cm.y); break; }   // (x,y) = điểm camera nhìn vào
  if(_bg.toi==='arena') _camDrawArenaEdge();   // nền đen/hố đen thì bỏ luôn khung viền sàn cho sạch
  _scSyncWhisper(act);   // 🗣️ tiếng quỷ xì xầm của Evil Larry chạy nền khi khối 'Quỷ trỗi dậy' đang chiếu
  const run=(cls)=>{ for(const c of act){ const B=SC_BLOCKS[c.type]; if(!B||B.cls!==cls) continue;
    const an=_scClipAnim(c,t);
    ctx.save();
    let bak=null;
    if(an){
      bak={x:c.p.x,y:c.p.y,size:c.p.size,ang:c.p.ang};
      c.p.x=an.x; c.p.y=an.y;
      if(c.p.size!==undefined) c.p.size=an.size;
      if(c.p.ang!==undefined)  c.p.ang=an.ang;
      if(an.alpha<1) ctx.globalAlpha*=Math.max(0,an.alpha);
    }
    try{ B.draw(c, t-c.t0, (t-c.t0)/c.len); }catch(e){}
    if(bak) Object.assign(c.p,bak);
    ctx.restore();
  } };
  run('fl');                                        // lớp SÀN (dưới chân diễn viên)
  for(const a of SCENE.actors) _scDrawActor(a,t);
  run('act');
  run('ov');                                        // lớp TRÊN (hiệu ứng phủ)
  { const o=_scSelObj(); if(o){ _scDrawGuides(); _scDrawBox(o); } }
  ctx.restore();
}
function _scLoopFn(){
  if(!sceneCtx) return;
  if(_scPlaying){
    _scT++;
    if(_scT>=SCENE.dur){ if(_scLoop){ _scT=0; for(const c of SCENE.clips){ c._E=null; c._last=-9; } } else { _scT=SCENE.dur-1; _scPlaying=false; _scSyncTop(); } }
  }
  _scRenderFrame();
  _scMovePlayhead();
  if(_scPlayer && _cinePanelCur) _cinePanelCur.update();
  _scRaf=requestAnimationFrame(_scLoopFn);
}

// ===================== THƯ VIỆN BÊN TRÁI =====================
const SC_TABS=[['meme','Meme'],['prop','Đạo cụ'],['vfx','VFX'],['film','Film'],['preset','Cảnh mẫu']];
function scSetTab(k){
  _scTab=k;
  for(const [id] of SC_TABS){ const el=document.getElementById('scTab_'+id); if(el) el.classList.toggle('on',id===k); }
  _scRenderLib();
}
function _scMkItem(box, html, payload){
  const d=document.createElement('div');
  d.className='sc-item'; d.draggable=true; d.innerHTML=html;
  d.ondragstart=e=>{ e.dataTransfer.setData('text/plain',payload); };
  box.appendChild(d);
  return d;
}
function _scRenderLib(){
  const b=document.getElementById('scLibBody'); if(!b) return;
  b.innerHTML='';
  if(_scTab==='meme'){
    roster.forEach((r,i)=>{
      if(!r || !r.charKey) return;
      const av=r.avatarUrl ? '<img src="'+(window.ASSETS?ASSETS.thumb(r.avatarUrl):r.avatarUrl)+'">' : '<span class="ic">'+((CHAR_DEFS[r.charKey]&&CHAR_DEFS[r.charKey].emoji)||'❓')+'</span>';
      _scMkItem(b, av+'<span>'+(r.name||r.charKey)+'</span>', 'meme:'+i);
    });
    if(!b.children.length) b.innerHTML='<div style="color:#666;font-size:0.62rem">Chưa có meme nào trong roster.</div>';
  } else if(_scTab==='vfx'){
    // 🎞️ kho VFX sprite sheet do chính m upload — thả thẳng 1 cái vào timeline là ra clip đã chọn sẵn tên đó
    vfxLibrary.forEach(v=>{
      const th=v.url ? '<img src="'+v.url+'">' : '<span class="ic">🎞️</span>';
      _scMkItem(b, th+'<span>'+(v.name||'?')+'</span>', 'vfx:'+(v.name||''));
    });
    if(!b.children.length) b.innerHTML='<div style="color:#666;font-size:0.62rem">Kho VFX đang trống. Vào ⚙️ → 🎬 VFX Library để thêm.</div>';
  } else if(_scTab==='prop'){
    for(const k in SC_PROPS){
      const P=SC_PROPS[k];
      const im=_scPropImg(k);
      _scMkItem(b, `<img src="${im?im.src:''}">`+'<span>'+P.name+'</span>', 'prop:'+k);
    }
  } else if(_scTab==='preset'){
    // bấm 1 phát nạp nguyên đoạn — không kéo thả, vì đây là CẢ cảnh chứ không phải 1 khối
    for(const P of SC_PRESETS){
      const d=document.createElement('div');
      d.className='sc-item'; d.style.cursor='pointer'; d.title=P.desc;
      d.innerHTML='<span class="ic">'+P.ic+'</span><span>'+P.name+
        '<br><span style="opacity:.5;font-size:0.55rem;line-height:1.25;display:block;margin-top:2px">'+P.desc+'</span></span>';
      d.onclick=()=>scLoadPreset(P.id);
      b.appendChild(d);
    }
  } else {
    for(const k of (SC_GROUPS[_scTab]||[])){
      const B=SC_BLOCKS[k]; if(!B) continue;
      _scMkItem(b, '<span class="ic">'+B.ic+'</span><span>'+B.name+'</span>', 'blk:'+k);
    }
  }
}

