function scLoadPreset(id){
  const P=SC_PRESETS.find(x=>x.id===id); if(!P) return;
  const coGi = SCENE.actors.length || SCENE.clips.length;
  if(coGi && !confirm('Nạp cảnh mẫu "'+P.name+'" sẽ THAY cảnh đang dựng. Tiếp tục?')) return;
  let n=1; const N=()=>n++;
  const built=P.build(N);
  SCENE={ dur:P.dur, lanes:P.lanes, nid:n, actors:built.actors, clips:built.clips, bg:P.bg };
  _scT=0; _scPlaying=false; _scSel=null;
  for(const c of SCENE.clips){ c._E=null; c._last=-9; }
  _scSyncBgBtn(); _scRenderTimeline(); _scRenderProps(); _scSyncTop(); _scSaveScene();
}

// ===================== TIMELINE =====================
function _scRenderTimeline(){
  const R=document.getElementById('scRuler'), L=document.getElementById('scLanes');
  if(!R||!L) return;
  R.innerHTML=''; L.innerHTML='';
  const wpx=SCENE.dur*SC_PPS;
  for(let s=0;s<=Math.floor(SCENE.dur/SC_FPS);s++){
    const d=document.createElement('div'); d.className='tk'; d.style.left=(s*SC_FPS*SC_PPS)+'px'; d.textContent=s+'s';
    R.appendChild(d);
  }
  R.style.width=wpx+'px';
  for(let ln=0; ln<SCENE.lanes; ln++){
    const row=document.createElement('div'); row.className='sc-lane'; row.style.width=wpx+'px'; row.dataset.lane=ln;
    row.ondragover=e=>{ e.preventDefault(); };
    row.ondrop=e=>{
      e.preventDefault();
      const dt=e.dataTransfer.getData('text/plain')||'';
      const t0=Math.max(0,Math.round((e.offsetX)/SC_PPS));
      if(dt.startsWith('blk:')) scAddClip(dt.slice(4), ln, t0);
      else if(dt.startsWith('vfx:')) scAddClip('vfx', ln, t0, {name:dt.slice(4)});
    };
    for(const c of SCENE.clips.filter(c=>c.lane===ln)){
      const B=SC_BLOCKS[c.type]; if(!B) continue;
      const el=document.createElement('div');
      el.className='sc-clip'+(_scSel&&_scSel.k==='clip'&&_scSel.id===c.id?' sel':'');
      el.style.left=(c.t0*SC_PPS)+'px'; el.style.width=Math.max(18,c.len*SC_PPS)+'px';
      el.textContent=B.ic+' '+B.name;
      el.innerHTML+='<div class="grip l"></div><div class="grip r"></div>';
      el.onmousedown=e=>_scClipDrag(e,c,el);
      row.appendChild(el);
    }
    L.appendChild(row);
  }
  const ph=document.createElement('div'); ph.className='sc-play'; ph.id='scPlayhead'; ph.style.left=(_scT*SC_PPS)+'px';
  L.appendChild(ph);
}
function _scMovePlayhead(){
  const ph=document.getElementById('scPlayhead'); if(ph) ph.style.left=(_scT*SC_PPS)+'px';
  const l=document.getElementById('scTimeLbl');
  if(l) l.textContent=(_scT/SC_FPS).toFixed(2)+'s / '+(SCENE.dur/SC_FPS).toFixed(2)+'s';
}
function _scClipDrag(e,c,el){
  e.preventDefault();
  _scSelect('clip',c.id);
  const mode = e.target.classList.contains('grip') ? (e.target.classList.contains('l')?'l':'r') : 'move';
  const x0=e.clientX, t0=c.t0, len0=c.len;
  const mv=ev=>{
    const d=Math.round((ev.clientX-x0)/SC_PPS);
    if(mode==='move') c.t0=Math.max(0,t0+d);
    else if(mode==='r') c.len=Math.max(4,len0+d);
    else { const nt=Math.max(0,t0+d); c.len=Math.max(4,len0-(nt-t0)); c.t0=nt; }
    el.style.left=(c.t0*SC_PPS)+'px'; el.style.width=Math.max(18,c.len*SC_PPS)+'px';
    SCENE.dur=Math.max(SCENE.dur, c.t0+c.len+60);
  };
  const up=()=>{ document.removeEventListener('mousemove',mv); document.removeEventListener('mouseup',up); _scRenderTimeline(); _scRenderProps(); };
  document.addEventListener('mousemove',mv); document.addEventListener('mouseup',up);
}

// ===================== THÊM / CHỌN / XOÁ =====================
// lớp nào trong khoảng [t0, t0+len) chưa có clip nào chiếm thì dùng lớp đó; kín hết thì đẻ thêm 1 lớp
function _scFreeLane(t0,len){
  for(let ln=0; ln<SCENE.lanes; ln++){
    const ban=SCENE.clips.some(c=>c.lane===ln && t0 < c.t0+c.len && c.t0 < t0+len);
    if(!ban) return ln;
  }
  SCENE.lanes++;
  return SCENE.lanes-1;
}
function scAddClip(type,lane,t0,over){
  const B=SC_BLOCKS[type]; if(!B) return;
  const p={}; for(const q of B.params) p[q.k]=q.def;
  if(over) Object.assign(p,over);
  if(p.who!==undefined && SCENE.actors[0]) p.who=SCENE.actors[0].id;
  if(p.gaze!==undefined && SCENE.actors[0]) p.gaze=SCENE.actors[0].id;
  if(type==='vfx' && !p.name && vfxLibrary[0]) p.name=vfxLibrary[0].name;
  const c={ id:SCENE.nid++, type, lane, t0, len:B.len, p };
  SCENE.clips.push(c);
  SCENE.dur=Math.max(SCENE.dur, t0+B.len+60);
  _scSelect('clip',c.id); _scRenderTimeline();
}
function _scSelect(k,id){ _scSel={k,id}; _scRenderTimeline(); _scRenderProps(); }
function scDelSelected(){
  if(!_scSel) return;
  if(_scSel.k==='clip') SCENE.clips=SCENE.clips.filter(c=>c.id!==_scSel.id && !(c.p&&c.p.who===_scSel.id));
  else { SCENE.actors=SCENE.actors.filter(a=>a.id!==_scSel.id);
         SCENE.clips=SCENE.clips.filter(c=>!(c.p&&(c.p.who===_scSel.id||c.p.gaze===_scSel.id))); }
  _scSel=null; _scRenderTimeline(); _scRenderProps();
}
function scAddLane(){ SCENE.lanes++; _scRenderTimeline(); }

// ===================== BẢNG THUỘC TÍNH =====================
function _scRenderProps(){
  const P=document.getElementById('scProps'); if(!P) return;
  if(!_scSel){ P.innerHTML='<h4>THUỘC TÍNH</h4><div style="color:#666;font-size:0.62rem">Chọn 1 khối cảnh hoặc 1 diễn viên.</div>'; return; }
  const row=(lab,inner)=>'<div class="sc-row"><label>'+lab+'</label>'+inner+'</div>';
  if(_scSel.k==='actor'){
    const a=SCENE.actors.find(x=>x.id===_scSel.id); if(!a){ _scSel=null; return _scRenderProps(); }
    const r=roster[a.rosterIdx]||{};
    // ⛔ KHÔNG còn ô nhập X/Y/Cỡ/Xoay: bốn thứ đó điều khiển bằng chuột ngay trên sàn (kéo thân, kéo nút góc,
    // nút xoay) — bày ô số ra chỉ tổ rối và hiện những con số lẻ dài loằng ngoằng.
    P.innerHTML='<h4>🧍 '+(r.name||'DIỄN VIÊN')+'</h4>'
      +'<div style="color:#666;font-size:0.58rem;margin:-4px 0 8px">Kéo trên sàn để dời · nút góc để phóng · nút trên để xoay</div>'
      +row('Lật ngang','<select onchange="_scSetActor('+a.id+',\'flip\',this.value)"><option value="0"'+(a.flip?'':' selected')+'>Không</option><option value="1"'+(a.flip?' selected':'')+'>Có</option></select>')
      +row('Lật dọc','<select onchange="_scSetActor('+a.id+',\'flipY\',this.value)"><option value="0"'+(a.flipY?'':' selected')+'>Không</option><option value="1"'+(a.flipY?' selected':'')+'>Có</option></select>')
      +row('Viền','<input type="color" value="'+(a.outline||'#ffffff')+'" oninput="_scSetOutline('+a.id+',this.value)">'
           +'<button class="sc-btn" style="padding:3px 7px" onclick="_scSetOutline('+a.id+',\'\')" title="Bỏ viền">✕</button>')
      +row('Dày','<select onchange="_scSetActor('+a.id+',\'outlineW\',this.value)">'
           +[['2','Mỏng'],['3','Vừa'],['5','Dày'],['8','Rất dày']].map(o=>'<option value="'+o[0]+'"'+(String(a.outlineW||3)===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')
           +'</select>')
      +'<div style="display:flex;gap:5px;margin-top:6px"><button class="sc-btn" style="flex:1" onclick="_scLayer('+a.id+',1)">⬆ Lên trên</button><button class="sc-btn" style="flex:1" onclick="_scLayer('+a.id+',-1)">⬇ Xuống dưới</button></div>'
      // 🎞️ ANIMATION nằm LUÔN ở đây: bấm 1 phát là gắn thẳng cho chính diễn viên này, đặt tại mốc thời gian
      // đang đứng, tự tìm lớp trống — khỏi phải sang tab Anim kéo khối rồi chọn lại diễn viên.
      +'<h4 style="margin-top:12px">🎞️ ANIMATION</h4>'
      +'<div style="color:#666;font-size:0.58rem;margin:-4px 0 7px">Gắn tại mốc '+(_scT/SC_FPS).toFixed(2)+'s</div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:5px">'
      +SC_GROUPS.anim.map(kk=>{ const B2=SC_BLOCKS[kk];
          return '<button class="sc-btn" style="flex:1 1 46%" onclick="_scAddAnim('+a.id+',\''+kk+'\')">'+B2.ic+' '+B2.name+'</button>'; }).join('')
      +'</div>'
      +_scAnimList(a.id);
    return;
  }
  const c=SCENE.clips.find(x=>x.id===_scSel.id); if(!c){ _scSel=null; return _scRenderProps(); }
  const B=SC_BLOCKS[c.type];
  let h='<h4>'+B.ic+' '+B.name.toUpperCase()+'</h4>';
  if(_scObj({k:'clip',id:c.id})) h+='<div style="color:#666;font-size:0.58rem;margin:-4px 0 8px">Kéo trên sàn để đặt vị trí / cỡ / góc</div>';
  h+=row('Bắt đầu','<input type="number" step="1" value="'+c.t0+'" oninput="_scSetClip('+c.id+',\'t0\',this.value)">');
  h+=row('Dài (tick)','<input type="number" step="1" value="'+c.len+'" oninput="_scSetClip('+c.id+',\'len\',this.value)">');
  const _onStage=!!_scObj({k:'clip',id:c.id});
  for(const q of B.params){
    // x/y/cỡ/góc của khối đặt trên sàn: đã kéo bằng chuột được rồi thì không bày ô số ra nữa
    if(_onStage && (q.k==='x'||q.k==='y'||q.k==='size'||q.k==='ang')) continue;
    const v=c.p[q.k];
    let inp;
    if(q.type==='actor'){
      inp='<select onchange="_scSetP('+c.id+',\''+q.k+'\',this.value)"><option value="">— chọn —</option>'
        +SCENE.actors.map(a=>'<option value="'+a.id+'"'+(v==a.id?' selected':'')+'>'+((roster[a.rosterIdx]||{}).name||a.id)+'</option>').join('')+'</select>';
    } else if(q.type==='vfx'){
      inp='<select onchange="_scSetP('+c.id+',\''+q.k+'\',this.value)">'
        +vfxLibrary.map(x=>'<option value="'+(x.name||'').replace(/"/g,'')+'"'+(v===x.name?' selected':'')+'>'+(x.name||'?')+'</option>').join('')+'</select>';
    } else if(q.type==='sel'){
      inp='<select onchange="_scSetP('+c.id+',\''+q.k+'\',this.value)">'
        +q.opts.map(o=>'<option value="'+o[0]+'"'+(String(v)===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')+'</select>';
    } else if(q.type==='color'){
      inp='<input type="color" value="'+v+'" oninput="_scSetP('+c.id+',\''+q.k+'\',this.value)">';
    } else if(q.type==='txt'){
      inp='<input type="text" value="'+String(v).replace(/"/g,'')+'" oninput="_scSetP('+c.id+',\''+q.k+'\',this.value)">';
    } else {
      inp='<input type="number" step="1" value="'+v+'" oninput="_scSetP('+c.id+',\''+q.k+'\',this.value)">';
    }
    h+=row(q.label,inp);
  }
  // 🎞️ khối nào ĐẶT ĐƯỢC TRÊN SÀN thì cũng gắn animation được y hệt meme — cùng bộ nút, cùng danh sách bên dưới
  if(_onStage){
    const _dung=['move','scale','rotate','fade'].filter(kk=>{
      if(kk==='scale')  return c.p.size!==undefined;
      if(kk==='rotate') return c.p.ang!==undefined;
      return true;
    });
    h+='<h4 style="margin-top:12px">🎞️ ANIMATION</h4>'
      +'<div style="color:#666;font-size:0.58rem;margin:-4px 0 7px">Gắn tại mốc '+(_scT/SC_FPS).toFixed(2)+'s</div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:5px">'
      +_dung.map(kk=>{ const B2=SC_BLOCKS[kk];
          return '<button class="sc-btn" style="flex:1 1 46%" onclick="_scAddAnim('+c.id+',\''+kk+'\')">'+B2.ic+' '+B2.name+'</button>'; }).join('')
      +'</div>'
      +_scAnimList(c.id);
  }
  P.innerHTML=h;
}
// gắn 1 khối animation cho ĐÚNG diễn viên này, tại mốc thời gian đang đứng
function _scAddAnim(actorId, type){
  const B=SC_BLOCKS[type]; if(!B) return;
  const p={}; for(const q of B.params) p[q.k]=q.def;
  p.who=actorId;
  // "Đi tới" mặc định lấy luôn chỗ diễn viên đang đứng làm đích, để kéo trên sàn là chỉnh được ngay
  if(type==='move'){
    const a=SCENE.actors.find(z=>z.id===actorId);
    const c0=a?null:SCENE.clips.find(z=>z.id===actorId);
    const src=a||(c0?c0.p:null);
    if(src){ p.x=Math.round(src.x); p.y=Math.round(src.y); }
  }
  // Phóng/Xoay lấy giá trị HIỆN TẠI làm mốc đích, để bấm xong chưa đổi gì đã thì hình không nhảy đột ngột
  const _t0=SCENE.clips.find(z=>z.id===actorId);
  if(_t0){ if(type==='scale' && _t0.p.size!==undefined) p.to=_t0.p.size;
           if(type==='rotate' && _t0.p.ang!==undefined) p.to=_t0.p.ang; }
  const c={ id:SCENE.nid++, type, lane:_scFreeLane(_scT,B.len), t0:_scT, len:B.len, p };
  SCENE.clips.push(c);
  SCENE.dur=Math.max(SCENE.dur, c.t0+c.len+60);
  _scRenderTimeline(); _scRenderProps();
}
// danh sách animation đang gắn cho diễn viên — bấm để nhảy tới, có nút xoá riêng
function _scAnimList(actorId){
  const cs=SCENE.clips.filter(c=>c.p && c.p.who===actorId).sort((m,n)=>m.t0-n.t0);
  if(!cs.length) return '<div style="color:#555;font-size:0.58rem;margin-top:8px">Chưa gắn animation nào.</div>';
  return '<div style="margin-top:9px;display:flex;flex-direction:column;gap:4px">'
    +cs.map(c=>{ const B=SC_BLOCKS[c.type];
      return '<div style="display:flex;align-items:center;gap:4px">'
        +'<button class="sc-btn" style="flex:1;text-align:left;font-size:0.6rem" onclick="_scSelect(\'clip\','+c.id+')">'
        +B.ic+' '+B.name+' <span style="opacity:.55">'+(c.t0/SC_FPS).toFixed(1)+'s</span></button>'
        +'<button class="sc-btn" style="padding:4px 6px" onclick="_scDelClip('+c.id+')">✕</button></div>'; }).join('')
    +'</div>';
}
function _scDelClip(id){ SCENE.clips=SCENE.clips.filter(c=>c.id!==id); if(_scSel&&_scSel.k==='clip'&&_scSel.id===id) _scSel=null; _scRenderTimeline(); _scRenderProps(); }
function _scSetOutline(id,v){ const a=SCENE.actors.find(x=>x.id===id); if(!a) return; a.outline=v||''; _scRenderProps(); }
function _scSetActor(id,k,v){ const a=SCENE.actors.find(x=>x.id===id); if(!a) return;
  a[k]=(k==='flip'||k==='flipY') ? (v==='1') : (parseFloat(v)||0); }
// thứ tự vẽ = thứ tự trong mảng: đẩy lên/xuống 1 bậc để chồng lớp như slide
function _scLayer(id,dir){
  const i=SCENE.actors.findIndex(x=>x.id===id); if(i<0) return;
  const j=i+dir; if(j<0||j>=SCENE.actors.length) return;
  const t=SCENE.actors[i]; SCENE.actors[i]=SCENE.actors[j]; SCENE.actors[j]=t;
}
function _scSetClip(id,k,v){ const c=SCENE.clips.find(x=>x.id===id); if(!c) return; c[k]=Math.max(k==='len'?4:0, parseInt(v)||0);
  SCENE.dur=Math.max(SCENE.dur, c.t0+c.len+60); _scRenderTimeline(); }
function _scSetP(id,k,v){ const c=SCENE.clips.find(x=>x.id===id); if(!c) return;
  const B=SC_BLOCKS[c.type], q=B.params.find(z=>z.k===k);
  c.p[k]=(q&&q.type==='num') ? (parseFloat(v)||0) : v;
  c._E=null; }

// ===================== ĐIỀU KHIỂN =====================
function _scSyncTop(){ const b=document.getElementById('scPlayBtn'); if(b) b.textContent=_scPlaying?'⏸':'▶'; }
const SC_BGS=[['arena','🟦 Nền sàn'],['black','⬛ Nền đen'],['blackhole','🕳️ Hố đen']];
function _scSyncBgBtn(){
  const b=document.getElementById('scBlackBtn'); if(!b) return;
  const cur=SCENE.bg||'arena', e=SC_BGS.find(x=>x[0]===cur)||SC_BGS[0];
  b.textContent=e[1]; b.classList.toggle('on',cur!=='arena');
}
function scToggleBlackBg(){   // bấm 1 nút xoay vòng: sàn → đen → hố đen → sàn
  const cur=SCENE.bg||'arena';
  const i=SC_BGS.findIndex(x=>x[0]===cur);
  SCENE.bg=SC_BGS[(i<0?0:i+1)%SC_BGS.length][0];
  _scSyncBgBtn(); _scSaveScene();
}
function scTogglePlay(){ _scPlaying=!_scPlaying; if(_scPlaying) for(const c of SCENE.clips){ c._E=null; c._last=-9; } _scSyncTop(); }
function scStop(){ _scStopWhisper(); _scStopLaugh(); _scStopTerror(); _scPlaying=false; _scT=0; for(const c of SCENE.clips){ c._E=null; c._last=-9; } _scSyncTop(); }
function scToggleLoop(){ _scLoop=!_scLoop; const b=document.getElementById('scLoopBtn'); if(b) b.classList.toggle('on',_scLoop); }


// ===================== VÀO / RA CHẾ ĐỘ =====================
// ===================== 🏅 TIER LIST: kéo avatar meme vào các hàng S/A/B/C/D (lưu bền qua storage) =====================
const TL_TIERS=[['Broken','#d58cff','Broken\nOP\nLore'],['S+','#ff5f5f'],['S-','#ff9f9f'],['A','#ffbf7f'],['B','#ffdf7f'],['C','#ffff7f'],['Fixing','#c9c9c9']];   // Broken = mạnh quá mức (trên S), Fixing = đang sửa (dưới D)
let tierList={};   // tier -> [roster id...] theo đúng thứ tự trong hàng; meme không nằm trong hàng nào = ở kho bên dưới
function _tlLoad(){
  try{ const raw=storeGet('cbs_tierlist'); tierList=raw?JSON.parse(raw):{}; }catch(e){ tierList={}; }
  // 🔁 bản cũ: S tách thành S+/S- → meme ở S cũ chuyển lên S+; tier D đã bỏ → meme ở D về lại kho
  if(tierList.S || tierList.D){ if(tierList.S) tierList['S+']=[...tierList.S,...(tierList['S+']||[])]; delete tierList.S; delete tierList.D; _tlSave(); }
}
function _tlSave(){ try{ storeSet('cbs_tierlist', JSON.stringify(tierList)); }catch(e){} }
function _tlMemes(){ return roster.filter(r=>r && r.charKey && r.charKey!=='trainingdummy' && r.charKey!=='fanchar'); }
function openTierList(){
  if(animId) cancelAnimationFrame(animId);
  animId=null; isPaused=true; stopAllBattleMusic();
  document.querySelectorAll('.screen').forEach(el=>el.classList.remove('active'));
  document.getElementById('tierScreen').classList.add('active');
  _tlLoad(); _tlRender();
}
function closeTierList(){
  document.getElementById('tierScreen').classList.remove('active');
  document.getElementById('mainMenuScreen').classList.add('active');
}
function tlReset(){ if(!confirm('Move every meme back to the pool?')) return; tierList={}; _tlSave(); _tlRender(); }
function _tlItem(r){
  const d=document.createElement('div'); d.className='tl-item'; d.dataset.id=r.id; d.title=r.name||r.charKey;
  if(r.avatarUrl){ const im=document.createElement('img'); im.src=(window.ASSETS?ASSETS.thumb(r.avatarUrl):r.avatarUrl); im.draggable=false; d.appendChild(im); }
  else { const e=document.createElement('span'); e.className='tl-emo'; e.textContent=(CHAR_DEFS[r.charKey]&&CHAR_DEFS[r.charKey].emoji)||'❓'; d.appendChild(e); }
  const nm=document.createElement('div'); nm.className='tl-nm'; nm.textContent=r.name||r.charKey; d.appendChild(nm);
  d.addEventListener('pointerdown',_tlDragStart);
  return d;
}
function _tlRender(){
  const memes=_tlMemes(), byId=new Map(memes.map(r=>[String(r.id),r])), placed=new Set();
  const board=document.getElementById('tlBoard'); board.innerHTML='';
  for(const [t,col,label] of TL_TIERS){   // label: tên hiển thị (khác key lưu trữ để không mất meme đã xếp)
    const row=document.createElement('div'); row.className='tl-row';
    const lb=document.createElement('div'); lb.className='tl-label'+((label||t).length>2?' tl-label-word':''); lb.style.background=col; lb.textContent=label||t; row.appendChild(lb);
    const box=document.createElement('div'); box.className='tl-items tl-drop'; box.dataset.tier=t;
    for(const id of (tierList[t]||[])){ const r=byId.get(String(id)); if(!r || placed.has(String(id))) continue; placed.add(String(id)); box.appendChild(_tlItem(r)); }
    row.appendChild(box); board.appendChild(row);
  }
  const pool=document.getElementById('tlPool'); pool.innerHTML='';
  for(const r of memes) if(!placed.has(String(r.id))) pool.appendChild(_tlItem(r));
}
// 🖱️ kéo thả bằng pointer (chuột + cảm ứng): ô gốc mờ đi làm chỗ giữ, bản sao bay theo tay, thả xuống thì chèn đúng vị trí
let _tlDrag=null;
function _tlDragStart(ev){
  if(ev.button!==undefined && ev.button!==0) return;
  ev.preventDefault();
  const el=ev.currentTarget, rc=el.getBoundingClientRect();
  const fl=el.cloneNode(true); fl.classList.add('tl-float'); fl.style.left=rc.left+'px'; fl.style.top=rc.top+'px'; fl.style.width=rc.width+'px'; fl.style.height=rc.height+'px';
  document.body.appendChild(fl); el.classList.add('tl-ghost');
  _tlDrag={el, fl, dx:ev.clientX-rc.left, dy:ev.clientY-rc.top, over:null, x:ev.clientX, y:ev.clientY};
  _tlDrag.raf=requestAnimationFrame(_tlAutoScroll);
  window.addEventListener('pointermove',_tlDragMove); window.addEventListener('pointerup',_tlDragEnd); window.addEventListener('pointercancel',_tlDragEnd);
}
// 📜 kéo sát mép trên/dưới màn hình → trang tự cuộn (kho meme dài hơn màn hình, kéo từ dưới kho lên hàng S vẫn tới)
function _tlAutoScroll(){
  const D=_tlDrag; if(!D) return;
  const E=70, h=window.innerHeight, v = D.y<E ? -Math.ceil((E-D.y)/4) : D.y>h-E ? Math.ceil((D.y-(h-E))/4) : 0;
  if(v){ const y0=window.scrollY; window.scrollBy(0,v); if(window.scrollY!==y0) _tlDragMove({clientX:D.x, clientY:D.y}); }
  D.raf=requestAnimationFrame(_tlAutoScroll);
}
function _tlDragMove(ev){
  const D=_tlDrag; if(!D) return;
  D.x=ev.clientX; D.y=ev.clientY;
  D.fl.style.left=(ev.clientX-D.dx)+'px'; D.fl.style.top=(ev.clientY-D.dy)+'px';
  const zone=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.tl-drop')||null;
  if(D.over!==zone){ if(D.over) D.over.classList.remove('tl-over'); if(zone) zone.classList.add('tl-over'); D.over=zone; }
  if(!zone) return;
  // chèn ô gốc ngay trước ô đầu tiên nằm sau con trỏ (theo hàng rồi theo cột)
  let before=null;
  for(const c of zone.children){ if(c===D.el) continue; const r=c.getBoundingClientRect();
    if(ev.clientY<r.top || (ev.clientY<=r.bottom && ev.clientX<r.left+r.width/2)){ before=c; break; } }
  if(before) { if(D.el.nextSibling!==before) zone.insertBefore(D.el,before); }
  else if(zone.lastChild!==D.el) zone.appendChild(D.el);
}
function _tlDragEnd(){
  const D=_tlDrag; if(!D) return; _tlDrag=null; cancelAnimationFrame(D.raf);
  window.removeEventListener('pointermove',_tlDragMove); window.removeEventListener('pointerup',_tlDragEnd); window.removeEventListener('pointercancel',_tlDragEnd);
  D.fl.remove(); D.el.classList.remove('tl-ghost'); if(D.over) D.over.classList.remove('tl-over');
  tierList={};
  document.querySelectorAll('#tlBoard .tl-items').forEach(z=>{ const ids=[...z.children].map(c=>c.dataset.id); if(ids.length) tierList[z.dataset.tier]=ids; });
  _tlSave();
}

function openScene(){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi (Scene Builder = công cụ chỉnh sửa)
  _openSceneScreen();
}
function _openSceneScreen(){
  if(animId) cancelAnimationFrame(animId);
  animId=null; isPaused=true;
  stopAllBattleMusic();
  document.querySelectorAll('.screen').forEach(el=>el.classList.remove('active'));
  document.getElementById('sceneScreen').classList.add('active');
  sceneCtx={};
  // mượn đúng canvas/pipeline của battleScreen, dựng khung DỌC 9:16 sạch (không tên, không thanh máu, không watermark)
  const aw=document.querySelector('.arena-wrap');
  document.getElementById('scStage').appendChild(aw);
  aw.classList.add('cam-mode');
  const vs=document.getElementById('vsLabel'); if(vs) vs.style.display='none';
  const rb=document.getElementById('tbRosterBar'); if(rb) rb.style.display='none';
  _setArenaSize(ARENA_NORMAL.w, ARENA_NORMAL.h, ARENA_NORMAL.ss, true);
  _scLoadScene();
  _scRenderLib(); _scRenderTimeline(); _scRenderProps(); _scSyncTop();
  const lb=document.getElementById('scLoopBtn'); if(lb) lb.classList.toggle('on',_scLoop);
  _scSyncBgBtn();
  _scWireStage(); _scWireRuler(); _scWireKeys();
  if(_scRaf) cancelAnimationFrame(_scRaf);
  _scRaf=requestAnimationFrame(_scLoopFn);
}
function closeScene(){
  _scStopWhisper(); _scStopLaugh(); _scStopTerror();
  const _wasPlayer=!!_scPlayer;
  if(_scPlayer){ SCENE=_scPlayer.bak; _scLoop=_scPlayer.loop; _scPlayer=null; _cinePanelRemove(); document.getElementById('sceneScreen').classList.remove('player'); }
  else _scSaveScene();
  _scPlaying=false; _scRec=false;
  document.getElementById('sceneScreen').classList.remove('recmode');
  if(_scRaf) cancelAnimationFrame(_scRaf); _scRaf=null;
  sceneCtx=null;
  const aw=document.querySelector('.arena-wrap');
  aw.classList.remove('cam-mode');
  document.querySelector('.battle-frame').appendChild(aw);
  const vs=document.getElementById('vsLabel'); if(vs) vs.style.display='';
  isPaused=false;
  _setArenaSize(ARENA_NORMAL.w, ARENA_NORMAL.h, ARENA_NORMAL.ss);
  document.getElementById('sceneScreen').classList.remove('active');
  document.getElementById('mainMenuScreen').classList.add('active');
  if(_wasPlayer) openCinema('__lore1');   // xem xong → về lại thư mục Meme Lore 1
}
// thả MEME vào khung → thành diễn viên đứng đúng chỗ vừa thả; kéo diễn viên trong khung để dời chỗ
function _scWireStage(){
  const st=document.getElementById('scStage'); if(!st || st._wired) return; st._wired=true;
  st.ondragover=e=>{ e.preventDefault(); st.classList.add('dragover'); };
  st.ondragleave=()=>st.classList.remove('dragover');
  st.ondrop=e=>{
    e.preventDefault(); st.classList.remove('dragover');
    const dt=e.dataTransfer.getData('text/plain')||'';
    const pt=_scPtFromEvent(e); if(!pt) return;
    if(dt.startsWith('prop:')){
      const k=dt.slice(5), P=SC_PROPS[k];
      const a={ id:SCENE.nid++, propKey:k, x:pt.x, y:pt.y,
                size:Math.round(Math.max(P?P.w:120, P?P.h:120)*0.55),
                rot:0, flip:false, flipY:false, outline:'', outlineW:3 };
      SCENE.actors.push(a); _scSelect('actor',a.id);
      return;
    }
    if(dt.startsWith('meme:')){
      const a={ id:SCENE.nid++, rosterIdx:+dt.slice(5), x:pt.x, y:pt.y, size:96, rot:0, flip:false, flipY:false, outline:'', outlineW:3 };
      SCENE.actors.push(a); _scSelect('actor',a.id);
      return;
    }
    // 🎯 Thả khối cảnh/VFX THẲNG VÀO KHUNG: tự đặt clip tại ĐÚNG mốc thời gian đang đứng, tự tìm lớp còn trống,
    // và nếu khối đó có toạ độ thì lấy luôn CHỖ VỪA THẢ làm vị trí — khỏi phải thả xuống timeline rồi chỉnh tay.
    let type=null, over={};
    if(dt.startsWith('blk:')) type=dt.slice(4);
    else if(dt.startsWith('vfx:')){ type='vfx'; over.name=dt.slice(4); }
    if(!type || !SC_BLOCKS[type]) return;
    const B=SC_BLOCKS[type];
    if(B.params.some(q=>q.k==='x')) over.x=Math.round(pt.x);
    if(B.params.some(q=>q.k==='y')) over.y=Math.round(pt.y);
    scAddClip(type, _scFreeLane(_scT, B.len), _scT, over);
  };
  st.onmousedown=_scStageDown;
  st.onmousemove=_scStageMove;
}
// đổi toạ độ chuột → % SÀN (canvas là khung 9:16, sàn nằm giữa nên phải trừ lề _worldOX/_worldOY)
function _scPtFromEvent(e){
  const cv=canvas, r=cv.getBoundingClientRect();
  if(!r.width||!r.height) return null;
  const vx=(e.clientX-r.left)/r.width*(_viewW||W);
  const vy=(e.clientY-r.top)/r.height*(_viewH||H);
  return { x:(vx-(_worldOX||0))/W*100, y:(vy-(_worldOY||0))/H*100 };
}
// ⌨️ Delete / Backspace = xoá thứ đang chọn. Chặn khi con trỏ đang ở trong ô nhập của bảng thuộc tính,
// nếu không thì đang sửa số lại thành xoá mất cả khối.
let _scKeysWired=false;
function _scWireKeys(){
  if(_scKeysWired) return; _scKeysWired=true;
  document.addEventListener('keydown', e=>{
    if(!sceneCtx) return;
    const t=e.target, tag=t&&t.tagName;
    if(tag==='INPUT'||tag==='SELECT'||tag==='TEXTAREA'||(t&&t.isContentEditable)) return;
    const B=e.shiftKey?10:1;
    if(e.key==='Delete'||e.key==='Backspace'){ if(_scSel){ e.preventDefault(); scDelSelected(); } }
    else if(e.key===' '){ e.preventDefault(); scTogglePlay(); }        // Space = chạy/dừng
    else if(e.key==='Escape'){ _scSel=null; _scRenderTimeline(); _scRenderProps(); }
    else if((e.ctrlKey||e.metaKey) && (e.key==='d'||e.key==='D')){ e.preventDefault(); _scDuplicate(); }
    else if(e.key==='ArrowLeft'){ e.preventDefault(); _scNudge(-B,0); }
    else if(e.key==='ArrowRight'){ e.preventDefault(); _scNudge(B,0); }
    else if(e.key==='ArrowUp'){ e.preventDefault(); _scNudge(0,-B); }
    else if(e.key==='ArrowDown'){ e.preventDefault(); _scNudge(0,B); }
  });
}
function _scWireRuler(){
  const R=document.getElementById('scRuler'); if(!R || R._wired) return; R._wired=true;
  const seek=e=>{ const b=R.getBoundingClientRect();
    _scT=Math.max(0,Math.min(SCENE.dur-1, Math.round((e.clientX-b.left+R.parentElement.scrollLeft)/SC_PPS)));
    for(const c of SCENE.clips){ c._E=null; c._last=-9; } _scMovePlayhead(); };
  R.onmousedown=e=>{ seek(e);
    const mv=ev=>seek(ev), up=()=>{ document.removeEventListener('mousemove',mv); document.removeEventListener('mouseup',up); };
    document.addEventListener('mousemove',mv); document.addEventListener('mouseup',up); };
}
// ---------- lưu / nạp (dùng chung kho IndexedDB với roster & kho VFX) ----------
function _scSaveScene(){
  try{ storeSet('cbs_scene', JSON.stringify({ dur:SCENE.dur, lanes:SCENE.lanes, nid:SCENE.nid, bg:SCENE.bg||'arena',
    actors:SCENE.actors, clips:SCENE.clips.map(c=>({id:c.id,type:c.type,lane:c.lane,t0:c.t0,len:c.len,p:c.p})) })); }catch(e){}
}
function _scLoadScene(){
  try{
    const raw=storeGet('cbs_scene'); if(!raw) return;
    const o=JSON.parse(raw); if(!o||!o.clips) return;
    // o.blackBg là định dạng cũ (chỉ có bật/tắt đen) — vẫn đọc được cảnh đã lưu từ trước
    SCENE={ dur:o.dur||600, lanes:o.lanes||5, nid:o.nid||1, actors:o.actors||[], clips:o.clips||[],
            bg:o.bg || (o.blackBg?'black':'arena') };
  }catch(e){}
}


// ===================== ⭐ FAN BATTLE — VÒNG QUAY MAY MẮN =====================
// Trước khi vào trận, fan được quay 3 lượt lấy buff. Buff cộng dồn, quay trúng ô nào cũng có lợi —
// riêng ô THU PHỤC là canh bạc: trúng ô đó rồi vẫn phải bốc tiếp xem lôi kéo được mấy con.
// Múi TO NHỎ THEO TỈ LỆ TRÚNG (w = trọng số, tổng 100) — buff càng ngon múi càng hẹp, nhìn là biết ngay
// cái nào hiếm, đúng kiểu bánh xe quay trên mạng.
// HAI BÁNH XE RIÊNG BIỆT — quay xong cái này mới thay mặt sang cái kia, không quay cùng lúc:
//   • BUFF    — chỉ số cho con của fan
//   • RECRUIT — lôi kéo meme phe địch về phe mình
const FAN_WHEELS = {
  // Trọng số tính trên 400 để chia CHẴN: 80/400=20% trượt, 12/400=3% ăn trọn,
  // 77/400=19.25% cho mỗi buff lẻ. Phần cắt bớt của "trượt" (30%→20%) chia đều cho 4 buff lẻ,
  // KHÔNG cộng vào "ăn trọn" — ô đó vẫn giữ nguyên 3% cho hiếm.
  buff: { nm:'BUFF WHEEL', q:'What did the algorithm bless you with?', chain:true, seg:[
    { k:'none', v:0,    w:80,  ic:'💨',  nm:'NOTHING',     col:'#37474f' },
    { k:'dmg',  v:0.25, w:77,  ic:'⚔️',  nm:'+25% DMG',    col:'#1e88e5' },
    { k:'spd',  v:0.25, w:77,  ic:'👟',  nm:'+25% SPEED',  col:'#fb8c00' },
    { k:'hp',   v:1000, w:77,  ic:'❤️',  nm:'+1000 HP',    col:'#e53935' },
    { k:'inv',  v:300,  w:77,  ic:'🛡️', nm:'5s IMMORTAL', col:'#00897b' },
    { k:'all',  v:0,    w:12,  ic:'🌟',  nm:'ALL BUFFS',   col:'#8e24aa' },
  ]},
  // 89% trượt / 10% được 1 con / 1% được 2 con
  recruit: { nm:'RECRUIT WHEEL', q:'Anybody switching sides for you?', seg:[
    { k:'rec', v:0, w:89, ic:'🚫', nm:'NOBODY',  col:'#37474f' },
    { k:'rec', v:1, w:10, ic:'🤝', nm:'1 JOINS', col:'#43a047' },
    { k:'rec', v:2, w:1,  ic:'🎉', nm:'2 JOIN!', col:'#8e24aa' },
  ]},
  // 84% một mạng / 15% hai mạng / 1% ba mạng (tăng 2 mạng từ 10%→15%, trừ vào phần 1 mạng, giữ nguyên 3 mạng hiếm)
  lives: { nm:'LIVES WHEEL', q:'How many lives bro have?', seg:[
    { k:'life', v:1, w:84, ic:'💀', nm:'1 LIFE',   col:'#37474f' },
    { k:'life', v:2, w:15, ic:'💚', nm:'2 LIVES',  col:'#43a047' },
    { k:'life', v:3, w:1,  ic:'👑', nm:'3 LIVES!', col:'#8e24aa' },
  ]},
};
const FAN_ORDER = ['buff','recruit','lives'];   // mỗi bánh quay ĐÚNG 1 lượt; cộng máy loto là tròn 4 vòng
let _fwKind='buff';
let _fwUsed=new Set();       // chỉ số các múi ĐÃ TRÚNG ở bánh hiện tại — tối đi, không bốc lại
function _fwSeg(){ return FAN_WHEELS[_fwKind].seg; }
function _fwTotal(){ return _fwSeg().reduce((a,x)=>a+x.w,0); }
function _fwDim(i){ return _fwUsed.has(i); }
// làm tối 1 màu hex xuống còn ~28% độ sáng, để múi đã trúng nhìn là biết ngay không quay lại được nữa
function _fwDark(hex){
  const n=parseInt(hex.slice(1),16);
  const r=Math.round((n>>16&255)*0.28), g=Math.round((n>>8&255)*0.28), b=Math.round((n&255)*0.28);
  return `rgb(${r},${g},${b})`;
}
// góc [bắt đầu, kết thúc] của từng múi, tính từ 12h theo chiều kim đồng hồ
function _fwSpans(){
  const out=[]; let acc=0; const T=_fwTotal();
  for(const x of _fwSeg()){ const d=x.w/T*360; out.push([acc,acc+d]); acc+=d; }
  return out;
}
// dựng lại MẶT bánh xe theo đúng loại đang quay (múi + màu + chữ)
function _fwPaintWheel(){
  const SP=_fwSpans(), SEG=_fwSeg();
  document.getElementById('fwWheel').style.background=
    `conic-gradient(${SEG.map((s,i)=>`${_fwDim(i)?_fwDark(s.col):s.col} ${SP[i][0]}deg ${SP[i][1]}deg`).join(',')})`;
  // Chữ chạy DỌC THEO CÁNH (từ trục ra vành) và phải NẰM GỌN trong cánh:
  //   • đặt tại giữa dải dùng được (từ mép trục R0 tới sát vành R1) rồi xoay thêm 90° → chữ đi dọc bán kính
  //   • cỡ chữ tính lùi từ chiều dài dải: chữ càng dài thì cỡ càng nhỏ, không bao giờ tràn ra ngoài vành
  // ⭐ x2 theo yêu cầu (từ gốc R0=44,R1=148) + CĂN ĐỀU: mọi nhãn dùng CHUNG 1 bán kính bắt đầu — tính theo
  // CÁNH HẸP NHẤT trên bánh — thay vì mỗi cánh tự đẩy ra một mức riêng như bản trước. Nhờ vậy toàn bộ nhãn
  // nằm gọn trên đúng 1 vòng tròn, thẳng hàng với nhau, không lệch cái trong cái ngoài.
  const R0=88, R1=296;
  const _rongTaiChung=(r,goc)=>2*r*Math.sin(goc/2);
  let _r0Chung=R0;
  for(let i=0;i<SEG.length;i++){
    const _g=(SP[i][1]-SP[i][0])*Math.PI/180;
    let _r=R0;
    while(_r<R1-64 && _rongTaiChung(_r,_g)<24) _r+=10;
    if(_r>_r0Chung) _r0Chung=_r;
  }
  const _tamChung=(_r0Chung+R1)/2;
  const _daiChung=R1-_r0Chung;
  document.getElementById('fwLabels').innerHTML = SEG.map((s,i)=>{
    const a0=SP[i][0], a1=SP[i][1], mid=(a0+a1)/2;
    const _goc=(a1-a0)*Math.PI/180;                 // góc mở của cánh (radian)
    const _txt=s.ic+' '+s.nm;
    // cỡ chữ vẫn phải tôn trọng bề rộng RIÊNG của từng cánh tại bán kính CHUNG, không thì cánh hẹp bị tràn chữ
    const _fs=Math.max(14, Math.min(36,
                  _daiChung/(_txt.length*0.66),       // giới hạn theo CHIỀU DÀI dọc cánh
                  _rongTaiChung(_r0Chung,_goc)*0.85)); // giới hạn theo BỀ RỘNG của chính cánh này
    const _op=_fwDim(i)?'opacity:.32;text-decoration:line-through;':'';
    return `<div class="fw-lb" style="${_op}font-size:${_fs.toFixed(1)}px;`
         + `transform:rotate(${mid}deg) translateY(${-_tamChung}px) rotate(90deg)">${_txt}</div>`;
  }).join('');
}
const FAN_SPINS = FAN_ORDER.length;
// 🎰 Thời lượng quay CĂN THEO TIẾNG roulette-casino (dài 3.72s): đoạn 3.5s→3.7s trong file là tiếng kim
// chốt lại, nên bánh phải đứng hẳn ĐÚNG mốc 3.5s thì hình và tiếng mới khớp.
const FAN_SPIN_MS = 3000;
const FAN_SPIN_RATE = 3500/FAN_SPIN_MS;   // vòng quay rút còn 3s → tăng tốc độ tiếng quay theo đúng tỉ lệ cho khớp
const FAN_SPIN_TURNS = 7;      // số vòng quay trọn trước khi dừng — ít vòng quá thì nhìn quay chậm rề
let _fanRoulette=null;
function _fanPlayRoulette(){
  try{ if(_fanRoulette){ _fanRoulette.pause(); _fanRoulette.currentTime=0; } }catch(e){}
  _fanRoulette = AUDIO_SAMPLES['fan_roulette']?.cloneNode() || null;
  if(_fanRoulette){ _fanRoulette.volume=0.9; _fanRoulette.playbackRate=FAN_SPIN_RATE; _mixRoute(_fanRoulette); _fanRoulette.play().catch(()=>{}); }
}
function _fanStopRoulette(){
  if(_fanRoulette){ try{ _fanRoulette.pause(); _fanRoulette.currentTime=0; }catch(e){} _fanRoulette=null; }
}
const FAN_RECRUIT_MAX = 2;   // 1 đấu 3 nên nhiều nhất chỉ kéo được 2 con, để địch còn ít nhất 1 người
let fanBuff = null;          // {hpAdd, dmgMul, recruit} — chốt sau khi quay xong
// ⭐ Commenter Battle: 1 đấu 3 — máy loto bốc 3 đối thủ, rồi 3 bánh quay buff trước trận.
// (chế độ 1 đấu 1 đã bỏ theo yêu cầu — _fanFoeN giữ nguyên biến cho phần loop dùng chung với dưới, nhưng
// không còn đường nào gán nó khác 3 nữa.)
let _fanFoeN = 3;
let _fwSpun = 0, _fwRot = 0, _fwBusy = false;

// số con thu phục được khi trúng ô THU PHỤC: 80% trượt, 19% được 1, 1% được 2
function _fanRollRecruit(){
  const r = Math.random();
  if(r < 0.80) return 0;
  if(r < 0.99) return 1;
  return 2;
}
// 🎰 GIAI ĐOẠN 1 — MÁY LOTO 777: quay ra 3 đối thủ, hiện lần lượt từng con (avatar + tên), trái sang phải.
// Fan chỉ tự chọn CON CỦA MÌNH; 3 đứa còn lại hoàn toàn do máy bốc.
let _fwPhase='slot';                 // 'slot' → 'wheel'
// 🚫 loại khỏi Commenter Battle: 2 con này cơ chế không hợp sàn 1-đấu-nhiều của chế độ này
const FAN_BAN_KEYS = new Set(['flyingcat','loooongcat']);
function _fanBanned(k){ return !k || k==='trainingdummy' || k==='fanchar' || FAN_BAN_KEYS.has(k); }
function _fwRosterPool(){
  return roster.map((c,i)=>({c,i})).filter(x=>x.c && !_fanBanned(x.c.charKey));
}
// 🎲 random lại 3 đối thủ — CHẠY LẠI ĐÚNG animation + tiếng máy loto như lúc bấm ROLL OPPONENTS lần đầu
// (gọi thẳng _fwStartSlot(), không tự chế bản rút gọn tô ảnh ngay lập tức nữa — bản trước thiếu hẳn phần
// hoạt ảnh quay/tiếng động theo đúng yêu cầu). Không đụng gì tới commenter đang chọn (_fanIdxs[0]).
function _fwRerollOpponents(){
  if(_fwBusy) return;
  _fwBusy=true;
  document.getElementById('fwSpinBtn').disabled=true;
  document.getElementById('fwRerollBtn').disabled=true;
  document.getElementById('fwGoBtn').disabled=true;
  _fwSlotDone=false;
  _fwStartSlot();
}
function _fwPaintReel(el, entry, locked){
  const c=entry.c;
  const av=c.avatarUrl
    ? `<img src="${(window.ASSETS?ASSETS.thumb(c.avatarUrl):c.avatarUrl)}">`
    : `<span class="fw-em">${(CHAR_DEFS[c.charKey]&&CHAR_DEFS[c.charKey].emoji)||'❓'}</span>`;
  el.className='fw-reel'+(locked?' locked':'');
  el.innerHTML=av+`<div class="fw-rn">${_nameParts(c.name).main}</div>`;
}
let _fanSlotSfx=null;
function _fanStopSlot(){
  if(_fanSlotSfx){ try{ _fanSlotSfx.pause(); _fanSlotSfx.currentTime=0; }catch(e){} _fanSlotSfx=null; }
}
let _fwSlotDone=false;        // 🎰 đã bốc xong 3 đối thủ, đang đứng chờ bấm tiếp
let _fwReelEls=[];            // 3 ô loto, giữ lại để tô màu con nào đổi phe
function _fwEnterWheels(){
  _fwSlotDone=false;
  _fwPhase='wheel';
  // 🔀 3 ô đối thủ rời khỏi GIỮA (chỗ của bánh xe) sang cột PHẢI, đứng chung với HUD buff
  document.getElementById('fanWheelOverlay').classList.remove('slotphase');
  document.getElementById('fwHudMemes').appendChild(document.getElementById('fwReels'));
  document.getElementById('fwReels').classList.add('mini');   // sang bánh quay → 3 ô co lại
  _fwAsk(FAN_WHEELS[FAN_ORDER[0]].q, `WHEEL 1 / ${FAN_ORDER.length}`);
  document.getElementById('fwStage').style.display='';
  document.getElementById('fwRes').style.display='';
  document.getElementById('fwSpinBtn').textContent='🎡 SPIN';
  document.getElementById('fwSpinBtn').disabled=false;
  _fwBusy=false;
}
function _fwStartSlot(){
  // 🎰 tiếng máy loto — chạy suốt lúc 3 ô đang cuộn, chốt xong ô cuối là tắt
  _fanStopSlot();
  _fanSlotSfx = AUDIO_SAMPLES['fan_slot']?.cloneNode() || null;
  if(_fanSlotSfx){ _fanSlotSfx.loop=true; _fanSlotSfx.volume=0.85; _mixRoute(_fanSlotSfx); _fanSlotSfx.play().catch(()=>{}); }
  const box=document.getElementById('fwReels');
  box.innerHTML='';
  const reels=[]; _fwReelEls=reels;
  if(fanBuff) fanBuff.recruitIdx=[];
  for(let i=0;i<_fanFoeN;i++){ const d=document.createElement('div'); d.className='fw-reel'; box.appendChild(d); reels.push(d); }
  const pool=_fwRosterPool();
  const chot=[];
  const spin=[];
  reels.forEach((el,i)=>{
    spin[i]=setInterval(()=>_fwPaintReel(el, pool[Math.floor(Math.random()*pool.length)], false), 55);
  });
  // dừng lần lượt trái → phải, mỗi ô cách nhau 0.8s
  reels.forEach((el,i)=>{
    setTimeout(()=>{
      clearInterval(spin[i]);
      let pick=pool[Math.floor(Math.random()*pool.length)];
      // 🎛️ SETUP ROLL: ô nào đã chọn sẵn đối thủ thì chốt đúng con đó
      { const _rg=_fwRig.foes[i]; if(_rg!=null){ const _f=pool.find(x=>x.i===_rg); if(_f) pick=_f; } }
      chot[i]=pick.i;
      _fwPaintReel(el, pick, true);
      playSample('hit_mid',0.5);
      if(i===_fanFoeN-1){
        _fanStopSlot();                       // 🔇 chốt xong ô cuối thì tắt tiếng loto
        _fanIdxs=[_fanIdxs[0], ...chot.slice(0,_fanFoeN)];
        // ⏸️ DỪNG LẠI cho xem mặt 3 đối thủ vừa bốc. Bấm tiếp mới sang bánh quay đầu tiên.
        _fwSlotDone=true;
        _fwAsk('Bro is up against these three.', '');
        document.getElementById('fwSpinBtn').textContent='▶ CONTINUE';
        document.getElementById('fwSpinBtn').disabled=false;
        document.getElementById('fwRerollBtn').disabled=false;   // 🎲 mở lại nút reroll (đã tự khoá lúc bấm)
        _fwBusy=false;
      }
    }, 1300+i*800);
  });
}
function openFanWheel(){
  fanBuff = { hpAdd:0, dmgMul:1, spdMul:1, recruit:0, lives:1, invTicks:0 };
  _fwSpun = 0; _fwRot = 0; _fwBusy = false; _fwPhase='slot'; _fwUsed = new Set(); _fwSlotDone=false;
  // 🔀 quay lại giai đoạn LOTO: 3 ô về CHÍNH GIỮA, bố cục xếp dọc
  document.getElementById('fanWheelOverlay').classList.add('slotphase');
  document.getElementById('fwColMid').appendChild(document.getElementById('fwReels'));
  const wheel = document.getElementById('fwWheel');
  wheel.style.transition = 'none';
  wheel.style.transform = 'rotate(0deg)';
  void wheel.offsetWidth;                       // ép trình duyệt áp ngay, khỏi dính transition cũ
  wheel.style.transition = '';
  _fwKind = FAN_ORDER[0];
  _fwPaintWheel();
  { const _n=document.getElementById('fwNow'); if(_n){ _n.innerHTML=''; _n.classList.remove('locked'); } }
  _fwRenderRes();
  // vào là ở giai đoạn MÁY LOTO: giấu bánh xe, chỉ hiện 3 ô cuộn
  document.getElementById('fwStage').style.display='none';
  document.getElementById('fwRes').style.display='none';
  document.getElementById('fwReels').classList.remove('mini');
  document.getElementById('fwReels').innerHTML=
    '<div class="fw-reel"><span class="fw-em">❔</span><div class="fw-rn">?</div></div>'.repeat(3);
  document.getElementById('fwSpinBtn').textContent='🎰 ROLL OPPONENTS';
  document.getElementById('fwSpinBtn').disabled = false;
  document.getElementById('fwGoBtn').disabled = true;
  _fwAsk('Who are you up against, bro?', 'ROLLING YOUR THREE OPPONENTS');
  document.getElementById('fanWheelOverlay').classList.add('open');
}
// cánh nào đang nằm dưới cái kim ở 12h, theo góc xoay hiện tại của bánh
function _fwSegAt(rotDeg){
  const SP=_fwSpans(), SEG=_fwSeg();
  let a=((-rotDeg)%360+360)%360;          // đảo dấu vì bánh xoay, kim đứng yên
  for(let i=0;i<SP.length;i++) if(a>=SP[i][0] && a<SP[i][1]) return SEG[i];
  return SEG[SEG.length-1];
}
// đọc góc xoay THẬT của bánh (đang giữa chừng transition) từ ma trận CSS
function _fwLiveRot(){
  const m=getComputedStyle(document.getElementById('fwWheel')).transform.match(/matrix\(([^,]+),\s*([^,]+)/);
  return m ? Math.atan2(+m[2], +m[1])*180/Math.PI : 0;
}
function _fwShowNow(seg, chot){
  const el=document.getElementById('fwNow'); if(!el) return;
  el.classList.toggle('locked', !!chot);
  el.style.color = chot ? seg.col : '#fff';
  el.innerHTML = `<span class="fw-nowic">${seg.ic}</span>${seg.nm}`;
}
// bám theo bánh trong suốt lượt quay, mỗi khi đổi cánh thì đổi chữ
let _fwNowRaf=null;
function _fwTrackNow(){
  if(_fwNowRaf) cancelAnimationFrame(_fwNowRaf);
  let _last=null;
  const b=()=>{
    if(!_fwBusy){ _fwNowRaf=null; return; }
    const sg=_fwSegAt(_fwLiveRot());
    if(sg!==_last){ _last=sg; _fwShowNow(sg,false); }
    _fwNowRaf=requestAnimationFrame(b);
  };
  _fwNowRaf=requestAnimationFrame(b);
}
// câu hỏi TO nằm trên bánh xe, dòng nhỏ bên dưới cho biết đang ở vòng nào
function _fwAsk(q, step){
  const el=document.getElementById('fwSub');
  if(!el) return;
  el.innerHTML = q + (step?`<span class="fw-step">${step}</span>`:'');
  // bánh nào khai báo qNho thì câu hỏi của nó nhỏ hơn 1 nấc (câu dài, để nguyên chữ)
  el.classList.toggle('nho', !!(FAN_WHEELS[_fwKind] && FAN_WHEELS[_fwKind].qNho && q===FAN_WHEELS[_fwKind].q));
}
function _fwRenderRes(){
  const box = document.getElementById('fwRes');
  box.innerHTML = '';
  // 🎲 BÀN CỜ CỐ ĐỊNH 6 Ô (2 hàng × 3): tối đa thực tế cũng chỉ 6 (4 buff lẻ + thu phục + mạng).
  // Cố định số ô để bàn KHÔNG nhảy cỡ mỗi lần quay được thêm — ô chưa có thì để trống như ô bàn cờ.
  const n = Math.max(6, _fwRes.length);
  for(let i=0;i<n;i++){
    const got = _fwRes[i];
    const d = document.createElement('div');
    d.className = 'fw-slot' + (got ? ' done' : '');
    if(got) d.style.borderColor = got.col;
    d.innerHTML = got
      ? `<span class="fw-ic">${got.ic}</span>${got.txt}`
      : `<span class="fw-ic">❔</span>—`;
    box.appendChild(d);
  }
}
let _fwRes = [];
function fanSpin(){
  if(_fwBusy) return;
  if(_fwPhase==='slot'){
    if(_fwSlotDone){ _fwEnterWheels(); return; }   // đã bốc xong 3 đối thủ → bấm tiếp là sang bánh quay
    _fwBusy = true;
    document.getElementById('fwSpinBtn').disabled = true;
    _fwStartSlot();
    return;
  }
  if(_fwSpun >= FAN_SPINS) return;
  _fwBusy = true;
  document.getElementById('fwSpinBtn').disabled = true;
  const SP=_fwSpans(), SEG=_fwSeg();
  // bốc theo TRỌNG SỐ, BỎ QUA những múi đã trúng (chúng đang bị tối) — trọng số còn lại tự chia lại phần trăm
  const _con=SEG.map((x,i)=>i).filter(i=>!_fwUsed.has(i));
  const _tong=_con.reduce((a,i)=>a+SEG[i].w,0);
  let _r=Math.random()*_tong, pick=_con[_con.length-1];
  for(const i of _con){ _r-=SEG[i].w; if(_r<=0){ pick=i; break; } }
  // 🎛️ SETUP ROLL: ép bánh dừng đúng ô đã chọn. Bánh BUFF chọn theo TỪNG LƯỢT — lượt thứ mấy thì đếm bằng
  // số ô đã trúng ở bánh này (_fwUsed). Ô đã trúng rồi thì không chọn lại được (nó bị loại khỏi vòng bốc).
  { const _rg = (_fwKind==='buff') ? _fwRig.buff[_fwUsed.size] : _fwRig[_fwKind];
    if(_rg!=null && _con.includes(_rg)) pick=_rg; }
  const _mid=(SP[pick][0]+SP[pick][1])/2;
  // quay thêm nhiều vòng rồi dừng sao cho TÂM múi trúng đúng cái kim ở 12h.
  // ⚠️ TỪNG SAI: trước đây cộng thẳng (360-_mid) vào _fwRot. Nhưng _fwRot đã mang sẵn phần (360-_mid)
  //    của LƯỢT TRƯỚC, nên từ lượt quay thứ 2 kim dừng lệch đúng bằng góc múi lượt trước — bốc 1 đằng,
  //    kim chỉ 1 nẻo (đo được: chỉ 1/4 lượt khớp). Phải tính góc dừng TUYỆT ĐỐI rồi mới ra phần xoay thêm.
  const _cur  = ((_fwRot % 360) + 360) % 360;   // bánh đang đứng ở góc nào
  const _want = ((360 - _mid) % 360 + 360) % 360;  // góc cần dừng để tâm múi trúng nằm dưới kim
  const _delta = ((_want - _cur) % 360 + 360) % 360;
  _fwRot += 360*FAN_SPIN_TURNS + _delta;
  const wheel = document.getElementById('fwWheel');
  wheel.style.transitionDuration = FAN_SPIN_MS+'ms';
  wheel.style.transform = `rotate(${_fwRot}deg)`;
  _fanPlayRoulette();                  // 🎰 tiếng quay — khớp mốc dừng 3.5s của file
  _fwTrackNow();                       // chữ to bám theo cánh đang chạy qua kim
  setTimeout(()=>{
    const s = SEG[pick];
    _fwShowNow(s, true);               // dừng hẳn → chốt tên cánh trúng, tô đúng màu cánh
    let txt;
    if(s.k === 'none'){ txt = 'Nothing'; }
    else if(s.k === 'hp'){ fanBuff.hpAdd += s.v; txt = `+${s.v} max HP`; }
    else if(s.k === 'dmg'){ fanBuff.dmgMul += s.v; txt = `+${Math.round(s.v*100)}% damage`; }
    else if(s.k === 'spd'){ fanBuff.spdMul += s.v; txt = `+${Math.round(s.v*100)}% speed`; }
    else if(s.k === 'inv'){ fanBuff.invTicks = s.v; txt = '5s immortal'; }
    else if(s.k === 'all'){
      // 🌟 ô 1% — ĂN TRỌN MỌI BUFF, ở mức GỐC của từng ô. Đây là GÁN ĐÈ chứ không cộng dồn: quay trước đó
      // được gì cũng bỏ, vì "nhận tất cả" đã bao trùm hết rồi. Trúng ô này là hết bánh buff, sang bánh kế tiếp.
      const _B=FAN_WHEELS.buff.seg, _g=k=>{ const x=_B.find(y=>y.k===k); return x?x.v:0; };
      fanBuff.hpAdd    = _g('hp');
      fanBuff.dmgMul   = 1 + _g('dmg');
      fanBuff.spdMul   = 1 + _g('spd');
      fanBuff.invTicks = _g('inv');
      txt = 'ALL BUFFS!';
    }
    else if(s.k === 'life'){ fanBuff.lives = s.v; txt = s.v>1 ? `${s.v} lives!` : '1 life only'; }
    else {
      // bánh RECRUIT: giá trị nằm sẵn trên múi, chỉ chặn cho khỏi vượt trần 2 con
      const n = Math.min(s.v, FAN_RECRUIT_MAX - fanBuff.recruit);
      fanBuff.recruit += n;
      // 🤝 CHỐT LUÔN con nào đổi phe ngay tại đây (trước đây tới lúc vào trận mới bốc ngẫu nhiên),
      //    để tô được đúng ô của nó trên máy loto và ghi đúng tên ở phần versus.
      if(n>0){
        if(!fanBuff.recruitIdx) fanBuff.recruitIdx=[];
        const _con=[1,2,3].slice(0,_fanFoeN).filter(k=>!fanBuff.recruitIdx.includes(k))
                          .sort(()=>Math.random()-0.5).slice(0,n);
        fanBuff.recruitIdx.push(..._con);
        for(const k of fanBuff.recruitIdx){
          const el=_fwReelEls[k-1]; if(el) el.classList.add('joined');
        }
      }
      txt = n ? (n>1?`${n} joined!`:'1 joined!') : 'Nobody joined';
    }
    _fwRes.push({ ic:s.ic, col:s.col, txt });
    _fwRenderRes();
    _fwBusy = false;
    // 🔁 LUẬT QUAY TIẾP: bánh có chain (bánh BUFF) mà trúng thứ KHÁC 'NOTHING' thì được quay lại ngay trên
    // chính bánh đó — múi vừa trúng bị tối đi, lần sau chỉ còn bốc trong mấy múi còn lại. Trúng NOTHING mới hết.
    // quay lại chỉ khi trúng 1 buff LẺ. Trúng NOTHING (hết lượt) hay ALL BUFFS (đã ăn trọn) đều sang bánh kế tiếp.
    let _chain = FAN_WHEELS[_fwKind].chain && s.k!=='none' && s.k!=='all';
    if(_chain){
      _fwUsed.add(pick);
      // 🌟 ăn đủ CẢ 4 buff lẻ (dmg/spd/hp/inv) rồi thì thôi, khỏi bắt quay thêm: múi còn lại CHỈ còn
      // NOTHING và ALL BUFFS, mà cả hai đều dẫn sang bánh kế tiếp — quay nữa cũng chỉ để chọn "chả được gì".
      const _realIdx = SEG.map((x,i)=>i).filter(i=>SEG[i].k!=='none' && SEG[i].k!=='all');
      if(_realIdx.every(i=>_fwUsed.has(i))) _chain=false;
    }
    if(_chain){
      const _w=document.getElementById('fwWheel');
      _w.style.transition='none'; _w.style.transform='rotate(0deg)';
      void _w.offsetWidth; _w.style.transition=''; _w.style.transitionDuration=FAN_SPIN_MS+'ms';
      _fwRot=0;
      _fwPaintWheel();
      _fwAsk(FAN_WHEELS[_fwKind].q, 'YOU WON A BUFF — SPIN AGAIN!');
      document.getElementById('fwSpinBtn').disabled = false;
      document.getElementById('fwGoBtn').disabled = true;
      return;
    }
    _fwSpun++;
    const het = _fwSpun >= FAN_ORDER.length;
    // 🎡 XONG BÁNH NÀY THÌ THAY MẶT SANG BÁNH KẾ TIẾP — quay lại 0° rồi vẽ lại múi/màu/chữ của bánh mới
    if(!het){
      _fwKind = FAN_ORDER[_fwSpun];
      _fwUsed = new Set();
      const _w=document.getElementById('fwWheel');
      _w.style.transition='none'; _w.style.transform='rotate(0deg)';
      void _w.offsetWidth; _w.style.transition=''; _w.style.transitionDuration=FAN_SPIN_MS+'ms';
      _fwRot=0;
      _fwPaintWheel();
      _fwShowNow(_fwSegAt(0), false);
      _fwAsk(FAN_WHEELS[_fwKind].q, `WHEEL ${_fwSpun+1} / ${FAN_ORDER.length}`);
    }
    document.getElementById('fwSpinBtn').disabled = het;
    document.getElementById('fwGoBtn').disabled = !het;
    // ⛔ BỎ câu chốt tổng kết buff: quay xong bánh thứ 3 là bấm FIGHT vào trận luôn, không cần
    //    thêm một màn đọc lại chỉ số. Giữ nguyên kết quả vừa quay được trên màn cho gọn.
    if(false) document.getElementById('fwSub').textContent =
      `+${fanBuff.hpAdd} HP · DMG ×${fanBuff.dmgMul.toFixed(2)} · SPD ×${fanBuff.spdMul.toFixed(2)}`
      +` · ${fanBuff.recruit} joined · ${fanBuff.lives} ${fanBuff.lives>1?'lives':'life'}`
      +(fanBuff.invTicks?' · 5s immortal':'');
  }, FAN_SPIN_MS+120);   // khớp với thời gian transition của bánh xe, chờ thêm chút cho nó dừng hẳn
}
// ◀ bỏ giữa chừng: dọn sạch mọi thứ của lượt quay rồi về menu chính
function fanWheelBack(){
  _fanStopRoulette(); _fanStopSlot();
  if(_fwNowRaf){ cancelAnimationFrame(_fwNowRaf); _fwNowRaf=null; }
  _fwBusy=false; _fwRes=[]; _fwSpun=0; _fwUsed=new Set(); _fanPickKey=null; _fanIdxs=[];
  fanBuff=null;
  document.getElementById('fanWheelOverlay').classList.remove('open');
  document.querySelectorAll('.screen').forEach(el=>el.classList.remove('active'));
  document.getElementById('mainMenuScreen').classList.add('active');
}
function fanWheelDone(){
  document.getElementById('fanWheelOverlay').classList.remove('open');
  _fanEnterBattle();
}


// ===================== ⭐ FAN SERVICE — NHÂN VẬT CỦA NGƯỜI BÌNH LUẬN =====================
// Mỗi người xem để lại bình luận sẽ có 1 NHÂN VẬT RIÊNG với SKILL RIÊNG do chính họ nghĩ ra.
// Đây KHÔNG phải meme trong roster: nó không dùng chung khối code nào của 56 con kia, nên thêm bao nhiêu
// người cũng không đụng tới gameplay sẵn có.
//
// 👉 THÊM 1 NGƯỜI MỚI: chép nguyên 1 khối dưới đây rồi sửa. Mọi hàm đều KHÔNG BẮT BUỘC — bỏ hàm nào thì
//    nhân vật chỉ đơn giản không có phần đó.
//      name    : tên hiện trên sàn. KHÔNG tự đặt biệt hiệu — chỉ thêm phần " - Biệt hiệu" khi được yêu cầu.
//      avatar  : ảnh đại diện YouTube (data URI). Bỏ trống thì hiện emoji.
//      hp/size/speed : máu, cỡ, tốc chạy. Để trống lấy mặc định 1000 / 48 / 5.
//      desc    : 1 câu ngắn hiện dưới sàn lúc vào trận.
//      init(f)            : chạy 1 lần lúc vào trận — đặt biến trạng thái riêng.
//      tick(f,e,dist,cham): chạy MỖI FRAME — chỗ viết thân skill. e=địch gần nhất, cham=đang chạm địch.
//      draw(f,s)          : vẽ thêm quanh nhân vật (s = cỡ đang vẽ). Gọi sau khi đã vẽ quả bóng.
//      onHurt(f,dmg,atk)  : gọi mỗi khi ăn dame. Trả về true = CHẶN đòn đó lại.
const MSP_AXE_IMG = new Image(); MSP_AXE_IMG.src='assets/img/mosquitoviolin/MSP_AXE_IMG.webp'; // 🪓 TheGreatMagicspeller (Commenter Battle) — rìu kim cương user cung cấp, lưỡi chếch trên-phải, cán chếch dưới-trái
// 🪓 TheGreatMagicspeller: vung RÌU KIM CƯƠNG cận chiến y kiểu đại kiếm Berserk Cat — 1 đường vòng cung bổ về phía
//    địch, dame rơi ở 55% nhát vung, trúng MỌI kẻ địch trong tầm (bình luận: "251 damage to every meme who gets
//    close"). 0.6 nhát/giây THẬT. Dùng chung cho thân chính (Fighter) và bản sao (mspClones).
// Ảnh rìu (538×539): cán chéo từ góc DƯỚI-TRÁI lên, lưỡi ở góc TRÊN-PHẢI; chỗ tay cầm ~(20%,84%); trục cán ≈ -50°.
const MSP_SWING_T=16, MSP_DMG=251;
const MSP_AXE_LK=1.9;   // chiều dài rìu = 1.9 × cỡ người — DÙNG CHUNG cho phần vẽ vệt chém VÀ vùng gây dame, để chém trúng đâu là ăn dame đó
// thân v có chạm vào VÒNG CUNG rìu quét qua không (cùng hình học với vệt chém vẽ ở _mspDrawAxes)
function _mspInArc(u,v){
  const d=u._mspDir||1, aim=u._mspAim||0, a0=aim-d*2.4, a1=aim+d*0.8, lo=Math.min(a0,a1), hi=Math.max(a0,a1);
  const px=u.x+d*u.size*0.1, py=u.y-u.size*0.1, dx=v.x-px, dy=v.y-py, dist=Math.hypot(dx,dy), vr=(v.size||20)*0.85;
  if(dist > u.size*MSP_AXE_LK*1.02+vr) return false;
  if(dist < u.size*0.6+vr) return true;                         // sát người thì chắc chắn dính
  let a=Math.atan2(dy,dx); const pad=Math.asin(Math.min(1,vr/dist));
  while(a<lo-pad) a+=Math.PI*2; while(a>hi+pad) a-=Math.PI*2;
  return a>=lo-pad && a<=hi+pad;
}
const MSP_AXE_GRIP={x:0.2, y:0.84}, MSP_AXE_ANG=Math.atan2(100-450, 400-110), MSP_AXE_LEN_W=632/538;
const _mspAtkCD=()=>Math.round(60*GAME_SPEED*TIME_SCALE/0.6);      // 0.6 nhát/giây thật
const _mspReach=()=>MELEE_REACH*1.2;                               // tầm như đại kiếm Berserk
function _mspFoes(team){ const out=[];
  for(const arr of _hpSummonArrays()) for(const u of arr) if(u && !u.dead && u.team!==team && !(u.hp<=0)) out.push(u);   // thân phụ TRƯỚC
  for(const o of fighters) if(!o.dead && o.team!==team) out.push(o);
  return out; }
// u: thân đang vung (có x,y,size,team). foe: địch gần nhất. src: ai được ghi công dame. stunned: đang choáng thì không vung mới.
function _mspSwingTick(u, foe, src, stunned){
  u._mspCDt=Math.max(0,(u._mspCDt||0)-1);
  if((u._mspSwingT||0)>0){
    u._mspSwingT--;
    if(!u._mspHit && 1-u._mspSwingT/MSP_SWING_T>=0.55){
      u._mspHit=true; let any=false;
      for(const v of _mspFoes(u.team)){
        if(!_mspInArc(u,v)) continue;   // trúng theo ĐÚNG vệt chém nhìn thấy
        v.takeDamage(MSP_DMG, src); any=true;
        if(v.vx!==undefined && !v.dead){ const ka=Math.atan2(v.y-u.y,v.x-u.x); v.vx=Math.cos(ka)*BK_KNOCK; v.vy=Math.sin(ka)*BK_KNOCK; }   // lùi tí ti như Berserk
        _hitParticles(v.x,v.y,'#4dd0e1',8,false,true);
      }
      if(any){ playSample('mewing_statue_break',0.7); addShake(6,9); }   // tiếng trúng của tượng Mewing Cat
    }
    return;
  }
  if(foe && !foe.dead && !stunned && u._mspCDt<=0 && Math.hypot(foe.x-u.x,foe.y-u.y) < u.size*MSP_AXE_LK*0.95+(foe.size||20)*0.85){   // địch lọt vào tầm rìu thì vung
    u._mspSwingT=MSP_SWING_T; u._mspHit=false;
    u._mspAim=Math.atan2(foe.y-u.y, foe.x-u.x); u._mspDir=(foe.x>=u.x)?1:-1;
    u._mspCDt=_mspAtkCD();
    if(u.actionState!==undefined){ u.actionState='attack'; u.actionTimer=MSP_SWING_T; }
  }
}
function _mspDrawAxe(hx,hy,ang,L,d){
  const im=MSP_AXE_IMG;
  if(!(im.complete && im.naturalWidth>0)){ ctx.save(); ctx.font=`${Math.round(L*0.7)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('🪓',hx+Math.cos(ang)*L*0.5,hy+Math.sin(ang)*L*0.5); ctx.restore(); return; }
  const w=L/MSP_AXE_LEN_W, h=w*im.naturalHeight/im.naturalWidth;
  ctx.save(); ctx.translate(hx,hy); ctx.rotate(ang);
  if(d>0) ctx.scale(1,-1);                          // lật qua trục cán cho LƯỠI rìu luôn đi trước theo chiều vung (trước đây ngược mặt)
  ctx.rotate(-MSP_AXE_ANG);
  ctx.drawImage(im, -MSP_AXE_GRIP.x*w, -MSP_AXE_GRIP.y*h, w, h);
  ctx.restore();
}
// vẽ rìu đang vung + vệt chém XANH KIM CƯƠNG (y khuôn Berserk, đổi màu đỏ → xanh). Rìu chỉ hiện lúc đang chém.
function _mspDrawAxes(){
  const units=[];
  for(const f of fighters) if(fanCtx && f._fanSkillKey==='magicspeller' && !f.dead) units.push(f);
  for(const c of mspClones) if(!c.dead && c.hp>0) units.push(c);
  const foeAlive=team=>fighters.some(o=>o.team!==team && !o.dead);
  for(const u of units){
    // nhát chém KẾT LIỄU: hết địch thì tick không còn đếm → tự vung nốt cho khỏi đứng hình (cùng lỗi Berserk đã gặp)
    if((u._mspSwingT||0)>0 && !battleFreezeTimer && !foeAlive(u.team)) u._mspSwingT--;
    if(!((u._mspSwingT||0)>0)) continue;
    const s=u.size, L=s*MSP_AXE_LK, d=u._mspDir||1, aim=u._mspAim||0;
    const a0=aim-d*2.4, a1=aim+d*0.8;
    const pr=1-u._mspSwingT/MSP_SWING_T, e=1-Math.pow(1-pr,3), a=a0+(a1-a0)*e;
    const px=u.x+d*s*0.1, py=u.y-s*0.1, lo=Math.min(a0,a), hi=Math.max(a0,a);
    ctx.save(); ctx.globalAlpha=0.38*(1-pr*0.6);
    ctx.fillStyle='#29b6f6';
    ctx.beginPath(); ctx.arc(px,py,L*1.02,lo,hi); ctx.arc(px,py,L*0.55,hi,lo,true); ctx.closePath(); ctx.fill();
    ctx.globalAlpha=0.3*(1-pr*0.6); ctx.fillStyle='#b2ebf2';
    ctx.beginPath(); ctx.arc(px,py,L*1.02,lo,hi); ctx.arc(px,py,L*0.85,hi,lo,true); ctx.closePath(); ctx.fill();
    ctx.globalAlpha=0.6*(1-pr*0.6); ctx.strokeStyle='#ffffff'; ctx.lineWidth=Math.max(1.5,s*0.05);
    ctx.beginPath(); ctx.arc(px,py,L*0.98,lo,hi); ctx.stroke();
    ctx.restore();
    _mspDrawAxe(px,py,a,L,d);
  }
}
// bản sao vẽ y hệt QUẢ BÓNG avatar của thân chính (xem nhánh _fanBall trong Fighter.draw)
function _mspDrawCloneBall(mc){
  const own=mc.owner, img=own ? avatarImgs[own.slotIdx] : null, R=mc.size;
  ctx.save(); ctx.translate(mc.x,mc.y);
  ctx.globalAlpha=0.22; ctx.fillStyle='#000'; ctx.beginPath(); ctx.ellipse(0,R*0.92,R*0.78,R*0.2,0,0,Math.PI*2); ctx.fill(); ctx.globalAlpha=1;
  const fl = own && own.facingDefault==='left' ? mc._facingRight : !mc._facingRight;   // quay mặt về địch như thân chính
  ctx.save(); if(fl) ctx.scale(-1,1);
  ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.clip();
  ctx.fillStyle='#12121f'; ctx.fillRect(-R,-R,R*2,R*2);
  if(img && img.complete && img.naturalWidth>0){
    const sw=img.naturalWidth, sh=img.naturalHeight, ar=sw/sh, sq=(ar>0.75&&ar<1.34); let cw,ch;
    if(sq){ if(ar>=1){ ch=R*2; cw=ch*ar; } else { cw=R*2; ch=cw/ar; } } else { const D=R*1.92; if(ar>=1){ cw=D; ch=D/ar; } else { ch=D; cw=D*ar; } }
    ctx.drawImage(img,-cw/2,-ch/2,cw,ch);
  } else { ctx.font=`${Math.round(R*1.3)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('🪓',0,0); }
  const g=ctx.createRadialGradient(-R*0.35,-R*0.4,R*0.1,0,0,R*1.15);
  g.addColorStop(0,'rgba(255,255,255,0.30)'); g.addColorStop(0.45,'rgba(255,255,255,0)'); g.addColorStop(1,'rgba(0,0,0,0.45)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.fill();
  ctx.restore();
  ctx.lineWidth=Math.max(2,R*0.10); ctx.strokeStyle=_teamColor(mc.team); ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.stroke();
  ctx.lineWidth=Math.max(1,R*0.04); ctx.strokeStyle='rgba(255,255,255,0.55)'; ctx.beginPath(); ctx.arc(0,0,R*0.9,-2.5,-0.9); ctx.stroke();
  ctx.restore();
}
const TS_EYE={x:-0.3, y:-0.12};
// 🪝 vẽ 1 cây lao móc (mũi có ngạnh) ở toạ độ thế giới, mũi tại (x,y) hướng theo góc a; chain=true thì kéo dây xích về chủ
function _tsDrawHarpoon(f, x, y, a, red, chain){
  const len=46, ca=Math.cos(a), sa=Math.sin(a), tx=x-ca*len, ty=y-sa*len;
  ctx.save(); ctx.lineCap='round'; ctx.lineJoin='round';
  if(chain){
    const fx=f.x+ca*f.size*0.7, fy=f.y+sa*f.size*0.7, dx=tx-fx, dy=ty-fy, L=Math.hypot(dx,dy);
    ctx.strokeStyle='#263238'; ctx.lineWidth=3; ctx.beginPath(); ctx.moveTo(fx,fy); ctx.lineTo(tx,ty); ctx.stroke();
    const n=Math.floor(L/9), ang=Math.atan2(dy,dx);
    for(let i=0;i<n;i++){ const q=(i+0.5)/n; ctx.save(); ctx.translate(fx+dx*q, fy+dy*q); ctx.rotate(ang);
      ctx.strokeStyle=i%2?'#90a4ae':'#b0bec5'; ctx.lineWidth=1.8; ctx.beginPath();
      if(i%2) ctx.moveTo(-4,0), ctx.lineTo(4,0); else ctx.ellipse(0,0,5,2.6,0,0,Math.PI*2);
      ctx.stroke(); ctx.restore(); }
  }
  ctx.strokeStyle='#37474f'; ctx.lineWidth=5; ctx.beginPath(); ctx.moveTo(tx,ty); ctx.lineTo(x-ca*12,y-sa*12); ctx.stroke();   // cán
  ctx.strokeStyle='#78909c'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(tx,ty); ctx.lineTo(x-ca*12,y-sa*12); ctx.stroke();
  ctx.translate(x,y); ctx.rotate(a);                                                  // mũi lao có 2 ngạnh
  if(red){ ctx.shadowColor='#ff1744'; ctx.shadowBlur=12; }
  ctx.fillStyle=red?'#ff8a80':'#eceff1'; ctx.strokeStyle='#263238'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(-14,-6); ctx.lineTo(-10,-2); ctx.lineTo(-20,-9); ctx.lineTo(-16,0);
  ctx.lineTo(-20,9); ctx.lineTo(-10,2); ctx.lineTo(-14,6); ctx.closePath(); ctx.fill(); ctx.stroke();
  ctx.restore();
}   // 🔴 tanphamnhat969: chỗ MẮT TRÁI trên avatar (đơn vị = cỡ đang vẽ s) — chỉnh khi có ảnh thật
const FAN_SKILLS = {
  // ————————————————————————————————————————————————————————————————
  // @Train_Kidd — "constantly spinning and dealing 5 damage per hit
  //                (and healing 1 health for itself per hit)"
  // ————————————————————————————————————————————————————————————————
  trainkidd: {
    name: 'Train_Kidd',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    // Máu/tốc xuất phát như mọi meme; sức mạnh dồn hết vào đòn quay.
    // 50 dame × 5 nhát/giây = 250 dame/giây lên MỖI mục tiêu đang chạm.
    hp: 1000, size: 48, speed: 5,
    desc: 'Never stops spinning. Everyone it touches takes 50, gives it 1 HP back, and speeds it up 2% — the more it hits, the faster it goes.',
    init(f){ f._tkHit={}; },
    tick(f, e, dist, cham){
      // 🌀 quay không ngừng — góc quay dùng cho phần vẽ quả bóng
      f._fsSpin = (f._fsSpin||0) + 0.34;     // nhịp quay khớp với nhịp đánh
      // đếm lùi hồi chiêu RIÊNG cho từng nạn nhân, để 1 con không ăn 2 lần trong cùng nhịp
      for(const k in f._tkHit){ if(f._tkHit[k]>0) f._tkHit[k]--; }
      // chạm ai cũng ăn: cả meme lẫn quân triệu hồi có máu
      const _an=(u)=>{
        if(!u || u.dead || u.team===f.team || (u.hp!==undefined && u.hp<=0)) return;
        const _id = u.id || ('f'+u.slotIdx);
        if(f._tkHit[_id]>0) return;
        // 📏 dùng ĐÚNG chuẩn melee chung (size + size + MELEE_REACH). Trước đây thiếu MELEE_REACH nên
        //    tầm với ngắn hơn mọi con khác 16.17px — nhìn đã chạm nhau mà không ăn dame.
        if(Math.hypot(u.x-f.x, u.y-f.y) >= f.size+u.size+MELEE_REACH) return;
        f._tkHit[_id]=12;                      // 5 nhát/giây lên cùng 1 mục tiêu
        u.takeDamage(50, f);
        if(f.hp<f.maxHp){ f.hp=Math.min(f.maxHp, f.hp+1); }   // mỗi nhát tự hồi 1 máu (đúng như bình luận)
        // 🏃 CỘNG DỒN: mỗi nhát gây dame lại +2% tốc di chuyển, càng đánh càng nhanh. KHÔNG có trần.
        f.topSpeed *= 1.02;
        f._tkSpdStack = (f._tkSpdStack||0) + 1;
        _hitParticles(u.x, u.y, '#9ccc65', 4, false, true);
      };
      for(const o of fighters) if(o!==f) _an(o);
      for(const arr of _hpSummonArrays()) for(const u of arr) _an(u);
    },
  },

  // ————————————————————————————————————————————————————————————————
  // @李昱霏 (Li Xianfei) — "i have a insanely small hitbox have 500 base health and move
  //                        insanely slow, but i deal 100 damage on impact"
  //  ⚠️ máu chốt lại 1000 theo yêu cầu của m (bỏ số 500 gốc trong comment cho đơn giản)
  // ————————————————————————————————————————————————————————————————
  lixianfei: {
    name: 'Li Xianfei',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    hp: 1000, size: 30, speed: 1,   // size ~ nửa mặc định (48) rồi +25% theo yêu cầu (24→30), speed cực chậm so với mọi meme khác (5)
    desc: 'Tiny hitbox, moves painfully slowly, dodges 25% of incoming hits — but touch it and it hits back for 100.',
    init(f){ f._lxfCD=0; },
    tick(f, e, dist, cham){
      f._lxfCD=Math.max(0,(f._lxfCD||0)-1);
      if(!e || e.dead || !cham || f._lxfCD>0) return;
      e.takeDamage(100, f);
      playSample('punch2',0.7);
      addShake(6,9);
      f._lxfCD=45; // 0.75s hồi chiêu, cùng nhịp húc của Gigachad
      f.actionState='attack'; f.actionTimer=24; f.attackAvatarTimer=24;
    },
    onHurt(f, dmg, atk){
      // 🎯 hitbox cực nhỏ → né hẳn 25% đòn đánh, vô điều kiện
      return Math.random()<0.25;
    },
  },

  // ————————————————————————————————————————————————————————————————
  // @henrry13devotina — "I continuously fire lasers at the memes from a medium distance;
  //                      the longer I maintain the range, the greater the damage.
  //                      laser start with 10 damage and buildup +20 each s"
  // ⚠️ CHỈ dùng cho Commenter Battle (FAN_SKILLS) — KHÔNG đụng vào roster 56 con chính.
  // ————————————————————————————————————————————————————————————————
  henrry13devotina: {
    name: 'henrry13devotina',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    hp: 1000, size: 48, speed: 5,
    desc: "Locks a laser onto whoever steps into medium range. The longer the beam holds, the harder it hits — it only breaks when they run out of range.",
    init(f){ f._hlTarget=null; f._hlRangeT=0; f._hlHitCD=0; },
    tick(f, e, dist, cham){
      const MED_MIN=130, MED_MAX=336;   // tam trung: qua gan (can chien) hay qua xa deu khong ban duoc (tam xa giam 20%: 420 -> 336)
      if(f._hlTarget && (f._hlTarget.dead || (f._hlTarget.hp!==undefined && f._hlTarget.hp<=0))) f._hlTarget=null;
      if(!f._hlTarget){
        let best=null, bestD=Infinity;
        for(const o of fighters){
          if(o===f || o.team===f.team || o.dead) continue;
          const d=Math.hypot(o.x-f.x, o.y-f.y);
          if(d>=MED_MIN && d<=MED_MAX && d<bestD){ best=o; bestD=d; }
        }
        if(best){ f._hlTarget=best; f._hlRangeT=0; }
      }
      const t=f._hlTarget;
      if(!t){ f._hlRangeT=0; return; }
      const d=Math.hypot(t.x-f.x, t.y-f.y);
      // ⚠️ CHỈ mất khoá khi địch RA KHỎI TẦM (xa quá MED_MAX). Địch lao vào sát người thì tia VẪN giữ và
      // dame tích tiếp — trước đây gần quá cũng reset, nên cứ áp sát là tia đứt liên tục.
      if(d>MED_MAX){ f._hlTarget=null; f._hlRangeT=0; return; }
      f._hlRangeT++;
      f._hlHitCD=Math.max(0,(f._hlHitCD||0)-1);
      if(f._hlHitCD<=0){
        const dmg = 7 + 14*Math.floor(f._hlRangeT/60);   // giảm 30% (gốc 10 + 20/giây giữ được tia)
        t.takeDamage(dmg, f);
        playSample('mc_sfx_laser',0.32);
        f._hlHitCD=18;
      }
    },
  },

  // ————————————————————————————————————————————————————————————————
  // @TheGreatMagicspeller — "I simply do 251 damage to every meme who gets close with a
  //                          Diamond Axe, and can make a clone every 5 seconds that can do
  //                          the exact same thing, but they have only 251 hp and cannot
  //                          clone. I have 1000 hp. I fight 3 memes."
  //  (gian luoc theo dung yeu cau - "simpler version"; "toi dau 3 con" chi la mo ta luat
  //   san co cua Commenter Battle, khong phai co che rieng can code them)
  // ⚠️ CHỈ dùng cho Commenter Battle (FAN_SKILLS) — KHÔNG đụng vào roster 56 con chính.
  // ————————————————————————————————————————————————————————————————
  magicspeller: {
    name: 'TheGreatMagicspeller',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    hp: 1000, size: 48, speed: 5,
    desc: "Swings a Diamond Axe for 251 at everyone in reach. Every 5s it splits off a clone of itself — same axe, same 251, but only 251 HP and no cloning.",
    init(f){ f._mspCDt=0; f._mspSwingT=0; f._mspCloneCD=Math.round(2.5*60*GAME_SPEED*TIME_SCALE); },
    tick(f, e, dist, cham){
      // 🪓 vung rìu kim cương kiểu Berserk (xem _mspSwingTick)
      _mspSwingTick(f, e, f, f._isHardCC());
      // 👥 mỗi 5s THẬT: tách ra 1 BẢN SAO của chính nó (cùng quả bóng avatar, cùng rìu), chỉ 251 máu, không tự nhân bản
      f._mspCloneCD=Math.max(0,(f._mspCloneCD||0)-1);
      if(f._mspCloneCD<=0 && !f.dead){
        const _a=Math.random()*Math.PI*2;
        mspClones.push({
          team:f.team, owner:f, x:Math.max(f.size,Math.min(W-f.size,f.x+Math.cos(_a)*70)), y:Math.max(f.size,Math.min(H-f.size,f.y+Math.sin(_a)*70)),
          hp:MSP_DMG, maxHp:MSP_DMG, size:f.size, vx:Math.cos(_a)*3, vy:Math.sin(_a)*3, _lastAngle:_a, flash:0, dead:false, _mspCDt:0, _mspSwingT:0,
          takeDamage(dmg,attacker,isHuh,isBurn,dotIcon,hitFx){ _summonTakeDamage(this, dmg, attacker, isHuh, isBurn, dotIcon, hitFx); },
        });
        f._mspCloneCD=Math.round(5*60*GAME_SPEED*TIME_SCALE);
        spawnParticles(f.x,f.y,'#4dd0e1',10,false,true);
      }
    },
  },
  // ————————————————————————————————————————————————————————————————
  // @Firdhan_snowboarder — "i throw snowballs at my enemy that deals just 5 dmg,
  //                         my ability is 'snowdash' which deals like 100 dmg every 10 sec" (dame bóng tuyết 5 → 12 theo yêu cầu)
  //                        (đổi lại theo yêu cầu: snowdash không gây dame, thành đòn đẩy văng + để lại
  //                        vệt tuyết làm chậm, chu kỳ rút xuống 5s)
  // ————————————————————————————————————————————————————————————————
  firdhansnowboarder: {
    name: 'Firdhan_snowboarder',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    hp: 1000, size: 48, speed: 3,
    desc: 'Pelts the whole arena with snowballs, five a second for 12 dmg each. Every 5s it dashes through, knocking enemies back and leaving a 5s snow trail that slows anyone standing in it.',
    init(f){
      f._fsThrowCD=0;
      f._fsDashCD=150;   // nửa chu kỳ đầu (2.5s) để ném tuyết vài phát trước khi dash lần đầu
      f._fsTrail=[];     // {x,y,t} — mỗi điểm tự hết hạn sau 300 tick (5s), xem khối vẽ world-space trong loop()
      f._fsBalls=[];     // bóng tuyết tự bắn, hand-roll riêng KHÔNG qua mảng projectiles chung
      f._fsDashing=0;
      f._fsDashHitSet=new Set();
    },
    tick(f, e, dist, cham){
      // dọn vệt tuyết đã hết hạn
      if(f._fsTrail.length) f._fsTrail=f._fsTrail.filter(p=>(tick-p.t)<300);

      // di chuyển + va chạm bóng tuyết đang bay
      for(let _bi=f._fsBalls.length-1;_bi>=0;_bi--){
        const b=f._fsBalls[_bi];
        b.x+=b.vx; b.y+=b.vy; b.life--;
        let _hit=false;
        for(const other of [...fighters, ..._summonFoes(f.team)]){   // bóng tuyết trúng cả quân triệu hồi
          if(other.dead || other.team===f.team) continue;
          if(Math.hypot(other.x-b.x, other.y-b.y) < b.size+(other.size||20)){
            other.takeDamage(12, f);
            _hit=true;
            // ❄️ trúng bóng tuyết: bung 1 chùm bông tuyết li ti (cùng kiểu bông tuyết của VFX slow mới) rồi tắt
            _snowBurst(other.x, other.y, other.size);
            _hitParticles(other.x,other.y,'#e1f5fe',6,false,true);
            break;
          }
        }
        if(_hit || b.life<=0 || b.x<-20||b.x>W+20||b.y<-20||b.y>H+20) f._fsBalls.splice(_bi,1);
      }

      // đang trong lượt DASH: lướt thẳng theo hướng đã chốt, để lại vệt tuyết, đẩy văng ai bị chạm
      if(f._fsDashing>0){
        f.x+=f._fsDashVx; f.y+=f._fsDashVy;
        f.x=Math.max(f.size, Math.min(W-f.size, f.x));
        f.y=Math.max(f.size, Math.min(H-f.size, f.y));
        if((f._fsDashing%3)===0) f._fsTrail.push({x:f.x,y:f.y,t:tick});
        for(const other of [...fighters, ..._summonFoes(f.team)]){
          if(other===f || other.dead || other.team===f.team || f._fsDashHitSet.has(other)) continue;
          if(Math.hypot(other.x-f.x, other.y-f.y) < f.size+(other.size||20)+MELEE_REACH){
            const ka=Math.atan2(other.y-f.y, other.x-f.x);
            other.vx=Math.cos(ka)*12; other.vy=Math.sin(ka)*12;
            f._fsDashHitSet.add(other);
            _hitParticles(other.x,other.y,'#e1f5fe',10,false,true);
          }
        }
        f._fsDashing--;
        if(f._fsDashing<=0){ f._fsDashCD=300; f._fsDashHitSet.clear(); } // 5s tới lượt dash kế
        return; // đang dash thì không ném tuyết cùng lúc
      }
      f._fsDashCD=Math.max(0,(f._fsDashCD||0)-1);
      if(f._fsDashCD<=0 && e && !e.dead){
        const dAng=Math.atan2(e.y-f.y, e.x-f.x);
        f._fsDashVx=Math.cos(dAng)*10; f._fsDashVy=Math.sin(dAng)*10;
        f._fsDashing=36; // ~0.6s lướt (~360px) — kéo dài hơn để có cơ hội xuyên qua NHIỀU địch trên đường lướt
        f._fsDashHitSet.clear();
        playSample('hit_mid',0.4);
        return;
      }

      // ném bóng tuyết liên tục
      f._fsThrowCD=Math.max(0,(f._fsThrowCD||0)-1);
      // 🎯 TẦM CẢ SÀN: bỏ hẳn chốt dist<400 — đứng đâu cũng ném. Tuổi bóng 200 tick × tốc 7 = 1400px,
      //    thừa sức bay hết đường chéo sàn (sàn Commenter 815×781 → chéo ~1128px).
      if(f._fsThrowCD<=0 && e && !e.dead){
        const ang=Math.atan2(e.y-f.y, e.x-f.x);
        f._fsBalls.push({x:f.x,y:f.y,vx:Math.cos(ang)*7,vy:Math.sin(ang)*7,size:9,life:200});
        f._fsThrowCD=12; // 5 quả/giây (60 tick ÷ 5)
        playSample('hit_light',0.3);
      }

      // ai đứng trong vệt tuyết (của phe địch) thì bị chậm — refresh liên tục, tự hết khi bước ra
      for(const other of fighters){
        if(other===f || other.dead || other.team===f.team) continue;
        for(const p of f._fsTrail){
          if(Math.hypot(other.x-p.x, other.y-p.y)<34){ other._slowTimer=Math.max(other._slowTimer||0,20); break; }
        }
      }
    },
  },

  // ————————————————————————————————————————————————————————————————
  // @HamodehHamodeh-w3u — "Can I be next? So basically I'm like beluga, Except the messages are my daily
  //                       comments. You can choose the variants of some of them. But 3 of them are critical.
  //                       And I get 35% damage and I send my messages a little bit faster when I'm at 25% hp"
  //  → dùng lại NGUYÊN bộ chat của Beluga (bong bóng đang gõ, tiếng gõ phím, tin nhắn bay đuổi theo địch, cùng
  //    bậc dame theo độ dài tin + tỉ lệ ra tin đỏ có "pity"). Chỉ khác: nội dung là bình luận hằng ngày của anh
  //    ta, và đúng 3 câu là CHÍ MẠNG (đỏ). Dưới 25% máu: +35% dame, gõ nhanh hơn 25%.
  //    Nội dung lấy từ bình luận THẬT của anh ta dưới các video trận đấu (đa số là react về các meme), thêm vài câu
  //    cùng giọng: "Nein lose!", "The mlems are too op!", "HE GOT COOKED", "What's a wooden sword gonna do bro"...
  // ⚠️ CHỈ dùng cho Commenter Battle (FAN_SKILLS) — KHÔNG đụng vào roster 56 con chính.
  // ————————————————————————————————————————————————————————————————
  hamodehw3u: {
    name: 'HamodehHamodeh-w3u',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    hp: 1000, size: 48, speed: 5,
    desc: "Beluga, but every message is one of his daily comments — and three of them crit. Below 25% HP he types faster and hits 35% harder.",
    init(f){ f.belugaChatCD=63; f.belugaChatTimer=0; f.belugaPity=0; f._belugaPending=null; },
    tick(f, e, dist, cham){
      const low = f.hp <= f.maxHp*0.25;
      const TYPE_T = low ? 63 : 84, AFTER_CD = low ? 92 : 123;     // dưới 25% máu: gõ + nghỉ đều nhanh hơn 25%
      f.belugaChatCD = Math.max(0, (f.belugaChatCD||0) - 1);
      if(f.belugaChatTimer > 0){
        f.belugaChatTimer--;
        if(f.belugaChatTimer === 0){
          if(e && !e.dead && f._belugaPending){
            const {dmg, msgText, msgColor} = f._belugaPending;
            const dx=e.x-f.x, dy=e.y-f.y, d=Math.hypot(dx,dy)||1;
            const spd = dmg>=300 ? 22 : dmg>=80 ? 10 : dmg>=50 ? 13 : 16;
            const life = dmg>=300 ? 80 : dmg>=80 ? 130 : dmg>=50 ? 110 : 90;
            projectiles.push({ x:f.x, y:f.y-f.size, vx:dx/d*spd, vy:dy/d*spd, team:f.team, owner:f, dmg, life, maxLife:life,
              isBelugaMsg:true, msgText, msgColor, size:6, target:e });
            playSample('beluga_text', 0.85);
          }
          f._belugaPending = null;
          if(f._belugaTypeSfx){ try{ f._belugaTypeSfx.pause(); f._belugaTypeSfx.currentTime=0; }catch(_){} f._belugaTypeSfx=null; }
          f.belugaChatCD = AFTER_CD;
        }
        return;
      }
      if(f.belugaChatCD > 0 || !e || e.dead || f._isHardCC()) return;
      // 📝 chọn tin TRƯỚC khi gõ (để bong bóng hiện dần từng ký tự) — cùng tỉ lệ/bậc dame như Beluga
      const pick = a => a[Math.floor(Math.random()*a.length)];
      const roll = Math.random(), critChance = 0.15 + (f.belugaPity||0);
      let dmg, msgText, msgColor = '#80deea';
      if(roll < critChance){
        f.belugaPity = 0;
        dmg = 300; msgColor = '#ff1744';          // 🔴 3 câu CHÍ MẠNG
        msgText = pick(['HE GOT COOKED', 'NEIN LOSE!', 'THE MLEMS ARE TOO OP!']);
      } else {
        f.belugaPity = (f.belugaPity||0) + 0.05;
        if(roll < critChance+0.25){
          dmg = 100 + Math.floor(Math.random()*21);
          msgText = pick(['This guy is better at music than electric guitar cat omg',
                          'Chonky fell on him five times and I laughed every single time',
                          'Epic Sax Guy turned this whole fight into a concert bro',
                          'Catler really saluted his way out of that one 😭']);
        } else if(roll < critChance+0.55){
          dmg = 70 + Math.floor(Math.random()*21);
          msgText = pick(['He chunky ma boii', 'Damn a banger with my breakfast', 'Bro LET him complete his sentence 😭',
                          "What's a wooden sword gonna do bro", 'Pop cat drooled on my screen', 'Rick rolled AGAIN bro']);
        } else {
          dmg = 40 + Math.floor(Math.random()*11);
          msgText = pick(['Can I be next?', 'W mlem', 'HUH?', 'bro 😭', 'chunky boii', 'cooked', 'W sax', 'nein', '👀', 'banger']);
        }
      }
      if(low) dmg = Math.round(dmg*1.35);       // 💢 dưới 25% máu: +35% dame
      f._belugaPending = { dmg, msgText, msgColor };
      f.belugaChatTimer = TYPE_T; f._belugaTypeT = TYPE_T;
      // ⌨️ tiếng gõ phím y như Beluga: tốc độ phát theo số ký tự / thời gian gõ
      const rate = Math.max(0.7, Math.min(2.0, (msgText.length/26)*(84/TYPE_T)));
      if(f._belugaTypeSfx){ try{ f._belugaTypeSfx.pause(); }catch(_){} f._belugaTypeSfx=null; }
      const bs=AUDIO_SAMPLES['beluga_typing']?.cloneNode();
      if(bs){ bs.loop=true; bs.volume=0.5; bs.playbackRate=rate; _mixRoute(bs); bs.play().catch(()=>{}); f._belugaTypeSfx=bs; }
    },
  },

  // ————————————————————————————————————————————————————————————————
  // @tanphamnhat969 — "Elite Imperial Striker (Ursus Shocktrooper)
  //   [Harpoon shot] Every 5 seconds, launch a harpoon dealing 60 dmg
  //   [Harpoon thrust] Replace [Harpoon shot] if there's a target too close, lunge forward for a short
  //                    distance toward the target, dealing 120 dmg upon impact to enemy
  //   [Peak Morale] When at 50% HP or below, the left eye of this commenter glows red, doubling the
  //                 damage dealt of all of this commenter's abilities"
  //  Lao móc + dây xích bay ở toạ độ thế giới thật → vẽ trong loop() (khối "tanphamnhat969"), không dùng draw(f,s).
  // ⚠️ CHỈ dùng cho Commenter Battle (FAN_SKILLS) — KHÔNG đụng vào roster 56 con chính.
  // ————————————————————————————————————————————————————————————————
  tanphamnhat969: {
    name: 'tanphamnhat969',
    avatar: null,               // 👈 CHỜ ẢNH: lưu ảnh đại diện vào thư mục game rồi báo tôi, tôi nhúng vào đây
    hp: 1000, size: 48, speed: 5,
    desc: "Fires a chained harpoon every 5s — get too close and it lunges to skewer you instead. Below half HP its left eye burns red and every hit doubles.",
    init(f){ const tps=60*GAME_SPEED*TIME_SCALE; f._tsCD=Math.round(2.5*tps); f._tsHarpoons=[]; f._tsLunge=null; f._tsMorale=false; f._tsMoraleT=0; },
    tick(f, e, dist, cham){
      const tps=60*GAME_SPEED*TIME_SCALE;
      // 🔴 PEAK MORALE: ≤50% máu → mắt trái đỏ rực, mọi đòn ×2 (bật 1 lần, không tắt)
      if(!f._tsMorale && f.hp<=f.maxHp*0.5){ f._tsMorale=true; f._tsMoraleT=0; spawnParticles(f.x,f.y-f.size*0.2,'#ff1744',14,false,true); }
      if(f._tsMorale) f._tsMoraleT++;
      const mul=f._tsMorale?2:1;
      const foes=()=>{ const out=[];
        for(const arr of _hpSummonArrays()) for(const u of arr) if(u && !u.dead && u.team!==f.team && !(u.hp<=0)) out.push(u);   // thân phụ TRƯỚC
        for(const o of fighters) if(o!==f && !o.dead && o.team!==f.team) out.push(o);
        return out; };
      // 🪝 lao móc: bay thẳng → trúng ai thì CẮM vào người đó 1 nhịp → giật dây thu về
      for(let i=f._tsHarpoons.length-1;i>=0;i--){ const h=f._tsHarpoons[i];
        if(h.stuck){ h.t++;
          if(h.stuck.dead || (h.stuck.hp!==undefined && h.stuck.hp<=0)) h.stuck=null; else { h.x=h.stuck.x+h.ox; h.y=h.stuck.y+h.oy; }
          if(!h.stuck || h.t>=h.stickT){ h.stuck=null; h.ret=true; } else continue; }
        if(h.ret){ const dx=f.x-h.x, dy=f.y-h.y, d=Math.hypot(dx,dy);
          if(d<f.size){ f._tsHarpoons.splice(i,1); continue; }
          const sp=Math.max(16,d*0.22); h.x+=dx/d*sp; h.y+=dy/d*sp; continue; }
        h.x+=h.vx; h.y+=h.vy; h.life--;
        let hit=null; for(const u of foes()) if(Math.hypot(u.x-h.x,u.y-h.y)<(u.size||20)+6){ hit=u; break; }
        if(hit){
          hit.takeDamage(60*h.mul, f);
          playSample('hit_mid',0.45); addShake(4,7);
          _hitParticles(hit.x,hit.y,h.mul>1?'#ff1744':'#cfd8dc',8,false,true);
          h.stuck=hit; h.ox=h.x-hit.x; h.oy=h.y-hit.y; h.t=0; h.stickT=Math.round(0.35*tps);
          continue; }
        if(h.life<=0 || h.x<-30 || h.x>W+30 || h.y<-30 || h.y>H+30) h.ret=true;
      }
      // ⚡ đang LAO TỚI đâm: lướt thẳng, chạm địch đầu tiên là đâm 120 rồi khựng lại
      if(f._tsLunge){ const L=f._tsLunge;
        f.x+=L.vx; f.y+=L.vy; f.vx=0; f.vy=0;
        f.x=Math.max(f.size, Math.min(W-f.size, f.x)); f.y=Math.max(f.size, Math.min(H-f.size, f.y));
        if(!L.hit){ for(const u of foes()) if(Math.hypot(u.x-f.x,u.y-f.y)<f.size+(u.size||20)+MELEE_REACH){
          L.hit=true; u.takeDamage(120*L.mul, f);
          playSample('hit_heavy',0.5); addShake(7,10);
          _hitParticles(u.x,u.y,L.mul>1?'#ff1744':'#eceff1',12,false,true);
          L.t=Math.min(L.t,4); break; } }
        if(--L.t<=0) f._tsLunge=null;
        return;
      }
      f._tsCD=Math.max(0,f._tsCD-1);
      if(f._tsCD>0 || !e || e.dead || f._isHardCC()) return;
      const ang=Math.atan2(e.y-f.y, e.x-f.x), gap=dist-f.size-(e.size||20);
      if(gap<90){
        // [Harpoon thrust] địch quá gần → thay cú phóng bằng cú lao tới đâm (~0.22s, ~170px)
        f._tsLunge={ vx:Math.cos(ang)*13, vy:Math.sin(ang)*13, ang, t:Math.round(0.22*tps), hit:false, mul };
        playSample('fr_dash',0.6);
        f.actionState='attack'; f.actionTimer=24; f.attackAvatarTimer=24;
      } else {
        // [Harpoon shot]
        f._tsHarpoons.push({ x:f.x+Math.cos(ang)*f.size, y:f.y+Math.sin(ang)*f.size, vx:Math.cos(ang)*15, vy:Math.sin(ang)*15, ang,
          life:Math.round(1.6*tps), mul });
        playSample('wg_blade_throw',0.6);
      }
      f._tsCD=Math.round(5*tps);
    },
    draw(f, s){
      // 🔴 PEAK MORALE: mắt TRÁI đỏ rực (vẽ trong toạ độ của ảnh nên quay mặt nào mắt vẫn bám đúng chỗ)
      if(!f._tsMorale) return;
      const k=Math.min(1,f._tsMoraleT/20), pu=0.85+0.15*Math.sin(Date.now()/110);
      const ex=TS_EYE.x*s, ey=TS_EYE.y*s, R=s*0.5*pu*k;
      ctx.save(); ctx.globalCompositeOperation='lighter';
      const g=ctx.createRadialGradient(ex,ey,0,ex,ey,R);
      g.addColorStop(0,'rgba(255,90,80,1)'); g.addColorStop(0.18,'rgba(255,23,68,0.75)'); g.addColorStop(1,'rgba(255,0,40,0)');
      ctx.fillStyle=g; ctx.fillRect(ex-R,ey-R,R*2,R*2);
      ctx.fillStyle=`rgba(255,60,60,${0.55*k})`;                       // vệt loé ngang như ống kính
      ctx.beginPath(); ctx.ellipse(ex,ey,R*1.3,R*0.07,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle=`rgba(255,240,235,${k})`; ctx.beginPath(); ctx.arc(ex,ey,s*0.05,0,Math.PI*2); ctx.fill();
      ctx.restore();
    },
  },

};

// 🖼️ Ảnh đại diện của nhân vật fan: LƯU RIÊNG trong kho (cbs_fan_avatars) chứ không ghim vào code,
// nên m tự upload/đổi được bất cứ lúc nào. Ảnh nhúng sẵn trong FAN_SKILLS chỉ là mặc định dự phòng.
let _fanAvatars = {};
function _fanAvatarsLoad(){
  try{ const raw=storeGet('cbs_fan_avatars'); _fanAvatars = raw ? (JSON.parse(raw)||{}) : {}; }catch(e){ _fanAvatars={}; }
}
function _fanAvatarsSave(){ try{ storeSet('cbs_fan_avatars', JSON.stringify(_fanAvatars)); }catch(e){} }
function _fanAvatar(key){
  const S=FAN_SKILLS[key];
  return _fanAvatars[key] || (S && S.avatar) || null;
}
// mở hộp chọn file, đọc thành data URI rồi lưu lại cho đúng nhân vật đó
function fanPickAvatar(key){
  if(window.PLAY_ONLY) return;   // 🔒 bản online chỉ để chơi
  const inp=document.createElement('input');
  inp.type='file'; inp.accept='image/*';
  inp.onchange=()=>{
    const f=inp.files && inp.files[0]; if(!f) return;
    const r=new FileReader();
    r.onload=ev=>{ _fanAvatars[key]=ev.target.result; _fanAvatarsSave(); _ffa3RenderGrid(); };
    r.readAsDataURL(f);
  };
  inp.click();
}
function fanClearAvatar(key){ delete _fanAvatars[key]; _fanAvatarsSave(); _ffa3RenderGrid(); }
// tra về entry skill của con đang do FAN điều khiển (slot 0 trong Fan Battle), hoặc null
function _fanSkillOf(f){
  if(!fanCtx || !f || f.slotIdx!==0) return null;
  return FAN_SKILLS[f._fanSkillKey] || null;
}
// dựng/ cập nhật 1 mục roster ẩn cho nhân vật fan đang chọn, để mọi thứ đọc getSlotChar() vẫn chạy như thường
let _fanRosterIdx = null;
function _fanEnsureRoster(key){
  const S = FAN_SKILLS[key]; if(!S) return null;
  if(_fanRosterIdx==null || !roster[_fanRosterIdx] || roster[_fanRosterIdx].id!=='fan_char'){
    roster.push({ id:'fan_char', name:S.name, charKey:'fanchar', avatarUrl:_fanAvatar(key), idleAnim:'bounce' });
    _fanRosterIdx = roster.length-1;
  } else {
    roster[_fanRosterIdx].name = S.name;
    roster[_fanRosterIdx].avatarUrl = _fanAvatar(key);
  }
  return _fanRosterIdx;
}


// ===================== 🌬️ THE UNKNOWN GUY — "MUST'VE BEEN THE WIND" =====================
// Không tự đánh ai — chỉ lang thang khắp sàn (xem moveLogic()) và chạy vòng lặp 4 khung avatar (xem draw()).
// Cứ 4s có 1 sự kiện ngẫu nhiên xảy ra trên sàn, KHÔNG phụ thuộc vào trạng thái riêng của The Guy:
//   20% RỒNG bay ngang thiêu sàn · 55% VẬT LẠ rơi trúng mặt địch · 20% GÀ 100 HP chạy vào nảy khắp sàn
//   · 5% LỐC XOÁY hút toàn bộ meme vào tâm sàn, xoay tới khi có người chết.
const WG_EVENT_CD = 168;       // 2.8s theo yêu cầu — khoảng cách giữa các sự kiện từ lần thứ 2 trở đi
const WG_EVENT_FIRST_CD = 120; // 2s — riêng lần cast ĐẦU TIÊN sau khi vào trận
const WG_P_DRAGON  = 20;
const WG_P_ITEM    = 55;
const WG_P_CHICKEN = 20;
// còn lại 5% là lốc xoáy

function _wgTick(frozen){
  // các hệ quả (rồng bay/vật rơi/gà/lốc xoáy) luôn phải tự chạy vật lý + tự vẽ; đóng băng thì dừng lại,
  // chỉ vẽ, y hệt quy ước Fine Dog/UIA (không update/không gây dame trong lúc đóng băng toàn trận).
  _wgDragonTick(frozen);
  _wgFallItemsTick(frozen);
  _wgChickensTick(frozen);
  _wgTornadoTick(frozen);
  if(frozen) return;
  for(const guy of fighters){
    if(guy.type!=='windguy' || guy.dead) continue;
    guy._wgEventCD=(guy._wgEventCD===undefined?WG_EVENT_FIRST_CD:guy._wgEventCD)-1; // lần đầu 2s, các lần sau mới đúng 4s (WG_EVENT_CD)
    if(guy._wgEventCD<=0){
      guy._wgEventCD=WG_EVENT_CD;
      _wgFireEvent(guy);
    }
  }
}
function _wgFireEvent(guy){
  const r=Math.random()*100;
  let _wgIsTornado=false;
  if(r<WG_P_DRAGON) _wgEventDragon(guy);
  else if(r<WG_P_DRAGON+WG_P_ITEM) _wgEventFallItem(guy);
  else if(r<WG_P_DRAGON+WG_P_ITEM+WG_P_CHICKEN) _wgEventChicken(guy);
  else { _wgEventTornado(guy); _wgIsTornado=true; }
  // 🗨️ TRỪ lốc xoáy (nó đã tự khoá đứng yên + có bong bóng riêng lúc bị hút, xem _wgTornadoTick): mọi sự kiện
  // khác đều dừng The Guy lại 1.5s, chạy vòng 3 khung + hiện bong bóng "must've been the wind" đúng lúc đó.
  if(!_wgIsTornado){
    guy._wgAnimT=90; guy._wgAnimMax=90;
    playSample('wg_think', 0.8);   // 🍦 tiếng "suy nghĩ" đúng lúc The Guy dừng lại 1.5s phản ứng sự kiện
    if(!guy._cgSay || !guy._cgSay.perm) guy._cgSay={ text:"must've been the wind", life:90, maxLife:90, red:false };
  }
}

// ───── 🐉 SỰ KIỆN 1: RỒNG BAY NGANG THIÊU SÀN — 200 dmg + burn 20/s trong 3s cho mọi người, riêng The Guy chỉ dính burn ─────
const WG_DRAGON_IMGS=[WG_DRAGON1_IMG,WG_DRAGON2_IMG,WG_DRAGON3_IMG,WG_DRAGON4_IMG,WG_DRAGON5_IMG];
function _wgEventDragon(guy){
  playSample('wg_dragon_roar', 0.85);   // 🐉 gầm ngay lúc lao vào khung hình (tiếng nổ lửa lúc quét sàn là wg_dragon_impact, phát sau ở giữa đường bay)
  wgDragon = {
    t:0, dur:130, dir: Math.random()<0.5?1:-1,
    y: guy.size*1.8 + Math.random()*Math.max(1,H-guy.size*3.6),
    hit:false, owner:guy,
  };
}
function _wgDragonTick(frozen){
  if(!wgDragon) return;
  const D=wgDragon;
  if(!frozen){
    D.t++;
    if(!D.hit && D.t>=Math.round(D.dur*0.5)){
      D.hit=true;
      for(const f of fighters){
        if(f.dead) continue;
        if(f.type==='windguy'){
          f.burn=Math.max(f.burn,180); f._burnDmg=10; f._burnSrc=null; // chỉ dính burn 20/s trong 3s, KHÔNG dính cú 200 trực tiếp
        } else {
          f.takeDamage(200, D.owner);
          f.burn=Math.max(f.burn,180); f._burnDmg=10; f._burnSrc=D.owner; // 10 mỗi 0.5s = 20/s, kéo dài 3s
        }
      }
      // 🐉 DAME AOE THẬT SỰ: tác động luôn cả quân triệu hồi trên sàn (lính Commander/German, hiệp sĩ Doge,
      // tượng Mewing, dao Capybara, mèo phụ Crying Cat, clone Doge) — đúng lớp lỗi hay quên các mảng này,
      // vừa sửa y hệt ở gà của The Unknown Guy. Quân triệu hồi không có hệ `.burn` tự tick như Fighter thật
      // nên chỉ áp cú 200 dmg trực tiếp qua _summonTakeDamage, không gán burn (đằng nào cũng không ai đọc field đó).
      for(const _arr of _hpSummonArrays()){
        for(const s of _arr){
          if(s.dead || (s.hp!==undefined && s.hp<=0)) continue;
          if(typeof s.takeDamage!=='function') continue;
          s.takeDamage(200, D.owner);
        }
      }
      addShake(16,22);
      spawnParticles(W/2,D.y,'#ff6d00',30,false,true);
      playSample('wg_dragon_impact',0.9);
    }
    if(D.t>=D.dur) wgDragon=null;
  }
  if(wgDragon) _wgDrawDragon();
}
function _wgDrawDragon(){
  const D=wgDragon;
  const _p=D.t/D.dur;
  const _margin=140;
  const _x = D.dir>0 ? (-_margin + _p*(W+_margin*2)) : (W+_margin - _p*(W+_margin*2));
  if(D.t%3===0) spawnParticles(_x - D.dir*40, D.y+10, '#ff9100', 1, false, true);
  const _img=WG_DRAGON_IMGS[Math.floor(Date.now()/70)%5];
  if(!_img || !_img.complete || !_img.naturalWidth) return;
  const _asp=_img.naturalWidth/_img.naturalHeight;
  const _dh=360, _dw=_dh*_asp;   // x4 theo yêu cầu (90→360)
  ctx.save();
  ctx.translate(_x, D.y);
  if(D.dir<0) ctx.scale(-1,1); // ⚠️ ảnh gốc đầu quay sang PHẢI (đã xem lại trực tiếp file ảnh) — bay sang TRÁI mới cần lật, trước đó lật ngược hướng nên bay lùi
  ctx.drawImage(_img, -_dw/2, -_dh/2, _dw, _dh);
  ctx.restore();
}

// ───── 📦 SỰ KIỆN 2: VẬT LẠ BAY VÀO TỪ GÓC XA NHẤT — 130-195 dmg ngẫu nhiên (riêng bình máu thì đáp vào
// CHÍNH The Guy, hồi 250 HP). Bay kiểu giống hệt cú ném mèo của Yelling Women: xuất phát từ góc sân xa mục
// tiêu nhất, bám đúng theo mục tiêu suốt đường bay (không thể né), xoay tròn liên tục lúc bay.
const WG_ITEMS=[
  {img:WG_ITEM_AXE_IMG,      dh:78, sfxLoop:'wg_axe_whoosh',  sfxHit:'wg_blade_impact'}, // 🪓 rìu — rít loop suốt đường bay, tắt đúng lúc chạm địch + tiếng chém trúng
  {img:WG_ITEM_COW_IMG,      dh:127.5, cow:true, sfxSpawn:'wg_cow_moo'}, // 🐄 bò (giảm 15% theo yêu cầu, gốc 150) — ăn trọn TRẦN dải dame + choáng 1.5s
  {img:WG_ITEM_DILDOBLK_IMG, dh:120}, // +100% theo yêu cầu (gốc 60)
  {img:WG_ITEM_DILDO_IMG,    dh:128}, // +100% theo yêu cầu (gốc 64)
  {img:WG_ITEM_SWORD_IMG,    dh:80, sfxLoop:'wg_blade_throw', sfxHit:'wg_blade_impact'}, // 🗡️ kiếm — cùng kiểu với rìu, tiếng ném lưỡi bay + tiếng chém trúng
  {img:WG_ITEM_TRUCK_IMG,    dh:140, sfxSpawn:'wg_truck_horn'}, // 🚚 xe tải — to hẳn theo đúng tên, rú còi lúc lao vào
  {img:WG_ITEM_HEALING_IMG,  dh:70, heal:true}, // 🧪 bình máu — đáp vào CHÍNH The Guy, hồi 250 HP thay vì gây dame
];
function _wgEventFallItem(guy){
  const e=guy.enemy; if(!e || e.dead) return;
  const pick=WG_ITEMS[(Math.random()*WG_ITEMS.length)|0];
  const target = pick.heal ? guy : e;
  // 🎯 góc sân XA mục tiêu nhất — giống hệt cách Yelling Women chọn điểm xuất phát cho cú ném mèo
  const _sz=28;
  const _corners=[[_sz,_sz],[W-_sz,_sz],[_sz,H-_sz],[W-_sz,H-_sz]];
  _corners.sort((a,b)=>(b[0]-target.x)**2+(b[1]-target.y)**2-(a[0]-target.x)**2-(a[1]-target.y)**2);
  const [_sx,_sy]=_corners[0];
  const _ang=Math.atan2(target.y-_sy, target.x-_sx);
  const _spd=7;
  // 🌀 quay CHẬM: tổng cả quãng bay chỉ 1-2 vòng. Tính từ số tick dự kiến bay tới nơi thay vì đặt cứng
  // tốc quay (đặt cứng thì đường bay dài/ngắn khác nhau sẽ ra số vòng khác nhau, và trước đó quay tới 3-5 vòng).
  const _chamR=target.size + pick.dh*0.28;   // vật dừng ở rìa chứ không bay tới đúng tâm — phải trừ ra
  const _dir=Math.random()<0.5?-1:1;
  wgFallItems.push({
    img:pick.img, dh:pick.dh, x:_sx, y:_sy, vx:Math.cos(_ang)*_spd, vy:Math.sin(_ang)*_spd,
    hit:false, heal:!!pick.heal, cow:!!pick.cow, sfxHit:pick.sfxHit||null, target, owner:guy, chamR:_chamR, flySpd:_spd,
    // dame +30% theo yêu cầu: dải gốc 100-150 → 130-195. Bò vẫn luôn ăn TRẦN của dải (195, dải đã scale).
    dmg: pick.cow ? 195 : Math.round((100+Math.random()*50)*1.3),
    // 🌀 QUỸ QUAY CÒN LẠI (không phải tốc quay cố định): mỗi tick tiêu 1 phần quỹ này tỉ lệ với quãng đường
    // ĐÃ BAY so với quãng đường CÒN LẠI THỰC TẾ (đo lại mỗi tick) — nên dù đường bay dài/ngắn khác ước tính
    // ban đầu bao nhiêu (vật là đạn HOMING bám đuổi mục tiêu đang di chuyển), tổng số vòng quay không bao giờ
    // vượt quá quỹ đã đặt. Hạ xuống 0.6-1.1 vòng vì đo thực tế công thức cũ có lúc ra hẳn 2.1 vòng.
    rot:0, spinLeft:_dir*(0.6+Math.random()*0.5)*Math.PI*2,
  });
  // 🐄🚚 tiếng riêng lúc vật lao vào khung hình — PHẢI tự giữ tham chiếu (không dùng playSample bắn-rồi-quên)
  // để có thể NGẮT NGAY khi vật chạm địch: còi xe tải dài 2.35s trong khi xe thường bay chạm đích chưa đầy 1s.
  if(pick.sfxSpawn){
    const _ss=AUDIO_SAMPLES[pick.sfxSpawn]?.cloneNode();
    if(_ss){ _ss.volume=0.85; _mixRoute(_ss); try{ _ss.play().catch(()=>{}); }catch(e){}
             wgFallItems[wgFallItems.length-1].spawnSfx=_ss; }
  }
  // 🪓🗡️ vật nào khai sfxLoop thì rít LOOP suốt đường bay, tắt ngay khi chạm địch (xem _wgStopItemSfx ở
  // mọi lối xoá vật). Treo thẳng trên object vật bay (không phải trên Fighter) nên phải tự dọn — cùng khuôn
  // mẫu tiếng đĩa bay Alien Cat / tiếng rít mũi tên Loading Cat, đã khai thêm ở stopAllBattleMusic().
  if(pick.sfxLoop){
    const _sx=AUDIO_SAMPLES[pick.sfxLoop]?.cloneNode();
    if(_sx){ _sx.loop=true; _sx.volume=0.55; _registerBgMusic(_sx,0.55); _mixRoute(_sx);
             try{ _sx.play().catch(()=>{}); }catch(e){}
             wgFallItems[wgFallItems.length-1].sfx=_sx; }
  }
}
function _wgStopItemSfx(it){
  if(!it) return;
  if(it.sfx){ _stopLoopAudio(it.sfx); it.sfx=null; }               // 🪓🗡️ tiếng rít loop suốt đường bay
  if(it.spawnSfx){ try{ it.spawnSfx.pause(); it.spawnSfx.currentTime=0; }catch(e){} it.spawnSfx=null; } // 🐄🚚 tiếng lúc phóng
}
function _wgFallItemsTick(frozen){
  if(!wgFallItems.length) return;
  if(!frozen){
    for(let i=wgFallItems.length-1;i>=0;i--){
      const it=wgFallItems[i];
      {
        const t=it.target;
        if(t && !t.dead){
          // bám đúng theo mục tiêu suốt đường bay (homing thật, giống mèo Yelling Women) — không thể né
          const _dx=t.x-it.x, _dy=t.y-it.y, _d=Math.hypot(_dx,_dy)||1, _spd=Math.hypot(it.vx,it.vy)||7;
          it.vx=_dx/_d*_spd; it.vy=_dy/_d*_spd;
        }
        it.x+=it.vx; it.y+=it.vy;
        // 🌀 quãng còn lại tính LẠI mỗi tick theo vị trí thật hiện giờ — tự thích nghi nếu mục tiêu đổi
        // hướng/tốc độ, không phụ thuộc ước tính lúc phóng.
        const _con=Math.max(1, (Math.hypot(it.target.x-it.x,it.target.y-it.y)-it.chamR)/it.flySpd);
        const _tieu=it.spinLeft*(1/_con);
        it.rot+=_tieu; it.spinLeft-=_tieu;
        const _close = t && !t.dead && Math.hypot(t.x-it.x,t.y-it.y) < (t.size + it.dh*0.28);
        if(_close){
          if(it.heal){
            t.hp=Math.min(t.maxHp, t.hp+250);
            floatTexts.push(_ftFollow({x:t.x,y:t.y-t.size-18,text:'+250',color:'#69f0ae',life:55,isDmg:true,huge:true}, t));
            spawnParticles(t.x,t.y,'#69f0ae',14,false,true);
            _healSfx(250);   // 💚 tiếng hồi máu chung (thay cho hit_light trước đây — hồi máu mà kêu tiếng đánh trúng)
          } else {
            // 💥 để takeDamage() tự lo TOÀN BỘ hiệu ứng va chạm (impact Retro Impact Effect F + số dame +
            // rung + tiếng theo mức dame) — y hệt cú ném mèo của Yelling Women, không tự thêm hạt/tiếng/rung.
            t.takeDamage(it.dmg, it.owner);
            if(it.sfxHit) playSample(it.sfxHit, 0.8);            // 🪓🗡️ tiếng lưỡi chém trúng thân
            if(it.cow && !t.dead) t.stun=Math.max(t.stun,90);   // 🐄 bò còn đè choáng 1.5s
          }
          _wgStopItemSfx(it);
          wgFallItems.splice(i,1); continue;   // chạm là biến mất ngay, không nằm lại trên sàn
        } else if(it.x<-40||it.x>W+40||it.y<-40||it.y>H+40){
          _wgStopItemSfx(it);
          wgFallItems.splice(i,1); continue; // mục tiêu vừa chết giữa đường bay — dọn rác, không có ai để bám nữa
        }
      }
    }
  }
  _wgDrawFallItems();
}
function _wgDrawFallItems(){
  for(const it of wgFallItems){
    const img=it.img;
    if(!img || !img.complete || !img.naturalWidth) continue;
    const _asp=img.naturalWidth/img.naturalHeight;
    const _dh=it.dh, _dw=_dh*_asp;
    ctx.save();
    ctx.translate(it.x, it.y);
    ctx.rotate(it.rot);
    ctx.drawImage(img, -_dw/2, -_dh/2, _dw, _dh);
    ctx.restore();
  }
}

// ───── 🐔 SỰ KIỆN 3: GÀ CHẠY VÀO SÀN 5s RỒI BIẾN MẤT — 45 dmg mỗi va chạm, riêng đụng The Guy thì choáng 1s
// (không dame). KHÔNG có máu, không phải quân triệu hồi → không nằm trong _hpSummonArrays(), không ai đánh
// nó được; nó chỉ là vật cản chạy loạn có hạn giờ. Di chuyển dùng ĐÚNG bộ vật lý của meme thường
// (ma sát 0.992 + hồi nửa tốc khi rớt dưới 55% + dội tường damping 0.85). ─────
const WG_CHICKEN_IMGS=[WG_CHICK1_IMG,WG_CHICK2_IMG,WG_CHICK3_IMG,WG_CHICK4_IMG,WG_CHICK5_IMG];
const WG_JOCKEY_IMGS=[WG_JOCKEY1_IMG,WG_JOCKEY2_IMG,WG_JOCKEY3_IMG,WG_JOCKEY4_IMG,WG_JOCKEY5_IMG];
const WG_JOCKEY_TYLE=0.3;    // 30% số lần thả gà ra CHICKEN JOCKEY, 70% là gà thường
const WG_JOCKEY_LIFE=360;    // 6s (gà thường 5s)
const WG_JOCKEY_DMG=60;      // 45 của gà thường → 60
const WG_JOCKEY_KB=8;        // đẩy lùi NHẸ (so sánh: sóng Rubik 12, sóng Kermit 18)
const WG_CHICKEN_LIFE=300;   // 5s rồi biến mất
function _wgEventChicken(guy){
  const _jockey = Math.random() < WG_JOCKEY_TYLE;
  const _sz=guy.size*0.5*(_jockey?1.15:1);   // jockey to hơn chút vì có thằng zombie cưỡi trên lưng
  // ⚠️ vật lý chung cho tốc chạy thật = topSpeed*0.5, nên topSpeed phải gấp đôi tốc mong muốn.
  // Tốc chạy thật mong muốn = (2.4-3.2 của bản cũ) × 1.2 = 2.88-3.84 → topSpeed = 5.76-7.68.
  const _spd=(2.4+Math.random()*0.8)*1.2*2*(_jockey?1.2*1.5*1.5:1);   // 🧟 jockey: +20% rồi +50% rồi +50% nữa theo yêu cầu (1.2×1.5×1.5=2.7)
  const _le=_sz*1.05;
  const _bien=_sz*2;
  const _ngang=()=>(Math.random()-0.5)*0.7*_spd;
  // 🚪 CHỌN MÉP XA CÁC MEME NHẤT: mỗi mép bốc 1 điểm vào sân, chấm điểm bằng khoảng cách tới con meme
  // GẦN NHẤT, lấy mép có điểm cao nhất. Tránh cảnh gà vừa hiện ra đã dí ngay mặt ai đó (đúng lớp lỗi
  // "đừng để nó hiện thẳng vào địch" từng gặp ở hộp quà Rick Roll).
  const _song=fighters.filter(f=>!f.dead);
  const _diem=(px,py)=> _song.length ? Math.min(..._song.map(f=>Math.hypot(f.x-px,f.y-py))) : 0;
  const _ungVien=[
    { canh:0, x:_bien+Math.random()*Math.max(1,W-_bien*2), y:_le },
    { canh:1, x:W-_le, y:_bien+Math.random()*Math.max(1,H-_bien*2) },
    { canh:2, x:_bien+Math.random()*Math.max(1,W-_bien*2), y:H-_le },
    { canh:3, x:_le,   y:_bien+Math.random()*Math.max(1,H-_bien*2) },
  ];
  _ungVien.sort((a,b)=>_diem(b.x,b.y)-_diem(a.x,a.y));
  const _ch=_ungVien[0];
  let x=_ch.x, y=_ch.y, vx, vy;
  if(_ch.canh===0){ vx=_ngang(); vy=_spd;  }
  else if(_ch.canh===1){ vx=-_spd; vy=_ngang(); }
  else if(_ch.canh===2){ vx=_ngang(); vy=-_spd; }
  else { vx=_spd; vy=_ngang(); }
  wgChickens.push({
    x,y,vx,vy,size:_sz,team:guy.team,owner:guy,type:'wgchicken',
    hitCD:{}, life:_jockey?WG_JOCKEY_LIFE:WG_CHICKEN_LIFE, topSpeed:_spd, jockey:_jockey,
  });
  playSample('wg_chicken', 0.8);   // 🐔 tiếng gà thật do user cung cấp (trước dùng tạm wg_chicken_spawn = winner-chicken-dinner)
}
function _wgChickensTick(frozen){
  if(!wgChickens.length) return;
  if(frozen){ for(const c of wgChickens) _wgDrawChicken(c); return; }
  for(let i=wgChickens.length-1;i>=0;i--){
    const c=wgChickens[i];
    c.life=(c.life===undefined?WG_CHICKEN_LIFE:c.life)-1;
    if(c.life<=0){ spawnParticles(c.x,c.y,'#ffffff',8,false,true); wgChickens.splice(i,1); continue; }
    // 🏃 vật lý y hệt meme thường: ma sát → hồi nửa tốc khi rớt dưới 55% → kẹp trần tốc → dội tường damping 0.85
    c.vx*=0.992; c.vy*=0.992;
    const _cSpd=Math.hypot(c.vx,c.vy);
    if(_cSpd>0.05) c._lastAngle=Math.atan2(c.vy,c.vx);
    if(_cSpd<c.topSpeed*0.55){
      const _cAng=(c._lastAngle!==undefined)?c._lastAngle:Math.random()*Math.PI*2;
      c.vx=Math.cos(_cAng)*c.topSpeed*0.5; c.vy=Math.sin(_cAng)*c.topSpeed*0.5;
    }
    if(_cSpd>c.topSpeed){ c.vx=c.vx/_cSpd*c.topSpeed; c.vy=c.vy/_cSpd*c.topSpeed; }
    c.x+=c.vx; c.y+=c.vy;
    const _cD=0.85;
    if(c.x<c.size){ c.x=c.size; c.vx=Math.abs(c.vx)*_cD; c.vy*=_cD; }
    if(c.x>W-c.size){ c.x=W-c.size; c.vx=-Math.abs(c.vx)*_cD; c.vy*=_cD; }
    if(c.y<c.size){ c.y=c.size; c.vy=Math.abs(c.vy)*_cD; c.vx*=_cD; }
    if(c.y>H-c.size){ c.y=H-c.size; c.vy=-Math.abs(c.vy)*_cD; c.vx*=_cD; }
    for(const k in c.hitCD) c.hitCD[k]=Math.max(0,c.hitCD[k]-1);
    // ⚠️ QUÉT CẢ QUÂN TRIỆU HỒI, không chỉ `fighters` — đúng lớp lỗi đã dính nhiều lần trong file này (gà của
    // The Unknown Guy trước đây không đụng được 2 mèo phụ của Crying Cat team vì chỉ quét `fighters`).
    for(const _arr of [fighters, ..._hpSummonArrays()]){
    for(const f of _arr){
      if(f.dead) continue;
      if(f.hp!==undefined && f.hp<=0) continue;
      if(typeof f.takeDamage!=='function') continue;
      if(f._wgChkHitId===undefined) f._wgChkHitId=++_uiaHitIdSeq;
      const _hk=f._wgChkHitId;
      if((c.hitCD[_hk]||0)>0) continue;
      const d=Math.hypot(f.x-c.x,f.y-c.y);
      if(d<c.size+f.size){
        c.hitCD[_hk]=24;
        const _nx=(c.x-f.x)/(d||1), _ny=(c.y-f.y)/(d||1), _sp=Math.hypot(c.vx,c.vy)||2.5;
        c.vx=_nx*_sp; c.vy=_ny*_sp;
        // 🧟 ĐẨY LÙI: chỉ cộng vận tốc là VÔ HIỆU — moveLogic() kẹp tốc về topSpeed rồi ép về tốc "cruise"
        // mỗi tick nên cú đẩy bị nuốt sạch trong vài khung (codebase đã ghi đúng lỗi này ở sóng âm Guitar Cat).
        // Phải DỜI THẲNG VỊ TRÍ kèm theo, y hệt cách sóng âm xử lý.
        const _day=(muc)=>{
          f.vx=-_nx*muc; f.vy=-_ny*muc; f._slammed=true;
          f.x=Math.max(f.size, Math.min(W-f.size, f.x-_nx*muc*1.4));
          f.y=Math.max(f.size, Math.min(H-f.size, f.y-_ny*muc*1.4));
        };
        if(f.type==='windguy'){
          _day(WG_JOCKEY_KB); // 🐔🧟 gà nào đụng phe mình cũng CHỈ đẩy lùi nhẹ, không dame/choáng (gà thường trước đây gây choáng 1s, đã bỏ)
        } else if(c.jockey){
          f.takeDamage(WG_JOCKEY_DMG, c.owner);
          _day(WG_JOCKEY_KB);                                  // 🧟 đẩy lùi nhẹ kèm theo cú húc
          playSample('wg_jockey_hit', 0.8);                    // 🔊 chỉ kêu khi húc trúng ĐỊCH
        } else {
          f.takeDamage(45, c.owner);
        }
      }
    }
    }
    _wgDrawChicken(c);
  }
}
function _wgDrawChicken(c){
  const _idx=Math.floor(Date.now()/90)%5;
  const img=(c.jockey?WG_JOCKEY_IMGS:WG_CHICKEN_IMGS)[_idx];
  if(!img || !img.complete || !img.naturalWidth) return;
  const _asp=img.naturalWidth/img.naturalHeight;
  const _d=c.size*2.3;
  const _dh=_asp>=1?_d/_asp:_d, _dw=_asp>=1?_d:_d*_asp;
  ctx.save();
  ctx.translate(c.x,c.y);
  // ✅ đã xem lại trực tiếp cả 2 bộ ảnh: gà thường LẪN chicken jockey đều quay đầu về PHẢI như nhau
  //    (lần trước đoán nhầm jockey quay trái, làm nó đi giật lùi — đúng lớp lỗi con rồng bay ngược đã gặp).
  if(c.vx<0) ctx.scale(-1,1);
  ctx.drawImage(img,-_dw/2,-_dh/2,_dw,_dh);
  ctx.restore();
}

// ───── 🌪️ SỰ KIỆN 4: LỐC XOÁY GIỮA SÀN — hút toàn bộ meme vào tâm, xoay 100 dame/s tới khi có người chết ─────
// Spritesheet 5x12=60 khung: 0..19 = pha TÍCH TỤ LỚN DẦN (phát 1 lần lúc lốc vừa hiện), 20..59 = vòng lặp
// lúc đang hút/xoay; lúc có người chết thì PHÁT NGƯỢC 19→0 làm hiệu ứng thu bé rồi biến mất (yêu cầu của user:
// "lốc xoáy chỉ khi có người chết mới phát phần khung lốc thu bé và biến mất" — tái dùng ngược đúng dải khung
// lớn dần, không cần khung riêng).
const WG_TORNADO_COLS=5, WG_TORNADO_ROWS=12, WG_TORNADO_FRAMES=60;
const WG_TORNADO_GROW_END=20;
const WG_TORNADO_FRAME_HOLD=3;
// 🌀 bán kính quỹ đạo: thân meme đã ~46px bán kính, để 20-34 thì 2 con luôn chồng lên nhau thành 1 cục
// (đúng ảnh người dùng gửi). Nới rộng hơn 2 lần thân để chúng xoay tách bạch.
const WG_TORNADO_ORBIT_R=[76,98];
const WG_TORNADO_SPIN=0.05;    // tốc xoay quỹ đạo — vừa phải để vẫn đọc được bong bóng thoại (yêu cầu user)
const WG_TORNADO_PULL=3.0;
const WG_TORNADO_CATCH_R=104;   // bắt vào vòng NGAY khi tới rìa quỹ đạo, không hút dồn về tận tâm rồi mới bung ra
const WG_TORNADO_VOL=0.9;   // 0.75 × 1.2 = to hơn 20% so với mức loop thường của char này
function _wgEventTornado(guy){
  if(wgTornado) return; // đã có 1 lốc đang hoạt động — bỏ qua, không chồng 2 lốc
  wgTornado = { phase:'growing', frame:0, frameT:0, x:W/2, y:H/2, owner:guy, sfx:null };
  // 🔊 tiếng lốc chạy loop suốt cơn; lúc lốc thu nhỏ thì volume tụt dần đúng theo TIẾN ĐỘ khung hình
  // (xem nhánh 'shrinking'), về 0 đúng lúc lốc biến mất. Treo trên chính object lốc nên phải tự dọn —
  // đã khai thêm ở stopAllBattleMusic() cho trường hợp hết trận giữa lúc lốc còn xoay.
  const _ts=AUDIO_SAMPLES['wg_tornado']?.cloneNode();
  if(_ts){ _ts.loop=true; _ts.volume=WG_TORNADO_VOL; _registerBgMusic(_ts,WG_TORNADO_VOL); _mixRoute(_ts);
           try{ _ts.play().catch(()=>{}); }catch(e){}
           wgTornado.sfx=_ts; }
}
function _wgTornadoTick(frozen){
  if(!wgTornado) return;
  const T=wgTornado;
  if(!frozen){
    if(T.phase==='growing'){
      T.frameT++;
      if(T.frameT>=WG_TORNADO_FRAME_HOLD){
        T.frameT=0; T.frame++;
        if(T.frame>=WG_TORNADO_GROW_END){ T.frame=WG_TORNADO_GROW_END; T.phase='looping'; }
      }
    } else if(T.phase==='looping'){
      T.frameT++;
      if(T.frameT>=WG_TORNADO_FRAME_HOLD){
        T.frameT=0; T.frame++;
        if(T.frame>=WG_TORNADO_FRAMES) T.frame=WG_TORNADO_GROW_END;
      }
      // 🌪️ DAME AOE THẬT SỰ: hút cả quân triệu hồi trên sàn, không chỉ 2 meme chính — đúng lớp lỗi hay quên
      // các mảng này (vừa sửa y hệt ở gà và rồng của The Unknown Guy). Quân triệu hồi không có `.stun`/`_cgSay`
      // ý nghĩa gì (chẳng ai đọc) nhưng gán vào cũng vô hại, đỡ phải viết 2 nhánh riêng.
      const _tatCa=[fighters, ..._hpSummonArrays()].flatMap(_arr=>_arr.filter(x=>!x.dead && (x.hp===undefined||x.hp>0) && typeof x.takeDamage==='function'));
      for(const f of _tatCa){
        f._wgInVortex=true; // 🌪️ dùng để _bounceFighters() bỏ qua tách thân — xem ghi chú ở đó
        if(!f._wgCaptured){
          const _dx=T.x-f.x, _dy=T.y-f.y, _d=Math.hypot(_dx,_dy)||1;
          if(_d>WG_TORNADO_CATCH_R){
            const _pull=Math.min(_d,WG_TORNADO_PULL);
            f.x+=_dx/_d*_pull; f.y+=_dy/_d*_pull;
          } else {
            f._wgCaptured=true;
            f._wgOrbitR=WG_TORNADO_ORBIT_R[0]+Math.random()*(WG_TORNADO_ORBIT_R[1]-WG_TORNADO_ORBIT_R[0]);
            // 📐 chia ĐỀU góc quanh vòng theo thứ tự bị bắt (2 con → đối xứng nhau qua tâm), thay vì lấy góc
            // lúc chạm — hai con bay vào cùng một phía sẽ xoay chồng lên nhau.
            T.capCount=(T.capCount||0);
            const _soCon=Math.max(2, _tatCa.length);
            f._wgOrbitA=(T.capCount++)*(Math.PI*2/_soCon);
            f._wgSpinDmgCD=0;
            if(f.type==='windguy'){
              // 🗨️ bong bóng VĨNH VIỄN — tới hết trận (yêu cầu user), đè lên câu "must've been the wind" thường
              f._cgSay={ text:"It's actually the wind", life:999999, maxLife:999999, red:true, perm:true };
            }
          }
          f.vx=0; f.vy=0;
          f.stun=Math.max(f.stun,2);
        } else {
          f._wgOrbitA+=WG_TORNADO_SPIN;
          f.x=T.x+Math.cos(f._wgOrbitA)*f._wgOrbitR;
          f.y=T.y+Math.sin(f._wgOrbitA)*f._wgOrbitR;
          f.vx=0; f.vy=0;
          f.stun=Math.max(f.stun,2);
          f._wgSpinDmgCD=(f._wgSpinDmgCD||0)-1;
          if(f._wgSpinDmgCD<=0){
            f._wgSpinDmgCD=15; // 100 dame/s = 25 mỗi 0.25s (15 tick)
            f.takeDamage(25, T.owner, false, true, '🌪️', null, true);
          }
        }
      }
      // ⚠️ điều kiện KẾT THÚC lốc vẫn chỉ tính MEME chính chết (không tính quân triệu hồi) — lốc là chiêu
      // "xoay tới khi có người chết", quân phụ chết không phải là kết cục trận đấu.
      if(fighters.some(f=>f._wgCaptured && f.dead)){
        T.phase='shrinking'; T.frameT=0;
      }
    } else if(T.phase==='shrinking'){
      T.frameT++;
      if(T.frameT>=WG_TORNADO_FRAME_HOLD){
        T.frameT=0; T.frame--;
        if(T.frame<0){
          for(const _arr of [fighters, ..._hpSummonArrays()]) for(const f of _arr){ f._wgCaptured=false; f._wgInVortex=false; }
          if(T.sfx){ _stopLoopAudio(T.sfx); T.sfx=null; }
          wgTornado=null;
        }
      }
      // 🔉 nhỏ dần ĐÚNG theo tiến độ cột lốc co lại: khung 19→0 thì volume WG_TORNADO_VOL→0
      if(wgTornado && T.sfx){
        try{ T.sfx.volume=Math.max(0, Math.min(1, WG_TORNADO_VOL*(T.frame/WG_TORNADO_GROW_END))); }catch(e){}
      }
    }
  }
  if(wgTornado) _wgDrawTornado();
}
// 🦶 CHÂN LỐC (điểm chạm đất của cột xoáy) không nằm giữa khung ảnh — đo trực tiếp trên vài khung ở pha
// đang xoáy: tâm ngang ~50% bề rộng, đáy cột ở ~97% chiều cao khung (khung vuông nhưng cột xoáy dồn hẳn
// xuống đáy). Neo đúng điểm này vào (T.x,T.y) — chỗ các meme đang xoay quanh — thay vì neo giữa khung ảnh,
// nếu không cột lốc trôi lên cao ~150px so với vòng xoay, nhìn như 2 thứ không dính vào nhau.
const WG_TORNADO_ANCHOR_X=0.50, WG_TORNADO_ANCHOR_Y=0.97;
function _wgDrawTornado(){
  const T=wgTornado;
  const img=WG_TORNADO_IMG;
  if(!img || !img.complete || !img.naturalWidth) return;
  const _fw=img.naturalWidth/WG_TORNADO_COLS, _fh=img.naturalHeight/WG_TORNADO_ROWS;
  const _idx=Math.max(0,Math.min(WG_TORNADO_FRAMES-1,T.frame));
  const _sx=(_idx%WG_TORNADO_COLS)*_fw, _sy=Math.floor(_idx/WG_TORNADO_COLS)*_fh;
  const _d=320;
  ctx.save();
  ctx.globalAlpha=0.95;
  ctx.drawImage(img,_sx,_sy,_fw,_fh, T.x-_d*WG_TORNADO_ANCHOR_X, T.y-_d*WG_TORNADO_ANCHOR_Y, _d, _d);
  ctx.restore();
}

// ⚡ FIX KHỰNG HÌNH LẦN ĐẦU DÙNG SKILL — TÌM RA GỐC RỄ BẰNG CDP PROFILER (đúng cách đã ghi trong dự án): không
// phải do decode ảnh hay GPU upload texture (đã thử cả 2, đo lại vẫn khựng y hệt ~250-300ms). Thủ phạm THẬT là
// _stickerMask() — hàm cắt viền sticker cho avatar chạy erosion bán kính 4 trên TỪNG PIXEL, vốn thiết kế cho
// 1 avatar cỡ vài trăm px, nhưng vài nhân vật lại gán thẳng ẢNH SPRITE-SHEET NHIỀU KHUNG cỡ hơn 1000px (như
// DAMDAMDIDI_DANCE_IMG 1540×1494, gồm 86 khung nhảy) làm "avatar" — hàm này chạy trên NGUYÊN sprite-sheet mỗi
// lần đổi ảnh, tốn hẳn ~188ms 1 LẦN DUY NHẤT lúc lần đầu vẽ (rồi cache lại _sil nên các lần sau nhanh bình
// thường). Những ảnh nạp qua avatarImgs[] (do user upload) đã có CHARS_NO_STICKER_MASK/_applyNoMaskFlags() lo
// việc này; các ảnh sprite-sheet NHÚNG CỨNG (không qua avatarImgs[]) thì không ai đụng tới — set thẳng cờ
// _noMask=true ở đây để bỏ qua hẳn bước erosion tốn kém, viền vẫn ra đúng vì y hệt cách windguy/rickroll/
// mosquitoviolin đã dùng cho ảnh chi tiết mảnh.
(function _prewarmNoMask(){
  const _sheets=[DAMDAMDIDI_DANCE_IMG, DEPRESSED_CRY_IMG, SCAREDDOG_IMG, SMARTGUY_THINK_IMG, SCREAMING_MARMOT_SCREAM_IMG, ...CALMDOG_FORM_IMGS];
  for(const im of _sheets){ try{ if(im) im._noMask=true; }catch(e){} }
})();
